  `id` bigint NOT NULL COMMENT '雪花 ID',
  `plan_id` bigint NOT NULL COMMENT '计划 id',
  `day_id` bigint DEFAULT NULL COMMENT '每日任务 id（模考答完可空）',
  `mock_paper_id` bigint DEFAULT NULL COMMENT '模考卷 id（round_type=mock 时，作答幂等键用）',
  `platform_user_id` bigint NOT NULL COMMENT '学员',
  `exam_plan_id` bigint DEFAULT NULL COMMENT '冗余：train_exam_list.id（回写 PHP exam_result.exam_plan_id 用）',
  `question_id` bigint NOT NULL COMMENT 'exam_exam_detail.id',
  `question_score` decimal(10,1) DEFAULT NULL COMMENT '冗余：题目分值（回写 get_score 用，对=题分/错=0）',
  `earned_score` decimal(10,1) DEFAULT NULL COMMENT '实得分（严格判分部分分；空=按 is_correct 推导）',
  `knowledge_id` bigint DEFAULT NULL COMMENT '冗余便于统计',
  `question_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'single/multi/judge/...',
  `round_type` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'new/review/mock',
  `user_answer` text COLLATE utf8mb4_unicode_ci COMMENT '作答内容（单/判：选项内容；多选：内容数组 JSON）',
  `is_correct` tinyint NOT NULL DEFAULT '0' COMMENT '0/1',
  `use_time_sec` int NOT NULL DEFAULT '0' COMMENT '用时（秒）',
  `attempt_seq` int NOT NULL DEFAULT '1' COMMENT '该题第几次作答',
  `php_synced` tinyint NOT NULL DEFAULT '0' COMMENT '回写 PHP exam_result：0 未回写 1 已回写 2 失败待补偿',
  `php_sync_time` datetime DEFAULT NULL COMMENT '回写成功时间',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_review_answer_once` (`plan_id`,`day_id`,`question_id`,`attempt_seq`),
  KEY `idx_ai_review_answer_sync` (`php_synced`,`id`),
  KEY `idx_ai_review_answer_user` (`platform_user_id`,`plan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 复习作答记录';
CREATE TABLE `ai_review_gray_whitelist` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户 ID',
  `scope_type` varchar(16) NOT NULL COMMENT '范围类型：exam / user',
  `scope_id` bigint NOT NULL COMMENT '范围 ID：train_exam_list.id 或 platform_user.id',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注（试点说明）',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gray_scope` (`tenant_id`,`scope_type`,`scope_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='AI 同步学灰度白名单（D8）';
CREATE TABLE `ai_review_mock_paper` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `plan_id` bigint NOT NULL COMMENT '计划 id',
  `paper_no` int NOT NULL COMMENT '第几套',
  `question_count` int NOT NULL DEFAULT '0' COMMENT '题量',
  `total_score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '总分',
  `pass_score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '及格分（total×0.6）',
  `time_limit_min` int NOT NULL DEFAULT '60' COMMENT '时长（分钟）',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ready' COMMENT 'ready/done',
  `score` decimal(10,1) DEFAULT NULL COMMENT '得分',
  `correct_count` int DEFAULT NULL COMMENT '答对数',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ai_review_mock_plan` (`plan_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 复习自组模考卷';
CREATE TABLE `ai_review_mock_paper_item` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `paper_id` bigint NOT NULL COMMENT '模考卷 id',
  `question_id` bigint NOT NULL COMMENT 'exam_exam_detail.id',
  `question_type` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '题序（随机，脱离题库顺序）',
  `score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '分值',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_review_mock_item` (`paper_id`,`question_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 复习模考卷题明细';
CREATE TABLE `ai_review_plan` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `platform_user_id` bigint NOT NULL COMMENT '学员（PHP platform_user.id）',
  `exam_id` bigint NOT NULL COMMENT '培训考试计划 train_exam_list.id',
  `work_type_id` bigint DEFAULT NULL COMMENT '工种（题目范围快照）',
  `level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级快照',
  `course_id` bigint DEFAULT NULL COMMENT '科目快照',
  `source` int DEFAULT NULL COMMENT '题库来源快照（train_exam_list.source）',
  `weight_snapshot` json DEFAULT NULL COMMENT '权重快照（§5.7：计划生成时固化，[{knowledgeId,title,rate}]）',
  `weight_source` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '权重来源：standard(type=3)/custom(type=0)/count(题量兜底)',
  `exam_date` date DEFAULT NULL COMMENT '考试日期（最近未来日）',
  `start_date` date NOT NULL COMMENT '复习开始日（计划生成日）',
  `total_days` int NOT NULL COMMENT '总天数',
  `stage1_days` int NOT NULL COMMENT '阶段1天数（50%）',
  `stage2_days` int NOT NULL COMMENT '阶段2天数（30%）',
  `stage3_days` int NOT NULL COMMENT '阶段3天数（20%，尾差归此）',
  `total_questions` int NOT NULL DEFAULT '0' COMMENT '题目全集题数',
  `target_questions` int NOT NULL DEFAULT '0' COMMENT '冗余裁剪后必做题数',
  `must_do_ids` json DEFAULT NULL COMMENT '必做池题 id 列表（排题的输入快照，裁剪/中断删尾部后同步更新）',
  `dropped_question_ids` json DEFAULT NULL COMMENT '被裁剪/中断补救放弃的题 id（扩展题，不进任何每日任务）',
  `trimmed` tinyint NOT NULL DEFAULT '0' COMMENT '是否触发裁剪',
  `daily_new_cap` int NOT NULL DEFAULT '120' COMMENT '每日新题上限快照',
  `daily_total_cap` int NOT NULL DEFAULT '200' COMMENT '每日总量上限快照',
  `current_stage` tinyint NOT NULL DEFAULT '1' COMMENT '当前阶段 1/2/3',
  `current_day_index` int NOT NULL DEFAULT '1' COMMENT '当前第几天（从 1 起）',
  `last_active_date` date DEFAULT NULL COMMENT '最后活跃日（有作答即更新）',
  `interrupt_count` int NOT NULL DEFAULT '0' COMMENT '中断次数（零星中断判定用）',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'active/completed/abandoned',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_review_plan_user_exam` (`platform_user_id`,`exam_id`),
  KEY `idx_ai_review_plan_status` (`status`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 复习计划主表';
CREATE TABLE `ai_review_plan_day` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `plan_id` bigint NOT NULL COMMENT '计划 id',
  `day_index` int NOT NULL COMMENT '第几天',
  `plan_date` date NOT NULL COMMENT '计划日期',
  `stage` tinyint NOT NULL COMMENT '1/2/3',
  `new_question_ids` json DEFAULT NULL COMMENT '今日新题 id 有序列表',
  `review_question_ids` json DEFAULT NULL COMMENT '今日复盘题 id 有序列表（红牌置顶、加星优先）',
  `mock_paper_id` bigint DEFAULT NULL COMMENT '阶段3 模考卷 id',
  `new_target` int NOT NULL DEFAULT '0' COMMENT '新题目标量',
  `review_target` int NOT NULL DEFAULT '0' COMMENT '复盘目标量',
  `new_done` int NOT NULL DEFAULT '0' COMMENT '新题完成数',
  `review_done` int NOT NULL DEFAULT '0' COMMENT '复盘完成数',
  `correct_count` int NOT NULL DEFAULT '0' COMMENT '当日答对数',
  `answer_count` int NOT NULL DEFAULT '0' COMMENT '当日作答数',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/in_progress/done/skipped/abandoned',
  `strategy_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当日策略说明（中断补救文案等，展示给学员）',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_review_day_plan_day` (`plan_id`,`day_index`),
  KEY `idx_ai_review_day_date` (`plan_date`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 复习每日任务';
CREATE TABLE `ai_review_wrong_item` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `plan_id` bigint NOT NULL COMMENT '计划 id',
  `platform_user_id` bigint NOT NULL COMMENT '学员',
  `question_id` bigint NOT NULL COMMENT 'exam_exam_detail.id',
  `knowledge_id` bigint DEFAULT NULL COMMENT '知识点（L3）',
  `card_level` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'red' COMMENT 'red/yellow/green',
  `star` tinyint NOT NULL DEFAULT '0' COMMENT '二次错误加星（顽固盲区）',
  `consecutive_correct` int NOT NULL DEFAULT '0' COMMENT '连续答对计数',
  `last_correct_date` date DEFAULT NULL COMMENT '最近一次答对日期（黄牌间隔>3天判定）',
  `wrong_count` int NOT NULL DEFAULT '0' COMMENT '累计答错',
  `correct_count` int NOT NULL DEFAULT '0' COMMENT '累计答对',
  `first_wrong_time` datetime DEFAULT NULL COMMENT '首次答错时间',
  `last_wrong_time` datetime DEFAULT NULL COMMENT '最近答错时间',
  `removed` tinyint NOT NULL DEFAULT '0' COMMENT '是否已移出（绿牌=1）',
  `remove_time` datetime DEFAULT NULL COMMENT '移出时间',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_review_wrong_plan_q` (`plan_id`,`question_id`),
  KEY `idx_ai_review_wrong_level` (`plan_id`,`card_level`,`removed`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI 复习错题本（三级淘汰）';
CREATE TABLE `analysis_candidate_job` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID，0=全局默认',
  `job_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种名称',
  `job_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业代码，如 6-17-06-02',
  `parent_occupation` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '父职业名',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '手工' COMMENT '大典/机构MD/手工',
  `sort_order` int NOT NULL DEFAULT '100',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED',
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job` (`tenant_id`,`job_name`),
  KEY `idx_job_status` (`tenant_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='rencai-候选工种管理';
CREATE TABLE `analysis_confusable_pair` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID，0=全局默认',
  `pair_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组名，如 电解精炼工 vs 铝电解工',
  `jobs_json` json NOT NULL COMMENT '易混淆工种组',
  `discrimination_text` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '区分说明（注入 prompt 的正文）',
  `examples_json` json DEFAULT NULL COMMENT 'few-shot 示例 [{input,correct,wrong}]',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED',
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_pair_status` (`tenant_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='rencai-易混淆工种护栏';
CREATE TABLE `analysis_file` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_path` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人才识别-文件';
CREATE TABLE `analysis_manual_selection` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_id` bigint NOT NULL,
  `pending_item_id` bigint NOT NULL,
  `selected_job` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ams_task` (`task_id`),
  KEY `fk_ams_pending` (`pending_item_id`),
  CONSTRAINT `fk_ams_pending` FOREIGN KEY (`pending_item_id`) REFERENCES `analysis_pending_item` (`id`),
  CONSTRAINT `fk_ams_task` FOREIGN KEY (`task_id`) REFERENCES `analysis_task` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `analysis_pending_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_id` bigint NOT NULL,
  `row_index` int NOT NULL,
  `person_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `recommended_level` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `eligible_date` datetime DEFAULT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `candidate_jobs_json` json NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_api_task` (`task_id`),
  CONSTRAINT `fk_api_task` FOREIGN KEY (`task_id`) REFERENCES `analysis_task` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `analysis_prompt` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID，0=全局默认',
  `prompt_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'job_resolver_single/job_resolver_batch/company_filter',
  `version` int NOT NULL COMMENT '版本号，单调递增',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提示词全文',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT '同一 (tenant_id,prompt_key) 下最多一条 ENABLED',
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_prompt_version` (`tenant_id`,`prompt_key`,`version`),
  KEY `idx_prompt_active` (`tenant_id`,`prompt_key`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='rencai-LLM提示词版本管理';
CREATE TABLE `analysis_result_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_id` bigint NOT NULL COMMENT '所属分析任务ID，关联analysis_task.id',
  `row_index` int NOT NULL COMMENT '数据行序号（相对于表头的数据行1-based索引）',
  `person_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `person_id_number` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号码',
  `company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在单位',
  `original_job` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原工种（采集表原始值）',
  `actual_job` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际岗位名称（采集表原始值）',
  `major` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所学专业（初中、高中学历的填无）',
  `education_level` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历层次',
  `work_start` date DEFAULT NULL COMMENT '参加工作时间',
  `determined_job` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可认定工种（引擎判定输出）',
  `determined_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '可认定等级（引擎判定输出，如中级工/技师等）',
  `eligible_date` date DEFAULT NULL COMMENT '可认定时间（引擎判定输出，满足年限后可申报的日期）',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '认定状态（推荐/不推荐/待人工选择）',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '认定途径说明（引擎判定输出的路径与依据）',
  `certificate_count` int DEFAULT NULL COMMENT '持有证书数量',
  `context_json` json DEFAULT NULL COMMENT '人员认定上下文快照（证书、职称等结构化信息，供复核使用）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ari_task_job` (`task_id`,`determined_job`),
  KEY `idx_ari_task_level` (`task_id`,`determined_level`),
  CONSTRAINT `fk_ari_task` FOREIGN KEY (`task_id`) REFERENCES `analysis_task` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人才识别-结果明细';
CREATE TABLE `analysis_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID，0=全局默认',
  `rule_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则编号，如 高级-2 / 学徒高级-1 / 管理岗-1',
  `path_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'NORMAL=普通路径 | APPRENTICE=学徒制 | SPECIAL=特殊规则',
  `level_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标等级（特殊规则为空）',
  `rule_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则类型，如 work_years/cert_after/management_position_suppress',
  `params_json` json DEFAULT NULL COMMENT '条件参数：years/base_level/min_education/keywords 等',
  `reason_text` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '理由文案模板',
  `priority` int NOT NULL DEFAULT '100' COMMENT '同等级内择优顺序，小者优先',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `created_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule` (`tenant_id`,`rule_id`),
  KEY `idx_rule_status` (`tenant_id`,`status`,`path_type`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='rencai-认定规则管理';
CREATE TABLE `analysis_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_rows` int NOT NULL DEFAULT '0',
  `recommended_rows` int NOT NULL DEFAULT '0',
  `not_recommended_rows` int NOT NULL DEFAULT '0',
  `pending_manual_rows` int NOT NULL DEFAULT '0',
  `strict_failed_rows` int NOT NULL DEFAULT '0',
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `input_file_id` bigint NOT NULL,
  `output_file_id` bigint DEFAULT NULL,
  `review_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_STARTED',
  `reviewed_at` datetime DEFAULT NULL,
  `finalized_at` datetime DEFAULT NULL,
  `tenant_id` bigint DEFAULT NULL COMMENT 'Java 租户 sys_tenant.id',
  `external_plan_id` bigint DEFAULT NULL COMMENT 'Java train_three_year_plan.id',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `stage` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前进度节点/阶段：VALIDATING/VERIFYING/ANALYZING/GENERATING',
  `stage_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '当前进度节点/阶段文案',
  `auto_chazheng` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否开启自动查证：1=开启（执行查证+证书回填），0=直接分析',
  PRIMARY KEY (`id`),
  KEY `idx_analysis_task_plan` (`external_plan_id`),
  KEY `idx_analysis_task_tenant` (`tenant_id`),
  KEY `fk_analysis_task_input_file` (`input_file_id`),
  KEY `fk_analysis_task_output_file` (`output_file_id`),
  KEY `analysis_task_stage_IDX` (`stage`) USING BTREE,
  CONSTRAINT `fk_analysis_task_input_file` FOREIGN KEY (`input_file_id`) REFERENCES `analysis_file` (`id`),
  CONSTRAINT `fk_analysis_task_output_file` FOREIGN KEY (`output_file_id`) REFERENCES `analysis_file` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='人才识别-分析任务';
CREATE TABLE `biz_approval_record` (
  `id` bigint NOT NULL,
