CREATE TABLE `certification_application_material_batch` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `batch_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '批次号',
  `batch_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'upload/generate',
  `generate_scope` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'single/selected/all',
  `candidate_count` int NOT NULL DEFAULT '0' COMMENT '考生数',
  `success_count` int NOT NULL DEFAULT '0' COMMENT '成功数',
  `failed_count` int NOT NULL DEFAULT '0' COMMENT '失败数',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '状态',
  `package_file_id` bigint DEFAULT NULL COMMENT '文件包id',
  `package_file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件包名称',
  `process_instance_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程实例id',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `approved_at` datetime DEFAULT NULL COMMENT '通过时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_app_material_batch_no` (`tenant_id`,`batch_no`,`deleted`),
  KEY `idx_cert_app_material_batch_task` (`tenant_id`,`task_id`,`batch_type`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='申报材料批次';
CREATE TABLE `certification_application_material_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `batch_id` bigint DEFAULT NULL COMMENT '批次id',
