CREATE TABLE `certification_assessor` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `user_id` bigint DEFAULT NULL COMMENT '平台用户id',
  `account_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平板登录账号快照',
  `account_password` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '平板登录密码快照',
  `assessor_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考评员姓名',
  `identity_no` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `certificate_no` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证号',
  `certificate_photo_file_id` bigint DEFAULT NULL COMMENT '考评员证照片文件ID',
  `certificate_photo_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考评员证照片文件名',
  `work_type_scope` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种范围',
  `work_type_json` json DEFAULT NULL COMMENT '结构化工种范围',
  `level_scope` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级范围',
  `level_json` json DEFAULT NULL COMMENT '结构化等级范围',
  `valid_until` date NOT NULL COMMENT '有效期至',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `masked_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏电话',
  `org_id` bigint DEFAULT NULL COMMENT '所属机构id',
  `org_name` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属机构名称',
  `materials_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料说明',
  `audit_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '审核状态',
  `work_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'idle' COMMENT '在岗状态',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交审核时间',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `reviewed_by` bigint DEFAULT NULL COMMENT '审核人',
  `reviewer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名',
  `reject_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近驳回原因',
  `disabled_at` datetime DEFAULT NULL COMMENT '停用时间',
  `disabled_by` bigint DEFAULT NULL COMMENT '停用人',
  `disable_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '停用原因',
  `referenced_count` int NOT NULL DEFAULT '0' COMMENT '有效引用次数',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'idle' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_assessor_cert` (`tenant_id`,`certificate_no`,`deleted`),
  KEY `idx_cert_assessor_status` (`tenant_id`,`status`,`valid_until`,`deleted`),
  KEY `idx_cert_assessor_user` (`tenant_id`,`user_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评员基础档案';
CREATE TABLE `certification_assessor_group_worktype` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `group_id` bigint NOT NULL COMMENT '考评组id(关联 certification_task_assessor_group.id)',
  `scope_id` bigint NOT NULL COMMENT '任务工种范围id(关联 certification_task_scope.id)',
  `work_type_name` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种名(冗余便于展示)',
  `level_code` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级编码(冗余)',
  `level_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级名称(冗余)',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_group_scope` (`tenant_id`,`group_id`,`scope_id`,`deleted`),
  KEY `idx_group_scope_group` (`tenant_id`,`group_id`,`deleted`),
  KEY `idx_group_scope_scope` (`tenant_id`,`scope_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评组负责工种+等级范围';
CREATE TABLE `certification_assessor_ledger_import` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `source_file_id` bigint NOT NULL COMMENT '上传的台账文件ID',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'queued/processing/completed/failed',
  `total_count` int NOT NULL DEFAULT '0' COMMENT '台账有效行数',
  `imported_count` int NOT NULL DEFAULT '0' COMMENT '新增考评员数',
  `skipped_count` int NOT NULL DEFAULT '0' COMMENT '因姓名或证号已存在而跳过的数量',
  `failed_count` int NOT NULL DEFAULT '0' COMMENT '格式校验失败数量',
  `result_message` varchar(4000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导入摘要与前20条失败说明',
  `operator_id` bigint DEFAULT NULL COMMENT '发起导入的操作人ID',
  `started_at` datetime DEFAULT NULL COMMENT '处理开始时间',
  `completed_at` datetime DEFAULT NULL COMMENT '处理完成时间',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_assessor_ledger_import_status` (`tenant_id`,`status`,`created_at`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评员台账导入批次';
CREATE TABLE `certification_assessor_notification` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint DEFAULT NULL COMMENT '认定任务id',
  `assessor_id` bigint NOT NULL COMMENT '接收考评员id',
  `user_id` bigint DEFAULT NULL COMMENT '接收用户id',
  `message_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info' COMMENT '消息类型',
  `message_content` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `read_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unread' COMMENT '阅读状态',
  `read_at` datetime DEFAULT NULL COMMENT '阅读时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_assessor_noti_user` (`tenant_id`,`assessor_id`,`read_status`,`created_at`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评员消息';
CREATE TABLE `certification_assessor_task` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `group_id` bigint NOT NULL COMMENT '考评组id',
  `task_assessor_id` bigint NOT NULL COMMENT '任务考评员分配id',
  `assessor_id` bigint NOT NULL COMMENT '考评员id',
  `leader_assessor_id` bigint DEFAULT NULL COMMENT '组长考评员id',
  `candidate_id` bigint DEFAULT NULL COMMENT '考生id',
  `paper_id` bigint DEFAULT NULL COMMENT '实操试卷id',
  `paper_question_id` bigint DEFAULT NULL COMMENT '实操试题id',
  `revision_no` int NOT NULL DEFAULT '1' COMMENT '重评修订号',
  `version_no` int NOT NULL DEFAULT '0' COMMENT '乐观锁版本号',
  `candidate_snapshot_json` json DEFAULT NULL COMMENT '考生快照',
  `question_snapshot_json` json DEFAULT NULL COMMENT '题目与评分模板快照',
  `question_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目id',
  `subject` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '科目',
  `title` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '题目标题',
  `assessment_file_id` bigint DEFAULT NULL COMMENT '考评表文件id',
  `assessment_file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考评表文件名',
  `duration_min` int DEFAULT NULL COMMENT '时长',
  `due_date` date DEFAULT NULL COMMENT '截止日期',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'assigned' COMMENT '状态',
  `progress_note` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考评说明',
  `total_score` decimal(8,2) DEFAULT NULL COMMENT '总分',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `returned_at` datetime DEFAULT NULL COMMENT '退回时间',
  `returned_by` bigint DEFAULT NULL COMMENT '退回人',
  `return_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '退回原因',
  `reviewed_at` datetime DEFAULT NULL COMMENT '复核时间',
  `reviewed_by` bigint DEFAULT NULL COMMENT '复核人',
  `review_note` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核意见',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL COMMENT '未删除考生id，用于唯一约束',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_assessor_scoring_task_active` (`tenant_id`,`task_id`,`active_candidate_id`,`paper_question_id`,`assessor_id`),
  KEY `idx_cert_assessor_task_assessor` (`tenant_id`,`assessor_id`,`status`,`deleted`),
  KEY `idx_cert_assessor_task_group` (`tenant_id`,`group_id`,`status`,`deleted`),
  KEY `idx_cert_assessor_task_task` (`tenant_id`,`task_id`,`status`,`deleted`),
  KEY `idx_cert_assessor_scoring_candidate` (`tenant_id`,`task_id`,`candidate_id`,`paper_question_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评员实操任务';
CREATE TABLE `certification_assessor_task_history` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `assessor_task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `paper_question_id` bigint NOT NULL,
  `assessor_id` bigint NOT NULL,
  `revision_no` int NOT NULL,
  `action` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'draft/submit/return',
  `version_no` int NOT NULL,
  `total_score` decimal(8,2) DEFAULT NULL,
  `snapshot_json` json NOT NULL,
  `reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `operated_at` datetime NOT NULL,
  `operated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_assessor_task_history` (`tenant_id`,`assessor_task_id`,`operated_at`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评员评分提交与退回历史';
CREATE TABLE `certification_assessor_task_score` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `assessor_task_id` bigint NOT NULL COMMENT '实操任务id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `step_no` int NOT NULL COMMENT '步骤序号',
  `step_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '步骤名称',
  `criterion` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '评分标准快照',
  `max_score` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '分值上限',
  `max_deduction` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '最大扣分',
  `deduction_step` decimal(8,2) NOT NULL DEFAULT '1.00' COMMENT '扣分步长',
  `deducted_score` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '实际扣分',
  `awarded_score` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '要素得分',
  `score` decimal(8,2) DEFAULT NULL COMMENT '得分',
  `points_json` json DEFAULT NULL COMMENT '评分要点',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_assessor_score_item` (`tenant_id`,`assessor_task_id`,`step_no`,`deleted`),
  KEY `idx_cert_assessor_score_task` (`tenant_id`,`assessor_task_id`,`step_no`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评员任务评分明细';
CREATE TABLE `certification_assessor_workbench_context` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL COMMENT '租户id',
  `leader_assessor_id` bigint NOT NULL COMMENT '组长考评员id',
  `active_task_id` bigint NOT NULL COMMENT '组长当前指定的认定任务id',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_assessor_workbench_context` (`tenant_id`,`leader_assessor_id`,`deleted`),
  KEY `idx_cert_assessor_workbench_active_task` (`tenant_id`,`active_task_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考评平板当前认定任务上下文';
CREATE TABLE `certification_candidate` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `task_scope_id` bigint DEFAULT NULL COMMENT '认定班级（任务工种等级范围）id',
  `candidate_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考生编号',
  `admission_ticket_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'admission ticket number',
  `candidate_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `id_card_no` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `masked_id_card_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏身份证',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `masked_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏电话',
  `level_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报考等级编码',
  `level_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '报考等级名称',
  `work_type_id` bigint DEFAULT NULL COMMENT '工种id',
  `work_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种名称',
  `import_batch_id` bigint DEFAULT NULL COMMENT '导入批次id',
  `import_source` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual' COMMENT '来源',
  `org_name` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属机构',
  `document_completed_count` int NOT NULL DEFAULT '0' COMMENT '已完成资料数',
  `document_required_count` int NOT NULL DEFAULT '2' COMMENT '必需资料数',
  `document_complete` tinyint(1) NOT NULL DEFAULT '0' COMMENT '资料是否完整',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_candidate_id_card` (`tenant_id`,`task_id`,`id_card_no`,`deleted`),
  KEY `idx_cert_candidate_task` (`tenant_id`,`task_id`,`status`,`deleted`),
  KEY `idx_cert_candidate_level` (`tenant_id`,`task_id`,`level_code`,`deleted`),
  KEY `idx_cert_candidate_scope` (`tenant_id`,`task_id`,`task_scope_id`,`deleted`),
  KEY `idx_certification_candidate_admission_ticket` (`tenant_id`,`task_id`,`admission_ticket_no`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定考生';
CREATE TABLE `certification_candidate_document` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `candidate_id` bigint NOT NULL COMMENT '考生id',
  `template_id` bigint DEFAULT NULL COMMENT '模板id',
  `doc_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资料项编码',
  `doc_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资料项名称',
  `required` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否必需',
  `file_id` bigint DEFAULT NULL COMMENT '文件id',
  `file_ref_id` bigint DEFAULT NULL COMMENT '文件引用id',
  `file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `file_type` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件类型',
  `version_no` int NOT NULL DEFAULT '1' COMMENT '版本号',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'missing' COMMENT '资料状态',
  `uploaded_at` datetime DEFAULT NULL COMMENT '上传时间',
  `uploaded_by` bigint DEFAULT NULL COMMENT '上传人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `reviewed_by` bigint DEFAULT NULL COMMENT '审核人',
  `review_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核意见',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_candidate_doc_code` (`tenant_id`,`candidate_id`,`doc_code`,`deleted`),
  KEY `idx_cert_candidate_doc_task` (`tenant_id`,`task_id`,`status`,`deleted`),
  KEY `idx_cert_candidate_doc_candidate` (`tenant_id`,`candidate_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生资料项';
CREATE TABLE `certification_candidate_exam_session` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `exam_session_id` bigint NOT NULL,
  `participation_status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ASSIGNED',
  `collection_status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `collection_source_session_id` bigint DEFAULT NULL,
  `exempt_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL,
  `active_exam_session_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `exam_session_id` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_candidate_exam_session_active` (`tenant_id`,`active_candidate_id`,`active_exam_session_id`),
  KEY `idx_cert_candidate_exam_session_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_cert_candidate_exam_session_session` (`tenant_id`,`exam_session_id`,`participation_status`,`deleted`),
  KEY `idx_cert_candidate_exam_session_candidate` (`tenant_id`,`candidate_id`,`participation_status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='candidate exam session participation';
CREATE TABLE `certification_candidate_import_batch` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `task_scope_id` bigint DEFAULT NULL COMMENT '认定班级（任务工种等级范围）id',
  `batch_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '导入批次号',
  `source_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'trained_student/cert_candidate/excel/manual',
  `source_file_id` bigint DEFAULT NULL COMMENT '来源文件id',
  `total_count` int NOT NULL DEFAULT '0' COMMENT '总数',
  `success_count` int NOT NULL DEFAULT '0' COMMENT '成功数',
  `failed_count` int NOT NULL DEFAULT '0' COMMENT '失败数',
  `duplicate_count` int NOT NULL DEFAULT '0' COMMENT '重复数',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'completed' COMMENT '批次状态',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_candidate_batch_no` (`tenant_id`,`batch_no`,`deleted`),
  KEY `idx_cert_candidate_batch_task` (`tenant_id`,`task_id`,`created_at`,`deleted`),
  KEY `idx_cert_candidate_batch_scope` (`tenant_id`,`task_id`,`task_scope_id`,`created_at`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生导入批次';
CREATE TABLE `certification_candidate_import_error` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `batch_id` bigint NOT NULL COMMENT '导入批次id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `row_no` int DEFAULT NULL COMMENT '行号',
  `candidate_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `id_card_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `error_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '错误编码',
  `error_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '错误原因',
  `raw_json` json DEFAULT NULL COMMENT '原始数据',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_candidate_import_error_batch` (`tenant_id`,`batch_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生导入失败明细';
CREATE TABLE `certification_candidate_source_staging` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint DEFAULT NULL COMMENT '目标认定任务id（导入前可空）',
  `task_scope_id` bigint DEFAULT NULL COMMENT '认定班级（任务工种等级范围）id',
  `candidate_id` bigint DEFAULT NULL COMMENT '已晋升的认定考生id',
  `import_batch_id` bigint DEFAULT NULL COMMENT 'CSV 导入批次id',
  `source_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'test' COMMENT '来源类型: test|excel|training_sign_up|training_people|manual',
  `external_ref_table` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '外部来源表名，如 train_sign_up_people_self',
  `external_ref_id` bigint DEFAULT NULL COMMENT '外部来源主键',
  `sign_up_id` bigint DEFAULT NULL COMMENT '培训报名计划id（未来对接 Excel:sign_up_id）',
  `promote_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft|promoted|failed',
  `promote_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '晋升失败原因',
  `promoted_at` datetime DEFAULT NULL COMMENT '晋升认定考生时间',
  `candidate_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名 | {{candidate_name}} | Excel:name | cert.candidate_name',
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `birth_date` date DEFAULT NULL COMMENT '出生年月',
  `education` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文化程度',
  `graduate_date` date DEFAULT NULL COMMENT '毕业时间',
  `school` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '毕业院校',
  `major` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业',
  `graduation_certificate_no` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '毕业证编号或入学时间',
  `nation` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '民族',
  `political_status` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '政治面貌',
  `id_card_no` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号 | {{id_card_no}} | Excel:id_card_number | cert.id_card_no',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `home_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '个人住址',
  `company_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工作单位',
  `position_name` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在岗位',
  `company_address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位地址',
  `zip_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮编',
  `company_credit_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '统一社会信用代码',
  `industrial_park` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在产业园',
  `work_start_date` date DEFAULT NULL COMMENT '参加工作时间',
  `entry_date` date DEFAULT NULL COMMENT '入职时间',
  `labor_contract_start_date` date DEFAULT NULL COMMENT '劳动合同签订开始时间',
  `labor_contract_end_date` date DEFAULT NULL COMMENT '劳动合同签订结束时间',
  `responsible_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人',
  `responsible_phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人电话',
  `original_work_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原职业工种',
  `original_level_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原技术等级',
  `original_cert_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原证书编号',
  `apply_work_type_id` bigint DEFAULT NULL COMMENT '申报工种id',
  `apply_work_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报职业工种',
  `cert_work_type_id` bigint DEFAULT NULL COMMENT '认定工种id',
  `cert_work_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '认定职业',
  `work_direction` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种方向',
  `work_type_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业代码',
  `apply_level_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报等级编码',
  `apply_level_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报等级',
  `cert_level_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '认定等级',
  `apply_work_years` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报工种工龄',
  `apply_condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报条件',
  `work_resume` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '个人工作简历',
  `theory_score` decimal(10,2) DEFAULT NULL COMMENT '理论成绩',
  `practical_score` decimal(10,2) DEFAULT NULL COMMENT '实操成绩',
  `training_summary` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参加培训情况',
  `photo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证件照',
  `photo_alt_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证件照备用',
  `id_card_front_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证正面',
  `id_card_back_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证反面',
  `original_cert_image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '原工种证书',
  `education_cert_image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历证明',
  `platform_user_id` bigint DEFAULT NULL COMMENT '平台用户id',
  `user_id` bigint DEFAULT NULL COMMENT '用户id',
  `raw_payload` json DEFAULT NULL COMMENT '外部原始行JSON',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_candidate_staging_task` (`tenant_id`,`task_id`,`promote_status`,`deleted`),
  KEY `idx_cert_candidate_staging_source` (`tenant_id`,`source_type`,`external_ref_table`,`external_ref_id`,`deleted`),
  KEY `idx_cert_candidate_staging_id_card` (`tenant_id`,`task_id`,`id_card_no`,`deleted`),
  KEY `idx_cert_candidate_staging_candidate` (`tenant_id`,`candidate_id`,`deleted`),
  KEY `idx_cert_candidate_staging_batch` (`tenant_id`,`import_batch_id`,`deleted`),
  KEY `idx_cert_candidate_staging_scope` (`tenant_id`,`task_id`,`task_scope_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定考生来源暂存（Word映射测试/培训对接缓冲）';
CREATE TABLE `certification_charter_goal` (
