CREATE TABLE `certification_defense_score` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `candidate_id` bigint NOT NULL COMMENT '考生id',
  `report_id` bigint DEFAULT NULL COMMENT '业绩评估报告id',
  `assessor_id` bigint NOT NULL COMMENT '考评员档案id',
  `assessor_user_id` bigint NOT NULL COMMENT '考评员登录用户id',
  `sheet_type` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'THESIS/PERFORMANCE',
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/submitted',
  `payload_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评分表内容JSON',
  `content_subtotal` decimal(10,2) DEFAULT NULL COMMENT '论文内容部分小计(100分制)',
  `defense_subtotal` decimal(10,2) DEFAULT NULL COMMENT '论文答辩部分小计(100分制)',
  `raw_total` decimal(10,2) DEFAULT NULL COMMENT '业绩评估合计(100分制)',
  `final_score` decimal(10,2) DEFAULT NULL COMMENT '最终得分',
  `rejected` int NOT NULL DEFAULT '0' COMMENT '否定项是否成立 0/1',
  `signature_file_id` bigint DEFAULT NULL COMMENT '评审专家电子签名文件id',
  `signature_hash` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签名文件hash',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_defense_score` (`tenant_id`,`task_id`,`candidate_id`,`assessor_id`,`sheet_type`,`deleted`),
  KEY `idx_cert_defense_score_report` (`tenant_id`,`report_id`,`deleted`),
  KEY `idx_cert_defense_score_assessor` (`tenant_id`,`assessor_id`,`task_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='综合答辩评分表';
CREATE TABLE `certification_document_workflow_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT 'tenant id',
  `task_id` bigint NOT NULL COMMENT 'certification task id',
  `document_id` bigint NOT NULL COMMENT 'certification task document id',
  `document_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'document type',
  `process_instance_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Flowable process instance id',
  `task_id_in_engine` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Flowable task id',
  `node_key` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPMN node key',
  `node_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'BPMN node name',
  `action` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'submit, initial_review, final_review, archive',
  `action_result` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'submitted, approved, rejected, archived',
  `comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'operator comment',
  `operator_user_id` bigint DEFAULT NULL COMMENT 'operator user id',
  `operator_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'operator display name',
  `operated_at` datetime NOT NULL COMMENT 'operation time',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_certification_doc_wf_doc` (`tenant_id`,`document_id`,`operated_at`,`deleted`),
  KEY `idx_certification_doc_wf_process` (`tenant_id`,`process_instance_id`,`deleted`),
  KEY `idx_certification_doc_wf_task` (`tenant_id`,`task_id`,`document_type`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='certification document workflow record';
CREATE TABLE `certification_exam_equipment` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `equipment_type` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备类型',
  `asset_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资产编号',
  `equipment_quantity` int NOT NULL DEFAULT '1' COMMENT '设备数量',
  `site_id` bigint DEFAULT NULL COMMENT '所属考场id',
  `site_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属考点名称',
  `equipment_model` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '型号规格',
  `calibration_valid_until` date DEFAULT NULL COMMENT '校准有效期',
  `equipment_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal' COMMENT '设备状态',
  `equipment_photo_file_id` bigint DEFAULT NULL COMMENT 'equipment photo file id',
  `equipment_photo_file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'equipment photo file name',
  `materials_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备资料说明',
  `audit_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '审核状态',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交审核时间',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `reviewed_by` bigint DEFAULT NULL COMMENT '审核人',
  `reviewer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名',
  `reject_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近驳回原因',
  `disabled_at` datetime DEFAULT NULL COMMENT '停用时间',
  `disabled_by` bigint DEFAULT NULL COMMENT '停用人',
  `disable_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '停用原因',
  `referenced_count` int NOT NULL DEFAULT '0' COMMENT '有效引用次数',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_exam_equipment_asset` (`tenant_id`,`asset_no`,`deleted`),
  KEY `idx_cert_exam_equipment_audit` (`tenant_id`,`audit_status`,`deleted`),
  KEY `idx_cert_exam_equipment_status` (`tenant_id`,`equipment_status`,`calibration_valid_until`,`deleted`),
  KEY `idx_cert_exam_equipment_site` (`tenant_id`,`site_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考试设备基础档案';
CREATE TABLE `certification_exam_equipment_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `template_id` bigint DEFAULT NULL COMMENT '模板id',
  `item_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备编码',
  `item_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备名称',
  `exam_site_id` bigint DEFAULT NULL COMMENT '所属考场id',
  `exam_site_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属考场',
