  `exception_description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常说明',
  `exception_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none' COMMENT '异常处理状态',
  `checked_by_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查人',
  `checked_at` datetime DEFAULT NULL COMMENT '检查时间',
  `attachment_file_id` bigint DEFAULT NULL COMMENT '附件id',
