  `expected_quantity` int NOT NULL DEFAULT '1' COMMENT '应备数量',
  `actual_quantity` int NOT NULL DEFAULT '0' COMMENT '实备数量',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `responsible_person` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '责任人',
  `file_id` bigint DEFAULT NULL COMMENT '附件文件id',
  `file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '附件文件名',
  `version_no` int NOT NULL DEFAULT '1' COMMENT '版本号',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'missing' COMMENT '状态',
  `imported_by_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '导入人',
  `imported_at` datetime DEFAULT NULL COMMENT '导入时间',
  `reviewed_by_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '复核时间',
  `review_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核意见',
  `locked` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_exam_material_task_code` (`tenant_id`,`task_id`,`item_code`,`deleted`),
  KEY `idx_cert_exam_material_task` (`tenant_id`,`task_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定前考试材料清单';
CREATE TABLE `certification_exam_session` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1',
  `task_id` bigint NOT NULL,
  `task_scope_id` bigint DEFAULT NULL,
  `exam_type` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'THEORY or PRACTICE',
  `session_name` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `exam_date` date DEFAULT NULL,
  `start_time` datetime DEFAULT NULL,
  `end_time` datetime DEFAULT NULL,
  `exam_site_id` bigint DEFAULT NULL,
  `exam_venue` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考场场地',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `identity_check_required` tinyint NOT NULL DEFAULT '1',
  `fingerprint_required` tinyint NOT NULL DEFAULT '0',
  `signature_required` tinyint NOT NULL DEFAULT '0',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_session_name` varchar(160) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`deleted` = 0) then `session_name` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_exam_session_active_name` (`tenant_id`,`task_id`,`active_session_name`),
  KEY `idx_cert_exam_session_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_cert_exam_session_scope_type` (`tenant_id`,`task_id`,`task_scope_id`,`exam_type`,`deleted`),
  KEY `idx_cert_exam_session_time` (`tenant_id`,`exam_date`,`start_time`,`end_time`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='certification exam session';
CREATE TABLE `certification_exam_site` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `site_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考场名称',
  `site_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'comprehensive' COMMENT '考场类型',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '地址',
  `seat_count` int NOT NULL DEFAULT '0' COMMENT '考位数',
  `filing_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备案号',
  `contact_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `masked_contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏联系电话',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `equipment_condition` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '设备条件',
  `materials_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备案材料说明',
  `audit_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '审核状态',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交审核时间',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `reviewed_by` bigint DEFAULT NULL COMMENT '审核人',
  `reviewer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名',
  `reject_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近驳回原因',
  `disabled_at` datetime DEFAULT NULL COMMENT '停用时间',
  `disabled_by` bigint DEFAULT NULL COMMENT '停用人',
  `disable_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '停用原因',
  `referenced_count` int NOT NULL DEFAULT '0' COMMENT '有效引用次数',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_exam_site_filing` (`tenant_id`,`filing_no`,`deleted`),
  KEY `idx_cert_exam_site_type` (`tenant_id`,`site_type`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考场基础档案';
CREATE TABLE `certification_exam_staff` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `category_id` bigint NOT NULL COMMENT '类别id',
  `category_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类别编码',
  `category_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类别名称',
  `staff_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `id_card_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证件号码',
  `masked_id_card_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏证件号码',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系电话',
  `masked_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏联系电话',
  `org_name` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单位部门',
  `duty` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职责岗位',
  `exam_site_id` bigint DEFAULT NULL COMMENT '负责考场id',
  `exam_site_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责考场',
  `user_id` bigint DEFAULT NULL COMMENT '平台用户id',
  `assessor_id` bigint DEFAULT NULL COMMENT '考评员档案id',
  `task_assessor_id` bigint DEFAULT NULL COMMENT '任务考评员分配id',
  `certificate_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资质证书号',
  `work_type_scope` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种范围',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT '状态',
  `locked` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_exam_staff_task` (`tenant_id`,`task_id`,`category_code`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定前考务人员明细';
CREATE TABLE `certification_exam_staff_category` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `template_id` bigint DEFAULT NULL COMMENT '模板id',
  `category_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类别编码',
  `category_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类别名称',
  `required` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否必需',
  `minimum_count` int NOT NULL DEFAULT '1' COMMENT '最低人数',
  `current_count` int NOT NULL DEFAULT '0' COMMENT '当前有效人数',
  `complete_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '办结状态',
  `completed_by_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '办结人',
  `completed_at` datetime DEFAULT NULL COMMENT '办结时间',
  `review_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '复核状态',
  `reviewed_by_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '复核时间',
  `review_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '复核意见',
  `locked` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_exam_staff_category_code` (`tenant_id`,`task_id`,`category_code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定前考务人员类别';
CREATE TABLE `certification_file_ref` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `document_id` bigint DEFAULT NULL COMMENT '文档id',
  `biz_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '业务类型',
  `file_id` bigint NOT NULL COMMENT '文件id',
  `file_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件名',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_certification_file_task` (`tenant_id`,`task_id`,`biz_type`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目附件引用';
CREATE TABLE `certification_info_audit_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `owner_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'assessor/exam_site/exam_equipment',
  `owner_id` bigint NOT NULL COMMENT '业务对象id',
  `action` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'submit/pass/reject/disable/delete',
  `before_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作前状态',
  `after_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作后状态',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人id',
  `operator_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名',
  `comment` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '意见或原因',
  `snapshot_json` json DEFAULT NULL COMMENT '对象快照',
  `process_instance_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程实例id',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_info_audit_owner` (`tenant_id`,`owner_type`,`owner_id`,`created_at`,`deleted`),
  KEY `idx_cert_info_audit_operator` (`tenant_id`,`operator_id`,`created_at`,`deleted`),
  KEY `idx_cert_info_audit_action` (`tenant_id`,`owner_type`,`action`,`created_at`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='信息管理审核记录';
CREATE TABLE `certification_info_exam_staff` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `user_id` bigint DEFAULT NULL COMMENT 'registered platform user id',
  `staff_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考务人员姓名',
  `account_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'registered platform username',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `masked_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏电话',
  `audit_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '审核状态',
  `work_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'idle' COMMENT '在岗状态',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交审核时间',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `reviewed_at` datetime DEFAULT NULL COMMENT '审核时间',
  `reviewed_by` bigint DEFAULT NULL COMMENT '审核人',
  `reviewer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核人姓名',
  `reject_reason` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近驳回原因',
  `disabled_at` datetime DEFAULT NULL COMMENT '停用时间',
  `disabled_by` bigint DEFAULT NULL COMMENT '停用人',
  `disable_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '停用原因',
  `referenced_count` int NOT NULL DEFAULT '0' COMMENT '有效引用次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_info_exam_staff_audit` (`tenant_id`,`audit_status`,`deleted`),
  KEY `idx_cert_info_exam_staff_work` (`tenant_id`,`work_status`,`deleted`),
  KEY `idx_certification_info_exam_staff_user` (`tenant_id`,`user_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考务人员基础档案';
CREATE TABLE `certification_material_template` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `template_scope` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'candidate_doc/application_material/archive_file',
  `item_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资料项编码',
  `item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资料项名称',
  `item_group` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资料分组',
  `required` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否必需',
  `required_rule` json DEFAULT NULL COMMENT '必需规则',
  `template_file_id` bigint DEFAULT NULL COMMENT '模板文件id',
  `accept_file_types` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '允许文件类型',
  `max_file_size_mb` int NOT NULL DEFAULT '50' COMMENT '最大大小',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_material_template_code` (`tenant_id`,`template_scope`,`item_code`,`deleted`),
  KEY `idx_cert_material_template_scope` (`tenant_id`,`template_scope`,`enabled`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='资料项模板';
CREATE TABLE `certification_practical_candidate_result` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `question_count` int NOT NULL DEFAULT '0',
  `completed_question_count` int NOT NULL DEFAULT '0',
  `total_score` decimal(10,1) DEFAULT NULL COMMENT '所有试题最终分之和，保留1位小数',
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `calculated_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL COMMENT '未删除考生id，用于唯一约束',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_practical_candidate_result_active` (`tenant_id`,`task_id`,`active_candidate_id`),
  KEY `idx_cert_practical_candidate_result_task` (`tenant_id`,`task_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生实操总成绩';
CREATE TABLE `certification_practical_collection_exception` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `exam_session_id` bigint DEFAULT NULL COMMENT 'certification exam session id',
  `candidate_id` bigint NOT NULL,
  `exception_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `exception_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `release_scope` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reason` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `device_sn` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `handled_by` bigint DEFAULT NULL,
  `handled_at` datetime DEFAULT NULL,
  `request_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_practical_collect_exception_task` (`tenant_id`,`task_id`,`exception_status`,`deleted`),
  KEY `idx_cert_practical_collect_exception_candidate` (`tenant_id`,`task_id`,`candidate_id`,`deleted`),
  KEY `idx_cert_practical_collect_exception_type` (`tenant_id`,`task_id`,`exception_type`,`deleted`),
  KEY `idx_cert_practical_collect_exception_exam_session` (`tenant_id`,`exam_session_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='practical collection exception';
CREATE TABLE `certification_practical_collection_queue` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `exam_session_id` bigint DEFAULT NULL COMMENT 'certification exam session id',
  `candidate_id` bigint NOT NULL,
  `status_id` bigint DEFAULT NULL,
  `queue_no` int NOT NULL,
  `queue_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'QUEUED',
  `match_method` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `joined_at` datetime NOT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `removed_at` datetime DEFAULT NULL,
  `operator_id` bigint DEFAULT NULL,
  `remove_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `active_queue_candidate_id` bigint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`queue_status` in (_utf8mb4'QUEUED',_utf8mb4'COLLECTING'))) then `candidate_id` else NULL end)) VIRTUAL,
  `active_queue_no` int GENERATED ALWAYS AS ((case when (`deleted` = 0) then `queue_no` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_practical_collect_queue_candidate` (`tenant_id`,`task_id`,`active_queue_candidate_id`),
  UNIQUE KEY `uk_cert_practical_collect_queue_no` (`tenant_id`,`task_id`,`active_queue_no`),
  KEY `idx_cert_practical_collect_queue_status` (`tenant_id`,`task_id`,`queue_status`,`deleted`),
  KEY `idx_cert_practical_collect_queue_joined` (`tenant_id`,`task_id`,`joined_at`,`deleted`),
  KEY `idx_cert_practical_collect_queue_candidate` (`tenant_id`,`task_id`,`candidate_id`,`deleted`),
  KEY `idx_cert_practical_collect_queue_exam_session` (`tenant_id`,`exam_session_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='practical collection live queue';
CREATE TABLE `certification_practical_collection_status` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `session_id` bigint DEFAULT NULL,
  `exam_session_id` bigint DEFAULT NULL COMMENT 'certification exam session id',
  `collect_token` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `qr_issue_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_ISSUED',
  `overall_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_ARRIVED',
  `queue_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_QUEUED',
  `fingerprint_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_STARTED',
  `signature_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NOT_STARTED',
  `exception_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'NONE',
  `match_method` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `queue_no` int DEFAULT NULL,
  `id_card_last4` varchar(8) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `token_generated_at` datetime DEFAULT NULL,
  `qr_exported_at` datetime DEFAULT NULL,
  `qr_issued_at` datetime DEFAULT NULL,
  `arrived_at` datetime DEFAULT NULL,
  `collecting_started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `last_operator_id` bigint DEFAULT NULL,
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL,
  `active_collect_token` varchar(128) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`deleted` = 0) then `collect_token` else NULL end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_practical_collect_status_candidate` (`tenant_id`,`task_id`,`active_candidate_id`),
  UNIQUE KEY `uk_cert_practical_collect_status_token` (`tenant_id`,`active_collect_token`),
  KEY `idx_cert_practical_collect_status_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_cert_practical_collect_status_overall` (`tenant_id`,`task_id`,`overall_status`,`deleted`),
  KEY `idx_cert_practical_collect_status_queue` (`tenant_id`,`task_id`,`queue_status`,`deleted`),
  KEY `idx_cert_practical_collect_status_last4` (`tenant_id`,`task_id`,`id_card_last4`,`deleted`),
  KEY `idx_cert_practical_collect_status_candidate` (`tenant_id`,`candidate_id`,`deleted`),
  KEY `idx_cert_practical_collect_status_exam_session` (`tenant_id`,`exam_session_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='practical collection status';
