CREATE TABLE `certification_practical_fingerprint_trace` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `session_id` bigint DEFAULT NULL,
  `exam_session_id` bigint DEFAULT NULL COMMENT 'certification exam session id',
  `device_sn` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device_model` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device_vendor_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `device_product_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sdk_device_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `adapter_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MOCK',
  `collect_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quality_score` decimal(6,2) DEFAULT NULL,
  `duration_ms` bigint DEFAULT NULL,
  `error_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exception_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `collected_by` bigint DEFAULT NULL,
  `collected_at` datetime NOT NULL,
  `fingerprint_image_file_id` bigint DEFAULT NULL,
  `fingerprint_image_hash` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fingerprint_image_format` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fingerprint_image_captured_at` datetime DEFAULT NULL,
  `request_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
