  KEY `idx_cert_practical_fingerprint_status` (`tenant_id`,`task_id`,`collect_status`,`deleted`),
  KEY `idx_cert_practical_fingerprint_time` (`tenant_id`,`task_id`,`collected_at`,`deleted`),
  KEY `idx_cert_practical_fingerprint_image_file` (`tenant_id`,`fingerprint_image_file_id`,`deleted`),
  KEY `idx_cert_practical_fingerprint_exam_session` (`tenant_id`,`exam_session_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='practical fingerprint trace';
CREATE TABLE `certification_practical_question_result` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `paper_id` bigint NOT NULL,
  `paper_question_id` bigint NOT NULL,
  `submitted_count` int NOT NULL DEFAULT '0',
  `average_score` decimal(10,4) DEFAULT NULL COMMENT '三人平均原始分',
  `final_score` decimal(10,1) DEFAULT NULL COMMENT '保留1位小数的试题最终分',
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `calculated_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL COMMENT '未删除考生id，用于唯一约束',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_practical_question_result_active` (`tenant_id`,`task_id`,`active_candidate_id`,`paper_question_id`),
  KEY `idx_cert_practical_question_result_candidate` (`tenant_id`,`task_id`,`candidate_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='考生实操试题最终成绩';
CREATE TABLE `certification_practical_scoring_config` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `scope_id` bigint NOT NULL COMMENT '任务工种等级范围id',
  `candidate_id` bigint DEFAULT NULL COMMENT '按学员单独配置的考生id',
  `work_type_id` bigint DEFAULT NULL COMMENT '标准工种id，自定义实操试卷可为空',
  `work_type_name` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工种名称快照',
  `level_code` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '等级编码',
  `level_name` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级名称快照',
  `exam_date` date NOT NULL COMMENT '考试日期',
  `paper_id` bigint NOT NULL COMMENT '当天唯一实操试卷id',
  `group_id` bigint NOT NULL COMMENT '当天唯一三人考评组id',
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'configured',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL COMMENT '未删除考生id，用于唯一约束',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_practical_config_candidate_active` (`tenant_id`,`task_id`,`active_candidate_id`),
  KEY `idx_cert_practical_config_task` (`tenant_id`,`task_id`,`status`,`deleted`),
  KEY `idx_cert_practical_config_scope` (`tenant_id`,`task_id`,`scope_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实操评分任务配置';
CREATE TABLE `certification_practical_signature_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `session_id` bigint DEFAULT NULL,
  `exam_session_id` bigint DEFAULT NULL COMMENT 'certification exam session id',
  `signature_file_id` bigint NOT NULL,
  `signature_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signer_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signer_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signed_at` datetime NOT NULL,
  `device_info` json DEFAULT NULL,
  `record_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_practical_signature_candidate` (`tenant_id`,`task_id`,`candidate_id`,`deleted`),
  KEY `idx_cert_practical_signature_file` (`tenant_id`,`signature_file_id`,`deleted`),
  KEY `idx_cert_practical_signature_time` (`tenant_id`,`task_id`,`signed_at`,`deleted`),
  KEY `idx_cert_practical_signature_exam_session` (`tenant_id`,`exam_session_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='practical signature record';
CREATE TABLE `certification_practical_start_session` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `candidate_id` bigint NOT NULL,
  `config_id` bigint NOT NULL,
  `paper_id` bigint NOT NULL,
  `group_id` bigint NOT NULL,
  `candidate_confirmed_at` datetime DEFAULT NULL,
  `candidate_confirmed_by` bigint DEFAULT NULL,
  `assessor_confirmations_json` json DEFAULT NULL COMMENT '已确认考评员ID及确认时间',
  `status` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'waiting' COMMENT 'waiting/ready/started',
  `version_no` int NOT NULL DEFAULT '0',
  `started_at` datetime DEFAULT NULL,
  `started_by` bigint DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL COMMENT 'Practical exam completed time',
  `completed_by` bigint DEFAULT NULL COMMENT 'Practical exam completed by user id',
  `summary_generated_at` datetime DEFAULT NULL COMMENT 'Practical score summary generated time',
  `summary_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Practical score summary file name',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  `active_candidate_id` bigint GENERATED ALWAYS AS ((case when (`deleted` = 0) then `candidate_id` else NULL end)) VIRTUAL COMMENT '未删除考生id，用于唯一约束',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_practical_start_session_active` (`tenant_id`,`task_id`,`active_candidate_id`),
  KEY `idx_cert_practical_start_status` (`tenant_id`,`task_id`,`status`,`deleted`),
  KEY `idx_cert_practical_start_group_active` (`tenant_id`,`task_id`,`group_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实操考生与三名考评员统一开考会话';
CREATE TABLE `certification_pre_exam_review_record` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `review_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'material/equipment/staff/stage',
  `action` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'pass/reject/cancel/complete',
  `result_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '结果状态',
  `review_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '意见',
  `operator_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人',
  `operated_at` datetime NOT NULL COMMENT '操作时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_cert_pre_exam_review_task` (`tenant_id`,`task_id`,`review_type`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定前复核记录';
CREATE TABLE `certification_pre_exam_summary` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `material_imported_count` int NOT NULL DEFAULT '0' COMMENT '材料已导入数',
  `material_total_count` int NOT NULL DEFAULT '0' COMMENT '材料总数',
  `equipment_confirmed_count` int NOT NULL DEFAULT '0' COMMENT '设备已确认数',
  `equipment_total_count` int NOT NULL DEFAULT '0' COMMENT '设备总数',
  `equipment_unhandled_exception_count` int NOT NULL DEFAULT '0' COMMENT '未处理设备异常数',
  `staff_completed_category_count` int NOT NULL DEFAULT '0' COMMENT '人员已办结类别数',
  `staff_category_total_count` int NOT NULL DEFAULT '0' COMMENT '人员类别总数',
  `staff_total_count` int NOT NULL DEFAULT '0' COMMENT '考务人员总人数',
  `total_completed_count` int NOT NULL DEFAULT '0' COMMENT '总完成项数',
  `total_item_count` int NOT NULL DEFAULT '0' COMMENT '总项数',
  `completion_rate` int NOT NULL DEFAULT '0' COMMENT '完成率',
  `material_review_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '材料复核状态',
  `equipment_review_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '设备复核状态',
  `staff_review_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '人员复核状态',
  `stage_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress' COMMENT '阶段状态',
  `locked` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `completed_by` bigint DEFAULT NULL COMMENT '完成人',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_pre_exam_summary_task` (`tenant_id`,`task_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定前任务摘要';
CREATE TABLE `certification_pre_exam_template` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `item_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'material/equipment/staff',
  `item_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板编码',
  `item_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `required` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否必需',
  `default_quantity` int NOT NULL DEFAULT '1' COMMENT '默认数量',
  `require_file` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否必须上传附件',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_pre_exam_template_code` (`tenant_id`,`item_type`,`item_code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定前清单模板';
CREATE TABLE `certification_risk` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `document_id` bigint DEFAULT NULL COMMENT '风险文档id',
  `risk_no` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险编号',
  `risk_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险描述',
  `probability_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '概率 low/medium/high',
  `impact_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '影响 low/medium/high',
  `risk_level_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险等级',
  `risk_level_score` int NOT NULL COMMENT '风险分值',
  `response_plan` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应对计划',
  `owner_member_id` bigint DEFAULT NULL COMMENT '负责人项目成员',
  `owner_user_id` bigint DEFAULT NULL COMMENT '负责人用户',
  `owner_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人姓名',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open' COMMENT '状态',
  `expected_close_date` date DEFAULT NULL COMMENT '预计关闭日期',
  `closed_at` datetime DEFAULT NULL COMMENT '关闭时间',
  `closed_by` bigint DEFAULT NULL COMMENT '关闭人',
  `close_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关闭说明',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_certification_risk_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_certification_risk_level` (`tenant_id`,`risk_level_score`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目风险';
CREATE TABLE `certification_schedule_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `document_id` bigint DEFAULT NULL COMMENT '进度文档id',
  `day_no` int DEFAULT NULL COMMENT '第几天',
  `plan_date` date DEFAULT NULL COMMENT '计划日期',
  `start_date` date DEFAULT NULL COMMENT '开始日期',
  `end_date` date DEFAULT NULL COMMENT '结束日期',
  `item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事项名称',
  `item_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '事项说明',
  `required` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否必做',
  `completed` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否完成',
  `external_contact_member_id` bigint DEFAULT NULL COMMENT '外部联系人',
  `certification_owner_member_id` bigint DEFAULT NULL COMMENT '认定负责人',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_certification_schedule_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_certification_schedule_date` (`tenant_id`,`start_date`,`end_date`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目进度';
CREATE TABLE `certification_task` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务编号',
  `task_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称',
  `task_manager_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务经理',
  `company_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '企业名称',
  `certification_type` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '认定类型',
  `planned_people_count` int NOT NULL DEFAULT '0' COMMENT '计划人数',
  `plan_start_date` date DEFAULT NULL COMMENT '计划开始日期',
  `plan_end_date` date DEFAULT NULL COMMENT '计划结束日期',
  `exam_date` date DEFAULT NULL COMMENT '考试日期',
  `source_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual' COMMENT '来源类型',
  `source_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '来源名称',
  `current_phase` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'task_creation' COMMENT '任务阶段：task_creation=任务创建阶段，preparation=认定筹备阶段，archive=认定归档阶段，certification_completed=认定完成',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'in_progress' COMMENT '任务状态：in_progress=进行中，pending_review=待审核，rejected=已驳回，completed=已完成',
  `document_completed_count` int NOT NULL DEFAULT '0' COMMENT '已完成文档数',
  `document_total_count` int NOT NULL DEFAULT '5' COMMENT '文档总数',
  `phase_completed_count` int NOT NULL DEFAULT '0' COMMENT '已完成阶段数',
  `phase_total_count` int NOT NULL DEFAULT '4' COMMENT '阶段总数',
  `last_business_updated_at` datetime DEFAULT NULL COMMENT '最后业务更新时间',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_certification_task_no` (`tenant_id`,`task_no`,`deleted`),
  KEY `idx_certification_task_status` (`tenant_id`,`status`,`deleted`),
  KEY `idx_certification_task_updated` (`tenant_id`,`last_business_updated_at`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目任务';
CREATE TABLE `certification_task_assessor` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `group_id` bigint DEFAULT NULL COMMENT '考评组id',
  `assessor_id` bigint NOT NULL COMMENT '考评员id',
  `assessor_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `certificate_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证号',
  `task_role` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'member' COMMENT '角色',
  `role_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色名称',
  `work_type_scope` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种范围',
  `valid_until` date DEFAULT NULL COMMENT '有效期',
  `work_status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'preparing' COMMENT '状态',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_task_assessor` (`tenant_id`,`task_id`,`assessor_id`,`deleted`),
  KEY `idx_cert_task_assessor_group` (`tenant_id`,`group_id`,`task_role`,`deleted`),
  KEY `idx_cert_task_assessor_status` (`tenant_id`,`task_id`,`work_status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务考评员分配';
CREATE TABLE `certification_task_assessor_group` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `group_name` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考评组名称',
  `leader_assessor_id` bigint DEFAULT NULL COMMENT '组长考评员id',
  `work_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责工种',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_assessor_group_name` (`tenant_id`,`task_id`,`group_name`,`deleted`),
  KEY `idx_cert_assessor_group_task` (`tenant_id`,`task_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务考评组';
CREATE TABLE `certification_task_checklist_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '绉熸埛id',
  `task_id` bigint NOT NULL COMMENT '璁ゅ畾浠诲姟id',
  `item_no` int NOT NULL COMMENT '搴忓彿',
  `item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍚嶇О',
  `quantity_text` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '鏁伴噺',
  `checked` tinyint NOT NULL DEFAULT '0' COMMENT '鏄?惁宸叉牳',
  `confirmer_task_staff_id` bigint DEFAULT NULL COMMENT '纭??浜轰换鍔¤?鍔?d',
  `confirmer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纭??浜哄?鍚',
  `confirmed_at` datetime DEFAULT NULL COMMENT '纭??鏃堕棿',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '澶囨敞',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '鎺掑簭',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
