CREATE TABLE `certification_task_document` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `document_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档类型',
  `document_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档名称',
  `version_no` int NOT NULL DEFAULT '1' COMMENT '版本号',
  `is_current` int NOT NULL DEFAULT '1' COMMENT '是否当前版本',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT '文档状态',
  `locked` int NOT NULL DEFAULT '0' COMMENT '是否锁定',
  `content_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '文本内容',
  `content_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '结构化内容',
  `completion_percent` int NOT NULL DEFAULT '0' COMMENT '完成度',
  `required_valid` int NOT NULL DEFAULT '0' COMMENT '必填校验是否通过',
  `submitted_at` datetime DEFAULT NULL COMMENT '提交时间',
  `submitted_by` bigint DEFAULT NULL COMMENT '提交人',
  `approved_at` datetime DEFAULT NULL COMMENT '审批通过时间',
  `approved_by` bigint DEFAULT NULL COMMENT '审批人',
  `rejected_at` datetime DEFAULT NULL COMMENT '驳回时间',
  `rejected_by` bigint DEFAULT NULL COMMENT '驳回人',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `process_instance_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '流程实例id',
  `last_saved_at` datetime DEFAULT NULL COMMENT '最后保存时间',
  `remark` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_certification_document_current` (`tenant_id`,`task_id`,`document_type`,`version_no`,`deleted`),
  KEY `idx_certification_document_task` (`tenant_id`,`task_id`,`document_type`,`is_current`,`deleted`),
  KEY `idx_certification_document_status` (`tenant_id`,`status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目文档';
CREATE TABLE `certification_task_equipment` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `equipment_id` bigint NOT NULL COMMENT '设备档案id',
  `equipment_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备名',
  `equipment_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '设备编号',
  `equipment_quantity` int NOT NULL DEFAULT '1' COMMENT '设备数量',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'configured' COMMENT '配置状态',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_task_equipment` (`tenant_id`,`task_id`,`equipment_id`,`deleted`),
  KEY `idx_cert_task_equipment_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_cert_task_equipment_equipment` (`tenant_id`,`equipment_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定筹备任务设备配置';
CREATE TABLE `certification_task_exam_site` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `site_id` bigint DEFAULT NULL COMMENT '考场id',
  `site_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务侧考场名称',
  `site_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考场类型',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '地址',
  `seat_count` int NOT NULL DEFAULT '0' COMMENT '考位数',
  `filing_no` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备案号',
  `exam_date` date DEFAULT NULL COMMENT '考试日期',
  `start_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开始时间',
  `end_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结束时间',
  `exam_type` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'theory' COMMENT '考试类型',
  `arranged_count` int NOT NULL DEFAULT '0' COMMENT '安排人数',
  `contact_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'configured' COMMENT '配置状态',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_task_exam_site` (`tenant_id`,`task_id`,`site_id`,`deleted`),
  KEY `idx_cert_task_exam_site_type` (`tenant_id`,`task_id`,`site_type`,`deleted`),
  KEY `idx_cert_task_exam_site_time` (`tenant_id`,`task_id`,`site_id`,`exam_date`,`start_time`,`end_time`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务考场配置';
CREATE TABLE `certification_task_exam_staff` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '认定任务id',
  `staff_id` bigint DEFAULT NULL COMMENT '考务人员档案id',
  `staff_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考务人员姓名',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `masked_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏电话',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'configured' COMMENT '配置状态',
  `task_role` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'exam_staff' COMMENT '任务角色',
  `role_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色名称',
  `is_leader` int NOT NULL DEFAULT '0' COMMENT '是否组长 0-否 1-是',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cert_task_exam_staff` (`tenant_id`,`task_id`,`staff_id`,`deleted`),
  KEY `idx_cert_task_exam_staff_task` (`tenant_id`,`task_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='任务考务配置';
CREATE TABLE `certification_task_member` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `document_id` bigint DEFAULT NULL COMMENT '成员文档id',
  `user_id` bigint DEFAULT NULL COMMENT 'registered platform user id',
  `member_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '成员姓名',
  `role_code` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色编码',
  `role_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '角色名称',
  `department_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门',
  `responsibility` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职责',
  `start_date` date DEFAULT NULL COMMENT '投入开始日期',
  `end_date` date DEFAULT NULL COMMENT '投入结束日期',
  `input_frequency` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '投入频率',
  `workload_percent` decimal(8,2) DEFAULT NULL COMMENT '投入比例',
  `phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `masked_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '脱敏手机号',
  `core_role` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否核心角色',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_certification_member_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_certification_member_role` (`tenant_id`,`role_code`,`deleted`),
  KEY `idx_certification_member_user` (`tenant_id`,`user_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目成员';
CREATE TABLE `certification_task_phase` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `phase_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阶段编码',
  `phase_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '阶段名称',
  `phase_order` int NOT NULL COMMENT '阶段顺序',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '阶段状态',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `completed_by` bigint DEFAULT NULL COMMENT '完成人',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_certification_phase_task_code` (`tenant_id`,`task_id`,`phase_code`,`deleted`),
  KEY `idx_certification_phase_task` (`tenant_id`,`task_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目阶段';
CREATE TABLE `certification_task_scope` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `certification_type` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '认定类型',
  `work_type_id` bigint DEFAULT NULL COMMENT '标准工种id',
  `work_type_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种',
  `level_code` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级编码',
  `level_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级名称',
  `planned_people_count` int DEFAULT NULL COMMENT '计划人数',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_certification_scope_task` (`tenant_id`,`task_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定任务工种等级范围';
CREATE TABLE `certification_wbs_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `task_id` bigint NOT NULL COMMENT '任务id',
  `document_id` bigint DEFAULT NULL COMMENT 'WBS文档id',
  `parent_id` bigint DEFAULT NULL COMMENT '父级WBS',
  `wbs_code` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'WBS编码',
  `category_code` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类编码',
  `category_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类名称',
  `item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事项名称',
  `activity_description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '活动描述',
  `estimate_hours` decimal(12,2) DEFAULT NULL COMMENT '估算工时',
  `manpower_count` decimal(12,2) DEFAULT NULL COMMENT '人力数量',
  `manpower_role_code` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '人力角色',
  `responsible_member_id` bigint DEFAULT NULL COMMENT '负责成员',
  `resource_input` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '资源投入',
  `cost_amount` decimal(14,2) DEFAULT NULL COMMENT '费用',
  `duration_days` int DEFAULT NULL COMMENT '工期天数',
  `predecessor_id` bigint DEFAULT NULL COMMENT '前置事项',
  `leaf` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否叶子节点',
  `progress_percent` int NOT NULL DEFAULT '0' COMMENT '进度百分比',
  `status` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '状态',
  `sort_order` int NOT NULL DEFAULT '100' COMMENT '排序',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_certification_wbs_code` (`tenant_id`,`task_id`,`wbs_code`,`deleted`),
  KEY `idx_certification_wbs_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_certification_wbs_member` (`tenant_id`,`responsible_member_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认定项目WBS';
CREATE TABLE `chazheng_cert` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL COMMENT '用户ID',
  `cert_no` varchar(100) DEFAULT NULL COMMENT '证书编号',
  `cert_name` varchar(255) DEFAULT NULL COMMENT '证书名称',
  `cert_date` varchar(20) DEFAULT NULL COMMENT '发证日期',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chazheng_cert_user_cert_no` (`user_id`,`cert_no`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=521 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='查证证书';
CREATE TABLE `chazheng_cert_batch` (
  `id` bigint NOT NULL COMMENT '批次 ID（雪花 ID）',
  `tenant_id` bigint NOT NULL COMMENT '租户 ID',
  `total_count` int NOT NULL DEFAULT '0' COMMENT '总用户数',
  `completed_count` int NOT NULL DEFAULT '0' COMMENT '已完成数(原子 UPDATE 递增)',
  `status` varchar(32) NOT NULL DEFAULT 'processing' COMMENT 'processing / completed / failed',
  `source_filename` varchar(255) DEFAULT NULL COMMENT '导入的原始文件名(Excel),手动触发的批次为 NULL',
  `trigger_by` bigint DEFAULT NULL COMMENT '触发人用户 ID',
  `triggered_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completed_at` datetime DEFAULT NULL,
  `error_message` text,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_chazheng_cert_batch_tenant` (`tenant_id`,`deleted`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='查证批次';
CREATE TABLE `chazheng_cert_batch_item` (
  `id` bigint NOT NULL COMMENT '明细 ID（雪花 ID）',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户 ID',
  `batch_id` bigint NOT NULL COMMENT '批次 ID',
  `user_id` bigint NOT NULL COMMENT '用户 ID',
  `user_name` varchar(64) DEFAULT NULL COMMENT '用户姓名（冗余，便于排查）',
  `status` varchar(32) NOT NULL DEFAULT 'pending' COMMENT 'pending / processing / success / success_no_cert / failed',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '已重试次数',
  `error_message` varchar(500) DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`),
  KEY `idx_batch_item_batch` (`batch_id`,`status`),
  KEY `idx_batch_item_user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='查证明细';
CREATE TABLE `chazheng_user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `enterprise_id` int DEFAULT NULL COMMENT '企业ID',
  `user_name` varchar(10) DEFAULT NULL COMMENT '姓名',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `gender` int DEFAULT NULL COMMENT '0男 1女',
  `datas` json DEFAULT NULL COMMENT '花名册 JSON',
  `is_cert` int DEFAULT '0' COMMENT '是否有证书 0/1',
  `is_checked` int DEFAULT '0' COMMENT '是否已查证 0/1',
  `ymd` varchar(20) DEFAULT NULL COMMENT '批次时间戳',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除 0否 1是',
  PRIMARY KEY (`id`),
  KEY `idx_ymd` (`ymd`),
  KEY `idx_id_card` (`id_card`),
  KEY `idx_tenant_id` (`tenant_id`),
  KEY `chazheng_user_id_card_IDX` (`id_card`,`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=838 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='查证用户';
CREATE TABLE `competition_contestant_profile` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `member_id` bigint NOT NULL,
  `registration_id` bigint DEFAULT NULL COMMENT '关联历史参赛资格 competition_registration.id',
  `contestant_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `group_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `current_stage_id` bigint DEFAULT NULL,
  `event_work_type_id` bigint DEFAULT NULL COMMENT '已人工确认的赛事工种',
  `work_type_match_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unmatched' COMMENT '名单工种对账状态',
  `work_type_match_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '对账或人工确认说明',
  `promotion_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `total_score` decimal(12,2) NOT NULL DEFAULT '0.00',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_contestant_profile_member` (`tenant_id`,`member_id`,`deleted`),
  UNIQUE KEY `uk_competition_contestant_profile_registration` (`tenant_id`,`registration_id`,`deleted`),
  UNIQUE KEY `uk_competition_contestant_profile_no` (`tenant_id`,`contestant_no`,`deleted`),
  KEY `idx_competition_contestant_profile_stage` (`tenant_id`,`current_stage_id`,`promotion_status`,`deleted`),
  KEY `idx_competition_contestant_event_work_type` (`tenant_id`,`event_work_type_id`,`work_type_match_status`,`deleted`),
  KEY `idx_competition_contestant_profile_level` (`tenant_id`,`event_work_type_id`,`event_work_type_level_id`,`work_type_match_status`,`deleted`),
  CONSTRAINT `chk_competition_contestant_profile_promotion` CHECK ((`promotion_status` in (_utf8mb4'pending',_utf8mb4'promoted',_utf8mb4'eliminated'))),
  CONSTRAINT `chk_competition_contestant_profile_total_score` CHECK ((`total_score` >= 0)),
  CONSTRAINT `chk_competition_contestant_work_type_match_status` CHECK ((`work_type_match_status` in (_utf8mb4'matched',_utf8mb4'unmatched',_utf8mb4'conflict')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛选手角色扩展';
CREATE TABLE `competition_event` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `player_entry_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '选手端安全入口码',
  `scope` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `owner_org_id` bigint DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `stage_plan_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `stage_plan_confirmed_by` bigint DEFAULT NULL,
  `stage_plan_confirmed_at` datetime DEFAULT NULL,
  `registration_audit_required` tinyint NOT NULL DEFAULT '0',
  `start_at` datetime DEFAULT NULL,
  `end_at` datetime DEFAULT NULL,
  `description` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_event_code` (`tenant_id`,`code`,`deleted`),
  UNIQUE KEY `uk_competition_event_player_entry_code` (`player_entry_code`),
  KEY `idx_competition_event_scope_status` (`tenant_id`,`scope`,`status`,`deleted`),
  KEY `idx_competition_event_owner_status` (`tenant_id`,`owner_org_id`,`status`,`deleted`),
  CONSTRAINT `chk_competition_event_owner` CHECK (((`scope` <> _utf8mb4'enterprise_internal') or (`owner_org_id` is not null))),
  CONSTRAINT `chk_competition_event_scope` CHECK ((`scope` in (_utf8mb4'platform',_utf8mb4'enterprise_internal'))),
  CONSTRAINT `chk_competition_event_stage_plan_status` CHECK ((`stage_plan_status` in (_utf8mb4'draft',_utf8mb4'confirmed'))),
  CONSTRAINT `chk_competition_event_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published',_utf8mb4'closed',_utf8mb4'archived')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛赛事基础信息';
CREATE TABLE `competition_event_member` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `person_id` bigint NOT NULL COMMENT '关联 competition_player_identity.id',
  `role_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `joined_at` datetime NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_event_member_role` (`tenant_id`,`event_id`,`person_id`,`role_type`,`deleted`),
  KEY `idx_competition_event_member_event_role` (`tenant_id`,`event_id`,`role_type`,`status`,`deleted`),
  KEY `idx_competition_event_member_person` (`tenant_id`,`person_id`,`status`,`deleted`),
  CONSTRAINT `chk_competition_event_member_role` CHECK ((`role_type` in (_utf8mb4'contestant',_utf8mb4'expert',_utf8mb4'referee',_utf8mb4'event_admin',_utf8mb4'staff'))),
  CONSTRAINT `chk_competition_event_member_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'suspended',_utf8mb4'withdrawn')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛人员与赛事角色关系';
CREATE TABLE `competition_event_org` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `quota` int DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'invited',
  `import_permission` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_event_org` (`tenant_id`,`event_id`,`org_id`,`deleted`),
  KEY `idx_competition_event_org_org_status` (`tenant_id`,`org_id`,`status`,`deleted`),
  CONSTRAINT `chk_competition_event_org_quota` CHECK (((`quota` is null) or (`quota` >= 0))),
  CONSTRAINT `chk_competition_event_org_status` CHECK ((`status` in (_utf8mb4'invited',_utf8mb4'active',_utf8mb4'suspended',_utf8mb4'closed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛参与企业关系';
CREATE TABLE `competition_event_role_conflict_rule` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `role_type_a` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role_type_b` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `resolution` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_event_role_conflict_rule` (`tenant_id`,`event_id`,`role_type_a`,`role_type_b`,`deleted`),
  CONSTRAINT `chk_competition_event_role_conflict_resolution` CHECK ((`resolution` in (_utf8mb4'forbidden',_utf8mb4'recusal_required',_utf8mb4'allowed'))),
  CONSTRAINT `chk_competition_event_role_conflict_roles` CHECK (((`role_type_a` in (_utf8mb4'contestant',_utf8mb4'expert',_utf8mb4'referee',_utf8mb4'event_admin',_utf8mb4'staff')) and (`role_type_b` in (_utf8mb4'contestant',_utf8mb4'expert',_utf8mb4'referee',_utf8mb4'event_admin',_utf8mb4'staff')) and (`role_type_a` < `role_type_b`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='赛事角色冲突与回避规则';
CREATE TABLE `competition_event_work_type` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `work_type_id` bigint NOT NULL COMMENT '关联当前租户 exam_work_type.id',
  `display_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛事内工种显示快照',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `sort_order` int NOT NULL DEFAULT '0',
  `stage_plan_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `stage_plan_confirmed_by` bigint DEFAULT NULL,
  `stage_plan_confirmed_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_event_work_type` (`tenant_id`,`event_id`,`work_type_id`,`deleted`),
  KEY `idx_competition_event_work_type_event_status` (`tenant_id`,`event_id`,`status`,`sort_order`,`deleted`),
  KEY `idx_competition_event_work_type_source` (`tenant_id`,`work_type_id`,`deleted`),
  CONSTRAINT `chk_competition_event_work_type_sort_order` CHECK ((`sort_order` >= 0)),
  CONSTRAINT `chk_competition_event_work_type_stage_plan_status` CHECK ((`stage_plan_status` in (_utf8mb4'draft',_utf8mb4'confirmed'))),
  CONSTRAINT `chk_competition_event_work_type_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'inactive')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='赛事启用的规范化题库工种';
CREATE TABLE `competition_event_work_type_level` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `level_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL,
  `level_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_level_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_level_text` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reconciliation_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'matched',
  `confirmed_at` datetime DEFAULT NULL,
  `confirmed_by` bigint DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_event_work_type_level` (`tenant_id`,`event_work_type_id`,`level_code`,`deleted`),
  KEY `idx_competition_event_work_type_level_event` (`tenant_id`,`event_id`,`event_work_type_id`,`reconciliation_status`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_event_work_type_stage` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `enabled` tinyint NOT NULL DEFAULT '1',
  `sort_order` int DEFAULT NULL,
  `promotion_rule_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `promotion_percentage` int DEFAULT NULL,
  `legacy_rule` tinyint NOT NULL DEFAULT '1',
  `promotion_quota` int DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_event_work_type_stage` (`tenant_id`,`event_work_type_id`,`stage_id`,`deleted`),
  KEY `idx_comp_event_work_type_stage_scope` (`tenant_id`,`event_id`,`event_work_type_id`,`enabled`,`sort_order`,`deleted`),
  CONSTRAINT `chk_comp_event_work_type_stage_enabled` CHECK ((`enabled` in (0,1))),
  CONSTRAINT `chk_comp_event_work_type_stage_legacy` CHECK ((`legacy_rule` in (0,1))),
  CONSTRAINT `chk_comp_event_work_type_stage_percentage` CHECK (((`promotion_percentage` is null) or (`promotion_percentage` between 1 and 100))),
  CONSTRAINT `chk_comp_event_work_type_stage_quota` CHECK (((`promotion_quota` is null) or (`promotion_quota` >= 0))),
  CONSTRAINT `chk_comp_event_work_type_stage_rule_type` CHECK (((`promotion_rule_type` is null) or (`promotion_rule_type` in (_utf8mb4'FIXED_COUNT',_utf8mb4'PERCENTAGE',_utf8mb4'FINAL_PODIUM',_utf8mb4'LEGACY'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_expert_profile` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `member_id` bigint NOT NULL,
  `professional_field` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expert_level` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `certificate_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `review_group_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_expert_profile_member` (`tenant_id`,`member_id`,`deleted`),
  KEY `idx_competition_expert_profile_group` (`tenant_id`,`review_group_code`,`deleted`)
