  KEY `idx_competition_notice_content_type` (`tenant_id`,`event_id`,`content_type`,`status`,`deleted`),
  CONSTRAINT `chk_competition_notice_content_type` CHECK ((`content_type` in (_utf8mb4'markdown',_utf8mb4'pdf'))),
  CONSTRAINT `chk_competition_notice_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published'))),
  CONSTRAINT `chk_competition_notice_version` CHECK ((`version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛站内通知';
CREATE TABLE `competition_notice_asset` (
