  KEY `idx_competition_outbox_aggregate` (`tenant_id`,`aggregate_type`,`aggregate_id`,`event_type`,`deleted`),
  CONSTRAINT `chk_competition_outbox_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'publishing',_utf8mb4'published',_utf8mb4'retry',_utf8mb4'failed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='竞赛领域事件可靠投递 Outbox';
CREATE TABLE `competition_player_identity` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `id_card_ciphertext` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_card_lookup_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mobile_ciphertext` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `mobile_lookup_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `crypto_key_version` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending_activation',
  `activated_at` datetime DEFAULT NULL,
  `disabled_at` datetime DEFAULT NULL,
  `disabled_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '选手登录密码哈希',
  `password_initialized_at` datetime DEFAULT NULL COMMENT '初始密码生成时间',
  `active_mobile_lookup_hash` char(64) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`deleted` = 0) then `mobile_lookup_hash` else NULL end)) STORED,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_player_identity_id_card` (`tenant_id`,`id_card_lookup_hash`,`deleted`),
  UNIQUE KEY `uk_competition_player_identity_mobile` (`tenant_id`,`mobile_lookup_hash`,`deleted`),
  UNIQUE KEY `uk_competition_player_identity_active_mobile_global` (`active_mobile_lookup_hash`),
  KEY `idx_competition_player_identity_status` (`tenant_id`,`status`,`deleted`),
  CONSTRAINT `chk_competition_player_identity_status` CHECK ((`status` in (_utf8mb4'pending_activation',_utf8mb4'active',_utf8mb4'disabled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛全局自然人安全身份（敏感字段加密存储，兼容原选手身份表名）';
CREATE TABLE `competition_player_message` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `player_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `notice_id` bigint DEFAULT NULL,
  `schedule_version_id` bigint DEFAULT NULL,
  `type` varchar(64) NOT NULL,
  `title` varchar(256) DEFAULT NULL,
  `content` text,
  `published_at` datetime DEFAULT NULL,
  `received_at` datetime NOT NULL,
  `read_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_player_message_notice` (`tenant_id`,`notice_id`,`player_id`,`deleted`),
  UNIQUE KEY `uk_comp_player_message_schedule` (`tenant_id`,`schedule_version_id`,`player_id`,`type`,`deleted`),
  KEY `idx_competition_player_message_inbox` (`tenant_id`,`player_id`,`read_at`,`received_at`,`deleted`),
  KEY `idx_competition_player_message_event` (`tenant_id`,`event_id`,`received_at`,`deleted`),
  CONSTRAINT `chk_competition_player_message_reference` CHECK ((((`type` = _utf8mb4'notice_published') and (`notice_id` is not null) and (`schedule_version_id` is null)) or ((`type` in (_utf8mb4'theory_schedule_published',_utf8mb4'theory_schedule_withdrawn')) and (`notice_id` is null) and (`schedule_version_id` is not null) and (`title` is not null) and (`content` is not null) and (`published_at` is not null)))),
  CONSTRAINT `chk_competition_player_message_type` CHECK ((`type` in (_utf8mb4'notice_published',_utf8mb4'theory_schedule_published',_utf8mb4'theory_schedule_withdrawn')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='竞赛选手站内消息收件箱';
CREATE TABLE `competition_player_sms_challenge` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `player_id` bigint NOT NULL,
  `purpose` varchar(32) NOT NULL,
  `mobile_lookup_hash` char(64) NOT NULL,
  `code_hash` char(64) NOT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'pending',
  `failed_attempts` int NOT NULL DEFAULT '0',
  `locked_until` datetime DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `sent_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `delivery_status` varchar(32) NOT NULL DEFAULT 'pending',
  `provider_message_id` varchar(128) DEFAULT NULL,
  `request_ip_hash` char(64) DEFAULT NULL,
  `request_device_hash` char(64) DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_competition_player_sms_player` (`tenant_id`,`player_id`,`purpose`,`status`,`deleted`),
  KEY `idx_competition_player_sms_mobile_sent` (`tenant_id`,`mobile_lookup_hash`,`purpose`,`sent_at`,`deleted`),
  KEY `idx_competition_player_sms_locked` (`tenant_id`,`player_id`,`purpose`,`locked_until`,`deleted`),
  CONSTRAINT `chk_competition_player_sms_delivery` CHECK ((`delivery_status` in (_utf8mb4'pending',_utf8mb4'accepted',_utf8mb4'failed'))),
  CONSTRAINT `chk_competition_player_sms_purpose` CHECK ((`purpose` in (_utf8mb4'activation',_utf8mb4'login',_utf8mb4'change_mobile_old',_utf8mb4'change_mobile_new'))),
  CONSTRAINT `chk_competition_player_sms_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'verified',_utf8mb4'expired',_utf8mb4'locked',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='竞赛选手短信验证码挑战与审计记录';
CREATE TABLE `competition_practical_assignment` (
  `id` bigint NOT NULL,
