  KEY `idx_comp_practical_assignment_contestant` (`tenant_id`,`plan_id`,`contestant_member_id`,`session_id`,`status`,`deleted`),
  KEY `idx_comp_practical_assignment_group` (`tenant_id`,`judge_group_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_practical_assignment_status` CHECK ((`status` in (_utf8mb4'assigned',_utf8mb4'in_progress',_utf8mb4'completed',_utf8mb4'withdrawn')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_judge_group` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `session_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL,
  `group_no` int NOT NULL,
  `group_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `official_count` int NOT NULL DEFAULT '3',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_judge_group_no` (`tenant_id`,`session_id`,`group_no`,`deleted`),
  KEY `idx_comp_practical_judge_group_plan` (`tenant_id`,`plan_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_practical_judge_group_no` CHECK ((`group_no` > 0)),
  CONSTRAINT `chk_comp_practical_judge_group_official_count` CHECK ((`official_count` = 3)),
  CONSTRAINT `chk_comp_practical_judge_group_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published',_utf8mb4'closed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_judge_member` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `judge_group_id` bigint NOT NULL,
  `session_id` bigint NOT NULL,
  `referee_member_id` bigint NOT NULL,
  `member_role` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_judge_member` (`tenant_id`,`judge_group_id`,`referee_member_id`,`deleted`),
  KEY `idx_comp_practical_judge_member_session` (`tenant_id`,`session_id`,`member_role`,`status`,`deleted`),
  CONSTRAINT `chk_comp_practical_judge_member_role` CHECK ((`member_role` in (_utf8mb4'official',_utf8mb4'standby'))),
  CONSTRAINT `chk_comp_practical_judge_member_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'replaced',_utf8mb4'withdrawn')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_rule` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `event_work_type_level_id` bigint DEFAULT NULL,
  `rule_version` int NOT NULL,
  `rule_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `total_score` decimal(12,2) NOT NULL DEFAULT '100.00',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `published_at` datetime DEFAULT NULL,
  `published_by` bigint DEFAULT NULL,
  `active_current_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`status` = _utf8mb4'published')) then 1 else NULL end)) STORED,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_rule_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`rule_version`,`deleted`),
  UNIQUE KEY `uk_comp_practical_rule_current` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`active_current_key`),
  KEY `idx_comp_practical_rule_scope` (`tenant_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_practical_rule_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published',_utf8mb4'withdrawn'))),
  CONSTRAINT `chk_comp_practical_rule_total` CHECK (((`total_score` > 0) and (`total_score` <= 100))),
  CONSTRAINT `chk_comp_practical_rule_version` CHECK ((`rule_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_rule_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `rule_id` bigint NOT NULL,
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL,
  `max_score` decimal(12,2) NOT NULL,
  `deduction_allowed` tinyint NOT NULL DEFAULT '1',
  `criteria_payload` json DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_rule_item_code` (`tenant_id`,`rule_id`,`item_code`,`deleted`),
  UNIQUE KEY `uk_comp_practical_rule_item_order` (`tenant_id`,`rule_id`,`sort_order`,`deleted`),
  KEY `idx_comp_practical_rule_item_rule` (`tenant_id`,`rule_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_practical_rule_item_deduction` CHECK ((`deduction_allowed` in (0,1))),
  CONSTRAINT `chk_comp_practical_rule_item_order` CHECK ((`sort_order` > 0)),
  CONSTRAINT `chk_comp_practical_rule_item_score` CHECK ((`max_score` > 0)),
  CONSTRAINT `chk_comp_practical_rule_item_status` CHECK ((`status` in (_utf8mb4'enabled',_utf8mb4'disabled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_score` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `contestant_member_id` bigint NOT NULL,
  `referee_member_id` bigint NOT NULL,
  `referee_assignment_id` bigint NOT NULL,
  `criteria_version_reference` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '已锁定评分细则版本引用',
  `revision_no` int NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'assigned',
  `total_score` decimal(12,6) DEFAULT NULL,
  `current_flag` tinyint NOT NULL DEFAULT '1' COMMENT '1当前版本，0历史版本',
  `active_current_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`current_flag` = 1)) then 1 else NULL end)) STORED,
  `source_system` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'competition' COMMENT '为后续认定评分适配保留来源边界',
  `source_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `replaced_score_id` bigint DEFAULT NULL COMMENT '备用裁判评分指向被替换评分',
  `replacement_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `locked_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_score_revision` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`referee_member_id`,`criteria_version_reference`,`revision_no`,`deleted`),
  UNIQUE KEY `uk_comp_practical_score_current` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`referee_member_id`,`criteria_version_reference`,`active_current_key`),
  KEY `idx_comp_practical_score_average` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`status`,`current_flag`,`deleted`),
  KEY `idx_comp_practical_score_assignment` (`tenant_id`,`referee_assignment_id`,`deleted`),
  KEY `idx_comp_practical_score_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`contestant_member_id`,`deleted`),
  CONSTRAINT `chk_comp_practical_score_current` CHECK ((`current_flag` in (0,1))),
  CONSTRAINT `chk_comp_practical_score_locked` CHECK (((`status` <> _utf8mb4'submitted_locked') or ((`total_score` is not null) and (`submitted_at` is not null) and (`locked_at` is not null)))),
  CONSTRAINT `chk_comp_practical_score_replacement` CHECK (((`replaced_score_id` is null) or (`replacement_reason` is not null))),
  CONSTRAINT `chk_comp_practical_score_revision` CHECK ((`revision_no` > 0)),
  CONSTRAINT `chk_comp_practical_score_status` CHECK ((`status` in (_utf8mb4'assigned',_utf8mb4'draft',_utf8mb4'submitted_locked',_utf8mb4'unlocked_for_rescore',_utf8mb4'recused',_utf8mb4'voided'))),
  CONSTRAINT `chk_comp_practical_score_value` CHECK (((`total_score` is null) or ((`total_score` >= 0) and (`total_score` <= 100))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛实操裁判评分修订';
CREATE TABLE `competition_practical_score_entry` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `score_sheet_id` bigint NOT NULL,
  `rule_item_id` bigint NOT NULL,
  `score` decimal(12,2) NOT NULL DEFAULT '0.00',
  `deduction` decimal(12,2) NOT NULL DEFAULT '0.00',
  `remark` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_score_entry_item` (`tenant_id`,`score_sheet_id`,`rule_item_id`,`deleted`),
  KEY `idx_comp_practical_score_entry_sheet` (`tenant_id`,`score_sheet_id`,`deleted`),
  CONSTRAINT `chk_comp_practical_score_entry_deduction` CHECK ((`deduction` >= 0)),
  CONSTRAINT `chk_comp_practical_score_entry_score` CHECK ((`score` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_score_sheet` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `assignment_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL,
  `rule_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `event_work_type_level_id` bigint DEFAULT NULL,
  `contestant_member_id` bigint NOT NULL,
  `referee_member_id` bigint NOT NULL,
  `revision_no` int NOT NULL DEFAULT '1',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `total_score` decimal(12,2) DEFAULT NULL,
  `unlock_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `opened_at` datetime NOT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `locked_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_score_sheet_revision` (`tenant_id`,`assignment_id`,`revision_no`,`deleted`),
  UNIQUE KEY `uk_comp_practical_score_sheet_current` (`tenant_id`,`assignment_id`,`status`,`deleted`),
  KEY `idx_comp_practical_score_sheet_scope` (`tenant_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`contestant_member_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_practical_score_sheet_locked` CHECK (((`status` <> _utf8mb4'submitted_locked') or ((`total_score` is not null) and (`submitted_at` is not null) and (`locked_at` is not null)))),
  CONSTRAINT `chk_comp_practical_score_sheet_revision` CHECK ((`revision_no` > 0)),
  CONSTRAINT `chk_comp_practical_score_sheet_score` CHECK (((`total_score` is null) or (`total_score` between 0 and 100))),
  CONSTRAINT `chk_comp_practical_score_sheet_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'submitted_locked',_utf8mb4'unlocked_for_rescore',_utf8mb4'voided')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_practical_session` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `event_work_type_level_id` bigint DEFAULT NULL,
  `session_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `session_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_at` datetime NOT NULL,
  `end_at` datetime NOT NULL,
  `capacity` int DEFAULT NULL,
  `resource_id` bigint DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_practical_session_code` (`tenant_id`,`plan_id`,`session_code`,`deleted`),
  KEY `idx_comp_practical_session_scope` (`tenant_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`start_at`,`status`,`deleted`),
  KEY `idx_comp_practical_session_resource` (`tenant_id`,`resource_id`,`start_at`,`end_at`,`deleted`),
  CONSTRAINT `chk_comp_practical_session_capacity` CHECK (((`capacity` is null) or (`capacity` > 0))),
  CONSTRAINT `chk_comp_practical_session_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published',_utf8mb4'in_progress',_utf8mb4'closed',_utf8mb4'cancelled'))),
  CONSTRAINT `chk_comp_practical_session_time` CHECK ((`end_at` > `start_at`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_ranking_entry` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `ranking_snapshot_id` bigint NOT NULL,
  `contestant_member_id` bigint NOT NULL,
  `total_score_snapshot_id` bigint DEFAULT NULL COMMENT '缺考条目可为空',
  `total_score` decimal(12,6) NOT NULL DEFAULT '0.000000',
  `display_rank` int DEFAULT NULL COMMENT '缺考选手为空',
  `tie_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '应用层已冻结完整排序键的并列摘要',
  `tied_flag` tinyint NOT NULL DEFAULT '0',
  `contestant_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL,
  `active_entry_key` tinyint GENERATED ALWAYS AS ((case when (`deleted` = 0) then 1 else NULL end)) STORED,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_ranking_entry_contestant` (`tenant_id`,`ranking_snapshot_id`,`contestant_member_id`,`active_entry_key`),
  UNIQUE KEY `uk_comp_ranking_entry_order` (`tenant_id`,`ranking_snapshot_id`,`sort_order`,`active_entry_key`),
  KEY `idx_comp_ranking_entry_rank` (`tenant_id`,`ranking_snapshot_id`,`display_rank`,`sort_order`,`deleted`),
  CONSTRAINT `chk_comp_ranking_entry_absent` CHECK ((((`contestant_status` = _utf8mb4'absent') and (`display_rank` is null) and (`total_score` = 0)) or ((`contestant_status` = _utf8mb4'completed') and (`display_rank` is not null) and (`total_score_snapshot_id` is not null) and (`tie_key` is not null)))),
  CONSTRAINT `chk_comp_ranking_entry_order` CHECK ((`sort_order` > 0)),
  CONSTRAINT `chk_comp_ranking_entry_rank` CHECK (((`display_rank` is null) or (`display_rank` > 0))),
  CONSTRAINT `chk_comp_ranking_entry_score` CHECK ((`total_score` between 0 and 100)),
  CONSTRAINT `chk_comp_ranking_entry_status` CHECK ((`contestant_status` in (_utf8mb4'completed',_utf8mb4'absent'))),
  CONSTRAINT `chk_comp_ranking_entry_tied` CHECK ((`tied_flag` in (0,1)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛排名快照条目';
CREATE TABLE `competition_ranking_snapshot` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `score_rule_id` bigint NOT NULL,
  `snapshot_version` int NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `generation_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `generated_at` datetime NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_ranking_snapshot_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`score_rule_id`,`snapshot_version`,`deleted`),
  KEY `idx_comp_ranking_snapshot_scope` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`score_rule_id`,`status`,`generated_at`,`deleted`),
  KEY `idx_comp_ranking_snapshot_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_ranking_snapshot_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'confirmed',_utf8mb4'published'))),
  CONSTRAINT `chk_comp_ranking_snapshot_version` CHECK ((`snapshot_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛独立工种排名快照';
CREATE TABLE `competition_referee_assignment` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `referee_member_id` bigint NOT NULL COMMENT 'competition_event_member.id',
  `assignment_role` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'official/standby',
  `contestant_member_id` bigint NOT NULL DEFAULT '0' COMMENT '0表示当前工种全部选手',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `active_assignment_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`status` = _utf8mb4'active')) then 1 else NULL end)) STORED,
  `replaced_assignment_id` bigint DEFAULT NULL COMMENT '备用裁判补位记录指向被替换分配',
  `replacement_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assigned_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_referee_assignment_active` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`referee_member_id`,`contestant_member_id`,`active_assignment_key`),
  KEY `idx_comp_referee_assignment_scope` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`assignment_role`,`status`,`deleted`),
  KEY `idx_comp_referee_assignment_replaced` (`tenant_id`,`replaced_assignment_id`,`deleted`),
  KEY `idx_comp_referee_assignment_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`referee_member_id`,`event_work_type_level_id`,`deleted`),
  CONSTRAINT `chk_comp_referee_assignment_replaced_status` CHECK (((`status` <> _utf8mb4'replaced') or (`ended_at` is not null))),
  CONSTRAINT `chk_comp_referee_assignment_replacement_trace` CHECK (((`replaced_assignment_id` is null) or (`replacement_reason` is not null))),
  CONSTRAINT `chk_comp_referee_assignment_role` CHECK ((`assignment_role` in (_utf8mb4'official',_utf8mb4'standby'))),
  CONSTRAINT `chk_comp_referee_assignment_scope` CHECK ((`contestant_member_id` >= 0)),
  CONSTRAINT `chk_comp_referee_assignment_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'replaced',_utf8mb4'withdrawn')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛正式及现场备用裁判分配';
CREATE TABLE `competition_referee_avoidance` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `referee_member_id` bigint NOT NULL,
  `contestant_member_id` bigint NOT NULL,
  `relation_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'mentor/relative/same_org/other',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `configured_by` bigint NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `active_avoidance_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`status` = _utf8mb4'active')) then 1 else NULL end)) STORED,
  `configured_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_referee_avoidance_active` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`referee_member_id`,`contestant_member_id`,`active_avoidance_key`),
  KEY `idx_comp_referee_avoidance_contestant` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`status`,`deleted`),
  KEY `idx_comp_referee_avoidance_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`deleted`),
  CONSTRAINT `chk_comp_referee_avoidance_ended` CHECK (((`status` <> _utf8mb4'inactive') or (`ended_at` is not null))),
  CONSTRAINT `chk_comp_referee_avoidance_status` CHECK ((`status` in (_utf8mb4'active',_utf8mb4'inactive'))),
  CONSTRAINT `chk_comp_referee_avoidance_type` CHECK ((`relation_type` in (_utf8mb4'mentor',_utf8mb4'relative',_utf8mb4'same_org',_utf8mb4'other')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛裁判与选手禁评关系';
CREATE TABLE `competition_referee_profile` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `member_id` bigint NOT NULL,
  `professional_field` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referee_level` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `certificate_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referee_group_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_referee_profile_member` (`tenant_id`,`member_id`,`deleted`),
  KEY `idx_competition_referee_profile_group` (`tenant_id`,`referee_group_code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛裁判角色扩展';
CREATE TABLE `competition_registration` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `roster_item_id` bigint NOT NULL,
  `player_id` bigint DEFAULT NULL COMMENT '竞赛选手身份 ID',
  `member_id` bigint DEFAULT NULL COMMENT '关联 competition_event_member.id',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enterprise_import',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'imported_pending_confirm',
  `audit_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `audited_by` bigint DEFAULT NULL,
  `audited_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_registration_roster_item` (`tenant_id`,`roster_item_id`,`deleted`),
  UNIQUE KEY `uk_competition_registration_event_member` (`tenant_id`,`event_id`,`member_id`,`deleted`),
  KEY `idx_competition_registration_event_org_status` (`tenant_id`,`event_id`,`org_id`,`status`,`deleted`),
  KEY `idx_competition_registration_player_event_status` (`tenant_id`,`player_id`,`event_id`,`status`,`deleted`),
  KEY `idx_competition_registration_member` (`tenant_id`,`member_id`,`deleted`),
  CONSTRAINT `chk_competition_registration_source` CHECK ((`source` = _utf8mb4'enterprise_import')),
  CONSTRAINT `chk_competition_registration_status` CHECK ((`status` in (_utf8mb4'imported_pending_confirm',_utf8mb4'pending_audit',_utf8mb4'supplement_required',_utf8mb4'rejected',_utf8mb4'eligible_unactivated',_utf8mb4'eligible_activated',_utf8mb4'withdrawn',_utf8mb4'expired')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛参赛资格';
CREATE TABLE `competition_roster_import` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `event_work_type_id` bigint DEFAULT NULL COMMENT '本次导入选择的赛事工种',
  `batch_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_file_id` bigint DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'validating',
  `total_count` int NOT NULL DEFAULT '0',
  `valid_count` int NOT NULL DEFAULT '0',
  `invalid_count` int NOT NULL DEFAULT '0',
  `confirmed_by` bigint DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `summary` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_roster_import_batch_no` (`tenant_id`,`batch_no`,`deleted`),
  KEY `idx_competition_roster_import_event_org_status` (`tenant_id`,`event_id`,`org_id`,`status`,`deleted`),
  KEY `idx_competition_roster_import_event_work_type` (`tenant_id`,`event_id`,`event_work_type_id`,`deleted`),
  CONSTRAINT `chk_competition_roster_import_status` CHECK ((`status` in (_utf8mb4'validating',_utf8mb4'validation_failed',_utf8mb4'pending_confirm',_utf8mb4'confirmed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛名单导入批次';
CREATE TABLE `competition_roster_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `batch_id` bigint NOT NULL,
  `player_id` bigint DEFAULT NULL COMMENT '竞赛选手身份 ID',
  `employee_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `work_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `validation_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'valid',
  `error_message` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_roster_item_employee_no` (`tenant_id`,`batch_id`,`employee_no`,`deleted`),
  KEY `idx_competition_roster_item_validation` (`tenant_id`,`batch_id`,`validation_status`,`deleted`),
  KEY `idx_competition_roster_item_player` (`tenant_id`,`player_id`,`deleted`),
  CONSTRAINT `chk_competition_roster_item_validation_status` CHECK ((`validation_status` in (_utf8mb4'valid',_utf8mb4'invalid')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛名单导入行';
CREATE TABLE `competition_score_rule` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `scoring_system` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'B',
  `theory_template` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `theory_weight` decimal(5,2) DEFAULT NULL,
  `simulation_practical_weight` decimal(5,2) DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `rule_version` int NOT NULL,
  `published_at` datetime DEFAULT NULL,
  `published_by` bigint DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  `simulation_weight` decimal(5,2) DEFAULT NULL,
  `practical_weight` decimal(5,2) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_score_rule_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`rule_version`,`deleted`),
  UNIQUE KEY `uk_competition_score_rule_level_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`rule_version`,`deleted`),
  KEY `idx_competition_score_rule_scope_status` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`status`,`deleted`),
  KEY `idx_competition_score_rule_published` (`tenant_id`,`event_id`,`status`,`published_at`,`deleted`),
  KEY `idx_competition_score_rule_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`status`,`deleted`),
  CONSTRAINT `chk_competition_score_rule_published_values` CHECK (((`status` <> _utf8mb4'published') or ((`theory_template` is not null) and (`theory_weight` is not null) and (`simulation_practical_weight` is not null) and (`theory_weight` >= 0.00) and (`theory_weight` <= 100.00) and (`simulation_practical_weight` >= 0.00) and (`simulation_practical_weight` <= 100.00) and ((`theory_weight` + `simulation_practical_weight`) = 100.00)))),
  CONSTRAINT `chk_competition_score_rule_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published',_utf8mb4'deprecated'))),
  CONSTRAINT `chk_competition_score_rule_system` CHECK ((`scoring_system` = _utf8mb4'B')),
  CONSTRAINT `chk_competition_score_rule_template` CHECK (((`theory_template` is null) or (`theory_template` in (_utf8mb4'THEORY_90',_utf8mb4'THEORY_120',_utf8mb4'CUSTOM')))),
  CONSTRAINT `chk_competition_score_rule_version` CHECK ((`rule_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛赛制B评分规则版本';
CREATE TABLE `competition_score_source` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `contestant_member_id` bigint NOT NULL,
  `source_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'theory/simulation/practical',
  `raw_score` decimal(12,6) NOT NULL,
  `confirmation_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `source_system` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'competition',
  `source_reference` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考试会话、仿真流水或实操汇总引用',
  `score_rule_id` bigint NOT NULL COMMENT 'competition_score_rule.id',
  `revision_no` int NOT NULL,
  `current_flag` tinyint NOT NULL DEFAULT '1' COMMENT '1当前版本，0历史版本',
  `active_current_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`current_flag` = 1)) then 1 else NULL end)) STORED,
  `achieved_at` datetime NOT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `confirmed_by` bigint DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_score_source_revision` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`source_type`,`revision_no`,`deleted`),
  UNIQUE KEY `uk_comp_score_source_current` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`source_type`,`active_current_key`),
  KEY `idx_comp_score_source_rule` (`tenant_id`,`score_rule_id`,`confirmation_status`,`deleted`),
  KEY `idx_comp_score_source_reference` (`tenant_id`,`source_system`,`source_reference`,`deleted`),
  KEY `idx_comp_score_source_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`source_type`,`deleted`),
  CONSTRAINT `chk_comp_score_source_confirmed` CHECK (((`confirmation_status` <> _utf8mb4'confirmed') or ((`confirmed_at` is not null) and (`confirmed_by` is not null)))),
  CONSTRAINT `chk_comp_score_source_current` CHECK ((`current_flag` in (0,1))),
  CONSTRAINT `chk_comp_score_source_revision` CHECK ((`revision_no` > 0)),
  CONSTRAINT `chk_comp_score_source_score` CHECK (((`raw_score` >= 0) and (`raw_score` <= 100))),
  CONSTRAINT `chk_comp_score_source_status` CHECK ((`confirmation_status` in (_utf8mb4'pending',_utf8mb4'confirmed',_utf8mb4'voided'))),
  CONSTRAINT `chk_comp_score_source_type` CHECK ((`source_type` in (_utf8mb4'theory',_utf8mb4'simulation',_utf8mb4'practical')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛理论、仿真、实操成绩来源修订';
CREATE TABLE `competition_score_unlock_request` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `practical_score_id` bigint NOT NULL,
  `request_no` int NOT NULL,
  `request_reason` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidence_file_id` bigint DEFAULT NULL,
  `applicant_member_id` bigint NOT NULL COMMENT '主裁判长赛事成员ID',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `active_pending_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`status` = _utf8mb4'pending')) then 1 else NULL end)) STORED,
  `decided_by` bigint DEFAULT NULL COMMENT '系统管理员用户ID',
  `decision_comment` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `requested_at` datetime NOT NULL,
  `decided_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_unlock_request_version` (`tenant_id`,`practical_score_id`,`request_no`,`deleted`),
  UNIQUE KEY `uk_comp_unlock_request_pending` (`tenant_id`,`practical_score_id`,`active_pending_key`),
  KEY `idx_comp_unlock_request_status` (`tenant_id`,`status`,`requested_at`,`deleted`),
  CONSTRAINT `chk_comp_unlock_request_decision` CHECK (((`status` = _utf8mb4'pending') or ((`decided_by` is not null) and (`decided_at` is not null)))),
  CONSTRAINT `chk_comp_unlock_request_no` CHECK ((`request_no` > 0)),
  CONSTRAINT `chk_comp_unlock_request_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'approved',_utf8mb4'rejected')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛实操评分解锁申请与审批历史';
CREATE TABLE `competition_stage` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `stage_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `start_at` datetime DEFAULT NULL,
  `end_at` datetime DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `description` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_by` bigint DEFAULT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `frozen_at` datetime DEFAULT NULL,
  `ready_at` datetime DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `result_published_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_competition_stage_type` (`tenant_id`,`event_id`,`stage_type`,`deleted`),
  KEY `idx_competition_stage_order` (`tenant_id`,`event_id`,`sort_order`,`deleted`),
  KEY `idx_competition_stage_status` (`tenant_id`,`event_id`,`status`,`deleted`),
  KEY `idx_competition_stage_lifecycle` (`tenant_id`,`event_id`,`status`,`start_at`,`end_at`,`deleted`),
  CONSTRAINT `chk_competition_stage_sort_order` CHECK ((`sort_order` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛赛段';
CREATE TABLE `competition_stage_assignment` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL,
  `roster_snapshot_id` bigint NOT NULL,
