  KEY `idx_comp_stage_assignment_session` (`tenant_id`,`session_id`,`assignment_status`,`deleted`),
  KEY `idx_comp_stage_assignment_scope` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`deleted`),
  CONSTRAINT `chk_comp_stage_assignment_status` CHECK ((`assignment_status` in (_utf8mb4'assigned',_utf8mb4'withdrawn'))),
  CONSTRAINT `chk_comp_stage_assignment_type` CHECK ((`assignment_type` in (_utf8mb4'theory',_utf8mb4'simulation',_utf8mb4'practical')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `competition_stage_content` (
  `id` bigint NOT NULL,
