CREATE TABLE `competition_stage_execution_plan` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `event_work_type_level_id` bigint DEFAULT NULL,
  `plan_version` int NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `resource_version` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `preflight_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
