  `legacy_rule` tinyint NOT NULL DEFAULT '1',
  `target_stage_id` bigint DEFAULT NULL,
  `roster_snapshot_id` bigint DEFAULT NULL,
  `active_plan_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`status` = _utf8mb4'published')) then 1 else NULL end)) STORED,
  `published_at` datetime DEFAULT NULL,
  `published_by` bigint DEFAULT NULL,
  `withdrawn_at` datetime DEFAULT NULL,
  `withdrawn_by` bigint DEFAULT NULL,
  `withdraw_reason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_stage_plan_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`plan_version`,`deleted`),
  UNIQUE KEY `uk_comp_stage_plan_published` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`active_plan_key`),
  KEY `idx_comp_stage_plan_scope` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`status`,`deleted`),
  KEY `idx_comp_stage_plan_frozen_scope` (`tenant_id`,`event_id`,`stage_id`,`score_rule_id`,`target_stage_id`,`deleted`),
  CONSTRAINT `chk_comp_stage_plan_legacy_rule` CHECK ((`legacy_rule` in (0,1))),
  CONSTRAINT `chk_comp_stage_plan_preflight` CHECK ((`preflight_status` in (_utf8mb4'pending',_utf8mb4'blocked',_utf8mb4'passed'))),
  CONSTRAINT `chk_comp_stage_plan_promotion_percentage` CHECK (((`promotion_percentage` is null) or (`promotion_percentage` between 1 and 100))),
  CONSTRAINT `chk_comp_stage_plan_promotion_quota` CHECK (((`promotion_quota` is null) or (`promotion_quota` >= 0))),
  CONSTRAINT `chk_comp_stage_plan_promotion_rule_type` CHECK (((`promotion_rule_type` is null) or (`promotion_rule_type` in (_utf8mb4'FIXED_COUNT',_utf8mb4'PERCENTAGE',_utf8mb4'FINAL_PODIUM',_utf8mb4'LEGACY')))),
  CONSTRAINT `chk_comp_stage_plan_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'published',_utf8mb4'withdrawn'))),
  CONSTRAINT `chk_comp_stage_plan_version` CHECK ((`plan_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
