  CONSTRAINT `chk_comp_stage_import_status` CHECK ((`status` in (_utf8mb4'received',_utf8mb4'validating',_utf8mb4'validation_failed',_utf8mb4'pending_confirm',_utf8mb4'confirmed',_utf8mb4'processing',_utf8mb4'completed',_utf8mb4'failed')))
