  KEY `idx_comp_stage_promotion_scope` (`tenant_id`,`source_stage_id`,`target_stage_id`,`status`,`deleted`),
  KEY `idx_comp_stage_promotion_source_plan` (`tenant_id`,`source_plan_id`,`source_stage_id`,`target_stage_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_stage_promotion_percentage` CHECK (((`promotion_percentage` is null) or (`promotion_percentage` between 1 and 100))),
  CONSTRAINT `chk_comp_stage_promotion_podium_status` CHECK ((`final_podium_status` in (_utf8mb4'not_generated',_utf8mb4'draft',_utf8mb4'confirmed',_utf8mb4'published'))),
