  CONSTRAINT `chk_comp_stage_promotion_result_status` CHECK ((`promotion_status` in (_utf8mb4'not_generated',_utf8mb4'candidate',_utf8mb4'confirmed',_utf8mb4'published'))),
  CONSTRAINT `chk_comp_stage_promotion_rule_type` CHECK (((`promotion_rule_type` is null) or (`promotion_rule_type` in (_utf8mb4'FIXED_COUNT',_utf8mb4'PERCENTAGE',_utf8mb4'FINAL_PODIUM',_utf8mb4'LEGACY')))),
