  CONSTRAINT `chk_comp_theory_answer_scores` CHECK (((`question_score` >= 0) and ((`awarded_score` is null) or ((`awarded_score` >= 0) and (`awarded_score` <= `question_score`))))),
  CONSTRAINT `chk_comp_theory_answer_version` CHECK ((`save_version` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛理论考试当前答案与逐题判分结果';
