  CONSTRAINT `chk_comp_theory_attempt_session_state` CHECK ((`session_state` in (_utf8mb4'offline',_utf8mb4'active',_utf8mb4'forced_offline',_utf8mb4'closed'))),
  CONSTRAINT `chk_comp_theory_attempt_status` CHECK ((`status` in (_utf8mb4'waiting',_utf8mb4'ready',_utf8mb4'in_progress',_utf8mb4'submitting',_utf8mb4'provisional_absent',_utf8mb4'submitted_manual',_utf8mb4'submitted_auto',_utf8mb4'submitted_forced',_utf8mb4'absent'))),
  CONSTRAINT `chk_comp_theory_attempt_submit_type` CHECK (((`submit_type` is null) or (`submit_type` in (_utf8mb4'manual',_utf8mb4'auto',_utf8mb4'forced',_utf8mb4'absent'))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛理论考试选手作答会话';
