CREATE TABLE `competition_theory_paper_snapshot` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `score_rule_id` bigint DEFAULT NULL,
  `requirement_id` bigint DEFAULT NULL,
  `paper_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '当前页面使用A/B，字段预留C/D等扩展',
  `version_no` int NOT NULL,
  `source_course_id` bigint NOT NULL,
  `source_plan_id` bigint NOT NULL,
  `source_paper_id` bigint NOT NULL,
  `source_title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_minutes` int NOT NULL,
  `question_count` int NOT NULL,
  `total_score` decimal(12,6) NOT NULL,
  `pass_score` decimal(12,6) NOT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published',
  `active_published_key` tinyint GENERATED ALWAYS AS ((case when ((`deleted` = 0) and (`status` = _utf8mb4'published')) then 1 else NULL end)) STORED,
  `imported_at` datetime NOT NULL,
  `imported_by` bigint NOT NULL,
  `published_at` datetime NOT NULL,
  `published_by` bigint NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_theory_snapshot_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`score_rule_id`,`paper_code`,`version_no`,`deleted`),
  UNIQUE KEY `uk_comp_theory_snapshot_current` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`score_rule_id`,`paper_code`,`active_published_key`),
  KEY `idx_comp_theory_snapshot_source` (`tenant_id`,`source_course_id`,`source_plan_id`,`source_paper_id`,`deleted`),
  KEY `idx_comp_theory_snapshot_requirement` (`tenant_id`,`requirement_id`,`status`,`deleted`),
  KEY `idx_comp_theory_snapshot_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`status`,`deleted`),
  CONSTRAINT `chk_comp_theory_snapshot_code` CHECK ((char_length(`paper_code`) between 1 and 16)),
  CONSTRAINT `chk_comp_theory_snapshot_duration` CHECK ((`duration_minutes` > 0)),
  CONSTRAINT `chk_comp_theory_snapshot_questions` CHECK ((`question_count` > 0)),
  CONSTRAINT `chk_comp_theory_snapshot_scores` CHECK (((`total_score` > 0) and (`total_score` <= 100) and (`pass_score` >= 0) and (`pass_score` <= `total_score`))),
  CONSTRAINT `chk_comp_theory_snapshot_status` CHECK ((`status` in (_utf8mb4'published',_utf8mb4'deprecated'))),
  CONSTRAINT `chk_comp_theory_snapshot_version` CHECK ((`version_no` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛理论试卷不可变发布快照';
CREATE TABLE `competition_theory_requirement` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `event_id` bigint NOT NULL,
  `stage_id` bigint NOT NULL,
  `event_work_type_id` bigint NOT NULL,
  `score_rule_id` bigint NOT NULL,
  `template_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_minutes` int NOT NULL,
  `single_count` int NOT NULL,
  `single_score` decimal(12,6) NOT NULL,
  `multi_count` int NOT NULL,
  `multi_score` decimal(12,6) NOT NULL,
  `judge_count` int NOT NULL,
  `judge_score` decimal(12,6) NOT NULL,
  `total_score` decimal(12,6) NOT NULL,
  `pass_score` decimal(12,6) NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_theory_requirement_rule` (`tenant_id`,`score_rule_id`,`deleted`),
  KEY `idx_comp_theory_requirement_scope` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`score_rule_id`,`deleted`),
  KEY `idx_comp_theory_requirement_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`deleted`),
  CONSTRAINT `chk_comp_theory_requirement_counts` CHECK (((`single_count` >= 0) and (`multi_count` >= 0) and (`judge_count` >= 0) and (((`single_count` + `multi_count`) + `judge_count`) > 0))),
  CONSTRAINT `chk_comp_theory_requirement_duration` CHECK ((`duration_minutes` > 0)),
  CONSTRAINT `chk_comp_theory_requirement_nonzero_score` CHECK ((((`single_count` = 0) or (`single_score` > 0)) and ((`multi_count` = 0) or (`multi_score` > 0)) and ((`judge_count` = 0) or (`judge_score` > 0)))),
  CONSTRAINT `chk_comp_theory_requirement_pass` CHECK (((`pass_score` >= 0) and (`pass_score` <= `total_score`))),
  CONSTRAINT `chk_comp_theory_requirement_scores` CHECK (((`single_score` >= 0) and (`multi_score` >= 0) and (`judge_score` >= 0))),
  CONSTRAINT `chk_comp_theory_requirement_template` CHECK ((`template_code` in (_utf8mb4'THEORY_90',_utf8mb4'THEORY_120',_utf8mb4'CUSTOM'))),
  CONSTRAINT `chk_comp_theory_requirement_total` CHECK (((`total_score` > 0) and (`total_score` <= 100) and (`total_score` = (((`single_count` * `single_score`) + (`multi_count` * `multi_score`)) + (`judge_count` * `judge_score`)))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛评分规则版本的理论考试要求';
