  CONSTRAINT `chk_comp_theory_schedule_version` CHECK ((`version_no` > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛理论考试整版安排版本';
