  `updated_at` datetime NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `event_work_type_level_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_comp_total_score_version` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`score_rule_id`,`calculation_version`,`deleted`),
  UNIQUE KEY `uk_comp_total_score_current` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`contestant_member_id`,`score_rule_id`,`active_current_key`),
  KEY `idx_comp_total_score_sources` (`tenant_id`,`theory_source_id`,`simulation_source_id`,`practical_source_id`,`deleted`),
  KEY `idx_comp_total_score_ranking` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`score_rule_id`,`confirmation_status`,`total_score`,`deleted`),
  KEY `idx_comp_total_score_level` (`tenant_id`,`event_id`,`stage_id`,`event_work_type_id`,`event_work_type_level_id`,`confirmation_status`,`deleted`),
  CONSTRAINT `chk_comp_total_score_confirmed` CHECK (((`confirmation_status` <> _utf8mb4'confirmed') or (`total_score` is not null))),
  CONSTRAINT `chk_comp_total_score_current` CHECK ((`current_flag` in (0,1))),
  CONSTRAINT `chk_comp_total_score_inputs` CHECK (((`theory_score` between 0 and 100) and (`simulation_score` between 0 and 100) and (`practical_score` between 0 and 100) and (`simulation_practical_score` between 0 and 100))),
  CONSTRAINT `chk_comp_total_score_status` CHECK ((`confirmation_status` in (_utf8mb4'pending',_utf8mb4'confirmed',_utf8mb4'voided'))),
  CONSTRAINT `chk_comp_total_score_value` CHECK (((`total_score` is null) or (`total_score` between 0 and 100))),
  CONSTRAINT `chk_comp_total_score_version` CHECK ((`calculation_version` > 0)),
  CONSTRAINT `chk_comp_total_score_weights` CHECK (((`theory_weight` between 0 and 100) and (`simulation_practical_weight` between 0 and 100) and ((`theory_weight` + `simulation_practical_weight`) = 100)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='竞赛赛制B总分计算不可变快照';
CREATE TABLE `course` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `work_type_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cover_file_id` bigint DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `outline` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `owner_user_id` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_tenant_code` (`tenant_id`,`code`,`deleted`),
  KEY `idx_course_status` (`tenant_id`,`status`),
  KEY `idx_course_owner` (`tenant_id`,`owner_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `course_chapter` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `course_id` bigint NOT NULL,
  `parent_id` bigint NOT NULL DEFAULT '0',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'text',
  `content_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `file_id` bigint DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_course_chapter_course` (`tenant_id`,`course_id`),
  KEY `idx_course_chapter_parent` (`tenant_id`,`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `exam_faq_conversion` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` bigint NOT NULL COMMENT '租户 ID',
  `batch_id` bigint DEFAULT NULL COMMENT '所属批次 exam_faq_conversion_batch.id',
  `exam_id` int DEFAULT NULL COMMENT '来源试题 exam_exam_detail.id',
  `work_type_id` int NOT NULL COMMENT '工种 ID exam_work_type.id',
  `course_id` int DEFAULT NULL COMMENT '科目 ID exam_course.id',
  `knowledge_id` int DEFAULT NULL COMMENT '知识点 ID exam_knowledge_structure.id',
  `source_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '题型: single/multi/judge',
  `source_difficulty` int DEFAULT NULL COMMENT '难度',
  `source_content` text COLLATE utf8mb4_unicode_ci COMMENT '原始题干',
  `source_answer` text COLLATE utf8mb4_unicode_ci COMMENT '原始答案 JSON',
  `standard_question` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准问',
  `answers` json NOT NULL COMMENT '答案数组',
  `similar_questions` json DEFAULT NULL COMMENT '相似问数组（LLM 生成）',
  `negative_questions` json DEFAULT NULL COMMENT '反例数组（LLM 生成）',
  `tag_name` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签路径：题型|知识点末三级|难度',
  `conversion_status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending=待转换 / processing=转换中 / success=成功 / failed=失败 / skipped=跳过',
  `model_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '使用的 LLM 模型编码',
  `error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '转换失败原因',
  `retry_count` int NOT NULL DEFAULT '0' COMMENT '重试次数',
  `weknora_imported` tinyint NOT NULL DEFAULT '0' COMMENT '是否已导入 WeKnora: 0=否 1=是',
  `weknora_imported_at` datetime DEFAULT NULL COMMENT '导入 WeKnora 时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0=未删 1=已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exam_faq_conversion_exam` (`tenant_id`,`exam_id`,`deleted`),
  KEY `idx_efc_work_type_status` (`tenant_id`,`work_type_id`,`conversion_status`),
  KEY `idx_efc_status` (`tenant_id`,`conversion_status`),
  KEY `idx_efc_knowledge` (`tenant_id`,`knowledge_id`),
  KEY `idx_efc_batch` (`tenant_id`,`batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='试题 FAQ 结构化转换记录表';
CREATE TABLE `exam_faq_conversion_batch` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` bigint NOT NULL COMMENT '租户 ID',
  `work_type_id` int NOT NULL COMMENT '工种 ID',
  `work_type_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种名称（快照）',
  `course_ids` json DEFAULT NULL COMMENT '选中的科目 ID 列表（空=全部科目）',
  `model_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本次使用的模型编码',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称快照',
  `total_exams` int NOT NULL DEFAULT '0' COMMENT '参与转换的试题总数',
  `success_count` int NOT NULL DEFAULT '0' COMMENT '转换成功数',
  `failed_count` int NOT NULL DEFAULT '0' COMMENT '转换失败数',
  `skipped_count` int NOT NULL DEFAULT '0' COMMENT '跳过数',
  `pending_count` int NOT NULL DEFAULT '0' COMMENT '待转换数',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'running' COMMENT 'running=执行中 / paused=暂停 / completed=完成 / canceled=取消',
  `started_at` datetime DEFAULT NULL COMMENT '开始时间',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `error_message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '错误信息',
  `concurrency_limit` int NOT NULL DEFAULT '5' COMMENT '并发批次数',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0=未删 1=已删',
  PRIMARY KEY (`id`),
  KEY `idx_efcb_work_type` (`tenant_id`,`work_type_id`),
  KEY `idx_efcb_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='试题 FAQ 转换批次表';
CREATE TABLE `exam_faq_model_config` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` bigint NOT NULL COMMENT '租户 ID',
  `model_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型编码（唯一标识，如 deepseek-v3）',
  `model_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型显示名称',
  `base_url` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API Base URL',
  `api_key` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API 密钥',
  `api_format` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'openai_compatible' COMMENT 'API 格式: openai_compatible / anthropic / custom',
  `model_id` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型 ID（请求 body 中的 model 字段值）',
  `temperature` decimal(3,2) NOT NULL DEFAULT '0.70' COMMENT '采样温度',
  `max_tokens` int NOT NULL DEFAULT '2000' COMMENT '最大输出 token',
  `extra_config` json DEFAULT NULL COMMENT '扩展配置（可选，存储自定义 headers 等）',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT 'enabled / disabled',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0=未删 1=已删',
  `thinking` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'LongCat 思考模式：enabled/disabled，非 LongCat 模型留空',
  `reasoning_effort` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'high' COMMENT 'DeepSeek 推理强度：low/high/max，仅 thinking=enabled 时随 thinking 节点发送',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_model_config_code` (`tenant_id`,`model_code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FAQ 转换 LLM 模型连接参数配置表';
CREATE TABLE `exam_faq_weknora_config` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` bigint NOT NULL COMMENT '租户 ID',
  `webhook_secret` varchar(256) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签名密钥（共享给 WeKnora，用于 sha256 校验）',
  `enabled_events` json DEFAULT NULL COMMENT '启用的事件列表',
  `knowledge_base_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'WeKnora 知识库 ID',
  `faq_set_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'FAQ 数据集 ID',
  `webhook_enabled` tinyint NOT NULL DEFAULT '0' COMMENT 'Webhook 接收开关: 0=关 1=开',
  `auto_export` tinyint NOT NULL DEFAULT '0' COMMENT '转换成功后自动导出到 WeKnora: 0=否 1=是',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0=未删 1=已删',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_weknora_config_tenant` (`tenant_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WeKnora 集成配置表（回调签名校验 + FAQ 导出目标）';
CREATE TABLE `exam_mock_paper` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '所属学员',
  `tenant_id` bigint NOT NULL,
  `class_id` bigint DEFAULT NULL COMMENT '刷题班级',
  `people_id` bigint DEFAULT NULL COMMENT '花名册学员',
  `course_id` int DEFAULT NULL COMMENT '主科目',
  `title` varchar(128) NOT NULL COMMENT '试卷标题',
  `question_ids` varchar(2000) NOT NULL COMMENT '题目 id 列表(英文逗号分隔)',
  `total_count` int NOT NULL DEFAULT '0' COMMENT '题目数',
  `total_point` int NOT NULL DEFAULT '0' COMMENT '总分',
  `pass_point` int NOT NULL DEFAULT '0' COMMENT '及格分',
  `time_limit` int NOT NULL DEFAULT '0' COMMENT '限时(分钟)',
  `mode` varchar(16) NOT NULL DEFAULT 'mock' COMMENT 'mock=模拟考 wrong=错题重练 random=随机练习',
  `score` int NOT NULL DEFAULT '0' COMMENT '本次得分(交卷后填)',
  `right_count` int NOT NULL DEFAULT '0' COMMENT '答对题数',
  `status` varchar(16) NOT NULL DEFAULT 'pending' COMMENT 'pending=未开始 doing=答题中 done=已交卷',
  `create_time` datetime NOT NULL,
  `finish_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_emp_user` (`tenant_id`,`user_id`,`status`),
  KEY `idx_mock_paper_class_user` (`tenant_id`,`class_id`,`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='App 端模拟考卷';
CREATE TABLE `exam_session` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `course_id` bigint NOT NULL,
  `paper_id` bigint NOT NULL,
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `start_at` datetime NOT NULL,
  `end_at` datetime NOT NULL,
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `allow_retake` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_exam_session_time` (`tenant_id`,`start_at`,`end_at`),
  KEY `idx_exam_session_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `exam_standard_node` (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `task_id` bigint NOT NULL COMMENT '所属任务',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父节点（本表 id），0=L0 之上',
  `node_key` varchar(64) NOT NULL COMMENT '树内编码 A / A-A / A-A-A / A-A-A-001',
  `node_level` int NOT NULL DEFAULT '0' COMMENT '层级 0~3',
  `sort_number` int NOT NULL DEFAULT '100' COMMENT '同级排序',
  `dimension` varchar(10) NOT NULL DEFAULT 'theory' COMMENT 'theory/skill，骨架节点恒为 theory',
  `title_raw` text COMMENT 'docx 抽取原文',
  `title` varchar(512) NOT NULL DEFAULT '' COMMENT '展示标题（含编码后缀，人工可改）',
  `important` varchar(4) DEFAULT NULL COMMENT '重要程度 X/Y/Z（仅 L3）',
  `weight` decimal(6,4) DEFAULT NULL COMMENT '权重（如 0.2500），L0/L1 解析期落值，L2 可人工微调',
  `related_knowledge` text COMMENT 'L2 相关知识原文（理论细目表"相关知识"列）',
  `skill_requirement` text COMMENT 'L2 技能要求原文（技能细目表"技能要求"列）',
  `source` varchar(10) NOT NULL DEFAULT 'extract' COMMENT 'extract/llm/manual',
  `review_status` varchar(10) NOT NULL DEFAULT 'pending' COMMENT 'pending/approved/modified',
  `direction` varchar(64) NOT NULL DEFAULT '默认' COMMENT '所属方向（无方向工种为"默认"）',
  `level_code` int NOT NULL DEFAULT '0' COMMENT '所属等级 0=五级/初级 … 4=一级/高级技师',
  `need_llm` tinyint NOT NULL DEFAULT '0' COMMENT '1=L2 无列举项，需 LLM 概括补叶',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_standard_node_key` (`task_id`,`level_code`,`direction`(32),`dimension`,`node_key`),
  KEY `idx_standard_node_task` (`task_id`,`deleted`),
  KEY `idx_standard_node_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='职业技能标准树节点草稿（staging）';
CREATE TABLE `exam_standard_task` (
  `id` bigint NOT NULL COMMENT '雪花ID',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `work_type_title` varchar(128) NOT NULL DEFAULT '' COMMENT '职业名称',
  `series_no` varchar(64) DEFAULT NULL COMMENT '职业编码，如 6-16-01-12',
  `version` varchar(32) DEFAULT NULL COMMENT '版本年，如 2019',
  `file_id` bigint DEFAULT NULL COMMENT '上传 docx 文件ID（file 模块）',
  `file_hash` varchar(64) DEFAULT NULL COMMENT '文件 SHA-256，重复上传检测',
  `status` varchar(20) NOT NULL DEFAULT 'uploaded' COMMENT 'uploaded/parsed/llm_running/reviewing/confirmed/exported',
  `directions_json` text COMMENT '方向列表 JSON，如 ["电焊工","气焊工"]',
  `levels_json` text COMMENT '等级列表 JSON，如 [{"levelCode":0,"levelName":"五级/初级工"}]',
  `weights_json` mediumtext COMMENT '双权重表 JSON：{"theory":[{category,item,values:{"0|电焊工":25}}],"skill":[...]}',
  `parse_warnings` text COMMENT '解析警告（每行一条）',
  `llm_model_id` varchar(64) DEFAULT NULL COMMENT 'LLM 概括所用模型',
  `llm_finished_at` datetime DEFAULT NULL COMMENT 'LLM 概括完成时间',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `direction_levels_json` text COMMENT '工种 -> 可用 levelCode 列表的 JSON，来自 docx 1.4 节',
  PRIMARY KEY (`id`),
  KEY `idx_standard_task_tenant` (`tenant_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='职业技能标准解析任务（staging）';
CREATE TABLE `exam_user_answer_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '答题学员',
  `tenant_id` bigint NOT NULL COMMENT '租户',
  `class_id` bigint DEFAULT NULL COMMENT '刷题班级 train_info_class.id',
  `people_id` bigint DEFAULT NULL COMMENT '花名册 train_people_list.id',
  `course_id` int DEFAULT NULL COMMENT '科目 exam_course.id',
  `biz_date` date DEFAULT NULL COMMENT '练习自然日',
  `question_id` int NOT NULL COMMENT '题目 id (exam_exam_detail.id)',
  `knowledge_id` int DEFAULT NULL COMMENT '知识点 id (冗余，便于聚合)',
  `question_type` varchar(16) DEFAULT NULL COMMENT '题型: single/multiple/judge/subjective',
  `user_answer` varchar(2000) DEFAULT NULL COMMENT '学员作答',
  `is_right` tinyint NOT NULL DEFAULT '0' COMMENT '1对 0错',
  `source` varchar(32) NOT NULL DEFAULT 'mock' COMMENT '来源: mock=模考 wrong=错题重练 practice=随机练习',
  `paper_id` int DEFAULT NULL COMMENT '关联模拟考卷 id (exam_mock_paper.id)',
  `spend_ms` bigint NOT NULL DEFAULT '0' COMMENT '本题耗时(毫秒)',
  `create_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_eual_user` (`tenant_id`,`user_id`,`is_right`),
  KEY `idx_eual_paper` (`paper_id`),
  KEY `idx_eual_knowledge` (`tenant_id`,`knowledge_id`,`is_right`),
  KEY `idx_answer_log_class_user_time` (`tenant_id`,`class_id`,`user_id`,`create_time`),
  KEY `idx_answer_log_class_knowledge` (`tenant_id`,`class_id`,`knowledge_id`,`is_right`)
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='App 端用户答题明细';
CREATE TABLE `flyway_failed_backup_20260604` (
  `installed_rank` int NOT NULL,
  `version` varchar(50) DEFAULT NULL,
  `description` varchar(200) NOT NULL,
  `type` varchar(20) NOT NULL,
  `script` varchar(1000) NOT NULL,
  `checksum` int DEFAULT NULL,
  `installed_by` varchar(100) NOT NULL,
  `installed_on` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `execution_time` int NOT NULL,
  `success` tinyint(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `flyway_schema_history` (
  `installed_rank` int NOT NULL,
  `version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `script` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `checksum` int DEFAULT NULL,
  `installed_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
