  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_student_wrong_question` (`tenant_id`,`user_id`,`question_id`,`deleted`),
  KEY `idx_student_wrong_user` (`tenant_id`,`user_id`,`mastered`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `sync_checkpoint` (
  `table_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '同步表名：platform_user / platform_user_token / platform_user_detail',
  `last_max_id` bigint NOT NULL DEFAULT '0' COMMENT 'id 水位线（新增快路径）',
  `last_run_at` datetime DEFAULT NULL COMMENT '最近执行时间',
  `last_success_at` datetime DEFAULT NULL COMMENT '最近成功时间',
  `fail_count` int NOT NULL DEFAULT '0' COMMENT '连续失败次数（成功即清零）',
  `last_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一次错误信息',
  `stats` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '最近一周期统计：new=x,updated=y,deleted=z',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`table_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='PHP→SaaS 三表同步检查点';
CREATE TABLE `sys_audit_log` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '操作用户ID',
  `module` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作模块，如 User, Role',
  `action` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型：CREATE, UPDATE, DELETE, LOGIN, LOGOUT',
  `target_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标对象类型，如 User, Role',
  `target_id` bigint DEFAULT NULL COMMENT '目标对象ID',
  `request_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求追踪ID',
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求来源IP地址',
  `user_agent` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求User-Agent',
  `detail_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '操作详情JSON',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  KEY `idx_sys_audit_log_tenant_created` (`tenant_id`,`created_at`),
  KEY `idx_sys_audit_log_target` (`tenant_id`,`target_type`,`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='审计日志表';
CREATE TABLE `sys_dict_item` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `dict_id` bigint NOT NULL COMMENT '所属字典ID',
  `item_value` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典项值，如 male',
  `item_label` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典项标签，如 男',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号，值越小越靠前',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  KEY `idx_sys_dict_item_dict` (`tenant_id`,`dict_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据字典项表';
CREATE TABLE `sys_file` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `storage_provider` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '存储提供商：local-本地, minio, oss',
  `bucket` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '存储桶名称',
  `object_key` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对象存储Key',
  `original_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始文件名',
  `content_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME类型',
  `size_bytes` bigint NOT NULL COMMENT '文件大小（字节）',
  `sha256` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件SHA256哈希值',
  `access_policy` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'private' COMMENT '访问策略：private-私有, public-公开',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'uploaded' COMMENT '状态：uploaded-已上传',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  KEY `idx_sys_file_tenant_status` (`tenant_id`,`status`),
  KEY `idx_sys_file_created_at` (`tenant_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件表';
CREATE TABLE `sys_menu` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级菜单ID，0表示顶级',
  `menu_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单类型：directory-目录, menu-菜单, button-按钮',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单编码，租户内唯一',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '菜单名称',
  `path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端路由路径',
  `component` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '前端组件路径',
  `permission_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '权限标识码，如 user:view',
  `icon` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '菜单图标名称',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号，值越小越靠前',
  `visible` tinyint NOT NULL DEFAULT '1' COMMENT '是否可见：1-可见, 0-隐藏',
  `expanded` tinyint NOT NULL DEFAULT '1' COMMENT '目录默认展开(1展开 0收起)',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_menu_tenant_code` (`tenant_id`,`code`,`deleted`),
  KEY `idx_sys_menu_parent` (`tenant_id`,`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='菜单表';
CREATE TABLE `sys_org` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '上级组织ID，0表示顶级',
  `org_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组织类型：company-公司, department-部门, team-小组',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组织编码，租户内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组织名称',
  `organization_full_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '机构全称',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系电话',
  `industry` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属行业',
  `legal_person` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '法定代表人',
  `registered_capital` decimal(18,2) DEFAULT NULL COMMENT '注册资金',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在省份',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所在城市',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号，值越小越靠前',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_org_tenant_code` (`tenant_id`,`code`,`deleted`),
  KEY `idx_sys_org_parent` (`tenant_id`,`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='组织架构表';
CREATE TABLE `sys_permission` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `menu_id` bigint DEFAULT NULL COMMENT '所属菜单ID',
  `code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限编码，如 user:view',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '权限名称',
  `action` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型：view-查看, create-创建, update-更新, delete-删除',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_permission_tenant_code` (`tenant_id`,`code`,`deleted`),
  KEY `idx_sys_permission_menu` (`tenant_id`,`menu_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='权限表';
CREATE TABLE `sys_post` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '岗位编码，租户内唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '岗位名称',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序号，值越小越靠前',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_post_tenant_code` (`tenant_id`,`code`,`deleted`),
  KEY `idx_sys_post_status` (`tenant_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='岗位表';
CREATE TABLE `sys_role` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色编码，租户内唯一',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色名称',
  `role_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '角色类型：platform-平台角色, tenant-租户角色, custom-自定义',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_role_tenant_code` (`tenant_id`,`code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色表';
CREATE TABLE `sys_role_menu` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `role_id` bigint NOT NULL COMMENT '角色ID',
  `menu_id` bigint NOT NULL COMMENT '菜单ID',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_role_menu` (`tenant_id`,`role_id`,`menu_id`,`deleted`),
  KEY `idx_sys_role_menu_role` (`tenant_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色菜单关联表';
CREATE TABLE `sys_role_permission` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `role_id` bigint NOT NULL COMMENT '角色ID',
  `permission_id` bigint NOT NULL COMMENT '权限ID',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_role_permission` (`tenant_id`,`role_id`,`permission_id`,`deleted`),
  KEY `idx_sys_role_permission_role` (`tenant_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='角色权限关联表';
CREATE TABLE `sys_user_role` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `role_id` bigint NOT NULL COMMENT '角色ID',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_role` (`tenant_id`,`user_id`,`role_id`,`deleted`),
  KEY `idx_sys_user_role_user` (`tenant_id`,`user_id`),
  KEY `idx_sys_user_role_role` (`tenant_id`,`role_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户角色关联表';
CREATE TABLE `train_archive` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `archive_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '档案类型',
  `file_count` int DEFAULT '0' COMMENT '文件数',
  `archive_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '归档时间',
  `file_paths` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '文件路径JSON',
  `status` int DEFAULT '0' COMMENT '状态',
  `approver_id` bigint DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人姓名',
  `approve_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_archive_tenant` (`tenant_id`),
  KEY `idx_train_archive_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_attendance` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `class_id` bigint DEFAULT NULL COMMENT '班级ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `attendance_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '考勤日期',
  `schedule_id` bigint DEFAULT NULL COMMENT '课次 train_schedule.id；空=按日考勤',
  `status` int DEFAULT '0' COMMENT '状态 0-缺勤 1-出勤 2-迟到 3-早退',
  `check_in_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签到时间',
  `check_out_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签退时间',
  `photo_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '照片路径',
  `video_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '视频路径',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_attendance_tenant` (`tenant_id`),
  KEY `idx_train_attendance_class` (`class_id`),
  KEY `idx_train_attendance_schedule` (`class_id`,`attendance_date`,`schedule_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=3251 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_certificate` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `class_id` bigint DEFAULT NULL COMMENT '班级ID',
  `people_id` bigint DEFAULT NULL COMMENT '花名册学员ID',
  `template_id` bigint DEFAULT NULL COMMENT '模板ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `user_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `certificate_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书编号',
  `certificate_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书类型',
  `work_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种',
  `level` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级',
  `issue_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发证日期',
  `expire_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '过期日期',
  `issuing_authority` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发证机构',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `status` int DEFAULT '1' COMMENT '状态',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_certificate_tenant` (`tenant_id`),
  KEY `idx_train_certificate_project` (`project_id`),
  KEY `idx_train_certificate_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_class_practice_course` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `exam_course_id` int NOT NULL COMMENT 'exam_course.id',
  `create_time` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_practice_course` (`tenant_id`,`class_id`,`exam_course_id`),
  KEY `idx_class_practice_course_class` (`class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='班级练习科目白名单';
CREATE TABLE `train_class_practice_knowledge` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `exam_course_id` int NOT NULL COMMENT '冗余科目，便于校验',
  `knowledge_id` int NOT NULL COMMENT 'exam_knowledge_structure.id',
  `create_time` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_practice_knowledge` (`tenant_id`,`class_id`,`knowledge_id`),
  KEY `idx_class_practice_knowledge_class` (`class_id`),
  KEY `idx_class_practice_knowledge_course` (`class_id`,`exam_course_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1859 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='班级练习知识点白名单；空表示所选科目下不限知识点';
CREATE TABLE `train_class_practice_scope` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '1启用 0停用',
  `remark` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `practice_start_time` datetime DEFAULT NULL COMMENT '刷题开放开始时间，空=不限开始',
  `practice_end_time` datetime DEFAULT NULL COMMENT '刷题截止时间，空=不过期',
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_practice_scope` (`tenant_id`,`class_id`),
  KEY `idx_class_practice_scope_class` (`class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='班级练习范围主配置';
CREATE TABLE `train_class_role` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `role_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'head_teacher/follow_staff/lead_teacher/assistant/monitor',
  `subject_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'platform_user/people/teacher_bank',
  `subject_id` bigint NOT NULL COMMENT '主体 ID',
  `platform_user_id` bigint DEFAULT NULL COMMENT 'App 鉴权用 platform_user.id',
  `people_id` bigint DEFAULT NULL COMMENT '关联 train_people_list.id',
  `display_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '展示姓名',
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号冗余',
  `start_date` date DEFAULT NULL COMMENT '起任',
  `end_date` date DEFAULT NULL COMMENT '卸任',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'active/ended',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tcr_class_status` (`class_id`,`status`,`deleted`),
  KEY `idx_tcr_platform_user` (`platform_user_id`,`status`,`deleted`),
  KEY `idx_tcr_role` (`class_id`,`role_code`,`status`),
  KEY `idx_tcr_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='班级岗位角色指派';
CREATE TABLE `train_class_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `rule_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规则类型',
  `rule_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '规则配置JSON',
  `max_students` int DEFAULT NULL COMMENT '最大学生数',
  `status` int DEFAULT '1' COMMENT '状态',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_class_rule_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_class_teacher_pay` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `teacher_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与课表 teacher_name 对齐（trim）',
  `teach_form` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '未填' COMMENT '理论/实操/未填',
  `rate_per_day` decimal(12,2) DEFAULT NULL COMMENT '课酬单价（元/天）',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_teacher_form` (`tenant_id`,`class_id`,`teacher_name`,`teach_form`,`deleted`),
  KEY `idx_class_teacher_pay_class` (`class_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=2090287568531767298 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班班级教师课酬配置';
CREATE TABLE `train_division_pack_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL COMMENT '三年规划ID',
  `train_info_id` bigint NOT NULL COMMENT '关联培训信息ID',
  `company_id` bigint DEFAULT NULL COMMENT '企业组织ID（审核范围）',
  `strategy` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'by_shift_team',
  `class_max` int NOT NULL DEFAULT '50',
  `year` int NOT NULL,
  `month` int NOT NULL,
  `month_end` int DEFAULT NULL COMMENT '排班结束月（含），空则等于 month',
  `class_name_prefix` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/pending/rejected/materialized/superseded',
  `class_count` int NOT NULL DEFAULT '0',
  `assigned_count` int NOT NULL DEFAULT '0',
  `unassigned_count` int NOT NULL DEFAULT '0',
  `classes_json` mediumtext COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预览班级与学员',
  `unassigned_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `warning_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `reject_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submit_user_id` bigint DEFAULT NULL,
  `submit_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confirm_user_id` bigint DEFAULT NULL,
  `confirm_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confirm_time` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tdpt_plan` (`tenant_id`,`plan_id`,`deleted`),
  KEY `idx_tdpt_train` (`tenant_id`,`train_info_id`,`deleted`),
  KEY `idx_tdpt_company_status` (`tenant_id`,`company_id`,`status`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=64 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='名单排班自动分班方案（草稿/待企业审核）';
CREATE TABLE `train_exam_score_import_batch` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `tenant_id` bigint NOT NULL,
  `operator_user_id` bigint DEFAULT NULL,
  `operator_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `file_path` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exam_time_text` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `layout` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'RENSHE_ROSTER / FLAT_TEMPLATE',
  `class_ids_json` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '选定班级 ID JSON 数组',
  `train_info_id` bigint DEFAULT NULL,
  `sync_exam_plan` tinyint NOT NULL DEFAULT '0' COMMENT 'P0 固定 0',
  `total_rows` int NOT NULL DEFAULT '0',
  `matched_count` int NOT NULL DEFAULT '0',
  `written_count` int NOT NULL DEFAULT '0',
  `overwritten_count` int NOT NULL DEFAULT '0',
  `skipped_count` int NOT NULL DEFAULT '0',
  `unmatched_count` int NOT NULL DEFAULT '0',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tesib_tenant_time` (`tenant_id`,`created_at`),
  KEY `idx_tesib_plan_code` (`tenant_id`,`plan_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='成绩单导入批次';
CREATE TABLE `train_exam_score_import_item` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `batch_id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `row_no` int DEFAULT NULL,
  `id_card` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ticket_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `theory_score` decimal(10,2) DEFAULT NULL,
  `skill_score` decimal(10,2) DEFAULT NULL,
  `comprehensive_score` decimal(10,2) DEFAULT NULL,
  `people_id` bigint DEFAULT NULL,
  `class_id` bigint DEFAULT NULL,
  `result_code` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `old_exam_score` decimal(10,2) DEFAULT NULL,
  `new_exam_score` decimal(10,2) DEFAULT NULL,
  `old_real_score` decimal(10,2) DEFAULT NULL,
  `new_real_score` decimal(10,2) DEFAULT NULL,
  `theory_fallback` tinyint NOT NULL DEFAULT '0',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tesii_batch` (`batch_id`,`deleted`),
  KEY `idx_tesii_people` (`people_id`),
  KEY `idx_tesii_idcard` (`tenant_id`,`id_card`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='成绩单导入明细';
CREATE TABLE `train_file_temp` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板类型',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模板名称',
  `city` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市/地区',
  `path_source` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '源文件路径',
  `ext` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '扩展名',
  `path_used` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变量替换后的Word路径',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_file_temp_type` (`type`),
  KEY `idx_file_temp_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_follow_evidence` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `schedule_id` bigint DEFAULT NULL COMMENT 'train_schedule.id，优先挂课次',
  `session_id` bigint DEFAULT NULL COMMENT '预留 follow_session',
  `biz_date` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '无课次时 YYYY-MM-DD',
  `teach_form_override` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '按日上传时手工理论/实操',
  `class_hours_override` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '按日上传时手工学时',
  `media_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'photo' COMMENT 'photo/video',
  `duration_seconds` int DEFAULT NULL COMMENT '视频时长（秒），照片为空',
  `file_id` bigint DEFAULT NULL COMMENT 'sys/file id',
  `file_path` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '如 /api/files/{id}/download',
  `thumb_path` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `caption` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uploader_user_id` bigint DEFAULT NULL,
  `uploader_role` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'monitor/head_teacher/...',
  `review_status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/approved/rejected',
  `reviewed_by` bigint DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `reject_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_no` int NOT NULL DEFAULT '0',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfe_class_sched` (`class_id`,`schedule_id`,`deleted`),
  KEY `idx_tfe_class_date` (`class_id`,`biz_date`,`deleted`),
  KEY `idx_tfe_status` (`class_id`,`review_status`,`deleted`),
  KEY `idx_tfe_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班课堂影像证据';
CREATE TABLE `train_follow_issue` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `supervision_id` bigint DEFAULT NULL,
  `item_id` bigint DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'warn' COMMENT 'info/warn/critical',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open' COMMENT 'open/doing/done/closed',
  `assignee_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `due_date` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `resolve_note` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `opened_by` bigint DEFAULT NULL,
  `opened_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `closed_at` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfi_class_status` (`class_id`,`status`,`deleted`),
  KEY `idx_tfi_sup` (`supervision_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班异常整改单';
CREATE TABLE `train_follow_log` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `schedule_id` bigint DEFAULT NULL,
  `session_id` bigint DEFAULT NULL,
  `biz_date` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'YYYY-MM-DD',
  `author_user_id` bigint DEFAULT NULL,
  `author_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `attendance_summary` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '出勤概况',
  `exception_note` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常学员与处理',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '正文',
  `source_op_ids_json` text COLLATE utf8mb4_unicode_ci COMMENT '引用的过程动态 id 列表 JSON',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published' COMMENT 'draft/published',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfl_class_date` (`class_id`,`biz_date`,`deleted`),
  KEY `idx_tfl_tenant` (`tenant_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班/班主任工作日志（手写）';
CREATE TABLE `train_follow_op_log` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `schedule_id` bigint DEFAULT NULL COMMENT 'train_schedule.id',
  `session_id` bigint DEFAULT NULL COMMENT '预留 follow_session',
  `biz_date` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'YYYY-MM-DD',
  `event_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '如 evidence.upload',
  `event_category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'attendance/evidence/task/schedule/role/work_log/supervision/system',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `detail_json` text COLLATE utf8mb4_unicode_ci,
  `actor_user_id` bigint DEFAULT NULL,
  `actor_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actor_role` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `target_id` bigint DEFAULT NULL,
  `severity_level` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'info' COMMENT 'info/warn/critical',
  `client` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'admin/app/job',
  `request_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfop_class_date` (`class_id`,`biz_date`,`created_at`),
  KEY `idx_tfop_class_cat` (`class_id`,`event_category`,`deleted`),
  KEY `idx_tfop_tenant_time` (`tenant_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班过程操作日志（自动）';
CREATE TABLE `train_follow_photo_pack` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `class_id` bigint NOT NULL,
  `file_id` bigint DEFAULT NULL,
  `file_path` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生成的培训照片.docx',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `snapshot_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '生成时课次/照片快照',
  `generated_at` datetime NOT NULL,
  `generated_by` bigint DEFAULT NULL,
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfpp_class` (`class_id`,`deleted`),
  KEY `idx_tfpp_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班培训照片材料生成记录';
CREATE TABLE `train_follow_supervision` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `biz_date` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'YYYY-MM-DD',
  `schedule_id` bigint DEFAULT NULL,
  `inspector_user_id` bigint DEFAULT NULL,
  `inspector_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/submitted/closed',
  `conclusion` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'pass/fail/conditional',
  `remark` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfs_class_date` (`class_id`,`biz_date`,`deleted`),
  KEY `idx_tfs_tenant` (`tenant_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班督导检查单';
CREATE TABLE `train_follow_supervision_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `supervision_id` bigint NOT NULL,
  `item_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `item_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sort_no` int NOT NULL DEFAULT '0',
  `result` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'pass/fail/na',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfsi_sup` (`supervision_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='督导检查项';
CREATE TABLE `train_follow_survey_response` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `biz_date` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `respondent_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `score` decimal(4,1) NOT NULL COMMENT '1.0～5.0',
  `comment_text` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT 'admin/app/import',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tfsr_class` (`class_id`,`deleted`),
  KEY `idx_tfsr_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班满意度答卷';
CREATE TABLE `train_follow_task` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `train_info_id` bigint DEFAULT NULL COMMENT '开班项目冗余',
  `schedule_id` bigint DEFAULT NULL COMMENT 'train_schedule.id，可空',
  `biz_date` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '无课次时的业务日 YYYY-MM-DD',
  `task_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'homework/practice',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deadline_at` datetime DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/published/closed',
  `pass_score` decimal(10,2) DEFAULT NULL COMMENT '达标分数，空则交卷即达标',
  `pass_rule` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'submitted/score',
  `show_analysis_after_submit` tinyint NOT NULL DEFAULT '0' COMMENT '交卷后是否立即显示解析',
  `published_at` datetime DEFAULT NULL,
  `make_exam_plan_id` int DEFAULT NULL COMMENT '来源组卷计划 exam_make_exam_plan.id',
  `source_paper_id` int DEFAULT NULL COMMENT '来源正式卷 exam_paper.id',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tft_class_status` (`class_id`,`status`,`deleted`),
  KEY `idx_tft_schedule` (`schedule_id`),
  KEY `idx_tft_tenant` (`tenant_id`),
  KEY `idx_follow_task_make_plan` (`make_exam_plan_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班作业/随堂练任务';
CREATE TABLE `train_follow_task_answer` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `task_id` bigint NOT NULL,
  `item_id` bigint NOT NULL,
  `question_id` bigint NOT NULL,
  `people_id` bigint NOT NULL,
  `answer_json` text COLLATE utf8mb4_unicode_ci,
  `is_correct` tinyint DEFAULT NULL,
  `score` decimal(10,2) DEFAULT NULL,
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tfta_item_question` (`item_id`,`question_id`,`deleted`),
  KEY `idx_tfta_task` (`task_id`),
  KEY `idx_tfta_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班作业作答明细';
CREATE TABLE `train_follow_task_item` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `task_id` bigint NOT NULL,
  `people_id` bigint NOT NULL COMMENT 'train_people_list.id',
  `user_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/submitted/graded',
  `score` decimal(10,2) DEFAULT NULL,
  `passed` tinyint DEFAULT NULL COMMENT '是否达标 0/1',
  `submitted_at` datetime DEFAULT NULL,
  `graded_at` datetime DEFAULT NULL,
  `graded_by` bigint DEFAULT NULL,
  `comment_text` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `started_at` datetime DEFAULT NULL COMMENT '首次打开试卷时间',
  `duration_seconds` int DEFAULT NULL COMMENT '答题时长秒',
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tfti_task_people` (`task_id`,`people_id`,`deleted`),
  KEY `idx_tfti_people_status` (`people_id`,`status`,`deleted`),
  KEY `idx_tfti_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班作业学员任务态';
CREATE TABLE `train_follow_task_question` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `task_id` bigint NOT NULL,
  `sort_number` int NOT NULL DEFAULT '1',
  `question_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'single/multi/judge',
  `stem` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `options_json` text COLLATE utf8mb4_unicode_ci COMMENT '选项 JSON',
  `answer_json` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准答案 JSON',
  `score` decimal(10,2) NOT NULL DEFAULT '1.00',
  `source_exam_detail_id` bigint DEFAULT NULL,
  `analysis` text COLLATE utf8mb4_unicode_ci,
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tftq_task` (`task_id`,`deleted`),
  KEY `idx_tftq_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='跟班作业题目快照';
CREATE TABLE `train_graduation_archive` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `file_id` bigint DEFAULT NULL,
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version_no` int NOT NULL DEFAULT '1',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tga_class` (`class_id`,`deleted`),
  KEY `idx_tga_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='结业材料归档包';
CREATE TABLE `train_graduation_notice` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `class_id` bigint NOT NULL,
  `channel` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'inbox' COMMENT 'inbox/sms',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `total_count` int NOT NULL DEFAULT '0',
  `success_count` int NOT NULL DEFAULT '0',
  `fail_count` int NOT NULL DEFAULT '0',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tgn_class` (`class_id`,`deleted`),
  KEY `idx_tgn_tenant` (`tenant_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='结业通知批次';
CREATE TABLE `train_graduation_notice_item` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `notice_id` bigint NOT NULL,
  `people_id` bigint DEFAULT NULL,
  `platform_user_id` bigint DEFAULT NULL,
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'success/fail/skip',
  `fail_reason` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `read_at` datetime DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tgni_notice` (`notice_id`,`deleted`),
  KEY `idx_tgni_people` (`people_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='结业通知投递明细';
CREATE TABLE `train_plan_roster` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL COMMENT '三年规划ID',
  `train_info_id` bigint DEFAULT NULL COMMENT '关联培训信息ID',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'enterprise_roster/plan_item/manual',
  `person_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_card` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `job_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级（可认定等级等）',
  `workshop` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '车间',
  `shift_team` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生产班组',
  `plan_year` int DEFAULT NULL,
  `train_mode` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `assign_status` tinyint NOT NULL DEFAULT '0' COMMENT '0待分 1已分班 2排除',
  `train_class_id` bigint DEFAULT NULL,
  `row_json` text COLLATE utf8mb4_unicode_ci,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tpr_plan` (`tenant_id`,`plan_id`,`assign_status`,`deleted`),
  KEY `idx_tpr_idcard` (`tenant_id`,`id_card`),
  KEY `idx_tpr_train_info` (`train_info_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=16395 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='三年规划待分班池';
CREATE TABLE `train_project` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目名称',
  `company_id` bigint DEFAULT NULL COMMENT '企业ID',
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '企业名称',
  `manager_id` bigint DEFAULT NULL COMMENT '负责人ID',
  `manager_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人姓名',
  `plan_start` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计划开始',
  `plan_end` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '计划结束',
  `current_stage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '当前阶段',
  `progress` int DEFAULT '0' COMMENT '进度',
  `status` int DEFAULT '0' COMMENT '状态',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_project_tenant` (`tenant_id`),
  KEY `idx_train_project_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_project_table` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `table_type` int DEFAULT NULL COMMENT '表类型',
  `table_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '表名称',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `version` int DEFAULT '1' COMMENT '版本',
  `status` int DEFAULT '0' COMMENT '状态',
  `file_id` bigint DEFAULT NULL COMMENT '文件ID',
  `owner_id` bigint DEFAULT NULL COMMENT '负责人ID',
  `owner_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '负责人姓名',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_project_table_tenant` (`tenant_id`),
  KEY `idx_train_project_table_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_protocol` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `version` int DEFAULT '1' COMMENT '版本',
  `status` int DEFAULT '0' COMMENT '状态',
  `signed_at` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签署时间',
  `signer_id` bigint DEFAULT NULL COMMENT '签署人ID',
  `approver_id` bigint DEFAULT NULL COMMENT '审批人ID',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_protocol_tenant` (`tenant_id`),
  KEY `idx_train_protocol_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_schedule` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `class_id` bigint DEFAULT NULL COMMENT '班级ID',
  `course_id` bigint DEFAULT NULL COMMENT '课程ID',
  `teacher_id` bigint DEFAULT NULL COMMENT '教师ID',
  `teacher_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '教师姓名',
  `course_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '课程名称',
  `class_hours` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学时',
  `actual_class_hours` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '实际学时，空则用 class_hours',
  `teach_form` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '授课形式（理论/实操等）',
  `evidence_required` tinyint NOT NULL DEFAULT '1' COMMENT '是否须课堂影像 1是0否',
  `room_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '教室名称',
  `day_of_week` int DEFAULT NULL COMMENT '星期几',
  `start_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开始时间',
  `end_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结束时间',
  `schedule_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '日期',
  `status` int DEFAULT '1' COMMENT '状态',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_schedule_tenant` (`tenant_id`),
  KEY `idx_train_schedule_class` (`class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=517 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_schedule_change_request` (
  `id` bigint NOT NULL COMMENT '雪花 ID',
  `class_id` bigint NOT NULL COMMENT 'train_info_class.id',
  `schedule_id` bigint DEFAULT NULL COMMENT 'train_schedule.id；加课可空',
  `change_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'reschedule/replace_teacher/cancel/add',
  `before_snapshot` text COLLATE utf8mb4_unicode_ci COMMENT '原课次 JSON',
  `after_payload` text COLLATE utf8mb4_unicode_ci COMMENT '目标字段 JSON',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请原因',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/approved/rejected/cancelled',
  `applicant_platform_user_id` bigint NOT NULL COMMENT '申请人 platform_user.id',
  `applicant_role_code` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申请时班级角色',
  `reviewer_user_id` bigint DEFAULT NULL COMMENT '管理端审批人 sys user id',
  `reviewed_at` datetime DEFAULT NULL,
  `reject_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tscr_class_status` (`class_id`,`status`,`deleted`),
  KEY `idx_tscr_applicant` (`applicant_platform_user_id`,`status`,`deleted`),
  KEY `idx_tscr_schedule_pending` (`schedule_id`,`status`,`deleted`),
  KEY `idx_tscr_tenant` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课表调课申请';
CREATE TABLE `train_settlement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `settlement_amount` decimal(16,2) DEFAULT NULL COMMENT '结算金额',
  `institution_share` decimal(16,2) DEFAULT NULL COMMENT '机构分成',
  `enterprise_share` decimal(16,2) DEFAULT NULL COMMENT '企业分成',
  `third_party_share` decimal(16,2) DEFAULT NULL COMMENT '第三方分成',
  `share_ratio` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分成比例',
  `approval_status` int DEFAULT '0' COMMENT '审批状态',
  `approver_id` bigint DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人姓名',
  `approve_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `status` int DEFAULT '0' COMMENT '状态',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_settlement_tenant` (`tenant_id`),
  KEY `idx_train_settlement_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_shift_assign_record` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `task_id` bigint NOT NULL,
  `person_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_card` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '若解析到身份证/证件号',
  `employee_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dept` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shift_class` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生产班别',
  `assign_date` date NOT NULL,
  `slot` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上午/下午',
  `algo_class_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '算法班名如上午1班',
  `train_class_id` bigint DEFAULT NULL COMMENT '绑定的培训班级ID',
  `row_index` int DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tsar_task` (`tenant_id`,`task_id`,`deleted`),
  KEY `idx_tsar_class` (`algo_class_name`,`train_class_id`),
  KEY `idx_tsar_date` (`task_id`,`assign_date`,`slot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='排课分班明细';
CREATE TABLE `train_shift_assign_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL COMMENT '三年规划ID',
  `train_info_id` bigint DEFAULT NULL COMMENT '关联培训信息ID',
  `year` int NOT NULL,
  `month` int NOT NULL,
  `source_shift_file_id` bigint DEFAULT NULL COMMENT '企业回传排班表文件ID',
  `adapter_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'T0' COMMENT 'T0直通/后续企业Adapter',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'generated' COMMENT 'precheck/generated/patched',
  `version` int NOT NULL DEFAULT '1' COMMENT '调课乐观锁',
  `warning_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `config_json` text COLLATE utf8mb4_unicode_ci,
  `unassigned_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `theory_days_json` text COLLATE utf8mb4_unicode_ci,
  `practice_days_json` text COLLATE utf8mb4_unicode_ci,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tsat_plan` (`tenant_id`,`plan_id`,`deleted`),
  KEY `idx_tsat_train` (`train_info_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='排课分班任务';
CREATE TABLE `train_shift_normalize_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL,
  `year` int NOT NULL,
  `month` int NOT NULL,
  `source_shift_file_id` bigint NOT NULL COMMENT '原始企业排班',
  `adapter_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'T0/T0_PRIME/T1/...',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'converted' COMMENT 'converted/confirmed/failed',
  `standard_file_id` bigint DEFAULT NULL COMMENT '转换产出的标准模板附件',
  `standard_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `person_count` int NOT NULL DEFAULT '0',
  `warning_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `precheck_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `preview_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '标准表前若干行预览',
  `mapping_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '列映射/班次别名快照',
  `block_confirm` tinyint NOT NULL DEFAULT '0' COMMENT '1=存在阻断项不可确认',
  `confirm_user_id` bigint DEFAULT NULL,
  `confirm_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confirm_time` datetime DEFAULT NULL,
  `error_message` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tsnt_plan_ym` (`tenant_id`,`plan_id`,`year`,`month`,`deleted`),
  KEY `idx_tsnt_status` (`tenant_id`,`status`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='排班标准化任务（异构→导入模板）';
CREATE TABLE `train_subsidy` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `class_id` bigint DEFAULT NULL COMMENT '班级 train_info_class.id（首期强制）',
  `train_info_id` bigint DEFAULT NULL COMMENT '冗余培训单',
  `policy_template` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '政策模板',
  `subsidy_amount` decimal(16,2) DEFAULT NULL COMMENT '补贴金额',
  `student_count` int DEFAULT NULL COMMENT '学员人数',
  `material_package_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '材料包路径',
  `material_status` int DEFAULT '0' COMMENT '材料状态',
  `rssb_status` int DEFAULT '0' COMMENT '人社局状态',
  `rssb_submit_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '人社局提交时间',
  `rssb_receipt_no` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '人社局回执号',
  `rssb_reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '人社局驳回原因',
  `granted_amount` decimal(16,2) DEFAULT NULL COMMENT '已拨付金额',
  `grant_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '拨付时间',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `status` int DEFAULT '0' COMMENT '状态',
  `phase` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/checking/ready/submitted/rejected/approved/granting/granted/closed',
  `region_code` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报地市编码/名',
  `region_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报地市展示名',
  `train_mode` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'skill_upgrade/apprentice',
  `policy_year` int DEFAULT NULL COMMENT '政策年',
  `profile_id` bigint DEFAULT NULL COMMENT '锁定配方',
  `profile_version` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '锁定配方版本',
  `profile_locked` tinyint NOT NULL DEFAULT '0' COMMENT '1=已锁定配方',
  `checklist_json` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '齐套快照 JSON',
  `evidence_index_path` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证据索引包路径',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_subsidy_tenant` (`tenant_id`),
  KEY `idx_train_subsidy_project` (`project_id`),
  KEY `idx_ts_class` (`class_id`),
  KEY `idx_ts_phase` (`phase`),
  KEY `idx_ts_region_mode_year` (`region_code`,`train_mode`,`policy_year`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_subsidy_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `subsidy_id` bigint NOT NULL,
  `action` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'create/update/transition/generate/upload_slot/...',
  `from_phase` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_phase` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remark` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payload_json` mediumtext COLLATE utf8mb4_unicode_ci,
  `operator_id` bigint DEFAULT NULL,
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tse_subsidy` (`subsidy_id`,`deleted`),
  KEY `idx_tse_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='补贴进度事件';
CREATE TABLE `train_subsidy_pack_profile` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `region_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `region_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `train_mode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'skill_upgrade/apprentice',
  `policy_year` int NOT NULL,
  `profile_version` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'v1',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft/active/retired',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '同年同地市同模式默认',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '0=平台级共享配方',
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tspp_key` (`tenant_id`,`region_code`,`train_mode`,`policy_year`,`profile_version`,`deleted`),
  KEY `idx_tspp_active` (`region_code`,`train_mode`,`policy_year`,`status`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='补贴材料配方';
CREATE TABLE `train_subsidy_pack_slot` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `profile_id` bigint NOT NULL,
  `slot_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `required_flag` tinyint NOT NULL DEFAULT '1',
  `sort_order` int NOT NULL DEFAULT '0',
  `renderer` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'docx_var/xlsx_row/file_copy/pdf_merge/manual_upload/follow_photo',
  `template_id` bigint DEFAULT NULL,
  `data_binding` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `folder_path` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'ZIP 内相对目录',
  `remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tsps_profile` (`profile_id`,`deleted`,`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='补贴材料配方槽位';
CREATE TABLE `train_subsidy_slot_file` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `subsidy_id` bigint NOT NULL,
  `slot_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_id` bigint DEFAULT NULL,
  `file_path` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uploaded_by` bigint DEFAULT NULL,
  `tenant_id` bigint NOT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tssf_sub_slot` (`subsidy_id`,`slot_code`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='补贴单槽位人工附件';
CREATE TABLE `train_summary` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` bigint DEFAULT NULL COMMENT '项目ID',
  `certification_rate` decimal(10,2) DEFAULT NULL COMMENT '认定通过率',
  `subsidy_success_rate` decimal(10,2) DEFAULT NULL COMMENT '补贴成功率',
  `achievements` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '成果',
  `lessons_learned` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '经验教训',
  `improvement_suggestions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '改进建议',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `approval_status` int DEFAULT '0' COMMENT '审批状态',
  `approver_id` bigint DEFAULT NULL COMMENT '审批人ID',
  `approver_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批人姓名',
  `approve_time` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审批时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '驳回原因',
  `status` int DEFAULT '0' COMMENT '状态',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_summary_tenant` (`tenant_id`),
  KEY `idx_train_summary_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_teacher_bank_file` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `teacher_id` bigint NOT NULL,
  `file_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID_FRONT/ID_BACK/GRADUATE/EDUCATION/TEACHER_QUAL/TITLE/SKILL/OTHER',
  `file_id` bigint NOT NULL,
  `legacy_url` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cert_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_no` int NOT NULL DEFAULT '0',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_teacher_bank_file_teacher` (`teacher_id`,`deleted`),
  KEY `idx_teacher_bank_file_tenant` (`tenant_id`,`teacher_id`),
  KEY `idx_teacher_bank_file_legacy` (`tenant_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=2090707885813190659 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='师资库证照附件';
CREATE TABLE `train_three_year_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `plan_no` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规划编号',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规划标题',
  `target_org_id` bigint NOT NULL COMMENT '目标企业 sys_org.id',
  `research_org_id` bigint DEFAULT NULL COMMENT '关联企业调研 train_research_org.id',
  `source_sign_up_id` bigint DEFAULT NULL COMMENT '人员来源预报名批次',
  `rencai_task_id` bigint DEFAULT NULL COMMENT 'rencaishibie analysis_task.id',
  `rencai_input_file_id` bigint DEFAULT NULL COMMENT 'rencaishibie 输入文件 ID',
  `plan_years` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2026,2027,2028',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0草稿 1分析中 2待机构审核 3待企业确认 4企业已确认 5已驳回 6已作废',
  `analysis_status` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'pending/running/done/failed',
  `distribution_snapshot` text COLLATE utf8mb4_unicode_ci COMMENT '认定分布快照 JSON',
  `reviewed_plan_file_id` bigint DEFAULT NULL COMMENT '提交企业审核时生成的已审核规划表文件ID',
  `submit_personnel_file_id` bigint DEFAULT NULL COMMENT '提交企业审核时上传的审核人员名单文件ID',
  `submit_scheme_file_id` bigint DEFAULT NULL COMMENT '提交企业审核时上传的方案文档文件ID',
  `enterprise_roster_file_id` bigint DEFAULT NULL COMMENT 'enterprise roster file id',
  `enterprise_shift_file_id` bigint DEFAULT NULL COMMENT 'enterprise shift file id',
  `enterprise_roster_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'roster file name',
  `enterprise_roster_person_count` int DEFAULT NULL COMMENT '企业上传筛选名单解析人数',
  `enterprise_shift_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'shift file name',
  `standard_shift_file_id` bigint DEFAULT NULL COMMENT '已确认标准排班附件 fileId',
  `standard_shift_file_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '已确认标准排班文件名',
  `standard_shift_year` int DEFAULT NULL COMMENT '标准排班对应年',
  `standard_shift_month` int DEFAULT NULL COMMENT '标准排班对应月',
  `standard_shift_adapter` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '确认时使用的 adapter',
  `standard_shift_confirm_time` datetime DEFAULT NULL COMMENT '标准排班确认时间',
  `enterprise_return_time` datetime DEFAULT NULL COMMENT 'return time',
  `enterprise_return_user_id` bigint DEFAULT NULL COMMENT 'return user id',
  `enterprise_return_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'return username',
  `enterprise_return_history_json` text COLLATE utf8mb4_unicode_ci COMMENT 'return history json',
  `reject_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reject_history_json` text COLLATE utf8mb4_unicode_ci COMMENT '驳回历史 JSON：[{reason, rejectedBy, rejectedAt}]',
  `submit_history_json` text COLLATE utf8mb4_unicode_ci COMMENT '提交历史 JSON：[{submittedBy, submittedAt, personnelFileName, schemeFileName}]',
  `company_confirm_time` datetime DEFAULT NULL,
  `company_confirm_user_id` bigint DEFAULT NULL,
  `company_confirm_username` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_typ_tenant_org` (`tenant_id`,`target_org_id`,`deleted`),
  KEY `idx_typ_rencai_task` (`rencai_task_id`),
  KEY `idx_typ_status` (`tenant_id`,`status`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='三年培训规划';
CREATE TABLE `train_three_year_plan_item` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `person_name` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_card` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `job_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level_name` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `train_mode` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '自费认定/新型学徒制/岗位技能提升',
  `plan_year` int DEFAULT NULL,
  `train_year` int DEFAULT NULL,
  `cert_year` int DEFAULT NULL,
  `eligible_date` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `row_index` int DEFAULT NULL,
  `source` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'engine',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_typ_item_plan` (`plan_id`,`deleted`),
  KEY `idx_typ_item_year` (`plan_id`,`plan_year`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=3337 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='三年规划明细';
CREATE TABLE `train_three_year_plan_matrix` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `plan_id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `job_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `plan_year` int NOT NULL,
  `train_mode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `level_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `headcount` int NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_typ_matrix_cell` (`plan_id`,`job_name`,`plan_year`,`train_mode`,`level_name`,`deleted`),
  KEY `idx_typ_matrix_plan` (`plan_id`,`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=394 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='三年规划矩阵汇总';
CREATE TABLE `sys_dict` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典编码，租户内唯一',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典名称',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  `value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '字典值',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_dict_tenant_code` (`tenant_id`,`code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据字典表';
CREATE TABLE `sys_index_swiper` (
  `id` int NOT NULL AUTO_INCREMENT,
  `img` varchar(500) DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_show` tinyint NOT NULL DEFAULT '1',
  `url` varchar(500) DEFAULT NULL,
  `page_type` varchar(32) NOT NULL DEFAULT 'index',
  `param` varchar(500) DEFAULT NULL,
  `tenant_id` bigint NOT NULL DEFAULT '10159',
  PRIMARY KEY (`id`),
  KEY `idx_swiper_page_tenant` (`page_type`,`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='首页轮播';
CREATE TABLE `sys_tenant` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户编码，全局唯一',
  `name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '租户名称',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-启用, disabled-停用',
  `contact_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '联系人电话',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_tenant_code` (`code`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='租户表';
CREATE TABLE `sys_user` (
  `id` bigint NOT NULL COMMENT '主键ID（雪花ID）',
  `tenant_id` bigint NOT NULL COMMENT '所属租户ID',
  `org_id` bigint DEFAULT NULL COMMENT '所属组织ID',
  `post_id` bigint DEFAULT NULL COMMENT '所属岗位ID',
  `username` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录用户名，租户内唯一',
  `password_hash` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码哈希值',
  `display_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示姓名',
  `user_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'user type: platform_admin, tenant_admin, certification_admin, assessor, normal',
  `phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `email` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
  `avatar_file_id` bigint DEFAULT NULL COMMENT '头像文件ID',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'enabled' COMMENT '状态：enabled-正常, locked-锁定, disabled-停用',
  `last_login_at` datetime DEFAULT NULL COMMENT '最后登录时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL COMMENT '创建人ID',
  `updated_by` bigint DEFAULT NULL COMMENT '更新人ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0-未删除, 1-已删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_tenant_username` (`tenant_id`,`username`,`deleted`),
  KEY `idx_sys_user_org` (`tenant_id`,`org_id`),
  KEY `idx_sys_user_post` (`tenant_id`,`post_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';
CREATE TABLE `course_kejian` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `sno` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编号',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `keshi` int DEFAULT NULL COMMENT '课时',
  `cover` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面',
  `type` int DEFAULT NULL COMMENT '类型',
  `price` decimal(10,2) DEFAULT NULL COMMENT '价格',
  `desction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '描述',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '文件路径',
  `work_type_id` bigint DEFAULT NULL COMMENT '工种ID',
  `tag` int DEFAULT NULL COMMENT '标签',
  `jigou_id` bigint DEFAULT NULL COMMENT '机构ID',
  `owner_id` bigint DEFAULT NULL COMMENT '所有者ID',
  `addtime` bigint DEFAULT NULL COMMENT '添加时间(时间戳)',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_course_kejian_work_type` (`work_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=40006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `demand_train` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `org_id` bigint NOT NULL,
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `nums` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0',
  `addtime` int DEFAULT NULL COMMENT '添加时间戳',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `created_by` bigint DEFAULT NULL,
  `updated_by` bigint DEFAULT NULL,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_demand_train_tenant_org` (`tenant_id`,`org_id`),
  KEY `idx_demand_train_status` (`tenant_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=10013 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `exam_operate_paper` (
  `id` int NOT NULL AUTO_INCREMENT,
  `make_id` int DEFAULT NULL COMMENT '关联组卷计划ID',
  `source` int DEFAULT '0' COMMENT '来源',
  `work_type_id` int DEFAULT NULL COMMENT '工种ID',
  `course_id` int DEFAULT NULL COMMENT '科目ID',
  `num` int DEFAULT '0' COMMENT '总题数',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编号',
  `level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级名(初级工/五级~首席技师)',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称',
  `time` int DEFAULT NULL COMMENT '考试时间(分钟)',
  `total_point` int DEFAULT '100' COMMENT '总分',
  `pass_point` int DEFAULT '60' COMMENT '及格分',
  `comments` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `user_id` int DEFAULT NULL COMMENT '创建人',
  `status` int DEFAULT '1' COMMENT '状态: 0=无效, 1=有效',
  `sort_number` int DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_operate_paper_make` (`tenant_id`,`make_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实操试卷';
CREATE TABLE `exam_user_auth_course` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uid` int DEFAULT NULL,
  `realname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专家姓名',
  `course_id` int DEFAULT NULL,
  `course_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '科目名称',
  `type` tinyint(1) DEFAULT '0' COMMENT '0命题科目 1审题科目 2终审科目',
  `user_id` int DEFAULT NULL,
  `id_card` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` bigint NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_uid` (`uid`),
  KEY `idx_course_id` (`course_id`),
  KEY `idx_realname_idcard` (`realname`,`id_card`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='专家授权科目';
CREATE TABLE `task_ximu_audit_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `expert_id` int NOT NULL COMMENT '专家用户ID',
  `audit_role` tinyint NOT NULL DEFAULT '0' COMMENT '审核角色 0初审 1终审',
  `task_id` int NOT NULL COMMENT '任务ID',
  `ximu_id` int NOT NULL COMMENT '细目ID',
  `sno` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '编号',
  `sno_item` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '细目编号',
  `sno_title` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核内容',
  `audit_status` tinyint NOT NULL DEFAULT '0' COMMENT '审核状态 0待审核 1已审核',
  `ymd` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核日期 YYYY-MM-DD',
  `addtime` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户ID',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除 0否 1是',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `created_by` int DEFAULT NULL COMMENT '创建人',
  `updated_by` int DEFAULT NULL COMMENT '更新人',
  `uptime` int NOT NULL DEFAULT '0' COMMENT '更新时间戳(phalcon用)',
  PRIMARY KEY (`id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_ximu_id` (`ximu_id`),
  KEY `idx_expert_id` (`expert_id`),
  KEY `idx_tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='细目表审核记录';
CREATE TABLE `train_class_list` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `train_id` bigint DEFAULT NULL COMMENT '培训ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `is_leader` int DEFAULT '0' COMMENT '是否组长 0-否 1-是',
  `is_committee` int DEFAULT '0' COMMENT '是否班委 0-否 1-是',
  `class_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '班级名称',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `status` int DEFAULT '0' COMMENT '状态 0-未开班 1-开班 2-结课',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_class_tenant` (`tenant_id`),
  KEY `idx_train_class_train` (`train_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_declare` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `train_id` bigint DEFAULT NULL COMMENT '培训ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `city_id` bigint DEFAULT NULL COMMENT '城市ID',
  `city_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市名称',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `status` int DEFAULT '0' COMMENT '状态',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_declare_tenant` (`tenant_id`),
  KEY `idx_train_declare_train` (`train_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_people_list` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `train_id` bigint DEFAULT NULL COMMENT '培训ID',
  `train_class_id` bigint DEFAULT NULL COMMENT '班级ID',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `platform_user_id` bigint DEFAULT NULL COMMENT '平台用户ID',
  `realname` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `is_leader` int DEFAULT '0' COMMENT '是否组长 0-否 1-是',
  `is_committee` int DEFAULT '0' COMMENT '是否班委 0-否 1-是',
  `exam_score` decimal(10,2) DEFAULT NULL COMMENT '考试成绩',
  `theory_score` decimal(10,2) DEFAULT NULL COMMENT '理论成绩',
  `real_score` decimal(10,2) DEFAULT NULL COMMENT '实操成绩',
  `performance_score` decimal(10,2) DEFAULT NULL COMMENT '工作业绩',
  `paper` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书',
  `normal_score` decimal(10,2) DEFAULT NULL COMMENT '平时成绩',
  `national_paper` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家证书',
  `current_level` int DEFAULT NULL COMMENT '当前等级',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `id_card` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `ticket_no` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '准考证号',
  `graduate_status` tinyint NOT NULL DEFAULT '0' COMMENT '0未结业/1已结业/2不合格',
  `graduate_at` datetime DEFAULT NULL COMMENT '结业时间',
  `graduate_by` bigint DEFAULT NULL COMMENT '结业操作人',
  `graduate_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结业备注',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_train_people_tenant` (`tenant_id`),
  KEY `idx_train_people_train` (`train_id`),
  KEY `idx_train_people_class` (`train_class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=61603 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_sign_up_people_self` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sign_up_id` int DEFAULT NULL,
  `name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `age` int DEFAULT NULL COMMENT '年龄',
  `req_work_type_id` int DEFAULT NULL COMMENT '工种',
  `req_work_type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种',
  `req_level` int DEFAULT '0',
  `job` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业',
  `work_type_id` int DEFAULT NULL COMMENT '工种',
  `work_type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工种',
  `level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0',
  `cert_verified` tinyint DEFAULT NULL COMMENT '证书查证状态：null未查证 0查证中 1已查证 2查证无结果 3查证失败',
  `company_id` int DEFAULT NULL,
  `company_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `department` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '部门',
  `company_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `zip_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `company_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `industrial_park` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工业园',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号',
  `user_id` int DEFAULT NULL,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `comments` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `company_status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint(1) DEFAULT '0',
  `id_card_front` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_card_back` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_card_header` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '一寸照',
  `id_card_header2` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '两寸照',
  `id_card_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gender` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '性别',
  `work_type_paper_has` int NOT NULL DEFAULT '0' COMMENT '是否有上一等级证书:0否,1是',
  `work_type_paper` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上一等级证书图片',
  `work_type_paper_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上一等级证书编号',
  `work_type_paper_level` int NOT NULL DEFAULT '0' COMMENT '上一等级证书等级',
  `work_type_paper_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上一等级证书工种',
  `work_date_start` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本公司入职日期',
  `work_date_end` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本公司在职结束日期',
  `work_time` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '从业日期',
  `title_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称',
  `title_major` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称专业',
  `title_cert_date` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称获证时间',
  `title_level` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title_paper` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称证',
  `has_pay` tinyint(1) DEFAULT '0',
  `school` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `major` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `in_school_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `graduate_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `school_paper_has` int NOT NULL DEFAULT '0' COMMENT '是否有毕业证:0否,1有',
  `school_paper` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `education` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `photo` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '照片路径',
  `contract` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '合同路径',
  `certificate` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书路径',
  `condition` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '申报条件',
  `school_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '毕业证编号',
  `paper_no` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证书编号',
  `cert_issue_dates` text COLLATE utf8mb4_unicode_ci COMMENT '发证日期（多证换行）',
  `certificates_json` text COLLATE utf8mb4_unicode_ci COMMENT '多证结构化 JSON',
  `data_source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'h5' COMMENT 'h5/wxmini/import/admin',
  `work_exp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '工作经历',
  `contact_first_page` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '劳动合同第一页',
  `contact_expire_page` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '劳动合同期限页',
  `contact_sign_page` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '劳动合同盖章页三页',
  `social_security` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '社保',
  `house_type` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '户口性质',
  `political` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '政治面貌',
  `task` int NOT NULL DEFAULT '1',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `jog` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '岗位',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `sign_up_id` (`sign_up_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=91371 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='预约报名人员列表';
CREATE TABLE `train_task_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `train_class_id` bigint DEFAULT NULL COMMENT '班级ID',
  `ck_id` bigint DEFAULT NULL COMMENT '签到ID',
  `date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '日期',
  `addtime` int DEFAULT NULL COMMENT '添加时间(时间戳)',
  `status` int DEFAULT NULL COMMENT '状态',
  `times` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  `tenant_id` bigint NOT NULL DEFAULT '1' COMMENT '租户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_train_task_log_class` (`train_class_id`)
) ENGINE=InnoDB AUTO_INCREMENT=70042 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `train_teacher_bank` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `phone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `id_card` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证',
  `teacher_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '教师资格证',
  `engineer_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '工程师证',
  `level_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '等级证',
  `edu_license` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历证',
  `graduate_paper` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '毕业证',
  `company` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司',
  `address` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址',
  `id_card_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `start_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '开始日期',
  `end_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结束日期',
  `birthday` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生日',
  `gender` int DEFAULT NULL COMMENT '性别',
  `nation` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '民族',
  `education` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '学历',
  `major` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业',
  `skill_name` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业技能名称',
  `qualification_level` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职业资格等级',
  `professional_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '专业技术职务',
  `cert_text` text COLLATE utf8mb4_unicode_ci COMMENT '资格证书原文',
  `teacher_qual_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '教师资格证号',
  `title_cert_no` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称证号',
  `skill_cert_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '技能等级证号摘要',
  `id_card_front_file_id` bigint DEFAULT NULL COMMENT '身份证正面文件',
  `id_card_back_file_id` bigint DEFAULT NULL COMMENT '身份证反面文件',
  `graduate_file_id` bigint DEFAULT NULL COMMENT '毕业证文件',
  `education_file_id` bigint DEFAULT NULL COMMENT '学历证文件',
  `teacher_qual_file_id` bigint DEFAULT NULL COMMENT '教师资格证文件',
  `title_cert_file_id` bigint DEFAULT NULL COMMENT '职称证文件',
  `skill_cert_file_id` bigint DEFAULT NULL COMMENT '技能等级证文件',
  `legacy_id` bigint DEFAULT NULL COMMENT 'PHP师资库原id',
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'legacy/excel/manual',
  `status` int DEFAULT '1' COMMENT '状态',
  `tenant_id` bigint NOT NULL COMMENT '租户ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `sort_number` int DEFAULT '0' COMMENT '排序号',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_teacher_bank_legacy` (`tenant_id`,`legacy_id`),
  KEY `idx_train_teacher_bank_tenant` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=50216 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `exam_operate_paper_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `paper_id` int NOT NULL COMMENT '实操试卷ID → exam_operate_paper.id',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `student_prepare` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '考生准备',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '内容',
  `score` decimal(10,2) DEFAULT NULL COMMENT '配分',
  `weight` int NOT NULL DEFAULT '100' COMMENT '兼容字段，实操评分固定100%且不参与计算',
  `equip_prepare` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '设备设施及准备',
  `exam_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '考试内容',
  `scoring_template_json` json DEFAULT NULL COMMENT '评分要素模板快照',
  `user_id` int DEFAULT NULL COMMENT '创建人',
  `status` int DEFAULT '1' COMMENT '状态: 0=无效, 1=有效',
  `sort_number` int DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL COMMENT '租户ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_operate_detail_paper` (`tenant_id`,`paper_id`)
) ENGINE=InnoDB AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='实操试卷详情';
CREATE TABLE `train_research_org` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `target_org_id` bigint DEFAULT NULL COMMENT '对应 sys_org.id',
  `active_sign_up_id` bigint DEFAULT NULL COMMENT '当前进行中的预报名批次',
  `personnel_count` int NOT NULL DEFAULT '0' COMMENT '已采集人数',
  `collection_field_options` text COLLATE utf8mb4_general_ci COMMENT '人员采集字段下拉选项 JSON',
  `type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '类型',
  `province_id` int DEFAULT NULL COMMENT '所在省',
  `province_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所在省',
  `city_id` int DEFAULT NULL COMMENT '所在市',
  `city_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所在市',
  `area_id` int DEFAULT NULL COMMENT '所在区',
  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '所在区',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='调研机构';
CREATE TABLE `train_solution_badge` (
  `id` int NOT NULL AUTO_INCREMENT,
  `solution_id` int DEFAULT NULL COMMENT '培训方案',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '费用名',
  `badge` decimal(10,2) DEFAULT NULL COMMENT '预算',
  `expend` decimal(10,2) DEFAULT NULL COMMENT '支出',
  `status` int NOT NULL DEFAULT '0' COMMENT '任务状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint(1) DEFAULT '0',
  `user_id` int DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=150 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='培训方案预算管理';
CREATE TABLE `cms_article` (
  `article_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(300) NOT NULL DEFAULT '' COMMENT '文章标题',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '分类类型 0列表 1单页 2外链',
  `show_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '列表显示方式(10小图展示 20大图展示)',
  `topic` varchar(200) DEFAULT NULL COMMENT '话题',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章分类ID',
  `image` varchar(300) DEFAULT '' COMMENT '封面图',
  `source` varchar(100) DEFAULT NULL COMMENT '来源',
  `virtual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '虚拟阅读量(仅用作展示)',
  `actual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '实际阅读量',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '发布来源客户端 (APP、H5、小程序等)',
  `album` text COMMENT '文章附件',
  `files` text COMMENT '文章附件',
  `video` varchar(200) DEFAULT '' COMMENT '视频地址',
  `accept` varchar(50) DEFAULT '' COMMENT '接受的文件类型',
  `longitude` varchar(100) DEFAULT NULL COMMENT '经度',
  `latitude` varchar(100) DEFAULT NULL COMMENT '纬度',
  `province` varchar(50) DEFAULT NULL COMMENT '所在省份',
  `city` varchar(50) DEFAULT NULL COMMENT '所在城市',
  `region` varchar(50) DEFAULT NULL COMMENT '所在辖区',
  `address` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '街道地址',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数',
  `comment_numbers` int unsigned DEFAULT '0' COMMENT '评论数',
  `to_users` varchar(200) DEFAULT '' COMMENT '提醒谁看',
  `recommend` tinyint DEFAULT '0' COMMENT '是否推荐',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `company_id` int DEFAULT NULL COMMENT '关联的企业id',
  `company_name` varchar(255) DEFAULT NULL COMMENT '关联的企业名称',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `template_name` varchar(500) DEFAULT NULL COMMENT '模板名称',
  `publish_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `read_times` int DEFAULT '0' COMMENT '浏览时长',
  `match_id` int NOT NULL DEFAULT '0',
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '工种id',
  `work_type_level` int NOT NULL DEFAULT '0' COMMENT '1:一级/高级技师,2:二级/技师,3:三级/高级工,4:四级/中级工,5:五级/初级工',
  PRIMARY KEY (`article_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=643 DEFAULT CHARSET=utf8 COMMENT='文章记录表';
CREATE TABLE `cms_article_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章分类ID',
  `category_code` varchar(50) NOT NULL DEFAULT '' COMMENT '分类标识',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0列表 1单页 2外链',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '分类图片',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `component` varchar(300) NOT NULL DEFAULT '' COMMENT '组件路径',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `count` int unsigned NOT NULL DEFAULT '0' COMMENT '文章数量',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `show_index` int NOT NULL DEFAULT '0' COMMENT '是否显示在首页',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1禁用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=353 DEFAULT CHARSET=utf8 COMMENT='文章分类表';
CREATE TABLE `cms_article_content` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `article_id` int unsigned DEFAULT '0' COMMENT '文章ID',
  `content` longtext COMMENT '文章内容',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `article_id` (`article_id`),
  CONSTRAINT `article_id_ibfk_1` FOREIGN KEY (`article_id`) REFERENCES `cms_article` (`article_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=574 DEFAULT CHARSET=utf8mb4 COMMENT='文章记录表';
CREATE TABLE `demand_employee` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `work` varchar(50) DEFAULT NULL COMMENT '岗位',
  `education` varchar(50) DEFAULT NULL COMMENT '学历',
  `major` varchar(50) DEFAULT NULL COMMENT '专业',
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='需求管理-人才需求';
CREATE TABLE `demand_science` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `content` varchar(500) DEFAULT NULL COMMENT '需求内容',
  `status` int NOT NULL DEFAULT '0' COMMENT '0待处理,1:已处理',
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='需求管理-技术需求';
CREATE TABLE `exam_course` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int DEFAULT NULL COMMENT '工种',
  `title` varchar(255) DEFAULT NULL COMMENT '科目名称',
  `level` tinyint DEFAULT '0' COMMENT '0初级1中级2高级3技师4高级技师',
  `series_no_group` varchar(200) DEFAULT NULL COMMENT '科目编码(编组)',
  `series_no` varchar(200) DEFAULT NULL COMMENT '科目编码',
  `user_in_charge` int DEFAULT NULL COMMENT '拥有者',
  `last_level_get_year` int DEFAULT '0' COMMENT '上级获得年份要求',
  `work_year_limit` int DEFAULT NULL COMMENT '累计从事本职业或相关职业工作年',
  `min_level` int DEFAULT NULL COMMENT '最低证书要求',
  `min_level_year` int DEFAULT NULL COMMENT '最低证书获得年',
  `start_age` int DEFAULT '0' COMMENT '开始年龄',
  `is_general` tinyint DEFAULT '0' COMMENT '是否通用资源',
  `exam_condition` text,
  `version` varchar(255) DEFAULT NULL COMMENT '版本',
  `comments` varchar(255) DEFAULT NULL COMMENT '描述',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `work_type_id` (`work_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=293 DEFAULT CHARSET=utf8mb4 COMMENT='科目';
CREATE TABLE `exam_exam_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT '0' COMMENT 'exam_list主键',
  `knowledge_id` int DEFAULT NULL COMMENT '知识id',
  `task_detail_id` int DEFAULT '0' COMMENT '任务详情id',
  `is_private` tinyint DEFAULT '0' COMMENT '是否保密',
  `difficulty` tinyint DEFAULT '0' COMMENT '难度(0易1较易2中3较难4难)',
  `user_id` int DEFAULT NULL COMMENT '撰题人',
  `type` varchar(255) DEFAULT NULL COMMENT '试题类型',
  `source` tinyint DEFAULT '0' COMMENT '0内部  1外部',
  `keyword` varchar(255) DEFAULT NULL COMMENT '关键字',
  `audio` varchar(255) DEFAULT NULL COMMENT '音频',
  `video` varchar(255) DEFAULT NULL COMMENT '视频',
  `content` text COMMENT '内容',
  `answer` text COMMENT '答案',
  `score` decimal(10,1) unsigned DEFAULT '0.0' COMMENT '分值',
  `resolve` varchar(255) DEFAULT NULL COMMENT '解析',
  `suggest` text COMMENT '意见',
  `check_status` tinyint DEFAULT '0' COMMENT '0待审核1通过2不通过',
  `final_check_status` tinyint DEFAULT '0' COMMENT '终审 0待审核1通过2不通过',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `check_time` timestamp NULL DEFAULT NULL COMMENT '审题时间',
  `check_user_id` int DEFAULT NULL COMMENT '审题用户',
  `final_check_time` timestamp NULL DEFAULT NULL COMMENT '终审时间',
  `final_check_user_id` int DEFAULT NULL COMMENT '终审用户',
  `deleted` tinyint DEFAULT '0',
  `org_id` int DEFAULT NULL COMMENT '企业id',
  `org_name` varchar(255) DEFAULT NULL COMMENT '企业名称',
  `sno` varchar(30) DEFAULT NULL COMMENT '试题唯一编码',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `exam_id` (`exam_id`),
  KEY `knowledge_id` (`knowledge_id`),
  KEY `task_detail_id` (`task_detail_id`),
  KEY `difficulty` (`difficulty`),
  KEY `type` (`type`),
  KEY `source` (`source`),
  KEY `check_status` (`check_status`),
  KEY `final_check_status` (`final_check_status`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`),
  KEY `org_id` (`org_id`),
  KEY `org_name` (`org_name`),
  KEY `check_user_id` (`check_user_id`),
  KEY `final_check_user_id` (`final_check_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=385535 DEFAULT CHARSET=utf8mb4 COMMENT='命题详情';
CREATE TABLE `exam_knowledge_rate` (
  `id` int NOT NULL AUTO_INCREMENT,
  `course_id` int DEFAULT NULL COMMENT '科目id',
  `type` tinyint DEFAULT '0' COMMENT '0理论  1实操',
