  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(1000) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COMMENT='知识比重';
CREATE TABLE `exam_knowledge_rate_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `knowledge_rate_id` int DEFAULT NULL COMMENT '比重id',
  `knowledge_id` int DEFAULT NULL COMMENT '知识结构id',
  `rate` int DEFAULT NULL COMMENT '比重',
  `user_id` int DEFAULT NULL,
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(1000) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1368 DEFAULT CHARSET=utf8mb4 COMMENT='知识比重详情';
CREATE TABLE `exam_operate_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `course_id` int DEFAULT NULL COMMENT '科目',
  `work_type_id` int DEFAULT NULL COMMENT '工种',
  `knowledge_id` int DEFAULT NULL,
  `title` varchar(500) DEFAULT NULL,
  `student_prepare` text COMMENT '考生准备',
  `content` text COMMENT '内容',
  `score` decimal(10,1) DEFAULT NULL COMMENT '配分',
  `weight` int DEFAULT NULL COMMENT '权重',
  `equip_prepare` text COMMENT '设备设施及准备',
  `exam_content` text COMMENT '考试内容',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=183 DEFAULT CHARSET=utf8mb4 COMMENT='实操试题';
CREATE TABLE `exam_paper` (
  `id` int NOT NULL AUTO_INCREMENT,
  `source` int NOT NULL DEFAULT '0' COMMENT '0内部,1外部',
  `type` tinyint DEFAULT '0' COMMENT '0理论 1实操',
  `make_id` int DEFAULT NULL,
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '工种id',
  `level` int NOT NULL DEFAULT '0' COMMENT '工种等级',
  `code` varchar(255) DEFAULT NULL COMMENT '编号',
  `title` varchar(255) DEFAULT NULL COMMENT '名称',
  `nums` int NOT NULL DEFAULT '0' COMMENT '题量',
  `time` int DEFAULT NULL COMMENT '考试时间',
  `is_computer` tinyint DEFAULT '0' COMMENT '是否机考',
  `is_print` tinyint DEFAULT NULL COMMENT '是否打印',
  `total_point` int DEFAULT NULL COMMENT '总分',
  `pass_point` int DEFAULT NULL COMMENT '及格分',
  `comments` varchar(255) DEFAULT NULL COMMENT '描述',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `file_path` varchar(200) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `type` (`type`),
  KEY `source` (`source`),
  KEY `title` (`title`)
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `exam_paper_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `paper_id` int DEFAULT NULL COMMENT 'paper_list主键',
  `exam_id` int DEFAULT NULL COMMENT '命题id',
  `type` varchar(255) DEFAULT NULL COMMENT '试题类型',
  `content` text COMMENT '内容',
  `answer` text COMMENT '答案',
  `score` decimal(10,1) unsigned DEFAULT '0.0' COMMENT '分值',
  `resolve` varchar(255) DEFAULT NULL COMMENT '解析',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `diff` tinyint DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `paper_id` (`paper_id`),
  KEY `exam_id` (`exam_id`),
  KEY `type` (`type`),
  KEY `status` (`status`),
  KEY `sort_number` (`sort_number`),
  KEY `tenant_id` (`tenant_id`),
  KEY `create_time` (`create_time`),
  KEY `diff` (`diff`)
) ENGINE=InnoDB AUTO_INCREMENT=12069 DEFAULT CHARSET=utf8mb4 COMMENT='试卷详情';
CREATE TABLE `exam_result` (
  `id` int NOT NULL AUTO_INCREMENT,
