  `exam_plan_id` int NOT NULL DEFAULT '0' COMMENT 'train_exam_list表id',
  `paper_id` int DEFAULT NULL COMMENT '试卷id',
  `detail_id` int DEFAULT NULL COMMENT '题目id',
  `get_score` decimal(5,1) DEFAULT NULL COMMENT '获得分数',
  `exam_type` tinyint DEFAULT '0' COMMENT '0正考  1模拟考  2能力测评  3顺序练习 4随机练习',
  `exam_id` int DEFAULT NULL COMMENT '配置试卷的sim_exam/exam 主键,app3.2.3版本开始表示paper_detail表的exam_id',
  `user_id` int DEFAULT NULL,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `user_answer` text,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `type` (`type`),
  KEY `paper_id` (`paper_id`),
  KEY `detail_id` (`detail_id`),
  KEY `exam_type` (`exam_type`),
  KEY `exam_id` (`exam_id`),
  KEY `user_id` (`user_id`),
  KEY `deleted` (`deleted`),
  KEY `sort_number` (`sort_number`),
  KEY `tenant_id` (`tenant_id`),
  KEY `create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=262621 DEFAULT CHARSET=utf8mb4 COMMENT='考试结果';
CREATE TABLE `exam_work_type` (
