CREATE TABLE `task_ximu` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '工种id',
  `level` int NOT NULL DEFAULT '0' COMMENT '1高级技题,2技师,3高级工,4中级工,5初级工	',
  `status` int NOT NULL DEFAULT '0' COMMENT '0待审核,1初审中,2终审中,3完成',
  `addtime` int NOT NULL,
  `expert_start` int NOT NULL DEFAULT '0' COMMENT '初审专家id',
  `expert_end` int NOT NULL DEFAULT '0' COMMENT '终审专家id',
