  `nums` int NOT NULL DEFAULT '0' COMMENT '题量',
  `types` int NOT NULL DEFAULT '0' COMMENT '0理论,1实操',
  `is_archived` tinyint NOT NULL DEFAULT '0' COMMENT '是否已归档',
  `archived_at` datetime DEFAULT NULL COMMENT '归档时间',
  `archived_reason` varchar(50) DEFAULT NULL COMMENT '归档原因',
  PRIMARY KEY (`id`),
  KEY `idx_task_ximu_wt_lvl_type_arch` (`work_type_id`,`level`,`types`,`is_archived`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `task_ximu_detail` (
