  `sno_1` varchar(100) DEFAULT NULL COMMENT '考评范围_二级',
  `title` varchar(500) DEFAULT NULL COMMENT '考评范围_三级',
  `sno_item` varchar(50) DEFAULT NULL COMMENT '考评点_代码',
  `sno_title` varchar(500) DEFAULT NULL COMMENT '考评点_名称内容',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5803 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_ability_comment_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `score` tinyint DEFAULT NULL COMMENT '分数',
