  `sno` varchar(50) DEFAULT NULL COMMENT '编号',
  `title` varchar(100) DEFAULT NULL COMMENT '名称',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb4 COMMENT='培训导入表基础数据表';
CREATE TABLE `train_brushing` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `course_id` int DEFAULT NULL,
  `knowledge_id` int DEFAULT NULL,
  `score` decimal(10,0) DEFAULT '0',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COMMENT='刷题配置';
CREATE TABLE `train_budget` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `province` varchar(255) DEFAULT NULL COMMENT '省',
  `city` varchar(255) DEFAULT NULL COMMENT '市',
  `region` varchar(255) DEFAULT NULL COMMENT '市',
  `org_id` int DEFAULT NULL COMMENT '企业id',
  `org_name` varchar(255) DEFAULT NULL COMMENT '企业',
  `train_date` varchar(50) DEFAULT NULL COMMENT '培训时间',
  `train_work_type_id` int DEFAULT NULL COMMENT '培训工种id',
  `train_work_type_name` varchar(255) DEFAULT NULL COMMENT '培训工种',
  `train_level` varchar(255) DEFAULT NULL COMMENT '培训级别',
  `bonus_standard` varchar(255) DEFAULT NULL COMMENT '补贴标准',
  `expect_income` decimal(10,2) DEFAULT '0.00' COMMENT '预计收入',
  `actual_income` decimal(10,2) DEFAULT NULL COMMENT '实际收入',
  `school_manage_fee` decimal(10,2) DEFAULT NULL COMMENT '学校管理费',
  `manage_fee` decimal(10,2) DEFAULT NULL COMMENT '公司运营管理费（含APP支持、等费用）',
  `research_fee` decimal(10,2) DEFAULT NULL COMMENT '研发费用',
  `company_require_commission` decimal(10,2) DEFAULT NULL COMMENT '企业要求分成',
  `agent_require_commission` decimal(10,2) DEFAULT NULL COMMENT '中介要求分成',
  `teacher_course_fee` decimal(10,2) DEFAULT NULL COMMENT '培训讲师课酬（含师傅带徒费用）',
  `teacher_fee` decimal(10,2) DEFAULT NULL COMMENT '培训讲师（含师傅）食宿差旅费',
  `staff_fee` decimal(10,2) DEFAULT NULL COMMENT '工作人员（含调研人员、教务人员、助教及其它人员）劳务费用',
  `staff_travel_fee` decimal(10,2) DEFAULT NULL COMMENT '工作人员（含调研人员、教务人员、助教及其它人员）食宿差旅费',
  `train_fee` decimal(10,2) DEFAULT NULL COMMENT '培训耗材费',
  `point_rewards` decimal(10,2) DEFAULT NULL COMMENT '积分奖励',
  `business_fee` decimal(10,0) DEFAULT NULL COMMENT '业务招待费',
  `people_num` int DEFAULT NULL COMMENT '认定人数',
  `charge_fee` varchar(255) DEFAULT NULL COMMENT '收费标准',
  `service_fee` decimal(10,2) DEFAULT NULL COMMENT '行业服务费',
  `review_fee` decimal(10,2) DEFAULT NULL COMMENT '评审费用',
  `maintain_fee` decimal(10,2) DEFAULT NULL COMMENT '认定金额',
  `makeup_people_num` int DEFAULT NULL COMMENT '补考人数',
  `theory_makeup_people_num` int DEFAULT NULL COMMENT '理论补考',
  `operation_makeup_people_num` int DEFAULT NULL COMMENT '实操补考',
  `staff_makeup_train_fee` decimal(10,2) DEFAULT NULL COMMENT '工作人员差旅费',
  `review_makeup_train_fee` decimal(10,2) DEFAULT NULL COMMENT '考评员差旅费',
  `profit` decimal(10,2) DEFAULT NULL COMMENT '项目利润',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `user_id` int NOT NULL DEFAULT '1',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `sort_number` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='培训费用';
CREATE TABLE `train_course` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `teacher_id_card` varchar(255) DEFAULT NULL COMMENT '教师身份证',
  `teacher_name` varchar(20) DEFAULT NULL COMMENT '教师名字',
  `teacher_user_id` int DEFAULT NULL COMMENT '教师id',
  `type` tinyint DEFAULT '1' COMMENT '1理论  2实操',
  `course_date` varchar(20) DEFAULT NULL COMMENT '上课日期',
  `title` varchar(500) DEFAULT NULL COMMENT '课程名称',
  `start_time` varchar(20) DEFAULT NULL COMMENT '上课时间',
  `end_time` varchar(20) DEFAULT NULL COMMENT '下课时间',
  `theory_time` int DEFAULT NULL COMMENT '理论课时',
  `operation_time` int DEFAULT NULL COMMENT '实操课时',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=859 DEFAULT CHARSET=utf8mb4 COMMENT='课时列表';
CREATE TABLE `train_declare_fields` (
  `id` int NOT NULL AUTO_INCREMENT,
  `declare_id` int DEFAULT NULL,
  `field_name` varchar(255) DEFAULT NULL COMMENT '字段名',
  `type` varchar(20) DEFAULT NULL COMMENT '类型',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_declare_user_data` (
  `id` int NOT NULL AUTO_INCREMENT,
  `declare_id` int DEFAULT NULL,
  `field_name` varchar(255) DEFAULT NULL,
  `field_data` varchar(500) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COMMENT='用户申报数据';
CREATE TABLE `train_department_confirm` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_info_id` int DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL COMMENT '用户名',
  `organization_name` varchar(255) DEFAULT NULL COMMENT '部门',
  `user_id` int DEFAULT NULL,
  `feedback` varchar(255) DEFAULT NULL COMMENT '反馈',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=163 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_dev_organization` (
  `organization_id` int NOT NULL AUTO_INCREMENT COMMENT '机构id',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `organization_name` varchar(200) NOT NULL DEFAULT '' COMMENT '机构名称',
  `organization_full_name` varchar(200) DEFAULT NULL COMMENT '机构全称',
  `organization_code` varchar(100) DEFAULT NULL COMMENT '机构代码',
  `organization_type` varchar(100) NOT NULL DEFAULT '' COMMENT '机构类型',
  `province` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在辖区',
  `zip_code` varchar(100) DEFAULT NULL COMMENT '邮政编码',
  `park` varchar(200) NOT NULL DEFAULT '' COMMENT '所属园区',
  `phone` varchar(100) NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT '企业邮箱',
  `establish_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '成立日期',
  `registered_capital` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '注册资本',
  `business` varchar(200) NOT NULL DEFAULT '' COMMENT '经营范围',
  `business_status` varchar(50) DEFAULT '' COMMENT '经营状态',
  `insureds` int DEFAULT NULL COMMENT '参保人数',
  `industry` varchar(100) NOT NULL DEFAULT '' COMMENT '所属行业',
  `estate` varchar(255) DEFAULT NULL COMMENT '所属产业',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '园区图片',
  `about` varchar(3000) NOT NULL DEFAULT '' COMMENT '园区介绍',
  `is_coop` tinyint DEFAULT '0' COMMENT '是否合作单位',
  `leader_id` int DEFAULT NULL COMMENT '负责人id',
  `legal_person` varchar(255) DEFAULT NULL COMMENT '法定代表人',
  `set_up_date` varchar(20) DEFAULT NULL COMMENT '成立日期',
  `tag` varchar(200) DEFAULT NULL COMMENT '企业标签',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`organization_id`) USING BTREE,
  KEY `leader_id` (`leader_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=211 DEFAULT CHARSET=utf8mb4 COMMENT='开发单位';
CREATE TABLE `train_exam_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `level` varchar(255) DEFAULT NULL,
  `train_id` int DEFAULT NULL,
  `org_id` int NOT NULL,
  `org_name` varchar(255) DEFAULT NULL,
  `type` tinyint DEFAULT '0' COMMENT '0线上  1线下',
  `source` tinyint DEFAULT '0' COMMENT '0内部  1外部',
  `invigilate_user_id` int DEFAULT NULL COMMENT '监考人',
  `invigilate_username` varchar(255) DEFAULT NULL COMMENT '监考人',
  `evaluate_user_id` int DEFAULT NULL COMMENT '考评人',
  `evaluate_username` varchar(255) DEFAULT NULL COMMENT '考评人',
  `watcher_user_id` int DEFAULT NULL COMMENT '督导员',
  `watcher_username` varchar(255) DEFAULT NULL COMMENT '督导员',
  `staff_user_id` int DEFAULT NULL COMMENT '考务人员',
  `staff_username` varchar(255) DEFAULT NULL COMMENT '考务人员',
  `proposition_user_id` int DEFAULT NULL COMMENT '命题人员',
  `proposition_username` varchar(255) DEFAULT NULL COMMENT '命题人员',
  `marking_user_id` int DEFAULT NULL COMMENT '阅卷人员',
  `marking_username` varchar(255) DEFAULT NULL COMMENT '阅卷人员',
  `exam_id` int DEFAULT NULL COMMENT '试卷id',
  `exam_date` varchar(20) DEFAULT NULL COMMENT '考试日期',
  `exam_date_mode` tinyint DEFAULT '0' COMMENT '0截止日期 1时间段（仅限线上）',
  `exam_date_list` text COMMENT '考试日期',
  `exam_time` int DEFAULT NULL COMMENT '考试时间(分钟)',
  `need_finish_adventure` tinyint DEFAULT '0' COMMENT '是否需要先完成游戏学',
  `need_finish_normal` tinyint DEFAULT '0' COMMENT '是否需要先完成常规学',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `jigou_id` int NOT NULL DEFAULT '1' COMMENT '机构id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`,`org_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=466 DEFAULT CHARSET=utf8mb4 COMMENT='考试';
CREATE TABLE `train_exam_paper` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `exam_room_id` int DEFAULT NULL,
  `room_id` int DEFAULT NULL,
  `paper_id` int DEFAULT NULL,
  `operate_paper_id` int DEFAULT NULL COMMENT '实操试卷',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COMMENT='试卷派发';
CREATE TABLE `train_exam_people_in_room` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `course_id` int DEFAULT NULL COMMENT '工种id',
  `session_id` int DEFAULT NULL COMMENT '场次id',
  `room_id` int DEFAULT NULL COMMENT '考场id',
  `exam_room_id` int DEFAULT NULL COMMENT '考试考场id',
  `user_id` int DEFAULT NULL,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `realname` varchar(20) DEFAULT NULL COMMENT '姓名',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `id_card_num` varchar(100) DEFAULT NULL COMMENT '身份证',
  `gender` tinyint DEFAULT '0' COMMENT '性别',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=utf8mb4 COMMENT='考场人员列表';
CREATE TABLE `train_exam_people_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL COMMENT '考试计划id',
  `train_id` int DEFAULT NULL,
  `work_type_id` int DEFAULT NULL COMMENT '考试工种',
  `work_type_level` tinyint DEFAULT '0' COMMENT '等级',
  `user_id` int DEFAULT NULL,
  `id_card_num` varchar(100) DEFAULT NULL COMMENT '身份证',
  `gender` tinyint DEFAULT '0' COMMENT '性别',
  `realname` varchar(20) DEFAULT NULL COMMENT '姓名',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号',
  `education` varchar(50) DEFAULT NULL COMMENT '文化程度',
  `result_file_list` text COMMENT '考卷',
  `org_id` int DEFAULT NULL,
  `org_name` varchar(255) DEFAULT NULL,
  `room_id` int DEFAULT NULL COMMENT '考场id',
  `score` decimal(10,2) DEFAULT '0.00' COMMENT '分数',
  `normal_score` decimal(10,2) DEFAULT '0.00' COMMENT '平时分',
  `origin_normal_score` decimal(10,2) DEFAULT '0.00' COMMENT '原平时分',
  `operate_score` decimal(10,2) DEFAULT '0.00' COMMENT '实操分数',
  `real_score` decimal(10,2) DEFAULT '0.00' COMMENT '实操分数',
  `total_score` decimal(10,2) DEFAULT '0.00' COMMENT '总分',
  `has_set_real_score` tinyint DEFAULT '0' COMMENT '是否已手动设置真实分数',
  `high_level_status` tinyint DEFAULT '0' COMMENT '技师、高级技师论文答辩,专家评审结果',
  `result_paper` text COMMENT '工作结果证明',
  `in_white_list` tinyint DEFAULT '0' COMMENT '白名单内，不用先学游戏学',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `paper` varchar(500) DEFAULT NULL,
  `nation_paper` varchar(500) DEFAULT NULL,
  `learn_time` int DEFAULT '0' COMMENT '学习次数',
  `learn_use_time` int DEFAULT '0' COMMENT '学习时间',
  `platform_user_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `exam_id` (`exam_id`),
  KEY `train_id` (`train_id`),
  KEY `work_type_id` (`work_type_id`),
  KEY `user_id` (`user_id`),
  KEY `id_card_num` (`id_card_num`),
  KEY `phone` (`phone`),
  KEY `room_id` (`room_id`),
  KEY `deleted` (`deleted`),
  KEY `sort_number` (`sort_number`),
  KEY `tenant_id` (`tenant_id`),
  KEY `create_time` (`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=15948 DEFAULT CHARSET=utf8mb4 COMMENT='考试人员列表';
CREATE TABLE `train_exam_review` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL COMMENT 'train_exam_list主键',
  `paper_id` int DEFAULT NULL,
  `num` int DEFAULT NULL,
  `comments` varchar(255) DEFAULT NULL COMMENT '描述',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `jigou_id` int NOT NULL DEFAULT '0' COMMENT '机构id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=240 DEFAULT CHARSET=utf8mb4 COMMENT='考试复习';
CREATE TABLE `train_exam_room_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `course_id` int DEFAULT NULL COMMENT '工种id',
  `session_id` int DEFAULT NULL COMMENT '场次id',
  `room_id` int DEFAULT NULL COMMENT '考场id',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_exam_session` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `course_id` int DEFAULT NULL,
  `start_time` varchar(20) DEFAULT NULL,
  `end_time` varchar(20) DEFAULT NULL,
  `course_name` varchar(255) DEFAULT NULL COMMENT '考试科目',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8mb4 COMMENT='场次';
CREATE TABLE `train_exam_shijuan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int NOT NULL DEFAULT '0' COMMENT 'train_exam_list表id',
  `paper_id` int NOT NULL DEFAULT '0' COMMENT 'exam_paper表id',
  `plan_type` int NOT NULL DEFAULT '0' COMMENT '计划类型:0考试,1复习',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COMMENT='考试计划、复习计划绑定试卷表';
CREATE TABLE `train_exam_staff` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `exam_room_id` int DEFAULT NULL,
  `room_id` int DEFAULT NULL,
  `type` varchar(20) DEFAULT NULL COMMENT '人员类型',
  `realname` varchar(50) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COMMENT='考务人员';
CREATE TABLE `train_exam_staff_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(20) DEFAULT NULL COMMENT '人员类型',
  `realname` varchar(50) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COMMENT='考务人员';
CREATE TABLE `train_exam_work_type_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `work_type_id` int DEFAULT NULL,
  `level` tinyint DEFAULT '0',
  `course_id` int DEFAULT NULL COMMENT '科目',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1068 DEFAULT CHARSET=utf8mb4 COMMENT='考试工种';
CREATE TABLE `train_file_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `file_id` int DEFAULT NULL COMMENT 'file_list 主键',
  `title` varchar(255) DEFAULT NULL COMMENT '文件名',
  `path` varchar(500) DEFAULT NULL COMMENT '路径',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=311 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_group_ability` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `course_id` int DEFAULT NULL COMMENT '科目',
  `knowledge_id` int DEFAULT NULL,
  `result` varchar(500) DEFAULT NULL,
  `config_id` int DEFAULT NULL COMMENT '标题',
  `score` tinyint DEFAULT NULL COMMENT '得分',
  `current_score` tinyint DEFAULT NULL COMMENT '当前',
  `user_id` int DEFAULT NULL,
  `comments` varchar(20) DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=110 DEFAULT CHARSET=utf8mb4 COMMENT='技能矩阵';
CREATE TABLE `train_group_ability_task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ability_id` int DEFAULT NULL,
  `task_num` int DEFAULT '0',
  `done_num` int DEFAULT '0',
  `title` varchar(255) DEFAULT NULL COMMENT '科目',
  `point` decimal(10,3) DEFAULT '0.000',
  `get_point` decimal(10,3) DEFAULT '0.000',
  `result` text,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='技能矩阵';
CREATE TABLE `train_group_album` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `image` varchar(500) DEFAULT NULL,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_group_knowledge` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL,
  `filename` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `intro` varchar(500) DEFAULT NULL,
  `cover` varchar(500) DEFAULT NULL,
  `content` varchar(500) DEFAULT NULL,
  `get_point` int DEFAULT '0',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态,',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `check_status` tinyint DEFAULT '0' COMMENT '0待审核1通过2不通过',
  `check_user_id` int DEFAULT NULL COMMENT '审题用户',
  `check_username` varchar(255) DEFAULT NULL COMMENT '审题用户',
  `check_time` timestamp NULL DEFAULT NULL COMMENT '审题时间',
  `final_check_status` tinyint DEFAULT '0' COMMENT '终审 0待审核1通过2不通过',
  `final_check_time` timestamp NULL DEFAULT NULL COMMENT '终审时间',
  `final_check_user_id` int DEFAULT NULL COMMENT '终审用户',
  `final_check_username` varchar(255) DEFAULT NULL COMMENT '审题用户',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_group_point_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_id` int DEFAULT NULL,
  `point` int DEFAULT NULL,
  `scene` varchar(255) DEFAULT NULL,
  `content` varchar(255) DEFAULT NULL,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
