  `org_type` varchar(50) DEFAULT NULL COMMENT '企业性质',
  `org_province_id` int DEFAULT NULL COMMENT '所在省',
  `org_province_name` varchar(50) DEFAULT NULL COMMENT '所在省',
  `org_city_id` int DEFAULT NULL COMMENT '所在市',
  `org_city_name` varchar(50) DEFAULT NULL COMMENT '所在市',
  `org_area_id` int DEFAULT NULL COMMENT '所在区',
  `org_area_name` varchar(50) DEFAULT NULL COMMENT '所在区',
  `org_industry` varchar(50) DEFAULT NULL COMMENT '行业属性',
