) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COMMENT='调研导出字段';
CREATE TABLE `train_research_people_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `research_id` int DEFAULT NULL COMMENT '调研id',
  `research_org_id` int DEFAULT NULL COMMENT '调研机构',
  `research_org_type` varchar(200) DEFAULT NULL COMMENT '调研机构类型',
  `research_site_id` int DEFAULT NULL COMMENT '调研站点',
  `year` varchar(10) DEFAULT NULL COMMENT '采集年份',
  `name` varchar(20) DEFAULT NULL COMMENT '姓名',
  `gender` tinyint DEFAULT '0' COMMENT '性别(0男  1女)',
  `birthday` varchar(20) DEFAULT NULL COMMENT '出生日期',
  `age` int DEFAULT NULL COMMENT '年龄',
  `position` varchar(50) DEFAULT NULL COMMENT '岗位',
  `work_type_id` int DEFAULT NULL COMMENT '工种',
  `qualification_level` varchar(50) DEFAULT '0' COMMENT '资格证书级别（无证书、学徒工、初级工、中级工、高级工、技师、高级技师、特级技师、首席技师）',
  `cert_level` varchar(50) DEFAULT NULL COMMENT '职称证书级别（无证书、助理工程师、中级工程师、高级工程师、教授级高级工程师）',
  `inducation_cert` varchar(50) DEFAULT NULL COMMENT '上岗证书',
  `education` varchar(50) DEFAULT NULL COMMENT '学历',
  `people_type` varchar(50) DEFAULT NULL COMMENT '人员类型（管理人员、技术人员、技能人员）',
  `talent_type` varchar(50) DEFAULT NULL COMMENT '人才类型（政府授予的荣誉称号）',
  `sign_start_date` varchar(20) DEFAULT NULL COMMENT '劳动合同开始时间',
  `sign_end_date` varchar(20) DEFAULT NULL COMMENT '劳动合同结束时间',
  `start_work_date` varchar(20) DEFAULT NULL COMMENT '开始该工作的时间',
  `get_cert_date` varchar(20) DEFAULT NULL COMMENT '获得职称证书时间',
  `get_qualification_date` varchar(20) DEFAULT NULL COMMENT '获得资格证书时间',
  `get_inducation_date` varchar(20) DEFAULT NULL COMMENT '获得上岗证书时间',
  `is_unemployment` tinyint DEFAULT '0' COMMENT '是否城镇登记失业人员',
  `is_from_countryside` tinyint DEFAULT '0' COMMENT '是否农村转移就业劳动者',
  `graduate_year` varchar(20) DEFAULT NULL COMMENT '大学以上的毕业年份',
  `is_middle_school_urban` tinyint DEFAULT '0' COMMENT '是否城镇户籍未继续升学的初高中毕业',
  `is_middle_school_countryside` tinyint DEFAULT '0' COMMENT '是否乡村户籍未继续升学的初高中毕业',
  `is_poor_urban` tinyint DEFAULT NULL COMMENT '是否城镇户籍贫困劳动力',
  `is_poor_countryside` tinyint DEFAULT NULL COMMENT '是否乡村户籍贫困劳动力',
  `is_soldier` tinyint DEFAULT '0' COMMENT '是否退役军人',
  `is_soldier_family` tinyint DEFAULT '0' COMMENT '是否随军家属',
  `is_farmer` tinyint DEFAULT '0' COMMENT '是否返乡农民工',
  `is_staff` tinyint DEFAULT NULL COMMENT '是否在职职工',
  `source` varchar(50) DEFAULT NULL COMMENT '来源',
  `province_id` int DEFAULT NULL,
  `province_name` varchar(50) DEFAULT NULL,
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=122 DEFAULT CHARSET=utf8mb4 COMMENT='调研企业人员列表';
