CREATE TABLE `exam_knowledge_structure` (
  `id` int NOT NULL AUTO_INCREMENT,
  `use_type` tinyint DEFAULT '0' COMMENT '0其他  1题库/课件/教材',
  `type` tinyint DEFAULT '0' COMMENT '0理论  1实操',
  `cover` varchar(255) DEFAULT NULL,
  `intro` varchar(255) DEFAULT NULL,
  `course_id` int DEFAULT NULL,
  `parent_id` int DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `series_no` varchar(200) DEFAULT NULL COMMENT '科目编码',
  `level` tinyint DEFAULT '0' COMMENT '等级',
  `important` varchar(10) DEFAULT NULL COMMENT '重要等级',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `org_id` int DEFAULT NULL COMMENT '企业id',
  `org_name` varchar(255) DEFAULT NULL COMMENT '企业名称',
  `amount` decimal(10,2) DEFAULT '0.00' COMMENT '价格',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `type` (`type`),
  KEY `course_id` (`course_id`),
  KEY `parent_id` (`parent_id`),
  KEY `title` (`title`),
  KEY `series_no` (`series_no`),
  KEY `level` (`level`),
  KEY `sort_number` (`sort_number`),
  KEY `status` (`status`),
  KEY `tenant_id` (`tenant_id`),
  KEY `create_time` (`create_time`),
  KEY `deleted` (`deleted`),
  KEY `org_id` (`org_id`)
) ENGINE=InnoDB AUTO_INCREMENT=29389 DEFAULT CHARSET=utf8mb4 COMMENT='知识结果';
CREATE TABLE `exam_make_exam_plan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` tinyint DEFAULT '0' COMMENT '0内部1外部',
  `exam_type` tinyint DEFAULT '0' COMMENT '0理论1实操',
  `course_id` int DEFAULT NULL COMMENT '科目id',
  `rate_id` int DEFAULT NULL COMMENT '比重id',
  `title` varchar(255) DEFAULT NULL COMMENT '名称',
  `time` int DEFAULT NULL COMMENT '时长(分钟)',
  `is_computer` tinyint DEFAULT '0' COMMENT '是否机考',
  `is_print` tinyint DEFAULT NULL COMMENT '是否打印',
  `open_rate` tinyint DEFAULT '100' COMMENT '公开比例',
  `total_point` tinyint DEFAULT '100' COMMENT '总分值',
  `pass_point` tinyint DEFAULT NULL COMMENT '及格分数',
  `comments` varchar(255) DEFAULT NULL COMMENT '描述',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_all` tinyint DEFAULT '0' COMMENT '是否选择全部题目',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COMMENT='组卷计划';
CREATE TABLE `exam_make_exam_plan_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `make_id` int DEFAULT NULL COMMENT '名称',
  `course_id` int DEFAULT NULL,
  `type` enum('judge','single','multi','sort','answer','single_discrete','multi_discrete','match','simple_fill','fill','cal','essay','explain','drafting','correct','design','action','sim','example','context','cal-analysis','drag','analysis') DEFAULT NULL COMMENT '试题类型',
  `num` int DEFAULT '0' COMMENT '数量',
  `point` decimal(10,2) DEFAULT NULL COMMENT '分值',
  `start_point` tinyint DEFAULT '100' COMMENT '参考分值(开始)',
  `end_point` tinyint DEFAULT '100' COMMENT '参考分值(结束)',
  `difficulty_start` tinyint DEFAULT '0' COMMENT '难度(开始)',
  `difficulty_end` tinyint DEFAULT '0' COMMENT '难度(结束)',
  `total_point` decimal(10,2) DEFAULT '0.00' COMMENT '总分值',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=218 DEFAULT CHARSET=utf8mb4 COMMENT='组卷计划详情';
CREATE TABLE `platform_user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `realname` varchar(20) DEFAULT NULL,
  `idcard` varchar(20) DEFAULT NULL,
