  `logintime` int NOT NULL DEFAULT '0',
  `org_id` int NOT NULL DEFAULT '0' COMMENT '所属组织机构id',
  `company_id` int NOT NULL DEFAULT '0' COMMENT '所属企业id',
  `wxopenid` varchar(100) DEFAULT NULL,
  `device_id` varchar(64) DEFAULT NULL COMMENT '绑定的设备ID',
  `device_info` text COMMENT '设备描述JSON',
  `device_bindtime` datetime DEFAULT NULL COMMENT '设备绑定时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  `expert_id` int NOT NULL DEFAULT '0' COMMENT '大于0表示platfrom_account表的专家id',
  `task` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_device_id` (`device_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4782 DEFAULT CHARSET=utf8mb4 COMMENT='平台用户表';
CREATE TABLE `platform_user_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `phone` varchar(11) DEFAULT NULL,
  `realname` varchar(20) DEFAULT NULL,
  `idcard` varchar(20) DEFAULT NULL,
  `gender` int NOT NULL DEFAULT '0' COMMENT '0:男,1女',
  `idcard_front` varchar(255) DEFAULT NULL COMMENT '身份证正面',
  `idcard_back` varchar(255) DEFAULT NULL COMMENT '身份证反面',
  `birthday` varchar(20) DEFAULT NULL,
  `idcard_start_date` varchar(20) DEFAULT NULL,
  `idcard_end_date` varchar(20) DEFAULT NULL,
  `idcard_header` varchar(255) DEFAULT NULL COMMENT '证件照',
  `nation` varchar(20) DEFAULT NULL COMMENT '民族',
  `house_type` varchar(20) DEFAULT NULL COMMENT '户口性质',
  `address` varchar(100) DEFAULT NULL,
  `political` varchar(10) DEFAULT NULL COMMENT '政治面貌',
  `point` int NOT NULL DEFAULT '0' COMMENT '积分',
  `point_sign` int NOT NULL DEFAULT '0' COMMENT '签到积分',
  `school` varchar(100) DEFAULT NULL,
  `education` varchar(50) DEFAULT NULL,
  `major` varchar(100) DEFAULT NULL,
  `school_paper_has` int NOT NULL DEFAULT '0',
  `school_no` varchar(50) DEFAULT NULL,
  `in_school_date` varchar(20) DEFAULT NULL,
  `graduate_date` varchar(20) DEFAULT NULL,
  `school_paper` varchar(255) DEFAULT NULL,
  `work_time` varchar(20) DEFAULT NULL,
  `title_type` varchar(30) DEFAULT NULL COMMENT '职称',
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '当前从事的工种',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4685 DEFAULT CHARSET=utf8mb4 COMMENT='平台用户详情表';
CREATE TABLE `task_exam` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int NOT NULL DEFAULT '0',
  `level` int NOT NULL DEFAULT '0' COMMENT '1高级技题,2技师,3高级工,4中级工,5初级工',
  `status` int NOT NULL DEFAULT '0' COMMENT '0待审核,1初审中,2终审中,3完成',
  `addtime` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `expert_start` int NOT NULL DEFAULT '0' COMMENT '初审专家',
  `expert_end` int NOT NULL DEFAULT '0' COMMENT '终审专家',
  `file_path` varchar(200) DEFAULT NULL COMMENT '上传的文件路径',
  `nums` int NOT NULL DEFAULT '0' COMMENT '题量',
  `is_archived` tinyint NOT NULL DEFAULT '0' COMMENT '是否已归档(0在用 1已归档)',
  `archived_at` datetime DEFAULT NULL COMMENT '归档时间',
  `archived_reason` varchar(50) DEFAULT NULL COMMENT '归档原因',
  PRIMARY KEY (`id`),
  KEY `idx_task_exam_wt_lvl_arch` (`work_type_id`,`level`,`is_archived`)
) ENGINE=InnoDB AUTO_INCREMENT=76 DEFAULT CHARSET=utf8mb4 COMMENT='任务-试题审核';
CREATE TABLE `task_examshicao` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int NOT NULL DEFAULT '0',
  `level` int NOT NULL DEFAULT '0' COMMENT '1高级技题,2技师,3高级工,4中级工,5初级工	',
  `status` int NOT NULL DEFAULT '0' COMMENT '0待审核,1初审中,2终审中,3完成',
  `addtime` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `expert_start` int NOT NULL DEFAULT '0' COMMENT '初审专家',
  `expert_end` int NOT NULL DEFAULT '0' COMMENT '终审专家',
  `file_path` varchar(200) DEFAULT NULL COMMENT '上传的文件路径',
  `nums` int NOT NULL DEFAULT '0' COMMENT '题量',
  `is_archived` tinyint NOT NULL DEFAULT '0' COMMENT '是否已归档',
  `archived_at` datetime DEFAULT NULL COMMENT '归档时间',
  `archived_reason` varchar(50) DEFAULT NULL COMMENT '归档原因',
  PRIMARY KEY (`id`),
  KEY `idx_task_examshicao_wt_lvl_arch` (`work_type_id`,`level`,`is_archived`)
) ENGINE=InnoDB AUTO_INCREMENT=80 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `task_examshicao_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_id` int NOT NULL DEFAULT '0',
  `jianding` varchar(100) DEFAULT NULL COMMENT '考评点',
  `content` varchar(500) DEFAULT NULL COMMENT '题目干',
  `pingfen` json DEFAULT NULL COMMENT '评分标准',
  `kaochang` varchar(500) DEFAULT NULL COMMENT '考场准备',
  `kaosheng` varchar(500) DEFAULT NULL COMMENT '考生准备',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8866 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `task_examsub` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int NOT NULL DEFAULT '0',
  `level` int NOT NULL DEFAULT '0' COMMENT '1高级技题,2技师,3高级工,4中级工,5初级工',
  `status` int NOT NULL DEFAULT '0' COMMENT '0待审核,1初审中,2终审中,3完成',
  `addtime` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `expert_start` int NOT NULL DEFAULT '0' COMMENT '初审专家',
  `expert_end` int NOT NULL DEFAULT '0' COMMENT '终审专家',
  `file_path` varchar(200) DEFAULT NULL COMMENT '上传的文件路径',
  `nums` int NOT NULL DEFAULT '0' COMMENT '题量',
  `is_archived` tinyint NOT NULL DEFAULT '0' COMMENT '是否已归档',
  `archived_at` datetime DEFAULT NULL COMMENT '归档时间',
  `archived_reason` varchar(50) DEFAULT NULL COMMENT '归档原因',
  PRIMARY KEY (`id`),
  KEY `idx_task_examsub_wt_lvl_arch` (`work_type_id`,`level`,`is_archived`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `task_examsub_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_id` int NOT NULL DEFAULT '0',
  `zhishidian` varchar(100) DEFAULT NULL COMMENT '知识点',
  `content` varchar(500) DEFAULT NULL COMMENT '题干',
  `answer` text COMMENT '参考答案',
  `pic` varchar(200) DEFAULT NULL,
  `isJisuan` int NOT NULL DEFAULT '0' COMMENT '是否计算:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=530 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `task_expert` (
  `id` int NOT NULL AUTO_INCREMENT,
  `expert_id` int NOT NULL DEFAULT '0',
  `task_id` int NOT NULL DEFAULT '0' COMMENT '多态外键，取决于tag字段的值',
  `task_role` int NOT NULL DEFAULT '0' COMMENT '0初审,1终审',
  `tag` varchar(30) DEFAULT NULL COMMENT '值:exam题库理论,examshicao题库实操,examsub题库主观,ximu细目表',
  `addtime` int NOT NULL DEFAULT '0',
  `endtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=489 DEFAULT CHARSET=utf8mb4 COMMENT='专家任务列表';
CREATE TABLE `train_file_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `table_name` varchar(255) DEFAULT NULL COMMENT '表名',
  `pk` varchar(255) DEFAULT NULL COMMENT '主键',
  `title` varchar(255) DEFAULT NULL COMMENT '名称',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=699 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `train_info_class` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_info_id` int NOT NULL DEFAULT '0',
  `title` varchar(50) NOT NULL COMMENT '班级名称',
  `nums` int NOT NULL DEFAULT '0',
  `company_id` int NOT NULL,
  `work_type_id` int NOT NULL,
  `date_start` varchar(10) DEFAULT NULL COMMENT 'yyyy-mm-dd',
  `date_end` varchar(10) DEFAULT NULL COMMENT 'yyyy-mm-dd',
  `addtime` int NOT NULL,
  `file_temps` varchar(100) DEFAULT NULL COMMENT '材料模板',
  `kcbiao_file` varchar(255) DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COMMENT='培训班级表';
CREATE TABLE `train_info_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `cover` varchar(255) DEFAULT NULL COMMENT '封面',
  `intro` varchar(255) DEFAULT NULL COMMENT '简介',
  `group_type` tinyint DEFAULT '0' COMMENT '0培训班1技能大师工作室2企业级团队3部门级团队4班组级团队',
  `master_type` tinyint DEFAULT '0' COMMENT '工作室类型,0组织型团队 1学习型团队',
  `type` tinyint DEFAULT '0' COMMENT '0:新型学徒制培训    1:岗位技能提升',
  `cate` varchar(255) DEFAULT NULL COMMENT '类型',
  `company_id` int DEFAULT NULL COMMENT '公司',
  `company_name` varchar(255) DEFAULT NULL,
  `company_address` varchar(500) DEFAULT NULL,
  `work_type_id` int DEFAULT NULL COMMENT '工种',
  `work_type_level` int NOT NULL DEFAULT '0',
  `course_id` int DEFAULT NULL COMMENT '科目',
  `num` int DEFAULT NULL COMMENT '人数',
  `position` varchar(500) DEFAULT NULL COMMENT '地点',
  `course_num` int DEFAULT NULL COMMENT '课时',
  `head_confirm` tinyint DEFAULT '0' COMMENT '主任是否确认',
  `user_id` int DEFAULT NULL,
  `company_has_confirm` tinyint DEFAULT '0',
  `company_confirm_time` timestamp NULL DEFAULT NULL COMMENT '企业确认时间',
  `company_confirm_user_id` int DEFAULT NULL COMMENT '企业确认uid',
  `company_confirm_username` varchar(255) DEFAULT NULL,
  `pass_status` tinyint DEFAULT '0' COMMENT '是否立项',
  `check_user_id` int DEFAULT NULL COMMENT '审核人',
  `check_username` varchar(255) DEFAULT NULL,
  `is_sorted_learn` tinyint DEFAULT '0' COMMENT '是否强制顺序学习',
  `max_normal_score` decimal(10,2) DEFAULT '50.00' COMMENT '最大平时分',
  `course_file` varchar(500) DEFAULT NULL COMMENT '课程表',
  `start_date` varchar(20) DEFAULT NULL,
  `end_date` varchar(20) DEFAULT NULL,
  `train_company_name` varchar(255) DEFAULT NULL COMMENT '培训机构',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态:0进行中,1:待办公室主任确认,2已完成',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `point` int DEFAULT '0',
  `album` text,
  `summary` text COMMENT '总结',
  `province_id` int DEFAULT NULL,
  `province_name` varchar(255) DEFAULT NULL,
  `city_id` int DEFAULT NULL,
  `city_name` varchar(255) DEFAULT NULL,
  `ability_score` decimal(10,3) DEFAULT '0.000',
  `region_id` int DEFAULT NULL,
  `region_name` varchar(255) DEFAULT NULL,
  `in_charge_user_id` int DEFAULT NULL,
  `in_charge_username` varchar(255) DEFAULT NULL,
  `files` text,
  `traindemand_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `pass_status` (`pass_status`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`),
  KEY `work_type_id` (`work_type_id`),
  KEY `course_id` (`course_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COMMENT='开班信息';
CREATE TABLE `train_sign_up_self` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `cover` text COMMENT '封面',
  `train_time` text COMMENT '培训时间',
  `exam_time` text COMMENT '考试时间',
  `intro` text COMMENT '介绍',
  `user_id` int DEFAULT NULL,
  `has_open` tinyint DEFAULT '0',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  `need_contact` tinyint DEFAULT '0' COMMENT '是否需要合同',
  `company_id` int DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `train_info_id` int NOT NULL DEFAULT '0',
  `jigou_id` int NOT NULL DEFAULT '1' COMMENT '机构id',
  `files` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COMMENT='预约报名';
CREATE TABLE `train_solution` (
  `id` int NOT NULL AUTO_INCREMENT,
  `train_info_id` int NOT NULL DEFAULT '0',
  `company_id` int DEFAULT NULL,
  `company_name` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `nation_policy` text COMMENT '国家政策分析',
  `industry_situation_analysis` text COMMENT '行业态势分析',
  `company_development_analysis` text COMMENT '公司发展分析',
  `research_data_analysis` text COMMENT '调研数据分析',
  `project_development_ideas` text COMMENT '项目开展思路/培训思路',
  `main_objectives` text COMMENT '项目主要目标/培训目标',
  `main_initiatives` text COMMENT '项目主要举措',
  `development_plan` text COMMENT '项目开展计划、培训计划',
  `division` text COMMENT '项目分工管理',
  `risk` text COMMENT '风险管理',
  `communication` text COMMENT '项目沟通管理',
  `checkpoint` text COMMENT '项目里程碑',
  `results` text COMMENT '预期成效',
  `teacher_intro` text COMMENT '讲师介绍',
  `request_analysis` text COMMENT '需求分析',
  `train_content` text COMMENT '培训内容',
  `train_method` text COMMENT '培训方式',
  `course` text,
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  `user_id` int DEFAULT NULL,
  `content` longtext,
  `file_path` varchar(255) DEFAULT NULL,
  `reject_reason` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `booking_card` (
  `card_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `card_name` varchar(100) NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `card_code` varchar(100) NOT NULL DEFAULT '' COMMENT '会员卡标识',
  `card_desc` varchar(200) NOT NULL DEFAULT '' COMMENT '会员卡介绍',
  `card_type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '卡类型：1成人卡，2儿童卡',
  `type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'IC卡类型：1年卡，2次卡，3月卡，4会员IC卡，5充值卡\r\n',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '会员卡图片',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '价格',
  `number` int unsigned NOT NULL DEFAULT '0' COMMENT '次数',
  `month` int unsigned NOT NULL DEFAULT '0' COMMENT '月份',
  `discount` decimal(10,1) NOT NULL COMMENT '折扣',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '老师介绍',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '关联用户',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `merchant_type` varchar(100) NOT NULL DEFAULT '' COMMENT '商户类型',
  `merchant_ids` varchar(50) DEFAULT '' COMMENT '适用的场馆ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`card_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `card_code` (`card_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8 COMMENT='会员卡';
CREATE TABLE `booking_card_plan` (
  `card_plan_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '会员卡名称',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '标识',
  `comments` varchar(2000) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`card_plan_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8 COMMENT='会员卡类型';
CREATE TABLE `booking_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '商品分类ID',
  `category_code` varchar(50) NOT NULL DEFAULT '' COMMENT '分类标识',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0列表 1单页 2外链',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '分类图片',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `component` varchar(300) NOT NULL DEFAULT '' COMMENT '组件路径',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `count` int unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `show_index` int NOT NULL DEFAULT '0' COMMENT '是否显示在首页',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1禁用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='课程分类';
CREATE TABLE `booking_emergency` (
  `emergency_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '姓名',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '手机号',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '关联用户',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`emergency_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8 COMMENT='紧急联系人管理';
CREATE TABLE `booking_field` (
  `field_id` int unsigned NOT NULL AUTO_INCREMENT,
  `field_name` varchar(100) NOT NULL COMMENT '场地名称',
  `is_toilet` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否有卫生间，1有，0没有',
  `is_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '状态，0开启，1关闭',
  `is_repeat` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否重复预订，1可以，0不可以',
  `is_half` tinyint NOT NULL DEFAULT '0' COMMENT '是否可预定半场，1可以，0不可以',
  `is_children` tinyint NOT NULL DEFAULT '0' COMMENT '是否支持儿童价：1支持，0不支持',
  `num` smallint unsigned NOT NULL DEFAULT '0' COMMENT '可重复预订次数',
  `sort_number` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '排序',
  `merchant_id` mediumint NOT NULL COMMENT '关联id',
  `row` tinyint NOT NULL DEFAULT '1' COMMENT '显示在第几行',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`field_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=320 DEFAULT CHARSET=utf8mb4 COMMENT='场馆场地';
CREATE TABLE `booking_integral` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `username` varchar(50) NOT NULL COMMENT '微信昵称',
  `phone` char(11) NOT NULL COMMENT '手机号码',
  `integral` decimal(8,2) NOT NULL COMMENT '获得积分',
  `date_time` char(10) NOT NULL COMMENT '日期',
  `day` char(2) NOT NULL COMMENT '天',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` int NOT NULL COMMENT '签到时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3762 DEFAULT CHARSET=utf8 COMMENT='签到积分';
CREATE TABLE `booking_integral_log` (
  `id` mediumint unsigned NOT NULL AUTO_INCREMENT,
  `order_num` char(27) DEFAULT NULL COMMENT '场馆订单号',
  `oid` mediumint DEFAULT NULL COMMENT '订单id',
  `site_name` varchar(30) DEFAULT NULL COMMENT '场馆名称',
  `username` varchar(50) NOT NULL COMMENT '微信昵称',
  `phone` char(11) DEFAULT NULL COMMENT '手机号码',
  `integral` decimal(8,2) NOT NULL COMMENT '获得积分',
  `old_money` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '变化前积分',
  `new_money` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '变化后积分',
  `info` varchar(200) NOT NULL COMMENT '描述',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` int unsigned NOT NULL COMMENT '记录时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='积分明细';
CREATE TABLE `booking_item` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '项目类型',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '项目图标',
  `comments` longtext NOT NULL COMMENT '项目备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='项目类型';
CREATE TABLE `booking_lesson` (
  `lesson_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `lesson_name` varchar(255) NOT NULL DEFAULT '' COMMENT '课程名称',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '图标',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '分类ID',
  `teacher_id` int NOT NULL DEFAULT '0' COMMENT '老师ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `start_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上课时间',
  `max_number` int unsigned NOT NULL DEFAULT '0' COMMENT '报名人数上限',
  `address` varchar(200) NOT NULL DEFAULT '' COMMENT '上课地点',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`lesson_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='课程管理';
CREATE TABLE `booking_period` (
  `period_id` int unsigned NOT NULL AUTO_INCREMENT,
  `time_period` varchar(20) NOT NULL COMMENT '时段',
  `price` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '价格',
  `prices` varchar(5000) DEFAULT '0' COMMENT '每日不同价格',
  `half_price` decimal(8,2) DEFAULT '0.00' COMMENT '半场价格',
  `half_prices` varchar(5000) DEFAULT '0' COMMENT '每日不同半场价格',
  `children_price` decimal(8,2) DEFAULT '0.00' COMMENT '儿童价',
  `week` varchar(300) DEFAULT NULL COMMENT '星期选择',
  `sort_number` mediumint NOT NULL COMMENT '排序',
  `merchant_id` mediumint NOT NULL COMMENT '关联id',
  `is_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否关闭，0开启，1关闭',
  `is_free` tinyint NOT NULL DEFAULT '1' COMMENT '是否免费：0免费，1收费',
  `start_time` char(4) NOT NULL DEFAULT '0' COMMENT '开始时间',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`period_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=561 DEFAULT CHARSET=utf8mb4 COMMENT='场地时段';
CREATE TABLE `booking_teacher` (
  `teacher_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '手机号',
  `teacher_name` varchar(255) NOT NULL DEFAULT '' COMMENT '老师姓名',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '老师照片',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '老师介绍',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '关联用户',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`teacher_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='老师管理';
CREATE TABLE `booking_user_card` (
  `id` mediumint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `card_id` int NOT NULL DEFAULT '0' COMMENT '购买的卡片ID',
  `sid` varchar(50) NOT NULL DEFAULT '' COMMENT 'sid场馆id集合，适用的场馆',
  `uid` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '用户id（旧）',
  `vid` mediumint unsigned NOT NULL DEFAULT '0' COMMENT 'vip卡id',
  `aid` mediumint NOT NULL DEFAULT '0' COMMENT '开卡人id',
  `wechat_order` char(27) DEFAULT NULL COMMENT '微信订单号',
  `code` varchar(30) NOT NULL DEFAULT '' COMMENT '卡号',
  `name` varchar(20) NOT NULL COMMENT '会员卡名称',
  `username` char(30) NOT NULL COMMENT '真实姓名',
  `phone` char(11) NOT NULL DEFAULT '' COMMENT '手机号码',
  `image` varchar(200) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '会员卡图片',
  `price` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT 'vip购卡价格',
  `card_desc` varchar(100) DEFAULT NULL COMMENT '会员卡介绍',
  `info` varchar(100) DEFAULT NULL COMMENT '会员卡说明',
  `discount` decimal(3,1) NOT NULL DEFAULT '0.0' COMMENT 'vip卡折扣率',
  `count` mediumint unsigned DEFAULT '0' COMMENT '使用次数',
  `each_money` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '每使用一次减少的金额',
  `remaining_money` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '剩余金额',
  `number` mediumint DEFAULT '0' COMMENT '续费累加次数',
  `num` mediumint unsigned DEFAULT '0' COMMENT '剩余次数',
  `status` tinyint NOT NULL DEFAULT '2' COMMENT '付款状态,1已付款，2未付款',
  `term` tinyint NOT NULL DEFAULT '0' COMMENT '会员卡年限',
  `month` tinyint unsigned DEFAULT '0' COMMENT '月限',
  `type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'IC卡类型：1年卡，2次卡，3月卡，4会员IC卡，5充值卡\r\n',
  `card_type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '卡类型：1成人卡，2儿童卡',
  `vip_type` tinyint NOT NULL DEFAULT '2' COMMENT 'vip卡等级类型：1特殊vip卡，2普通vip卡',
  `pic` varchar(200) DEFAULT NULL COMMENT '特殊卡开发凭证图',
  `prices` varchar(5000) DEFAULT NULL COMMENT '价格组',
  `pay_type` tinyint DEFAULT '1' COMMENT '1微信支付，2支付宝支付，3现金，4POS机刷卡，15平安健康卡',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未付款，1已付款',
  `is_integral` tinyint unsigned NOT NULL DEFAULT '2' COMMENT '是否赠送积分：1赠送，2不赠送',
  `is_invoice` tinyint unsigned DEFAULT '2' COMMENT '是否已开具发票：1已开发票，2未开发票',
  `expiration_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'vip卡到期时间',
  `expire_time_old` int unsigned DEFAULT NULL COMMENT 'vip卡到期时间',
  `urgent_name` char(8) DEFAULT NULL COMMENT '紧急联系人',
  `urgent_phone` char(11) DEFAULT NULL COMMENT '紧急联系人号码',
  `card_num` varchar(20) DEFAULT NULL COMMENT '卡号',
  `password` varchar(20) DEFAULT NULL COMMENT '密码',
  `use_time` int unsigned DEFAULT '0' COMMENT '使用时间',
  `create_time_old` int DEFAULT NULL COMMENT '创建时间',
  `update_time_old` int DEFAULT '0',
  `id_card` varchar(255) DEFAULT NULL COMMENT '身份证号码',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `remark` varchar(2000) DEFAULT '' COMMENT '备注',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `code` (`code`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='会员卡';
CREATE TABLE `booking_user_card_log` (
  `log_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `user_card_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员卡ID',
  `card_num` varchar(20) NOT NULL DEFAULT '0' COMMENT '会员卡卡号',
  `type` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'IC卡类型：1年卡，2次卡，3月卡，4会员IC卡，5充值卡\r\n',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '变动金额',
  `balance` decimal(20,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '变动后余额',
  `num` mediumint unsigned DEFAULT '0' COMMENT '剩余次数',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '管理员备注',
  `order_no` varchar(30) NOT NULL DEFAULT '0' COMMENT '订单编号',
  `admin_id` int unsigned NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '0' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='明细表';
CREATE TABLE `booking_user_coupon` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `coupon_id` int NOT NULL DEFAULT '0' COMMENT '优惠劵id',
  `name` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '优惠券名称',
  `type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '优惠券类型(10满减券 20折扣券)',
  `reduce_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '满减券-减免金额',
  `discount` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '折扣券-折扣率(0-100)',
  `min_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '最低消费金额',
  `expire_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '到期类型(10领取后生效 20固定时间)',
  `expire_day` int unsigned NOT NULL DEFAULT '0' COMMENT '领取后生效-有效天数',
  `start_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '有效期开始时间',
  `end_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '有效期结束时间',
  `apply_range` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '适用范围(10全部商品 20指定商品)',
  `apply_range_config` text CHARACTER SET utf8 COMMENT '适用范围配置(json格式)',
  `is_expire` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否过期(0未过期 1已过期)',
  `is_use` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否已使用(0未使用 1已使用)',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0待使用, 1已使用, 2已失效',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='我的优惠券';
CREATE TABLE `booking_user_invoice` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '发票类型(0纸质 1电子)',
  `name` varchar(255) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '发票名称',
  `invoice_type` tinyint NOT NULL DEFAULT '0' COMMENT '开票类型(0普票 1专票)',
  `invoice_code` varchar(50) NOT NULL DEFAULT '0' COMMENT '税号',
  `address` varchar(100) NOT NULL DEFAULT '0' COMMENT '公司地址',
  `tel` varchar(50) NOT NULL DEFAULT '0' COMMENT '公司电话',
  `bank_name` varchar(50) NOT NULL DEFAULT '0' COMMENT '开户行',
  `bank_account` varchar(50) NOT NULL DEFAULT '0' COMMENT '开户账号',
  `phone` varchar(50) NOT NULL DEFAULT '0' COMMENT '手机号码',
  `email` varchar(50) NOT NULL DEFAULT '0' COMMENT '电子邮箱',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0待使用, 1已使用, 2已失效',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='发票';
CREATE TABLE `cms_ad` (
  `ad_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `ad_type` varchar(100) NOT NULL DEFAULT '' COMMENT '广告类型',
  `name` varchar(300) NOT NULL DEFAULT '' COMMENT '广告位名称',
  `width` varchar(300) NOT NULL DEFAULT '' COMMENT '宽',
  `height` varchar(300) NOT NULL DEFAULT '' COMMENT '高',
  `images` text CHARACTER SET utf8mb4 COMMENT '广告图片',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`ad_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=273 DEFAULT CHARSET=utf8 COMMENT='广告位';
CREATE TABLE `cms_ad_record` (
  `ad_record_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` text CHARACTER SET utf8mb4 COMMENT '广告标题',
  `path` varchar(300) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '图片地址',
  `url` text CHARACTER SET utf8mb4 COMMENT '链接地址',
  `ad_id` int unsigned NOT NULL DEFAULT '0' COMMENT '广告位ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`ad_record_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='广告图片';
CREATE TABLE `cms_album` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `type` tinyint DEFAULT NULL COMMENT '0技能大师工作室相册',
  `album` text,
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `cms_app_version` (
  `id` int NOT NULL AUTO_INCREMENT,
  `apk_type` varchar(20) DEFAULT 'wgt',
  `type` varchar(255) DEFAULT NULL,
  `version_code` varchar(255) DEFAULT NULL COMMENT '版本号',
  `version_num` int DEFAULT NULL COMMENT '版本号',
  `url` varchar(500) DEFAULT NULL,
  `intro` text COMMENT '更新信息',
  `is_on` tinyint DEFAULT '0',
  `sort_number` int DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=200 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `cms_article_comment` (
  `comment_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `score` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '评分 (10好评 20中评 30差评)',
  `content` text NOT NULL COMMENT '评价内容',
  `is_picture` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否为图片评价',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '评论者ID',
  `to_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '被评价者ID',
  `reply_comment_id` int unsigned NOT NULL DEFAULT '0' COMMENT '回复的评论ID',
  `reply_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '回复者ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未读, 1已读',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`comment_id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `shop_comment_ibfk_1` (`tenant_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文章评论表';
CREATE TABLE `cms_article_count` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='点赞文章';
CREATE TABLE `cms_article_like` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='点赞文章';
CREATE TABLE `cms_design` (
  `page_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '页面标题',
  `keywords` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面关键词',
  `description` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面描述',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '路由地址',
  `component` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '组件路径',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '缩列图',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '页面内容',
  `layout` text CHARACTER SET utf8mb4 COMMENT '页面布局',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`page_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=362 DEFAULT CHARSET=utf8 COMMENT='页面管理记录表';
CREATE TABLE `cms_design_record` (
  `page_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '页面标题',
  `keywords` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面关键词',
  `description` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面描述',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面路由地址',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '缩列图',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`page_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='页面组件表';
CREATE TABLE `cms_docs` (
  `docs_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文档ID',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '文档标题',
  `parent_id` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '上级目录',
  `book_id` int DEFAULT '0' COMMENT '书籍ID',
  `visibility` varchar(300) DEFAULT NULL COMMENT '可见性(public,private,protected)',
  `virtual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '虚拟阅读量(仅用作展示)',
  `actual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '实际阅读量',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`docs_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `book_id` (`book_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='文档管理记录表';
CREATE TABLE `cms_docs_book` (
  `book_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) DEFAULT NULL COMMENT '书籍名称',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '书籍标识',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '封面图',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `content` longtext NOT NULL COMMENT '文档内容',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`book_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='书籍记录表';
CREATE TABLE `cms_docs_content` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `docs_id` int unsigned DEFAULT '0' COMMENT '文档ID',
  `content` longtext COMMENT '文档内容',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `docs_id_ibfk_1` (`docs_id`),
  CONSTRAINT `docs_id_ibfk_1` FOREIGN KEY (`docs_id`) REFERENCES `cms_docs` (`docs_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文档内容记录表';
CREATE TABLE `cms_domain` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `domain` varchar(100) DEFAULT NULL COMMENT '域名',
  `host_name` varchar(100) CHARACTER SET utf8 DEFAULT '' COMMENT '主机记录',
  `host_value` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '记录值',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10270 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='网站域名记录表';
CREATE TABLE `cms_form` (
  `form_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `train_id` int DEFAULT NULL,
  `need_user_detail` tinyint DEFAULT '1',
  `type` varchar(255) DEFAULT NULL,
  `name` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '表单标题',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '顶部图片',
  `background` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '背景图片',
  `video` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '视频文件',
  `submit_number` int NOT NULL DEFAULT '0' COMMENT '提交次数',
  `layout` text CHARACTER SET utf8mb4 COMMENT '页面布局',
  `hide_photo` int NOT NULL DEFAULT '0' COMMENT '是否隐藏顶部图片',
  `hide_background` int NOT NULL DEFAULT '0' COMMENT '是否隐藏背景图片',
  `hide_video` int NOT NULL DEFAULT '0' COMMENT '是否隐藏视频',
  `opacity` decimal(2,1) NOT NULL DEFAULT '0.0' COMMENT '背景图片透明度',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(1000) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`form_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchat_id` (`merchant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=331 DEFAULT CHARSET=utf8 COMMENT='表单设计表';
CREATE TABLE `cms_form_record` (
  `form_record_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `phone` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '手机号',
  `form_data` text CHARACTER SET utf8mb4 COMMENT '表单数据',
  `form_id` int unsigned NOT NULL DEFAULT '0' COMMENT '表单ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned DEFAULT '0' COMMENT '商户ID',
  `name` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '姓名',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `id_card` varchar(300) DEFAULT NULL,
  PRIMARY KEY (`form_record_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `form_id` (`form_id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=575 DEFAULT CHARSET=utf8 COMMENT='表单数据记录表';
CREATE TABLE `cms_getcertconfig` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `url` varchar(255) DEFAULT NULL,
  `datas` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='查证信息配置';
CREATE TABLE `cms_liuyanban` (
  `id` int NOT NULL AUTO_INCREMENT,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `tag` varchar(50) NOT NULL,
  `content` varchar(100) NOT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `status` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='留言板';
CREATE TABLE `cms_mp_menu` (
  `menu_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '菜单名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0我的 1订单状态图标 2首页 3 商城 4管理 5 提升 6团队',
  `is_mp_weixin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否微信小程序菜单',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单路由地址',
  `component` varchar(300) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单组件地址, 目录可为空',
  `target` varchar(200) CHARACTER SET utf8mb4 DEFAULT '_self' COMMENT '打开位置',
  `icon` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单图标',
  `color` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '图标颜色',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `position` int NOT NULL DEFAULT '1' COMMENT '位置 0不限 1顶部 2底部',
  `rows` int NOT NULL DEFAULT '0' COMMENT '0 第一行 1第二行',
  `active` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单侧栏选中的path',
  `meta` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '其它路由元信息',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `article_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的文章分类ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的文章ID',
  `form_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的表单ID',
  `book_code` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '绑定的书籍标识',
  `goods_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的商品分类ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的商品ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `admin_show` int unsigned NOT NULL DEFAULT '0' COMMENT '是否管理人员可见',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`menu_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `path` (`path`) USING BTREE,
  KEY `form_id` (`form_id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `goods_category_id` (`goods_category_id`) USING BTREE,
  KEY `page_id` (`page_id`) USING BTREE,
  KEY `article_category_id` (`article_category_id`) USING BTREE,
  KEY `article_id` (`article_id`) USING BTREE,
  KEY `book_code` (`book_code`) USING BTREE,
  KEY `is_mp_weixin` (`is_mp_weixin`)
) ENGINE=InnoDB AUTO_INCREMENT=562 DEFAULT CHARSET=utf8 COMMENT='小程序端菜单';
CREATE TABLE `cms_navigation` (
  `navigation_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '菜单名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0自定义 1单页内容2外部链接',
  `is_mp_weixin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否微信小程序菜单',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单路由地址',
  `component` varchar(300) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单组件地址, 目录可为空',
  `target` varchar(200) CHARACTER SET utf8mb4 DEFAULT '_self' COMMENT '打开位置',
  `icon` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单图标',
  `color` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '图标颜色',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `position` int NOT NULL DEFAULT '1' COMMENT '位置 0不限 1顶部 2底部',
  `active` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单侧栏选中的path',
  `meta` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '其它路由元信息',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `article_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的文章分类ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的文章ID',
  `form_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的表单ID',
  `book_code` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '绑定的书籍标识',
  `goods_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的商品分类ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的商品ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`navigation_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `path` (`path`) USING BTREE,
  KEY `form_id` (`form_id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `goods_category_id` (`goods_category_id`) USING BTREE,
  KEY `page_id` (`page_id`) USING BTREE,
  KEY `article_category_id` (`article_category_id`) USING BTREE,
  KEY `article_id` (`article_id`) USING BTREE,
  KEY `book_code` (`book_code`) USING BTREE,
  KEY `is_mp_weixin` (`is_mp_weixin`)
) ENGINE=InnoDB AUTO_INCREMENT=522 DEFAULT CHARSET=utf8 COMMENT='网站导航记录表';
CREATE TABLE `cms_org_album` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `album` text,
  `org_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `cms_org_article` (
  `article_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(300) NOT NULL DEFAULT '' COMMENT '文章标题',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '分类类型0新闻1课程2师资3教室4实训中心',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章分类ID',
  `content` longtext COMMENT '内容',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `org_id` int DEFAULT NULL,
  `org_name` varchar(500) DEFAULT NULL,
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `publish_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '发布时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`article_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=560 DEFAULT CHARSET=utf8 COMMENT='文章记录表';
CREATE TABLE `cms_share` (
  `id` int NOT NULL AUTO_INCREMENT,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `content` varchar(200) DEFAULT NULL,
  `imgs` json DEFAULT NULL,
  `work_type_id` int NOT NULL DEFAULT '0',
  `work_type_level` int NOT NULL DEFAULT '0' COMMENT '1:一级/高级技师,2:二级/技师,3:三级/高级工,4:四级/中级工,5:五级/初级工',
  `see_count` int NOT NULL DEFAULT '0' COMMENT '浏览次数',
  `location` varchar(50) DEFAULT NULL COMMENT '位置',
  `add_time` int NOT NULL DEFAULT '0',
  `isaudit` int NOT NULL DEFAULT '0' COMMENT '否审核:0否,1是',
  `isaudit_time` int NOT NULL DEFAULT '0' COMMENT '审核时间',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='同行分享';
CREATE TABLE `cms_share_auditlog` (
  `id` int NOT NULL AUTO_INCREMENT,
  `audit_user_id` int NOT NULL DEFAULT '0',
  `cms_share_id` int NOT NULL DEFAULT '0',
  `audit_status` int NOT NULL COMMENT '审核状态:1通过,-1拒绝',
  `remark` varchar(300) DEFAULT NULL COMMENT '审核理由',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COMMENT='同行分计享审核日志';
CREATE TABLE `cms_website` (
  `website_id` int NOT NULL AUTO_INCREMENT COMMENT '站点ID',
  `website_name` varchar(50) NOT NULL DEFAULT '' COMMENT '网站名称',
  `website_code` varchar(100) NOT NULL DEFAULT '' COMMENT '网站标识',
  `website_icon` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_dark_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO(深色模式)',
  `website_type` varchar(50) NOT NULL DEFAULT '' COMMENT '网站类型',
  `keywords` varchar(50) NOT NULL DEFAULT '' COMMENT '网站关键词',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `template_id` int unsigned NOT NULL DEFAULT '10' COMMENT '模版ID',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `company_id` int unsigned NOT NULL DEFAULT '20' COMMENT '企业ID',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `phone` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `icp_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'ICP备案号',
  `police_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '公安备案',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`website_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=973 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='网站信息记录表';
CREATE TABLE `cms_website_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int DEFAULT '0' COMMENT '类型，0文本 1图片 2其他',
  `name` varchar(100) DEFAULT '' COMMENT '名称',
  `comments` varchar(500) DEFAULT '' COMMENT '备注',
  `value` varchar(200) DEFAULT '' COMMENT '名称',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `website_id` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10632 DEFAULT CHARSET=utf8 COMMENT='应用参数';
CREATE TABLE `comments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `tag` varchar(10) NOT NULL DEFAULT 'train' COMMENT 'train:部训讨论,team:工作室讨论',
  `tag_id` int NOT NULL DEFAULT '0' COMMENT 'tag对应有主体id',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父id:如果大于0表示回复父id',
  `types` int NOT NULL DEFAULT '0' COMMENT '0:综合讨论区,1老师答疑区,2课堂交流区',
  `text_type` int NOT NULL COMMENT '0:文本,1图片',
  `text_content` varchar(500) DEFAULT NULL,
  `imgs` json DEFAULT NULL,
  `rates` int NOT NULL COMMENT '评级',
  `addtime` int NOT NULL DEFAULT '0',
  `platform_user_id` int NOT NULL DEFAULT '0' COMMENT '发送评论用户id',
  `reply_count` int DEFAULT '0' COMMENT '回复次数',
  `reply_id` int NOT NULL DEFAULT '0' COMMENT '被回复评论id',
  `reply_user_id` int NOT NULL DEFAULT '0' COMMENT '被回复评论人id',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COMMENT='评论表';
CREATE TABLE `company_employee` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL DEFAULT '0',
  `realname` varchar(20) DEFAULT NULL,
  `idcard` varchar(18) DEFAULT NULL,
  `gender` int NOT NULL DEFAULT '0' COMMENT '0男,1女',
  `phone` varchar(11) DEFAULT NULL,
  `position` varchar(30) DEFAULT NULL COMMENT '岗位',
  `education` varchar(30) DEFAULT NULL COMMENT '学历',
  `major` varchar(50) DEFAULT NULL COMMENT '专业',
  `level_1` int NOT NULL DEFAULT '0' COMMENT '是否高级技师:0否,1是',
  `level_2` int NOT NULL DEFAULT '0' COMMENT '是否技师:0否,1是',
  `level_3` int NOT NULL DEFAULT '0' COMMENT '是否高级工:0否,1是',
  `level_4` int NOT NULL DEFAULT '0' COMMENT '是否中级工:0否,1是',
  `level_5` int NOT NULL DEFAULT '0' COMMENT '是否初级工:0否,1是',
  `addtime` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='企业员工表';
CREATE TABLE `course_kejian_practice` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ck_id` int NOT NULL DEFAULT '0',
  `exam_detail_id` int NOT NULL DEFAULT '0',
  `knowledge_id` int NOT NULL DEFAULT '0',
  `type` varchar(10) DEFAULT NULL,
  `content` varchar(500) DEFAULT NULL,
  `answer` varchar(500) DEFAULT NULL,
  `resolve` varchar(200) DEFAULT NULL,
  `source` int NOT NULL DEFAULT '1',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COMMENT='课件对应练习题';
CREATE TABLE `course_kejian_practice_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `ck_id` int NOT NULL DEFAULT '0' COMMENT 'course_kejian表id',
  `exams` json DEFAULT NULL,
  `score` int NOT NULL DEFAULT '0' COMMENT '得分',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COMMENT='课件习题练习记录';
CREATE TABLE `course_kejian_tocompany` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ck_id` int NOT NULL DEFAULT '0',
  `company_id` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否册除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='平台课件添加到企业';
CREATE TABLE `course_teach` (
  `id` int NOT NULL AUTO_INCREMENT,
  `sno` varchar(50) DEFAULT NULL COMMENT '教材编号',
  `title` varchar(50) DEFAULT NULL COMMENT '教材名称',
  `keshi` int NOT NULL DEFAULT '0' COMMENT '课时',
  `cover` varchar(100) DEFAULT NULL COMMENT '封面',
  `type` int NOT NULL DEFAULT '0' COMMENT '获取方式:0免费,1收费',
  `price` double(15,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `desction` varchar(255) DEFAULT NULL COMMENT '描述',
  `file_path` varchar(100) DEFAULT NULL COMMENT '文件路径',
  `tag` int NOT NULL DEFAULT '0' COMMENT '0平台,1企业',
  `jigou_id` int NOT NULL DEFAULT '0' COMMENT '机构id',
  `owner_id` int NOT NULL DEFAULT '0' COMMENT '拥有者id',
  `addtime` int NOT NULL DEFAULT '0' COMMENT '添加时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='课程建设-教材表';
CREATE TABLE `course_teach_tocompany` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ct_id` int NOT NULL DEFAULT '0',
  `company_id` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否册除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='平台教材添加到企业';
CREATE TABLE `device_bind_whitelist` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL COMMENT '用户ID',
  `phone` varchar(20) DEFAULT NULL COMMENT '手机号冗余',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_by` int unsigned DEFAULT NULL COMMENT '添加人管理员ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='设备绑定灰度白名单';
CREATE TABLE `device_unbind_requests` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int unsigned NOT NULL COMMENT '申请用户ID',
  `old_device_id` varchar(64) DEFAULT NULL COMMENT '旧设备ID',
  `new_device_id` varchar(64) NOT NULL COMMENT '新设备ID',
  `new_device_info` text COMMENT '新设备描述JSON',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0待审批 1已通过 2已拒绝',
  `admin_id` int unsigned DEFAULT NULL COMMENT '审批管理员ID',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_status` (`user_id`,`status`),
  KEY `idx_status_created` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb4 COMMENT='设备换绑申请';
CREATE TABLE `exam_correction` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `exam_detail_id` int DEFAULT NULL,
  `title` text,
  `type` varchar(255) DEFAULT NULL,
  `content` text,
  `images` text,
  `phone` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0' COMMENT '任务状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=391 DEFAULT CHARSET=utf8mb4 COMMENT='纠错';
CREATE TABLE `exam_courseware_exam_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT '0' COMMENT 'exam_list主键',
  `knowledge_id` int DEFAULT NULL COMMENT '知识id',
  `task_detail_id` int DEFAULT '0' COMMENT '任务详情id',
  `is_private` tinyint DEFAULT '0' COMMENT '是否保密',
  `difficulty` tinyint DEFAULT '0' COMMENT '难度(0易1较易2中3较难4难)',
  `user_id` int DEFAULT NULL COMMENT '撰题人',
  `type` varchar(255) DEFAULT NULL COMMENT '试题类型',
  `source` tinyint DEFAULT '0' COMMENT '0内部  1外部',
  `keyword` varchar(255) DEFAULT NULL COMMENT '关键字',
  `audio` varchar(255) DEFAULT NULL COMMENT '音频',
  `video` varchar(255) DEFAULT NULL COMMENT '视频',
  `content` text COMMENT '内容',
  `answer` text COMMENT '答案',
  `score` decimal(10,1) unsigned DEFAULT '0.0' COMMENT '分值',
  `resolve` varchar(255) DEFAULT NULL COMMENT '解析',
  `suggest` text COMMENT '意见',
  `check_status` tinyint DEFAULT '0' COMMENT '0待审核1通过2不通过',
  `final_check_status` tinyint DEFAULT '0' COMMENT '终审 0待审核1通过2不通过',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `check_time` timestamp NULL DEFAULT NULL COMMENT '审题时间',
  `check_user_id` int DEFAULT NULL COMMENT '审题用户',
  `final_check_time` timestamp NULL DEFAULT NULL COMMENT '终审时间',
  `final_check_user_id` int DEFAULT NULL COMMENT '终审用户',
  `deleted` tinyint DEFAULT '0',
  `org_id` int DEFAULT NULL COMMENT '企业id',
  `org_name` varchar(255) DEFAULT NULL COMMENT '企业名称',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `exam_id` (`exam_id`),
  KEY `knowledge_id` (`knowledge_id`),
  KEY `task_detail_id` (`task_detail_id`),
  KEY `difficulty` (`difficulty`),
  KEY `type` (`type`),
  KEY `source` (`source`),
  KEY `check_status` (`check_status`),
  KEY `final_check_status` (`final_check_status`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`),
  KEY `org_id` (`org_id`),
  KEY `org_name` (`org_name`),
  KEY `check_user_id` (`check_user_id`),
  KEY `final_check_user_id` (`final_check_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=126341 DEFAULT CHARSET=utf8mb4 COMMENT='命题详情';
CREATE TABLE `exam_courseware_exam_list` (
