  `status` int NOT NULL DEFAULT '0' COMMENT '任务状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='学员分配考场';
CREATE TABLE `exam_rooms_config` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` tinyint DEFAULT '0' COMMENT '0理论  1实操',
  `org_id` int DEFAULT NULL COMMENT '企业id',
  `org_name` varchar(255) DEFAULT NULL COMMENT '企业',
  `room_name` varchar(255) DEFAULT NULL COMMENT '考场名称',
  `position` varchar(255) DEFAULT NULL,
  `max_num` int DEFAULT NULL COMMENT '最多可容纳人数',
  `status` int NOT NULL DEFAULT '0' COMMENT '任务状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  `user_id` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COMMENT='考试教室配置';
CREATE TABLE `exam_task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '任务名称',
  `plan_id` int DEFAULT NULL COMMENT '计划id',
  `series_no` varchar(200) DEFAULT NULL COMMENT '任务编码',
  `course_id` int DEFAULT NULL COMMENT '征集科目',
  `type` tinyint DEFAULT '0' COMMENT '任务类型(0试题征集)',
  `task_status` tinyint DEFAULT '0' COMMENT '任务状态(0命题中1审题中2终审中3命审结束)',
  `has_publish` tinyint DEFAULT '0' COMMENT '是否发布',
  `has_done` tinyint DEFAULT '0' COMMENT '是否完成',
  `start_date` datetime DEFAULT NULL COMMENT '开始时间',
  `end_date` datetime DEFAULT NULL COMMENT '结束时间',
  `remind_date` datetime DEFAULT NULL COMMENT '提醒时间',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=244 DEFAULT CHARSET=utf8mb4 COMMENT='任务';
CREATE TABLE `exam_task_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `task_id` int DEFAULT NULL,
  `type` tinyint DEFAULT '0',
  `knowledge_id` int DEFAULT NULL,
  `last_check_user_id` int DEFAULT NULL COMMENT '终审专家',
  `is_whole` tinyint DEFAULT '0' COMMENT '是否整体命题',
  `has_stop` tinyint DEFAULT '0' COMMENT '是否停用',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `task_status` int NOT NULL DEFAULT '1' COMMENT '状态(0命题中1初审中2终审中3终审完成)',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=112 DEFAULT CHARSET=utf8mb4 COMMENT='任务详情';
CREATE TABLE `exam_task_detail_info_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `detail_id` int DEFAULT NULL,
  `type` enum('judge','single','multi','sort','answer','single_discrete','multi_discrete','match','simple_fill','fill','cal','essay','explain','drafting','correct','design','action','sim','example','context','cal-analysis','drag') DEFAULT NULL COMMENT '试题类型',
  `num` int DEFAULT NULL COMMENT '数量',
  `refer_score` int DEFAULT NULL COMMENT '参考分值',
  `make_user_id` int DEFAULT NULL COMMENT '命题专家',
  `check_user_id` int DEFAULT NULL COMMENT '审题专家',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `exam_task_detail_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `detail_id` int DEFAULT NULL,
  `type` enum('judge','single','multi','sort','answer','single_discrete','multi_discrete','match','simple_fill','fill','cal','essay','explain','drafting','correct','design','action','sim','example','context','cal-analysis','drag') DEFAULT NULL COMMENT '试题类型',
  `num` int DEFAULT NULL COMMENT '数量',
  `refer_score` int DEFAULT NULL COMMENT '参考分值',
  `make_user_id` int DEFAULT NULL COMMENT '命题专家',
  `check_user_id` int DEFAULT NULL COMMENT '审题专家',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `task_id` int DEFAULT NULL,
  `knowledge_id` int DEFAULT NULL,
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=203 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `exam_upgrade` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int DEFAULT NULL,
  `exam_detail_id` int DEFAULT NULL,
  `title` text,
  `content` text,
  `phone` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0' COMMENT '任务状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COMMENT='题库升级';
CREATE TABLE `exam_user_wrong_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` tinyint DEFAULT '0' COMMENT '0 普通题目  1 考试题目',
  `course_id` int DEFAULT NULL,
  `exam_plan_id` int NOT NULL DEFAULT '0' COMMENT 'train_exam_list表id',
  `paper_id` int NOT NULL DEFAULT '0',
  `exam_detail_id` int DEFAULT NULL COMMENT 'exam_paper_detail表id',
  `user_answer` varchar(500) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `deleted` int DEFAULT '0',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `type` (`type`),
  KEY `course_id` (`course_id`),
  KEY `exam_detail_id` (`exam_detail_id`),
  KEY `user_id` (`user_id`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`),
  KEY `sort_number` (`sort_number`),
  KEY `tenant_id` (`tenant_id`),
  KEY `create_time` (`create_time`),
  KEY `platform_user_id` (`platform_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=91087 DEFAULT CHARSET=utf8mb4 COMMENT='用户错题';
CREATE TABLE `file_template` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` int NOT NULL DEFAULT '0' COMMENT '0认定,1培训',
  `city` varchar(30) DEFAULT NULL,
  `title` varchar(100) DEFAULT NULL,
  `ext` varchar(10) DEFAULT NULL COMMENT '文件类型',
  `path_source` varchar(255) DEFAULT NULL,
  `path_used` varchar(255) DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COMMENT='材料文件模板';
CREATE TABLE `master_activity` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '活动标题',
  `content` text COMMENT '活动内容',
  `start_time` datetime DEFAULT NULL COMMENT '活动开始时间',
  `end_time` datetime DEFAULT NULL COMMENT '活动结束时间',
  `location` varchar(255) DEFAULT NULL COMMENT '活动地点',
  `registration_deadline` datetime DEFAULT NULL COMMENT '报名截止时间',
  `registration_count` int DEFAULT '0' COMMENT '报名人数',
  `photos` text COMMENT '活动照片',
  `status` int NOT NULL DEFAULT '0' COMMENT '0进行中,1完成',
  `type` varchar(20) DEFAULT NULL COMMENT '类型',
  `addtime` int NOT NULL DEFAULT '1' COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室活动表';
CREATE TABLE `master_activity_registration` (
  `id` int NOT NULL AUTO_INCREMENT,
  `activity_id` int NOT NULL COMMENT '活动ID，关联master_activity.id',
  `user_id` int NOT NULL COMMENT '用户ID，关联master_user.id',
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织ID',
  `registration_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '报名时间',
  `status` int NOT NULL DEFAULT '0' COMMENT '报名状态:0已报名,1已取消',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注信息',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`),
  KEY `idx_activity_id` (`activity_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_org_id` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='活动报名表';
CREATE TABLE `master_album` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `content` varchar(500) DEFAULT NULL COMMENT '相册描述',
  `pic` varchar(255) DEFAULT NULL COMMENT '文件地址',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室相册表';
CREATE TABLE `master_cuiqu` (
  `id` int NOT NULL AUTO_INCREMENT,
  `master_id` int NOT NULL DEFAULT '0',
  `content` varchar(500) DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='技能大题工作室萃取表';
CREATE TABLE `master_cuiqu_answer` (
  `id` int NOT NULL AUTO_INCREMENT,
  `master_id` int NOT NULL DEFAULT '0',
  `cuiqu_id` int NOT NULL DEFAULT '0',
  `content` varchar(500) DEFAULT NULL,
  `pics` json DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `platform_user_id` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室萃取回答表';
CREATE TABLE `master_outcome` (
  `id` int NOT NULL AUTO_INCREMENT,
  `master_id` int NOT NULL DEFAULT '0',
  `tag` varchar(20) DEFAULT NULL COMMENT '标签:patents专利,rewards获奖情况,experts专家团队,files文件资料,thesis论文,doplans计划执行记录,business经营管理情况',
  `title` varchar(50) DEFAULT NULL,
  `content` text,
  `zhicheng` varchar(20) DEFAULT NULL,
  `direction` varchar(30) DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室成果数据';
CREATE TABLE `master_publish_record` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `content` text COMMENT '记录内容',
  `type` varchar(20) DEFAULT NULL COMMENT '类型',
  `addtime` int NOT NULL DEFAULT '1' COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室发布记录表';
CREATE TABLE `master_publish_train` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `tag` varchar(10) DEFAULT NULL COMMENT '标签:train培训,exam考试,review复习',
  `content` text COMMENT '培训内容',
  `nums` int NOT NULL DEFAULT '0' COMMENT '人数',
  `addtime` int NOT NULL DEFAULT '1' COMMENT '创建时间',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室发布培训表';
CREATE TABLE `master_user` (
  `id` int NOT NULL AUTO_INCREMENT,
  `master_id` int NOT NULL DEFAULT '0' COMMENT '工作室id',
  `realname` varchar(50) DEFAULT NULL,
  `gender` int NOT NULL DEFAULT '0' COMMENT '0男,1女',
  `mobile` varchar(11) DEFAULT NULL,
  `level` varchar(50) DEFAULT NULL COMMENT '技能等级',
  `education` varchar(50) DEFAULT NULL COMMENT '学历',
  `major` varchar(50) DEFAULT NULL COMMENT '专业',
  `platform_user_id` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室成员表';
CREATE TABLE `master_vote` (
  `id` int NOT NULL AUTO_INCREMENT,
  `org_id` int NOT NULL DEFAULT '0' COMMENT '组织id',
  `content` text COMMENT '活动内容',
  `status` int NOT NULL DEFAULT '0' COMMENT '0进行中,1完成',
  `agree` int NOT NULL DEFAULT '0' COMMENT '赞成',
  `against` int NOT NULL DEFAULT '0' COMMENT '反对',
  `result` varchar(500) DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='技能大师工作室投票表';
CREATE TABLE `match_activity` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(20) DEFAULT NULL,
  `province_id` int DEFAULT NULL,
  `city_id` int DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `album` text COMMENT '相册',
  `intro` text COMMENT '介绍',
  `result` text COMMENT '成绩公布',
  `paper` text COMMENT '证书展示',
  `content_album` text COMMENT '内容相册',
  `process` text COMMENT '报名流程',
  `max_num` int DEFAULT '0' COMMENT '最大人数',
  `booking_num` int DEFAULT '0' COMMENT '已报名人数',
  `start_date` varchar(20) DEFAULT NULL,
  `end_date` varchar(20) DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `match_activity_people_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `activity_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `match_adventure_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(10) DEFAULT NULL,
  `checkpoint_id` int DEFAULT NULL,
  `content` text COMMENT '题目',
  `get_point` int DEFAULT NULL COMMENT '获得积分',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `match_path_rule_id` int DEFAULT NULL,
  `match_id` int DEFAULT NULL,
  `train_id` int DEFAULT NULL,
  `is_correct` tinyint DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1786 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `match_adventure_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `checkpoint_id` int DEFAULT NULL,
  `correct_num` int DEFAULT NULL COMMENT '答对数量',
  `get_point` int DEFAULT NULL COMMENT '获得积分',
  `user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `add_date` varchar(20) DEFAULT NULL COMMENT '闯关日期',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `match_path_rule_id` int DEFAULT NULL,
  `match_id` int DEFAULT NULL,
  `train_id` int DEFAULT NULL,
  `adventure_index` int DEFAULT NULL COMMENT '第几次',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=363 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `match_answer_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` tinyint DEFAULT '0' COMMENT '0个人  1团队 2答题闯关  3大冒险',
  `correct_num` int DEFAULT NULL COMMENT '答对数量',
  `get_point` int DEFAULT NULL COMMENT '获得积分',
  `match_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `add_date` varchar(20) DEFAULT NULL COMMENT '答题日期',
  `use_time` int DEFAULT NULL COMMENT '用时(秒)',
  `status` tinyint DEFAULT '0' COMMENT '0未比较  1已比较',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=212 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `match_article` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `train_id` int DEFAULT NULL,
  `title` varchar(300) NOT NULL DEFAULT '' COMMENT '文章标题',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '分类类型 0列表 1单页 2外链',
  `show_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '列表显示方式(10小图展示 20大图展示)',
  `topic` varchar(200) NOT NULL DEFAULT '' COMMENT '话题',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章分类ID',
  `album` text COMMENT '相册',
  `source` varchar(100) NOT NULL DEFAULT '' COMMENT '来源',
  `virtual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '虚拟阅读量(仅用作展示)',
  `actual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '实际阅读量',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '发布来源客户端 (APP、H5、小程序等)',
  `files` varchar(1000) DEFAULT NULL COMMENT '文章附件',
  `video` varchar(200) DEFAULT '' COMMENT '视频地址',
  `accept` varchar(50) DEFAULT '' COMMENT '接受的文件类型',
  `longitude` varchar(100) NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(50) NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '街道地址',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数',
  `comment_numbers` int unsigned DEFAULT '0' COMMENT '评论数',
  `to_users` varchar(200) DEFAULT '' COMMENT '提醒谁看',
  `is_public` tinyint DEFAULT NULL COMMENT '是否公开',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=538 DEFAULT CHARSET=utf8 COMMENT='文章记录表';
CREATE TABLE `match_article_comment` (
  `comment_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `score` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '评分 (10好评 20中评 30差评)',
  `content` text NOT NULL COMMENT '评价内容',
  `is_picture` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否为图片评价',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '评论者ID',
  `to_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '被评价者ID',
  `reply_comment_id` int unsigned NOT NULL DEFAULT '0' COMMENT '回复的评论ID',
  `reply_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '回复者ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
