  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='服务器资产记录表';
CREATE TABLE `oa_assets_site` (
  `site_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '网站名称',
  `code` varchar(100) NOT NULL COMMENT '域名标识',
  `type` varchar(100) NOT NULL COMMENT '主机型号',
  `brand` varchar(100) NOT NULL COMMENT '品牌厂商',
  `system` varchar(100) NOT NULL COMMENT '初始账号',
  `price` decimal(10,2) NOT NULL COMMENT '价格',
  `content` longtext COMMENT '详情内容',
  `ssl` varchar(50) NOT NULL DEFAULT '-' COMMENT 'ssl证书',
  `start_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '购买时间',
  `end_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '到期时间',
  `is_top` varchar(50) NOT NULL DEFAULT '-' COMMENT '置顶状态',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` longtext NOT NULL COMMENT '描述',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` varchar(3) NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`site_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='网站管理记录表';
CREATE TABLE `oa_assets_user` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `role` int unsigned NOT NULL DEFAULT '10' COMMENT '角色，10体验成员 20开发者成员 30管理员 ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `assets_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '昵称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `app_id` (`assets_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='服务器成员管理';
CREATE TABLE `oa_assets_vhost` (
  `vhost_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '域名',
  `code` varchar(100) NOT NULL COMMENT '域名标识',
  `type` varchar(100) NOT NULL COMMENT '主机型号',
  `brand` varchar(100) NOT NULL COMMENT '品牌厂商',
  `system` varchar(100) NOT NULL COMMENT '初始账号',
  `price` decimal(10,2) NOT NULL COMMENT '价格',
  `content` longtext COMMENT '详情内容',
  `ssl` varchar(50) NOT NULL DEFAULT '-' COMMENT 'ssl证书',
  `start_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '购买时间',
  `end_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '到期时间',
  `is_top` varchar(50) NOT NULL DEFAULT '-' COMMENT '置顶状态',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` longtext NOT NULL COMMENT '描述',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` varchar(3) NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`vhost_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='虚拟主机记录表';
CREATE TABLE `oa_company` (
  `company_id` int NOT NULL AUTO_INCREMENT COMMENT '企业id',
  `short_name` varchar(50) NOT NULL DEFAULT '' COMMENT '企业简称',
  `company_name` varchar(100) NOT NULL DEFAULT '' COMMENT '企业全称',
  `company_code` varchar(100) NOT NULL DEFAULT '' COMMENT '企业标识',
  `company_type` varchar(50) NOT NULL DEFAULT '' COMMENT '类型 10企业 20政府单位',
  `company_type_multiple` json DEFAULT NULL COMMENT '企业类型多选',
  `company_logo` varchar(200) DEFAULT NULL COMMENT '应用标识',
  `app_type` varchar(50) NOT NULL DEFAULT '' COMMENT '应用类型',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `phone` varchar(100) DEFAULT NULL COMMENT '联系电话',
  `tel` varchar(100) DEFAULT NULL COMMENT '座机电话',
  `email` varchar(200) DEFAULT NULL COMMENT '邮箱',
  `Invoice_header` varchar(50) DEFAULT NULL COMMENT '发票抬头',
  `business_entity` varchar(50) DEFAULT '' COMMENT '企业法人',
  `start_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务开始时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `version` int unsigned NOT NULL DEFAULT '10' COMMENT '应用版本 10体验版 20授权版 30旗舰版',
  `members` int unsigned NOT NULL DEFAULT '20' COMMENT '成员数量(人数上限)',
  `users` int NOT NULL DEFAULT '0' COMMENT '成员数量(当前)',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `departments` int unsigned NOT NULL DEFAULT '100' COMMENT '部门数量',
  `storage` bigint NOT NULL DEFAULT '0' COMMENT '存储空间',
  `storage_max` bigint NOT NULL DEFAULT '524288000' COMMENT '存储空间(上限)',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `authentication` int NOT NULL DEFAULT '0' COMMENT '是否实名认证',
  `authoritative` int NOT NULL DEFAULT '0' COMMENT '企业默认主体',
  `request_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'request合法域名',
  `socket_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'socket合法域名',
  `server_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '主控端域名',
  `modules_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '业务域名',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数量',
  `clicks` int unsigned DEFAULT '0' COMMENT '点击数量',
  `buys` int unsigned DEFAULT '0' COMMENT '购买数量',
  `is_tax` int NOT NULL DEFAULT '0' COMMENT '是否含税, 0不含, 1含',
  `plan_id` int unsigned NOT NULL DEFAULT '0' COMMENT '当前克隆的租户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`company_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `authoritative` (`authoritative`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10210 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='企业信息';
CREATE TABLE `oa_company_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `company_id` int DEFAULT '0' COMMENT '企业ID',
  `name` varchar(200) DEFAULT '' COMMENT '名称',
  `comments` varchar(1000) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1删除',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10578 DEFAULT CHARSET=utf8 COMMENT='企业参数';
CREATE TABLE `oa_company_user` (
  `company_user_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `role` int unsigned NOT NULL DEFAULT '10' COMMENT '角色，10体验成员 20开发者成员 30管理员 ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '昵称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`company_user_id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10357 DEFAULT CHARSET=utf8 COMMENT='成员管理';
CREATE TABLE `oa_link` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(300) NOT NULL DEFAULT '0' COMMENT '链接名称',
  `icon` varchar(300) NOT NULL DEFAULT '' COMMENT '图标',
  `url` varchar(300) NOT NULL DEFAULT '0' COMMENT '链接地址',
  `link_type` varchar(50) NOT NULL DEFAULT '' COMMENT '链接分类',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `recommend` tinyint NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10308 DEFAULT CHARSET=utf8 COMMENT='常用链接';
CREATE TABLE `oa_product` (
  `product_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '产品ID',
  `name` varchar(300) DEFAULT NULL COMMENT '产品名称',
  `code` varchar(300) DEFAULT NULL COMMENT '产品标识',
  `content` longtext NOT NULL COMMENT '产品详情',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '产品类型',
  `logo` varchar(255) DEFAULT NULL COMMENT '产品图标',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '产品金额',
  `sales_initial` int unsigned NOT NULL DEFAULT '0' COMMENT '初始销量',
  `sales_actual` int unsigned NOT NULL DEFAULT '0' COMMENT '实际销量',
  `stock_total` int unsigned NOT NULL DEFAULT '0' COMMENT '库存总量(包含所有sku)',
  `background_color` varchar(255) DEFAULT NULL COMMENT '背景颜色',
  `background_image` varchar(255) DEFAULT NULL COMMENT '背景图片',
  `background_gif` varchar(255) DEFAULT NULL COMMENT '背景图片(gif)',
  `buy_url` varchar(255) DEFAULT NULL COMMENT '购买链接',
  `admin_url` varchar(255) DEFAULT NULL COMMENT '控制台链接',
  `files` longtext COMMENT '附件',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已上架, 1已下架',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`product_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`),
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `code` (`code`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='产品记录表';
CREATE TABLE `oa_product_tabs` (
  `tab_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '产品标签ID',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '产品ID',
  `name` varchar(300) DEFAULT NULL COMMENT '标签名称',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '标签类型',
  `content` longtext NOT NULL COMMENT '产品标签详情',
  `background_color` varchar(255) DEFAULT NULL COMMENT '背景颜色',
  `background_image` varchar(255) DEFAULT NULL COMMENT '背景图片',
  `files` longtext COMMENT '附件',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已上架, 1已下架',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`tab_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='产品标签记录表';
CREATE TABLE `oa_task` (
  `task_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `task_type` varchar(50) NOT NULL DEFAULT '' COMMENT '工单类型',
  `name` longtext COMMENT '任务内容',
  `content` longtext NOT NULL COMMENT '问题描述',
  `files` longtext COMMENT '工单附件',
  `promoter` int NOT NULL DEFAULT '0' COMMENT '工单发起人',
  `commander` int DEFAULT NULL COMMENT '受理人',
  `progress` int NOT NULL DEFAULT '0' COMMENT '工单状态， 0未开始 1已指派 ',
  `priority` varchar(50) NOT NULL DEFAULT '0' COMMENT '优先级',
  `quality` varchar(50) NOT NULL DEFAULT '0' COMMENT '品质要求',
  `day` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '时限(天)',
  `phone` varchar(200) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '手机号',
  `start_time` date DEFAULT NULL COMMENT '开始时间',
  `end_time` date DEFAULT NULL COMMENT '结束时间',
  `overdue_days` int DEFAULT NULL COMMENT '逾期天数',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '项目ID',
  `organization_id` int NOT NULL DEFAULT '0' COMMENT '机构id',
  `project_id` int unsigned NOT NULL DEFAULT '0' COMMENT '项目ID',
  `customer_id` int unsigned NOT NULL DEFAULT '0' COMMENT '客户ID',
  `assets_id` int unsigned NOT NULL DEFAULT '0' COMMENT '资产ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `is_read` int NOT NULL DEFAULT '0' COMMENT '是否已查阅',
  `last_read_user` int NOT NULL DEFAULT '0' COMMENT '最后回复人',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '发起人昵称',
  `avatar` varchar(200) NOT NULL DEFAULT '' COMMENT '发起人头像',
  `last_avatar` varchar(200) NOT NULL DEFAULT '' COMMENT '最后回复人头像',
  `last_nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '最后回复人昵称',
  `is_settled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '订单是否已结算(0未结算 1已结算)',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`),
  KEY `commander` (`commander`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='任务记录表';
CREATE TABLE `oa_task_count` (
  `task_count_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `pending` int unsigned NOT NULL DEFAULT '0' COMMENT '待处理数',
  `unused` int unsigned NOT NULL DEFAULT '0' COMMENT '闲置的工单(废弃)',
  `completed` int unsigned NOT NULL DEFAULT '0' COMMENT '已完成数(废弃)',
  `today` int unsigned NOT NULL DEFAULT '0' COMMENT '今天处理数',
  `month` int unsigned NOT NULL DEFAULT '0' COMMENT '本月处理数',
  `year` int unsigned NOT NULL DEFAULT '0' COMMENT '今年处理数',
  `total` int unsigned NOT NULL DEFAULT '0' COMMENT '总工单数',
  `organization_id` int NOT NULL DEFAULT '0' COMMENT '部门ID',
  `role_id` int unsigned NOT NULL DEFAULT '0' COMMENT '角色ID',
  `role_code` varchar(50) NOT NULL DEFAULT '' COMMENT '角色标识',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`task_count_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='数据统计';
CREATE TABLE `oa_task_record` (
  `task_record_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '回复ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `task_id` int unsigned NOT NULL DEFAULT '0' COMMENT '工单ID',
  `content` longtext NOT NULL COMMENT '内容',
  `confidential` varchar(300) DEFAULT NULL COMMENT '机密信息',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '联系电话',
  `files` longtext COMMENT '工单附件',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`task_record_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`),
  KEY `task_id` (`task_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2258 DEFAULT CHARSET=utf8 COMMENT='工单回复记录表';
CREATE TABLE `oa_task_user` (
  `task_user_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `role` int unsigned NOT NULL DEFAULT '10' COMMENT '角色，10体验成员 20开发者成员 30管理员 ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `task_id` int unsigned NOT NULL DEFAULT '0' COMMENT '工单ID',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '昵称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  PRIMARY KEY (`task_user_id`) USING BTREE,
  KEY `task_id` (`task_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='工单成员';
CREATE TABLE `platform_account` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account` varchar(50) NOT NULL,
  `password` varchar(100) NOT NULL,
  `stat` varchar(6) NOT NULL DEFAULT 'qlgt',
  `role` varchar(50) DEFAULT NULL,
  `nickname` varchar(50) DEFAULT NULL,
  `org_id` int NOT NULL DEFAULT '0',
  `addtime` int NOT NULL DEFAULT '0',
  `logintime` int NOT NULL DEFAULT '0',
  `access_permission` json DEFAULT NULL,
  `access_permissionbtn` json DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `platform_jubao` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL DEFAULT '0',
  `platform_user_id` int NOT NULL DEFAULT '0',
  `content` text,
  `status` int NOT NULL DEFAULT '0',
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='举报日志';
CREATE TABLE `platform_organization` (
  `id` int NOT NULL AUTO_INCREMENT,
  `parent_id` int NOT NULL DEFAULT '0',
  `tag` varchar(50) DEFAULT NULL COMMENT '组织类型',
  `types` json DEFAULT NULL,
  `title` varchar(100) DEFAULT NULL COMMENT '组织名称',
  `title_code` varchar(50) DEFAULT NULL COMMENT '组织代码',
  `address` varchar(300) DEFAULT NULL COMMENT '址址',
  `zipcode` varchar(20) DEFAULT NULL COMMENT '邮编',
  `phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `industrial_id` int NOT NULL DEFAULT '0' COMMENT '所属工业园',
  `lng` varchar(50) DEFAULT NULL COMMENT '经度',
  `lat` varchar(50) DEFAULT NULL COMMENT '纬度',
  `isHot` int NOT NULL DEFAULT '0' COMMENT '是否热门:0否,1是',
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `platform_organization_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
