  `certno` varchar(100) DEFAULT NULL COMMENT '证书编号',
  `certdate` varchar(20) DEFAULT NULL COMMENT '获证日期',
  `certlevel` int NOT NULL DEFAULT '0' COMMENT '证书等级',
  `zymc` varchar(100) DEFAULT NULL COMMENT '职业名称',
  `gzmc` varchar(100) DEFAULT NULL COMMENT '工种名称',
  `tag` int NOT NULL DEFAULT '0' COMMENT '0:职业技能等级证书',
  `filepath` varchar(255) DEFAULT NULL COMMENT '图片路径',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='平台用户证书表';
CREATE TABLE `platform_user_copy1` (
  `id` int NOT NULL AUTO_INCREMENT,
