  `wxopenid` varchar(100) DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  `expert_id` int NOT NULL DEFAULT '0' COMMENT '大于0表示platfrom_account表的专家id',
  `task` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4080 DEFAULT CHARSET=utf8mb4 COMMENT='平台用户表';
CREATE TABLE `platform_user_copy3` (
  `id` int NOT NULL AUTO_INCREMENT,
  `realname` varchar(20) DEFAULT NULL,
  `idcard` varchar(20) DEFAULT NULL,
  `phone` varchar(11) DEFAULT NULL,
  `password` varchar(100) DEFAULT NULL,
  `stat` varchar(4) DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
