CREATE TABLE `platform_user_guzhi` (
  `id` int NOT NULL AUTO_INCREMENT,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `guzhi` int NOT NULL DEFAULT '0',
  `source` int NOT NULL DEFAULT '0' COMMENT '0:培训,1认定,2:竞赛,3开发,4申报',
