  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='用户估值明细';
CREATE TABLE `platform_user_jifen` (
  `id` int NOT NULL AUTO_INCREMENT,
