  `title` varchar(100) DEFAULT NULL COMMENT '项目名称',
  `times` varchar(30) DEFAULT NULL COMMENT '培训期间',
  `class` varchar(100) DEFAULT NULL COMMENT '班级',
  `work_type` varchar(30) DEFAULT NULL COMMENT '工种',
  `level` varchar(10) DEFAULT NULL COMMENT '等级',
  `subsidy` int NOT NULL DEFAULT '0' COMMENT '补贴标准',
  `nums` int NOT NULL DEFAULT '0' COMMENT '人数',
  `subsidy_nums` int NOT NULL DEFAULT '0' COMMENT '获得补贴人数',
  `subsidy_rate` varchar(10) DEFAULT NULL COMMENT '补贴率',
