  `work_type` varchar(50) DEFAULT NULL,
  `level` varchar(30) DEFAULT NULL,
  `times` varchar(50) DEFAULT NULL,
  `paper_no` varchar(50) DEFAULT NULL,
  `paper_time` varchar(30) DEFAULT NULL,
