) ENGINE=InnoDB AUTO_INCREMENT=2235 DEFAULT CHARSET=utf8mb4 COMMENT='营业数据人员情况表';
CREATE TABLE `qlgt_kjexam` (
  `id` int NOT NULL AUTO_INCREMENT,
