  `content` varchar(500) DEFAULT NULL COMMENT '题干',
  `answer` json DEFAULT NULL COMMENT '选项',
  `isright` varchar(30) DEFAULT NULL COMMENT '答案',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5635 DEFAULT CHARSET=utf8mb4 COMMENT='课件随堂练习题库';
