CREATE TABLE `qlgt_kjexam_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company` varchar(100) DEFAULT NULL COMMENT '企业名称',
  `company_code` varchar(50) DEFAULT NULL COMMENT '企业执照号',
  `banji` varchar(100) DEFAULT NULL,
  `banji_id` int NOT NULL DEFAULT '0',
  `kejian_id` int NOT NULL DEFAULT '0',
  `work_type_id` int NOT NULL DEFAULT '0',
  `kaodian_two` varchar(100) DEFAULT NULL,
  `time_start` int NOT NULL DEFAULT '0',
  `time_end` int NOT NULL DEFAULT '0',
  `teacher` varchar(20) DEFAULT NULL COMMENT '老师手机号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
