) ENGINE=InnoDB AUTO_INCREMENT=95 DEFAULT CHARSET=utf8mb4 COMMENT='课件随堂练习用户日志';
CREATE TABLE `qlgt_kjexam_worktype` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COMMENT='课件随堂练习工种表';
CREATE TABLE `qlgt_match_company` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(50) NOT NULL,
  `phone` varchar(11) DEFAULT NULL,
  `org_code` varchar(50) DEFAULT NULL COMMENT '营业执照号',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COMMENT='参赛企业表';
CREATE TABLE `qlgt_match_exam` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `qmlp_id` int NOT NULL DEFAULT '0',
  `type` int NOT NULL DEFAULT '0' COMMENT '0理论,1实操,2实操笔答',
  `path` varchar(100) DEFAULT NULL COMMENT '试题导入文件路径',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COMMENT='竞赛试卷表';
CREATE TABLE `qlgt_match_exam_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int NOT NULL DEFAULT '0' COMMENT '试卷表id',
  `exam_type` int NOT NULL DEFAULT '0' COMMENT '0理论,2实操笔答',
  `content` varchar(500) DEFAULT NULL COMMENT '题干',
  `type` varchar(10) DEFAULT NULL COMMENT '题型',
  `sn` int NOT NULL DEFAULT '0' COMMENT '序号',
  `score` int NOT NULL DEFAULT '1' COMMENT '分值',
  `isright` varchar(50) DEFAULT NULL COMMENT '参考答案',
  `A` varchar(100) DEFAULT NULL,
  `B` varchar(100) DEFAULT NULL,
  `C` varchar(100) DEFAULT NULL,
  `D` varchar(100) DEFAULT NULL,
  `E` varchar(100) DEFAULT NULL,
  `F` varchar(100) DEFAULT NULL,
  `G` varchar(100) DEFAULT NULL,
  `H` varchar(100) DEFAULT NULL,
  `answer` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1778 DEFAULT CHARSET=utf8mb4 COMMENT='试卷试题表';
CREATE TABLE `qlgt_match_exam_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL DEFAULT '0' COMMENT '考生id',
  `qmlp_id` int NOT NULL DEFAULT '0' COMMENT '计划id',
  `exam_id` int NOT NULL DEFAULT '0' COMMENT '试卷id',
  `score` int NOT NULL DEFAULT '0',
  `score_single` int NOT NULL DEFAULT '0',
  `score_multi` int NOT NULL DEFAULT '0',
  `score_judge` int NOT NULL DEFAULT '0',
  `exams` json DEFAULT NULL COMMENT '答题记录',
  `type` int NOT NULL DEFAULT '0' COMMENT '0理认,1实操,2实操笔答',
  `addtime` int NOT NULL,
  `task` int NOT NULL DEFAULT '0' COMMENT '任务状态:0待处,1已处理',
  `exam_file` varchar(200) DEFAULT NULL COMMENT '试卷文件',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=269 DEFAULT CHARSET=utf8mb4 COMMENT='考生答题记录';
CREATE TABLE `qlgt_match_exam_logexport_task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `qmlp_id` int NOT NULL DEFAULT '0',
  `file` varchar(500) DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='考试结果导出试卷格式任务';
CREATE TABLE `qlgt_match_people` (
  `id` int NOT NULL AUTO_INCREMENT,
  `qmlp_id` int NOT NULL DEFAULT '0' COMMENT 'qlgt_match_lilun_plan表id',
  `realname` varchar(10) DEFAULT NULL COMMENT '姓名',
  `idcard` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `mobile` varchar(11) DEFAULT NULL COMMENT '手机号',
  `gender` int NOT NULL DEFAULT '0' COMMENT '0男,1女',
  `type` int NOT NULL DEFAULT '0' COMMENT '人员类型:0参赛人员,1考评员,2后台人员',
  `company_id` int NOT NULL DEFAULT '0' COMMENT '企业id',
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '工种id',
  `work_type` varchar(100) DEFAULT NULL,
  `face_log` json DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=505 DEFAULT CHARSET=utf8mb4 COMMENT='理论考试计划人员表';
CREATE TABLE `qlgt_match_people_facehelp` (
  `id` int NOT NULL AUTO_INCREMENT,
  `idcard` varchar(18) NOT NULL,
  `realname` varchar(10) NOT NULL,
  `status` int NOT NULL DEFAULT '0' COMMENT '0待处理,1通过,2拒绝',
  `addtime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COMMENT='人脸识别帮助';
CREATE TABLE `qlgt_match_plan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `plan_type` varchar(20) NOT NULL DEFAULT '0' COMMENT '计划类型:0理论,1实操,2实操笔答',
  `type` int NOT NULL DEFAULT '0' COMMENT '0线上,1线下',
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '工种id',
  `exam_time` int NOT NULL COMMENT '考试时间,单位:分钟',
  `exam_id` int NOT NULL DEFAULT '0',
  `start_date` varchar(20) DEFAULT NULL,
  `addtime` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COMMENT='千铝工投竞赛计划表';
CREATE TABLE `qlgt_match_shicao_exam` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int NOT NULL DEFAULT '0',
  `work_type` varchar(50) DEFAULT NULL,
  `exam_title` varchar(200) DEFAULT NULL,
  `exam_score` int NOT NULL DEFAULT '0' COMMENT '配分',
  `exam_weight` int NOT NULL DEFAULT '0' COMMENT '权重',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COMMENT='竞赛实操题表';
CREATE TABLE `qlgt_match_shicao_exam_item` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exam_id` int NOT NULL DEFAULT '0',
  `title` varchar(100) DEFAULT NULL COMMENT '试题项目',
  `score` int NOT NULL DEFAULT '0' COMMENT '分值',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COMMENT='竞赛实操题项目表';
CREATE TABLE `qlgt_match_shicao_exam_user_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL DEFAULT '0',
  `work_type_id` int NOT NULL DEFAULT '0',
  `exam_id` int NOT NULL DEFAULT '0',
  `item_id` int NOT NULL DEFAULT '0',
  `item_score` int NOT NULL DEFAULT '0' COMMENT '试题细项得分',
  `exam_score` int NOT NULL DEFAULT '0' COMMENT '试题得分',
  `create_time` datetime DEFAULT NULL COMMENT '得分提交时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1199 DEFAULT CHARSET=utf8mb4 COMMENT='实操用户得分记录';
CREATE TABLE `qlgt_match_shicao_score` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL DEFAULT '0',
  `work_type_id` int NOT NULL DEFAULT '0',
  `score` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COMMENT='用户实操成绩表';
CREATE TABLE `qlgt_match_wenda` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) NOT NULL COMMENT '标题',
  `content` text NOT NULL COMMENT '内容',
  `read_count` int NOT NULL DEFAULT '0' COMMENT '被浏览次数',
  `answer_count` int NOT NULL DEFAULT '0' COMMENT '被回答次数',
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否为删除:0否,1是',
  `match_id` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='竞赛社群问答';
CREATE TABLE `qlgt_match_wenda_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `wenda_id` int NOT NULL DEFAULT '0' COMMENT '问答id',
  `user_id` int NOT NULL DEFAULT '0',
  `content` text COMMENT '回答内容',
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否为删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COMMENT='问答回答记录';
CREATE TABLE `shop_brand` (
  `brand_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `brand_name` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌名称',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '图标',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`brand_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='品牌';
CREATE TABLE `shop_cart` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `goods_sku_id` varchar(255) NOT NULL COMMENT '商品sku唯一标识',
  `cart_num` int unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `spec` varchar(500) DEFAULT NULL,
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `total_price` decimal(10,2) DEFAULT NULL,
  `point` int DEFAULT '0',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '商品封面图',
  `is_new` tinyint DEFAULT '1',
  `selected` tinyint DEFAULT '1',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `goods_id_2` (`goods_id`,`goods_sku_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=121 DEFAULT CHARSET=utf8 COMMENT='购物车记录表';
CREATE TABLE `shop_charge_package` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL COMMENT '金额',
  `send_amount` decimal(10,2) DEFAULT NULL COMMENT '赠送金额',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='充值套餐';
CREATE TABLE `shop_chat_conversation` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `friend_id` int DEFAULT NULL COMMENT '好友ID',
  `type` int DEFAULT NULL COMMENT '消息类型',
  `content` text NOT NULL COMMENT '消息内容',
  `un_read` int NOT NULL DEFAULT '0' COMMENT '未读消息',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未读, 1已读',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `id` (`id`),
  KEY `user_id` (`user_id`),
  KEY `friend_id` (`friend_id`),
  KEY `type` (`type`),
  KEY `un_read` (`un_read`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='聊天消息表';
CREATE TABLE `shop_chat_message` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `form_user_id` int NOT NULL COMMENT '发送人ID',
  `to_user_id` int NOT NULL COMMENT '接收人ID',
  `type` varchar(255) NOT NULL COMMENT '消息类型',
  `content` text NOT NULL COMMENT '消息内容',
  `side_to` int NOT NULL DEFAULT '0' COMMENT '屏蔽接收方',
  `side_from` int NOT NULL DEFAULT '0' COMMENT '屏蔽发送方',
  `withdraw` int NOT NULL DEFAULT '0' COMMENT '是否撤回',
  `file_info` json DEFAULT NULL COMMENT '文件信息',
  `has_contact` int DEFAULT NULL COMMENT '存在联系方式',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未读, 1已读',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `id` (`id`),
  KEY `form_user_id` (`form_user_id`),
  KEY `to_user_id` (`to_user_id`),
  KEY `type` (`type`),
  KEY `withdraw` (`withdraw`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='聊天消息表';
CREATE TABLE `shop_express_list` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(20) CHARACTER SET utf8 DEFAULT NULL,
  `shortname` varchar(100) CHARACTER SET utf8 DEFAULT NULL,
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` int DEFAULT '0',
  `sort_number` int DEFAULT '100',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`) USING BTREE,
  KEY `title` (`title`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `shop_goods` (
  `goods_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int NOT NULL DEFAULT '1' COMMENT '类型 1实物商品 2虚拟商品',
  `code` varchar(200) NOT NULL DEFAULT '' COMMENT '商品编码',
  `goods_name` varchar(200) NOT NULL DEFAULT '' COMMENT '商品标题',
  `image` varchar(2000) NOT NULL DEFAULT '' COMMENT '商品封面图',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '商品详情',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '商品分类ID',
  `category_parent` varchar(200) DEFAULT '' COMMENT '一级分类',
  `category_children` varchar(200) DEFAULT '' COMMENT '二级分类',
  `specs` int NOT NULL DEFAULT '0' COMMENT '商品规格 0单规格 1多规格',
  `position` varchar(50) DEFAULT NULL COMMENT '货架',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '进货价格',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '销售价格',
  `deduct_stock_type` tinyint unsigned NOT NULL DEFAULT '20' COMMENT '库存计算方式(10下单减库存 20付款减库存)',
  `files` varchar(2000) NOT NULL DEFAULT '' COMMENT '封面图',
  `sales` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '销量',
  `stock` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `goods_weight` int NOT NULL DEFAULT '0' COMMENT '商品重量',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '推荐',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `merchant_name` varchar(200) DEFAULT '' COMMENT '商户名称',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0上架 1下架 2待审核 3审核不通过',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `is_show` tinyint DEFAULT '1',
  `point` int DEFAULT '0',
  `unit_name` varchar(500) DEFAULT NULL,
  `gain_integral` int DEFAULT '0',
  PRIMARY KEY (`goods_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8 COMMENT='商品记录表';
CREATE TABLE `shop_goods_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '商品分类ID',
  `category_code` varchar(50) NOT NULL DEFAULT '' COMMENT '分类标识',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0列表 1单页 2外链',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '分类图片',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `component` varchar(300) NOT NULL DEFAULT '' COMMENT '组件路径',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `count` int unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `show_index` int NOT NULL DEFAULT '0' COMMENT '是否显示在首页',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1禁用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10076 DEFAULT CHARSET=utf8 COMMENT='商品分类';
CREATE TABLE `shop_goods_category_rel` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL COMMENT '商品ID',
  `category_id` int unsigned NOT NULL COMMENT '商品分类ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属门店ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商品与分类关系记录表';
CREATE TABLE `shop_goods_comment` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `uid` int NOT NULL DEFAULT '0' COMMENT '用户ID',
  `oid` int NOT NULL DEFAULT '0' COMMENT '订单ID',
  `unique` varchar(32) NOT NULL COMMENT '商品唯一id',
  `goods_id` int NOT NULL COMMENT '商品id',
  `reply_type` varchar(32) NOT NULL DEFAULT 'product' COMMENT '某种商品类型(普通商品、秒杀商品）',
  `goods_score` tinyint NOT NULL COMMENT '商品分数',
  `service_score` tinyint NOT NULL COMMENT '服务分数',
  `comment` varchar(512) NOT NULL COMMENT '评论内容',
  `pics` text NOT NULL COMMENT '评论图片',
  `merchant_reply_content` varchar(300) DEFAULT NULL COMMENT '管理员回复内容',
  `merchant_reply_time` int DEFAULT NULL COMMENT '管理员回复时间',
  `is_del` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未删除1已删除',
  `is_reply` tinyint NOT NULL DEFAULT '0' COMMENT '0未回复1已回复',
  `nickname` varchar(64) NOT NULL COMMENT '用户名称',
  `avatar` varchar(255) NOT NULL COMMENT '用户头像',
  `sku` varchar(128) NOT NULL DEFAULT '' COMMENT '商品规格属性值,多个,号隔开',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `parent_id` (`reply_type`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `goods_score` (`goods_score`) USING BTREE,
  KEY `service_score` (`service_score`) USING BTREE,
  KEY `uid+oid` (`uid`,`oid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='评论表';
CREATE TABLE `shop_goods_coupon` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '商品id',
  `issue_coupon_id` int NOT NULL DEFAULT '0' COMMENT '优惠劵id',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='商品优惠券表';
CREATE TABLE `shop_goods_image` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `url` varchar(200) NOT NULL COMMENT '图片路径',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='商品图片记录表';
CREATE TABLE `shop_goods_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `type` varchar(10) NOT NULL COMMENT '类型visit,cart,order,pay,collect,refund',
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '商品ID',
  `visit_num` tinyint NOT NULL DEFAULT '0' COMMENT '是否浏览',
  `cart_num` int NOT NULL DEFAULT '0' COMMENT '加入购物车数量',
  `order_num` int NOT NULL DEFAULT '0' COMMENT '下单数量',
  `pay_num` int NOT NULL DEFAULT '0' COMMENT '支付数量',
  `pay_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '支付金额',
  `cost_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品成本价',
  `pay_uid` int NOT NULL DEFAULT '0' COMMENT '支付用户ID',
  `refund_num` int NOT NULL DEFAULT '0' COMMENT '退款数量',
  `refund_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `collect_num` tinyint NOT NULL DEFAULT '0' COMMENT '收藏',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='商品日志表';
CREATE TABLE `shop_goods_relation` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` int unsigned NOT NULL COMMENT '用户ID',
  `goods_id` int unsigned NOT NULL COMMENT '商品ID',
  `type` varchar(32) NOT NULL COMMENT '类型(收藏(collect）、点赞(like))',
  `category` varchar(32) NOT NULL COMMENT '某种类型的商品(普通商品、秒杀商品)',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `user_id` (`user_id`,`goods_id`,`type`,`category`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `category` (`category`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='商品点赞和收藏表';
CREATE TABLE `shop_goods_service` (
  `service_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '商品服务ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '服务名称',
  `summary` varchar(500) NOT NULL DEFAULT '' COMMENT '概述',
  `is_default` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否默认(新增商品时)',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属门店ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`service_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商品服务与承诺记录表';
CREATE TABLE `shop_goods_service_rel` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL COMMENT '商品ID',
  `service_id` int unsigned NOT NULL COMMENT '服务承诺ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属门店ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `service_id` (`service_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商品与服务承诺关系记录表';
CREATE TABLE `shop_goods_sku` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `spec_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格组ID',
  `spec_value_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格值ID',
  `spec_value0` varchar(50) DEFAULT '' COMMENT '规格值0',
  `spec_value1` varchar(50) DEFAULT '' COMMENT '规格值1',
  `spec_value2` varchar(50) DEFAULT '' COMMENT '规格值2',
  `image` varchar(300) DEFAULT '' COMMENT '商品图片',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '市场价格',
  `stock` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `sku_no` varchar(300) DEFAULT '' COMMENT 'sku编码',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0正常, 1异常',
  `sku` varchar(500) DEFAULT NULL,
  `cost` int DEFAULT '0',
  `uuid` varchar(255) DEFAULT NULL,
  `bar_code` varchar(255) DEFAULT NULL,
  `weight` double DEFAULT NULL,
  `volume` double DEFAULT NULL,
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `point` int DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `spec_id` (`spec_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=552 DEFAULT CHARSET=utf8 COMMENT='商品sku列表';
CREATE TABLE `shop_goods_spec` (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `spec_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格ID',
  `spec_name` varchar(32) NOT NULL COMMENT '规格名称',
  `spec_values` varchar(2000) DEFAULT NULL COMMENT '规格值',
  `type` tinyint DEFAULT '0' COMMENT '活动类型 0=商品，1=秒杀，2=砍价，3=拼团',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `spec_value` text CHARACTER SET utf8,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `spec_id` (`spec_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=167 DEFAULT CHARSET=utf8mb4 COMMENT='商品多规格';
CREATE TABLE `shop_goods_spec_rel` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `spec_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格组ID',
  `spec_value_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格值ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属门店ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商品与规格值关系记录表';
CREATE TABLE `shop_merchant` (
  `merchant_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `merchant_name` varchar(255) NOT NULL DEFAULT '' COMMENT '商户名称',
  `merchant_code` varchar(100) NOT NULL DEFAULT '' COMMENT '商户编号',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '商户图标',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '商户手机号',
  `real_name` varchar(50) NOT NULL DEFAULT '' COMMENT '商户姓名',
  `shop_type` varchar(50) NOT NULL DEFAULT '' COMMENT '店铺类型',
  `item_type` varchar(50) NOT NULL DEFAULT '0' COMMENT '项目分类',
  `category` varchar(50) NOT NULL DEFAULT '' COMMENT '商户分类',
  `lng_and_lat` varchar(255) DEFAULT '' COMMENT '经纬度',
  `province` varchar(50) NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) NOT NULL DEFAULT '' COMMENT '详细地址',
  `commission` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `keywords` varchar(200) NOT NULL DEFAULT '' COMMENT '关键字',
  `files` varchar(2000) NOT NULL DEFAULT '' COMMENT '资质图片',
  `business_time` varchar(100) CHARACTER SET utf8mb4 NOT NULL COMMENT '营业时间',
  `content` text CHARACTER SET utf8mb4 COMMENT '文章内容',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '每小时价格',
  `own_store` int NOT NULL DEFAULT '0' COMMENT '是否自营',
  `recommend` int NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `goods_review` int NOT NULL DEFAULT '1' COMMENT '是否需要审核',
  `admin_url` varchar(300) DEFAULT '' COMMENT '管理入口',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所有人',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`merchant_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchant_code` (`merchant_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3030 DEFAULT CHARSET=utf8 COMMENT='商户';
CREATE TABLE `shop_merchant_account` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '商户手机号',
  `real_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '真实姓名',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `role_id` int unsigned NOT NULL DEFAULT '0' COMMENT '角色ID',
  `role_name` varchar(50) NOT NULL DEFAULT '' COMMENT '角色名称',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3071 DEFAULT CHARSET=utf8 COMMENT='商户账号';
CREATE TABLE `shop_merchant_apply` (
  `apply_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `merchant_name` varchar(255) NOT NULL DEFAULT '' COMMENT '商户名称',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '商户图标',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '商户手机号',
  `real_name` varchar(50) NOT NULL DEFAULT '' COMMENT '商户姓名',
  `shop_type` varchar(50) NOT NULL DEFAULT '' COMMENT '店铺类型',
  `category` varchar(50) NOT NULL DEFAULT '' COMMENT '商户分类',
  `commission` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `keywords` varchar(200) NOT NULL DEFAULT '' COMMENT '关键字',
  `files` varchar(2000) NOT NULL DEFAULT '' COMMENT '资质图片',
  `own_store` int NOT NULL DEFAULT '0' COMMENT '是否自营',
  `recommend` int NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `goods_review` int NOT NULL DEFAULT '1' COMMENT '是否需要审核',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`apply_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商户入驻申请';
CREATE TABLE `shop_merchant_type` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '店铺类型',
  `comments` longtext NOT NULL COMMENT '店铺入驻条件',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8 COMMENT='商户类型';
CREATE TABLE `shop_message` (
  `id` int NOT NULL AUTO_INCREMENT,
  `type` varchar(255) DEFAULT NULL,
  `pk` int DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `content` text,
  `user_id` int DEFAULT NULL,
  `platform_user_id` int NOT NULL DEFAULT '0',
  `has_read` tinyint DEFAULT '0',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `send_from` tinyint DEFAULT '0' COMMENT '0系统   1人工',
  PRIMARY KEY (`id`),
  KEY `id` (`id`),
  KEY `type` (`type`),
  KEY `pk` (`pk`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10765 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `shop_order` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订单号',
  `order_no` char(64) NOT NULL DEFAULT '' COMMENT '订单编号',
  `type` int unsigned NOT NULL DEFAULT '1' COMMENT '订单类型，0商城订单 1预定订单 2会员卡 3充值',
  `channel` tinyint DEFAULT '0' COMMENT '下单渠道，0小程序预定 1俱乐部训练场 3活动订场',
  `transaction_id` char(64) DEFAULT '' COMMENT '微信支付订单号',
  `refund_order` char(64) DEFAULT '' COMMENT '微信退款订单号',
  `merchant_id` int DEFAULT '0' COMMENT '商户ID',
  `merchant_name` varchar(200) DEFAULT '' COMMENT '商户名称',
  `merchant_code` varchar(50) DEFAULT '' COMMENT '商户编号',
  `coupon_id` int DEFAULT '0' COMMENT '使用的优惠券id',
  `card_id` varchar(20) DEFAULT '' COMMENT '使用的会员卡id',
  `admin_id` int unsigned DEFAULT '0' COMMENT '关联管理员id',
  `confirm_id` int unsigned DEFAULT '0' COMMENT '核销管理员id',
  `ic_card` varchar(50) DEFAULT NULL COMMENT 'IC卡号',
  `real_name` char(20) NOT NULL COMMENT '真实姓名',
  `phone` char(11) DEFAULT NULL COMMENT '手机号码',
  `address` varchar(500) DEFAULT NULL,
  `total_price` decimal(8,2) NOT NULL COMMENT '订单总额',
  `reduce_price` decimal(8,2) DEFAULT '0.00' COMMENT '减少的金额，使用VIP会员折扣、优惠券抵扣、优惠券折扣后减去的价格',
  `pay_price` decimal(8,2) NOT NULL COMMENT '实际付款',
  `point` decimal(10,2) DEFAULT '0.00',
  `price` decimal(8,2) DEFAULT NULL COMMENT '用于统计',
  `money` decimal(8,0) unsigned DEFAULT '0' COMMENT '价钱，用于积分赠送',
  `refund_money` decimal(8,2) DEFAULT '0.00' COMMENT '退款金额',
  `coach_price` decimal(8,2) DEFAULT '0.00' COMMENT '教练价格',
  `total_num` int unsigned NOT NULL DEFAULT '1' COMMENT '购买数量',
  `coach_id` mediumint unsigned DEFAULT '0' COMMENT '教练id',
  `pay_type` int unsigned NOT NULL DEFAULT '1' COMMENT '0余额支付, 1微信支付，2积分，3支付宝',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未付款，1已付款',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0待付款  1已付款待发货  2已发货   3已收货  ',
  `coupon_type` int NOT NULL DEFAULT '0' COMMENT '优惠类型：0无、1抵扣优惠券、2折扣优惠券、3、VIP月卡、4VIP年卡，5VIP次卡、6VIP会员卡、7IC月卡、8IC年卡、9IC次卡、10IC会员卡、11免费订单、12VIP充值卡、13IC充值卡、14VIP季卡、15IC季卡',
  `coupon_desc` varchar(200) DEFAULT NULL COMMENT '优惠说明',
  `qrcode` varchar(200) DEFAULT NULL COMMENT '二维码地址，保存订单号，支付成功后才生成',
  `return_num` mediumint DEFAULT '0' COMMENT 'vip月卡年卡、ic月卡年卡回退次数',
  `return_money` decimal(8,2) DEFAULT '0.00' COMMENT 'vip充值回退金额',
  `start_time` varchar(300) NOT NULL DEFAULT '' COMMENT '预约详情开始时间数组',
  `is_invoice` tinyint unsigned DEFAULT '0' COMMENT '是否已开具发票：0未开发票，1已开发票，2不能开具发票',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `refund_time` timestamp NULL DEFAULT NULL COMMENT '退款时间',
  `refund_apply_time` timestamp NULL DEFAULT NULL COMMENT '申请退款时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `check_bill` tinyint DEFAULT '0' COMMENT '对账情况：0=未对账；1=已对账；3=已对账，金额对不上；4=未查询到该订单',
  `is_settled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '订单是否已结算(0未结算 1已结算)',
  `version` int NOT NULL DEFAULT '0' COMMENT '系统版本号 0当前版本 value=其他版本',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `comments` varchar(500) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `express_id` int DEFAULT NULL,
  `express_name` varchar(255) DEFAULT NULL,
  `express_no` varchar(255) DEFAULT NULL,
  `receive_time` timestamp NULL DEFAULT NULL COMMENT '收货时间',
  `pay_method` varchar(20) DEFAULT NULL,
  `charge_package_id` int DEFAULT NULL,
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE,
  KEY `merchant_code` (`merchant_code`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=582929 DEFAULT CHARSET=utf8mb4 COMMENT='订单';
CREATE TABLE `shop_order_goods` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联订单表id',
  `order_code` varchar(30) NOT NULL DEFAULT '' COMMENT '订单标识',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联商户ID',
  `merchant_name` varchar(30) NOT NULL DEFAULT '' COMMENT '商户名称',
  `image` varchar(500) NOT NULL DEFAULT '' COMMENT '商品封面图',
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '关联商品id',
  `goods_name` varchar(200) NOT NULL DEFAULT '' COMMENT '商品名称',
  `price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单价',
  `total_num` int unsigned NOT NULL DEFAULT '1' COMMENT '购买数量',
  `pay_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0 未付款 1已付款，2无需付款或占用状态',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未使用，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `is_free` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否免费：0收费、1免费',
  `version` tinyint NOT NULL DEFAULT '0' COMMENT '系统版本 0当前版本 其他版本',
  `time_period` varchar(30) NOT NULL DEFAULT '' COMMENT '预约时间段',
  `date_time` date DEFAULT NULL COMMENT '预定日期',
  `start_time` time DEFAULT NULL COMMENT '开场时间',
  `end_time` time DEFAULT NULL COMMENT '结束时间',
  `time_flag` bigint NOT NULL DEFAULT '0' COMMENT '毫秒时间戳',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `point` decimal(10,2) DEFAULT '0.00',
  `sku_name` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `order_id` (`order_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=754686 DEFAULT CHARSET=utf8mb4 COMMENT='商品信息';
CREATE TABLE `shop_order_info` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联订单表id',
  `order_code` varchar(30) NOT NULL DEFAULT '' COMMENT '组合数据:日期+时间段+场馆id+场地id',
  `price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单价',
  `pay_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0 未付款 1已付款，2无需付款或占用状态',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未使用，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `oid` (`order_id`) USING BTREE,
  KEY `merge_time_status` (`order_code`,`pay_status`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=754563 DEFAULT CHARSET=utf8mb4 COMMENT='场地';
CREATE TABLE `shop_order_info_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int unsigned NOT NULL COMMENT '关联订单表id',
  `merchant_id` int unsigned NOT NULL COMMENT '关联商户ID',
  `field_id` int NOT NULL COMMENT '关联场地id',
  `use_num` tinyint NOT NULL DEFAULT '0' COMMENT '核销数量',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=288248 DEFAULT CHARSET=utf8mb4 COMMENT='订单核销';
CREATE TABLE `shop_spec` (
  `spec_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格组ID',
  `spec_name` varchar(255) NOT NULL DEFAULT '' COMMENT '规格组名称',
  `spec_value` text NOT NULL,
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0正常, 1待修,2异常已修，3异常未修',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`spec_id`) USING BTREE,
  KEY `spec_name` (`spec_name`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8 COMMENT='规格';
CREATE TABLE `shop_spec_value` (
  `spec_value_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格值ID',
  `spec_id` int NOT NULL COMMENT '规格组ID',
  `spec_value` varchar(255) NOT NULL COMMENT '规格值',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`spec_value_id`) USING BTREE,
  KEY `spec_value` (`spec_value`),
  KEY `spec_id` (`spec_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='规格值';
CREATE TABLE `shop_user_address` (
  `address_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(30) NOT NULL DEFAULT '' COMMENT '收货人姓名',
  `phone` varchar(20) NOT NULL DEFAULT '' COMMENT '联系电话',
  `province_id` int unsigned NOT NULL DEFAULT '0' COMMENT '省份ID',
  `city_id` int unsigned NOT NULL DEFAULT '0' COMMENT '城市ID',
  `region_id` int unsigned NOT NULL DEFAULT '0' COMMENT '区/县ID',
  `detail` varchar(255) NOT NULL DEFAULT '' COMMENT '详细地址',
  `full_address` varchar(500) DEFAULT NULL COMMENT '完整地址',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `is_default` tinyint DEFAULT '0' COMMENT '是否默认地址',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`address_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8 COMMENT='用户收货地址表';
CREATE TABLE `shop_user_balance_log` (
  `log_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `scene` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '余额变动场景(10用户充值 20用户消费 30管理员操作 40订单退款)',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '变动金额',
  `balance` decimal(20,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '变动后余额',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '管理员备注',
  `order_no` varchar(30) NOT NULL DEFAULT '0' COMMENT '订单编号',
  `admin_id` int unsigned NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '0' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='用户余额变动明细表';
CREATE TABLE `shop_user_collection` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tid` int unsigned NOT NULL DEFAULT '0' COMMENT '租户ID',
  `type` varchar(255) DEFAULT NULL,
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10824 DEFAULT CHARSET=utf8 COMMENT='我的收藏';
CREATE TABLE `shop_users` (
  `uid` int unsigned NOT NULL AUTO_INCREMENT,
  `openid` varchar(100) NOT NULL COMMENT '用户唯一小程序id',
  `session_key` varchar(100) DEFAULT NULL COMMENT '小程序用户秘钥',
  `username` varchar(30) NOT NULL COMMENT '用户名',
  `avatar_url` varchar(200) NOT NULL COMMENT '头像地址',
  `sex` tinyint unsigned NOT NULL COMMENT '1男，2女',
  `country` varchar(20) NOT NULL COMMENT '国家',
  `province` varchar(20) NOT NULL COMMENT '省份',
  `city` varchar(20) NOT NULL COMMENT '城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `phone` char(11) DEFAULT NULL COMMENT '手机号码',
  `email` varchar(200) DEFAULT NULL COMMENT '邮箱',
  `email_verified` int NOT NULL DEFAULT '0' COMMENT '邮箱是否验证, 0否, 1是',
  `points` decimal(10,2) DEFAULT '0.00' COMMENT '积分',
  `balance` decimal(10,2) DEFAULT '0.00' COMMENT '余额',
  `add_time` int unsigned NOT NULL COMMENT '注册时间',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号码',
  `real_name` varchar(30) DEFAULT NULL COMMENT '真实姓名',
  `is_admin` tinyint DEFAULT '2' COMMENT '是否管理员：1是；2否',
  `client_id` varchar(100) DEFAULT '' COMMENT '客户端ID',
  `platform` varchar(20) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '注册来源客户端 (APP、H5、小程序等)',
  `sort_number` mediumint NOT NULL COMMENT '排序',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`uid`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户';
CREATE TABLE `shop_wechat_deposit` (
  `id` mediumint unsigned NOT NULL AUTO_INCREMENT,
  `oid` mediumint unsigned NOT NULL COMMENT '订单id',
  `uid` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `order_num` char(27) NOT NULL COMMENT '场地订单号',
  `wechat_order` char(27) NOT NULL COMMENT '付款订单号',
  `wechat_return` char(27) DEFAULT NULL COMMENT '退款订单号 ',
  `site_name` varchar(50) NOT NULL COMMENT '场馆名称',
  `username` varchar(50) NOT NULL COMMENT '微信昵称',
  `phone` char(11) NOT NULL COMMENT '手机号码',
  `name` varchar(50) NOT NULL COMMENT '物品名称',
  `price` decimal(8,2) NOT NULL COMMENT '押金金额',
  `status` tinyint unsigned NOT NULL DEFAULT '2' COMMENT '押金状态，1已付款，2未付款，已退押金',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8 COMMENT='押金';
CREATE TABLE `sys_area` (
  `id` int NOT NULL,
  `name` varchar(50) DEFAULT NULL,
  `fid` int DEFAULT NULL,
  `level_id` tinyint DEFAULT NULL,
  `tenant_id` int NOT NULL DEFAULT '10036' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE `sys_dictionary` (
  `id` int NOT NULL AUTO_INCREMENT,
  `codes` varchar(50) DEFAULT NULL,
  `title` varchar(50) DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `uptime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `sys_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account_id` int NOT NULL DEFAULT '0',
  `opt_type` int NOT NULL DEFAULT '0' COMMENT '0:新增,1更新,2删除,3上传,4导出',
  `post` json DEFAULT NULL,
  `api` varchar(255) DEFAULT NULL,
  `addtime` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10662 DEFAULT CHARSET=utf8mb4 COMMENT='账号作操日志';
CREATE TABLE `sys_qlgt` (
  `id` int NOT NULL AUTO_INCREMENT,
  `account` varchar(50) DEFAULT NULL,
  `password` varchar(50) DEFAULT NULL,
  `stat` varchar(4) DEFAULT NULL,
  `title` varchar(50) DEFAULT NULL,
  `addtime` int DEFAULT '0',
  `logintime` int DEFAULT '0',
  `role` int DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `sys_user_detail` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL COMMENT '联系方式',
  `realname` varchar(20) DEFAULT NULL COMMENT '姓名',
  `id_card` varchar(50) DEFAULT NULL COMMENT '身份证号',
  `birthday` varchar(20) DEFAULT NULL,
  `head_photo` varchar(255) DEFAULT NULL COMMENT '证件照',
  `head_photo2` varchar(255) DEFAULT NULL COMMENT '证件照(两寸)',
  `role` tinyint DEFAULT '0' COMMENT '0命审专家1项目负责人2终审专家',
  `is_in_charge` tinyint DEFAULT '0' COMMENT '是否为机构负责人',
  `position` varchar(255) DEFAULT NULL COMMENT '职称',
  `email` varchar(255) DEFAULT NULL COMMENT '电子邮箱',
  `company` varchar(255) DEFAULT NULL COMMENT '工作单位',
  `company_name` varchar(255) DEFAULT NULL,
  `company_address` varchar(500) DEFAULT NULL,
  `company_code` varchar(255) DEFAULT NULL COMMENT '统一信用代码',
  `company_park` varchar(255) DEFAULT NULL COMMENT '工业园区',
  `company_zip_code` varchar(255) DEFAULT NULL COMMENT '工作单位邮编',
  `type` tinyint DEFAULT '0' COMMENT '专家类型(0一线专家1鉴定中心专家2社会专家3企业专家4其他)',
  `education` varchar(255) DEFAULT NULL COMMENT '学历',
  `major` varchar(255) DEFAULT NULL COMMENT '专业',
  `work_time` varchar(255) DEFAULT NULL COMMENT '工作时间',
  `work_type_id` int DEFAULT NULL COMMENT '工种',
  `level` varchar(20) DEFAULT NULL COMMENT '级别',
  `class_no` varchar(50) DEFAULT NULL COMMENT '班次',
  `room_no` varchar(50) DEFAULT NULL COMMENT '车间',
  `avatar` varchar(255) DEFAULT NULL,
  `sort_number` int DEFAULT '0',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `point` decimal(10,2) DEFAULT '0.00' COMMENT '积分',
  `sign_point` decimal(10,2) DEFAULT '0.00' COMMENT '签到积分',
  `sign_day` int DEFAULT '0' COMMENT '连续签到天数',
  `people_type` varchar(20) DEFAULT NULL COMMENT '人员类型',
  `job_title` varchar(20) DEFAULT NULL COMMENT '职称',
  `has_set_data` tinyint DEFAULT '0',
  `id_card_front` varchar(255) DEFAULT NULL,
  `id_card_back` varchar(255) DEFAULT NULL,
  `gender` tinyint DEFAULT '0',
  `nation` varchar(50) DEFAULT NULL COMMENT '民族',
  `address` varchar(500) DEFAULT NULL,
  `id_card_start_date` varchar(100) DEFAULT NULL COMMENT '身份证开始时间',
  `id_card_end_date` varchar(100) DEFAULT NULL COMMENT '身份证结束时间',
  `person_type` varchar(200) DEFAULT NULL COMMENT '人员类型',
  `person_supplementary` varchar(200) DEFAULT NULL COMMENT '人员补充身份',
  `house_type` varchar(200) DEFAULT NULL COMMENT '户口性质',
  `nationality` varchar(20) DEFAULT NULL COMMENT '民族',
  `job_intention` varchar(200) DEFAULT NULL COMMENT '就业意向',
  `is_party_member` tinyint DEFAULT '0' COMMENT '是否党员',
  `political` varchar(255) DEFAULT NULL COMMENT '政治面貌',
  `in_company_time` varchar(30) DEFAULT NULL,
  `work_contract_start_time` varchar(30) DEFAULT NULL,
  `work_contract_end_time` varchar(30) DEFAULT NULL,
  `job_title_paper` varchar(255) DEFAULT NULL COMMENT '职称证书',
  `school` varchar(255) DEFAULT NULL,
  `school_paper` varchar(255) DEFAULT NULL,
  `school_no` varchar(255) DEFAULT NULL COMMENT '毕业证编号',
  `in_school_date` varchar(255) DEFAULT NULL COMMENT '入学时间',
  `out_school_date` varchar(255) DEFAULT NULL COMMENT '毕业时间',
  `graduate_date` varchar(30) DEFAULT NULL COMMENT '毕业时间',
  `request_work_type_id` int DEFAULT NULL COMMENT '申报工种id',
  `request_work_type_name` varchar(255) DEFAULT NULL COMMENT '申报工种id',
  `request_work_type_level` varchar(255) DEFAULT NULL COMMENT '申报工种id',
  `request_work_type_work_year` int DEFAULT NULL COMMENT '申报工种工龄',
  `get_current_paper_year` int DEFAULT NULL COMMENT '本职业证书获证后工作年限',
  `origin_work_type_id` int DEFAULT NULL COMMENT '申报工种id',
  `origin_work_type_name` varchar(255) DEFAULT NULL COMMENT '申报工种id',
  `origin_work_type_level` varchar(255) DEFAULT NULL COMMENT '申报工种id',
  `chinese_skill` varchar(255) DEFAULT NULL COMMENT '中华技能大奖',
  `nation_skill` varchar(255) DEFAULT NULL COMMENT '全国技术能手',
  `industry_skill` varchar(255) DEFAULT NULL COMMENT '行业技术能手',
  `industry_skill_pacemaker` varchar(255) DEFAULT NULL COMMENT '行业技术标兵',
  `gx_skill` varchar(255) DEFAULT NULL COMMENT '广西技术能手',
  `model_worker` varchar(255) DEFAULT NULL COMMENT '劳模',
  `gx_artizan` varchar(255) DEFAULT NULL COMMENT '广西工匠',
  `high_skill_artizan` varchar(255) DEFAULT NULL COMMENT '技能大师',
  `gov_bonus` varchar(255) DEFAULT NULL COMMENT '享受政府特殊津贴人员',
  `department` varchar(255) DEFAULT NULL COMMENT '部门',
  `people_type_in_org` varchar(255) DEFAULT NULL COMMENT '人员类型',
  `aisle` varchar(255) DEFAULT NULL COMMENT '所在工段',
  `position_in_org` varchar(255) DEFAULT NULL COMMENT '岗位',
  `contact_first_page` varchar(500) DEFAULT NULL COMMENT '劳动合同第一页',
  `contact_expire_page` varchar(500) DEFAULT NULL COMMENT '劳动合同期限页',
  `contact_sign_page` varchar(500) DEFAULT NULL COMMENT '劳动合同盖章页三页',
  `social_security` varchar(500) DEFAULT NULL COMMENT '社保',
  `province` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在辖区',
  `deleted` int DEFAULT '0',
  `wealth_value` decimal(10,2) DEFAULT '0.00' COMMENT '财富值',
  `value_valuation` decimal(10,2) DEFAULT '0.00' COMMENT '价值估值',
  `work_type_paper` varchar(255) DEFAULT NULL COMMENT '工种等级证书',
  `work_type_number` varchar(255) DEFAULT NULL COMMENT '工种等级证书编号',
  `work_exp` text COMMENT '工作经历',
  `sign_up_id` int NOT NULL DEFAULT '0',
  `sign_up_type` int NOT NULL DEFAULT '0' COMMENT '0认定报名,1自主报名',
  `iscopy` int NOT NULL DEFAULT '0' COMMENT '数据迁移使用',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `id` (`id`),
  KEY `user_id` (`user_id`),
  KEY `phone` (`phone`),
  KEY `id_card` (`id_card`),
  KEY `sort_number` (`sort_number`),
  KEY `tenant_id` (`tenant_id`),
  KEY `deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=3678 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `sys_user_follow` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `follow_user_id` int DEFAULT NULL,
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4;
CREATE TABLE `sys_user_value_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `value` decimal(10,2) DEFAULT NULL,
  `reason` text,
  `action_name` varchar(50) DEFAULT NULL COMMENT '经办人',
  `type` varchar(255) DEFAULT NULL,
  `sort_number` int DEFAULT '0',
  `tenant_id` int NOT NULL DEFAULT '10159' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COMMENT='财富值/估值变动记录';
CREATE TABLE `tiku_exam` (
  `id` int NOT NULL AUTO_INCREMENT,
  `logid` int NOT NULL DEFAULT '0',
  `work_type_id` int NOT NULL DEFAULT '0' COMMENT '工种id',
  `level` int NOT NULL DEFAULT '0' COMMENT '工种等级',
  `tiku_knowledge_id` int NOT NULL DEFAULT '0' COMMENT '题库结构id',
  `type` varchar(10) DEFAULT NULL COMMENT '试题类型',
  `score` decimal(10,1) NOT NULL DEFAULT '0.0' COMMENT '分值',
  `content` text COMMENT '题干内容',
  `answer` text COMMENT '答案',
  `resolve` text COMMENT '解析',
  `addtime` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1264 DEFAULT CHARSET=utf8mb4 COMMENT='题库详情表';
CREATE TABLE `tiku_exam_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `work_type_id` int NOT NULL DEFAULT '0',
  `level` int NOT NULL DEFAULT '0',
  `file_path` varchar(200) DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除:0否,1是',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='题库上传记录';
CREATE TABLE `tiku_knowledge` (
  `id` int NOT NULL AUTO_INCREMENT,
  `logid` int NOT NULL DEFAULT '0',
  `parent_id` int NOT NULL DEFAULT '0',
  `title` varchar(100) DEFAULT NULL,
  `work_type_id` int NOT NULL DEFAULT '0',
  `level` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=427 DEFAULT CHARSET=utf8mb4 COMMENT='题库知识结构';
CREATE TABLE `tiku_knowledge_rate` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `description` varchar(100) DEFAULT NULL,
  `work_type_id` int NOT NULL DEFAULT '0',
  `level` int NOT NULL DEFAULT '0',
  `ids` json DEFAULT NULL COMMENT '比重数据',
  `scoure` json DEFAULT NULL,
  `addtime` int NOT NULL DEFAULT '0',
  `uptime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COMMENT='题库组卷比重表';

