USE gxwebsoft_core;

CREATE TABLE `cms_ad` (
  `ad_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `design_id` int unsigned NOT NULL DEFAULT '0' COMMENT '页面ID',
  `ad_type` varchar(100) NOT NULL DEFAULT '' COMMENT '广告类型',
  `name` varchar(300) NOT NULL DEFAULT '' COMMENT '广告位名称',
  `width` varchar(300) NOT NULL DEFAULT '' COMMENT '宽',
  `height` varchar(300) NOT NULL DEFAULT '' COMMENT '高',
  `images` text CHARACTER SET utf8mb4 COMMENT '广告图片',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '页面ID',
  `page_name` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面名称',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`ad_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=269 DEFAULT CHARSET=utf8 COMMENT='广告位';
CREATE TABLE `cms_ad_record` (
  `ad_record_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` text CHARACTER SET utf8mb4 COMMENT '广告标题',
  `path` varchar(300) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '图片地址',
  `url` text CHARACTER SET utf8mb4 COMMENT '链接地址',
  `ad_id` int unsigned NOT NULL DEFAULT '0' COMMENT '广告位ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`ad_record_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='广告图片';
CREATE TABLE `cms_article` (
  `article_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章ID',
  `title` varchar(300) NOT NULL DEFAULT '' COMMENT '文章标题',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '文章类型 0常规 1视频',
  `model` varchar(100) DEFAULT '' COMMENT '文章模型',
  `show_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '列表显示方式(10小图展示 20大图展示)',
  `topic` varchar(200) NOT NULL DEFAULT '' COMMENT '话题',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章分类ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `image` varchar(300) DEFAULT '' COMMENT '封面图',
  `source` varchar(100) NOT NULL DEFAULT '' COMMENT '来源',
  `virtual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '虚拟阅读量(仅用作展示)',
  `actual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '实际阅读量',
  `permission` int unsigned NOT NULL DEFAULT '0' COMMENT '可见类型 0所有人 1登录可见 2密码可见',
  `password` varchar(255) DEFAULT '' COMMENT '访问密码',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '发布来源客户端 (APP、H5、小程序等)',
  `files` varchar(1000) DEFAULT NULL COMMENT '文章附件',
  `video` varchar(200) DEFAULT '' COMMENT '视频地址',
  `accept` varchar(50) DEFAULT '' COMMENT '接受的文件类型',
  `longitude` varchar(100) NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) NOT NULL DEFAULT '' COMMENT '纬度',
  `province` varchar(50) NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '街道地址',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '推荐',
  `comment_numbers` int unsigned DEFAULT '0' COMMENT '评论数',
  `to_users` varchar(200) DEFAULT '' COMMENT '提醒谁看',
  `author` varchar(50) DEFAULT '' COMMENT '作者',
  `lang` varchar(50) DEFAULT '' COMMENT '语言',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已发布, 1待审核 2已驳回 3违规内容',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`article_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=751 DEFAULT CHARSET=utf8 COMMENT='文章';
CREATE TABLE `cms_article_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文章分类ID',
  `category_code` varchar(50) NOT NULL DEFAULT '' COMMENT '分类标识',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '分类名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0列表 1单页 2外链',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '分类图片',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `component` varchar(300) NOT NULL DEFAULT '' COMMENT '组件路径',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `count` int unsigned NOT NULL DEFAULT '0' COMMENT '文章数量',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `show_index` int NOT NULL DEFAULT '0' COMMENT '是否显示在首页',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1禁用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8 COMMENT='文章分类表';
CREATE TABLE `cms_article_comment` (
  `comment_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '评价ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `score` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '评分 (10好评 20中评 30差评)',
  `content` text NOT NULL COMMENT '评价内容',
  `is_picture` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否为图片评价',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '评论者ID',
  `to_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '被评价者ID',
  `reply_comment_id` int unsigned NOT NULL DEFAULT '0' COMMENT '回复的评论ID',
  `reply_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '回复者ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未读, 1已读',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`comment_id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `shop_comment_ibfk_1` (`tenant_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='文章评论表';
CREATE TABLE `cms_article_content` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `article_id` int unsigned DEFAULT '0' COMMENT '文章ID',
  `content` longtext COMMENT '文章内容',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `article_id` (`article_id`),
  CONSTRAINT `article_id_ibfk_1` FOREIGN KEY (`article_id`) REFERENCES `cms_article` (`article_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=526 DEFAULT CHARSET=utf8mb4 COMMENT='文章记录表';
CREATE TABLE `cms_article_count` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='点赞文章';
CREATE TABLE `cms_article_like` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文章ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='点赞文章';
CREATE TABLE `cms_components` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '组件标题',
  `navigation_id` int NOT NULL DEFAULT '0' COMMENT '关联导航ID',
  `type` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '组件类型',
  `keywords` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面关键词',
  `description` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面描述',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '组件路径',
  `icon` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '组件图标',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='组件';
CREATE TABLE `cms_design` (
  `page_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '页面标题',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '所属栏目ID',
  `keywords` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面关键词',
  `description` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面描述',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '缩列图',
  `buy_url` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '购买链接',
  `style` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面样式',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '页面内容',
  `show_layout` int NOT NULL DEFAULT '0' COMMENT '是否开启布局',
  `show_banner` int NOT NULL DEFAULT '0' COMMENT '是否显示banner',
  `show_button` int NOT NULL DEFAULT '0' COMMENT '是否显示按钮',
  `layout` text CHARACTER SET utf8mb4 COMMENT '页面布局',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `lang` varchar(50) DEFAULT '' COMMENT '语言',
  `translation` tinyint DEFAULT '1' COMMENT '是否自动翻译',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`page_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=824 DEFAULT CHARSET=utf8 COMMENT='页面管理记录表';
CREATE TABLE `cms_design_record` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `navigation_id` int NOT NULL DEFAULT '0' COMMENT '关联导航ID',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '组件',
  `dict_code` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '组件标识',
  `styles` varchar(500) CHARACTER SET utf8mb4 NOT NULL COMMENT '组件样式',
  `shadow` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '卡片阴影显示时机',
  `keywords` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面关键词',
  `description` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面描述',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面路由地址',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '缩列图',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8 COMMENT='页面组件表';
CREATE TABLE `cms_docs` (
  `docs_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '文档ID',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '文档标题',
  `parent_id` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '上级目录',
  `book_id` int DEFAULT '0' COMMENT '书籍ID',
  `visibility` varchar(300) DEFAULT NULL COMMENT '可见性(public,private,protected)',
  `virtual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '虚拟阅读量(仅用作展示)',
  `actual_views` int unsigned NOT NULL DEFAULT '0' COMMENT '实际阅读量',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`docs_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `book_id` (`book_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=215 DEFAULT CHARSET=utf8 COMMENT='文档管理记录表';
CREATE TABLE `cms_docs_book` (
  `book_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) DEFAULT NULL COMMENT '书籍名称',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '书籍标识',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '封面图',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `content` longtext NOT NULL COMMENT '文档内容',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`book_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=209 DEFAULT CHARSET=utf8 COMMENT='书籍记录表';
CREATE TABLE `cms_docs_content` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `docs_id` int unsigned DEFAULT '0' COMMENT '文档ID',
  `content` longtext COMMENT '文档内容',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `docs_id_ibfk_1` (`docs_id`),
  CONSTRAINT `docs_id_ibfk_1` FOREIGN KEY (`docs_id`) REFERENCES `cms_docs` (`docs_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=209 DEFAULT CHARSET=utf8mb4 COMMENT='文档内容记录表';
CREATE TABLE `cms_domain` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0赠送域名 1绑定域名 ',
  `domain` varchar(100) DEFAULT NULL COMMENT '域名',
  `host_name` varchar(100) CHARACTER SET utf8 DEFAULT '' COMMENT '主机记录',
  `host_value` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '记录值',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `website_id` int unsigned NOT NULL DEFAULT '0' COMMENT '网站ID',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '租户ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10479 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='网站域名记录表';
CREATE TABLE `cms_form` (
  `form_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '表单标题',
  `photo` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '顶部图片',
  `background` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '背景图片',
  `video` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '视频文件',
  `submit_number` int NOT NULL DEFAULT '0' COMMENT '提交次数',
  `layout` text CHARACTER SET utf8mb4 COMMENT '页面布局',
  `hide_photo` int NOT NULL DEFAULT '0' COMMENT '是否隐藏顶部图片',
  `hide_background` int NOT NULL DEFAULT '0' COMMENT '是否隐藏背景图片',
  `hide_video` int NOT NULL DEFAULT '0' COMMENT '是否隐藏视频',
  `opacity` decimal(2,1) NOT NULL DEFAULT '0.0' COMMENT '背景图片透明度',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(1000) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`form_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchat_id` (`merchant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='表单设计表';
CREATE TABLE `cms_form_record` (
  `form_record_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `phone` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '手机号',
  `form_data` text CHARACTER SET utf8mb4 COMMENT '表单数据',
  `form_id` int unsigned NOT NULL DEFAULT '0' COMMENT '表单ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `name` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '姓名',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`form_record_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='表单数据记录表';
CREATE TABLE `cms_link` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(300) NOT NULL DEFAULT '0' COMMENT '链接名称',
  `icon` varchar(300) NOT NULL DEFAULT '' COMMENT '图标',
  `url` varchar(300) NOT NULL DEFAULT '0' COMMENT '链接地址',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '栏目ID',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `recommend` tinyint NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='常用链接';
CREATE TABLE `cms_model` (
  `model_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(300) NOT NULL DEFAULT '' COMMENT '模型名称',
  `model` varchar(100) NOT NULL DEFAULT '' COMMENT '唯一标识',
  `component` varchar(300) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '菜单组件地址, 目录可为空',
  `component_detail` varchar(200) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '菜单路由地址',
  `banner` varchar(300) DEFAULT '' COMMENT '模型banner图片',
  `thumb` varchar(300) DEFAULT '' COMMENT '预览图',
  `style` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT 'css样式',
  `image_width` varchar(50) DEFAULT '' COMMENT '封面图宽',
  `image_height` varchar(50) DEFAULT '' COMMENT '封面图高',
  `title` varchar(300) DEFAULT '' COMMENT 'Banner上的标题',
  `show_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '列表显示方式(10小图展示 20大图展示)',
  `suffix` varchar(50) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '后缀 .html',
  `disabled` tinyint NOT NULL DEFAULT '0' COMMENT '是否可编辑',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已发布, 1待审核 2已驳回 3违规内容',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`model_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='模型';
CREATE TABLE `cms_mp` (
  `mp_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` int NOT NULL DEFAULT '0' COMMENT '是否主账号',
  `app_id` varchar(100) CHARACTER SET utf8mb4 NOT NULL COMMENT '小程序ID',
  `app_secret` varchar(100) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '小程序密钥',
  `mp_name` varchar(100) CHARACTER SET utf8mb4 NOT NULL COMMENT '小程序名称',
  `short_name` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '小程序简称',
  `avatar` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '头像',
  `mp_qrcode` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '小程序码',
  `authentication` int NOT NULL DEFAULT '0' COMMENT '微信认证',
  `company_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '主体信息',
  `icp_no` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '小程序备案',
  `email` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '登录邮箱',
  `password` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '登录密码',
  `gh_id` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '原始ID',
  `main_path` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '入口页面',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '介绍',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`mp_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=637 DEFAULT CHARSET=utf8 COMMENT='小程序信息';
CREATE TABLE `cms_mp_ad` (
  `ad_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '页面ID',
  `ad_type` varchar(100) NOT NULL DEFAULT '' COMMENT '广告类型',
  `name` varchar(300) NOT NULL DEFAULT '' COMMENT '广告位名称',
  `width` varchar(300) NOT NULL DEFAULT '' COMMENT '宽',
  `height` varchar(300) NOT NULL DEFAULT '' COMMENT '高',
  `images` text CHARACTER SET utf8mb4 COMMENT '广告图片',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `page_name` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面名称',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`ad_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=268 DEFAULT CHARSET=utf8 COMMENT='小程序广告位';
CREATE TABLE `cms_mp_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int DEFAULT '0' COMMENT '类型，0文本 1图片 2其他',
  `name` varchar(100) DEFAULT '' COMMENT '名称',
  `comments` varchar(500) DEFAULT '' COMMENT '备注',
  `value` varchar(200) DEFAULT '' COMMENT '名称',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '页面ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `mp_id` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10634 DEFAULT CHARSET=utf8 COMMENT='小程序配置';
CREATE TABLE `cms_mp_menu` (
  `menu_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '菜单名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0功能图标 1订单状态图标 2首页导航图标 3 商城导航图标 4管理人员功能图标',
  `is_mp_weixin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否微信小程序菜单',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单路由地址',
  `component` varchar(300) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单组件地址, 目录可为空',
  `target` varchar(200) CHARACTER SET utf8mb4 DEFAULT '_self' COMMENT '打开位置',
  `avatar` varchar(200) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '菜单图标',
  `color` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '图标颜色',
  `icon` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '上传图标',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `position` int NOT NULL DEFAULT '1' COMMENT '位置 0不限 1顶部 2底部',
  `rows` int NOT NULL DEFAULT '0' COMMENT '0 第一行 1第二行',
  `active` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单侧栏选中的path',
  `meta` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '其它路由元信息',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `article_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的文章分类ID',
  `article_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的文章ID',
  `form_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的表单ID',
  `book_code` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '绑定的书籍标识',
  `goods_category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的商品分类ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的商品ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `admin_show` int unsigned NOT NULL DEFAULT '0' COMMENT '是否管理人员可见',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `group_name` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '分组名称',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`menu_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `path` (`path`) USING BTREE,
  KEY `page_id` (`page_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='小程序端菜单';
CREATE TABLE `cms_mp_official_menu` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `name` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '菜单名称',
  `type` varchar(50) CHARACTER SET utf8mb4 NOT NULL COMMENT '类型',
  `key` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '菜单值',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='小程序端菜单';
CREATE TABLE `cms_mp_pages` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '页面名称',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '页面路径',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `subpackage` varchar(50) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '分包',
  `icon` varchar(50) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '图标',
  `icon_path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '未选中图标',
  `selected_icon_path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '选中的图标',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `path` (`path`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=634 DEFAULT CHARSET=utf8 COMMENT='小程序页面';
CREATE TABLE `cms_navigation` (
  `navigation_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) CHARACTER SET utf8mb4 NOT NULL COMMENT '菜单名称',
  `model` varchar(50) NOT NULL DEFAULT '' COMMENT '模型',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '标识',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单路由地址',
  `component` varchar(300) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单组件地址, 目录可为空',
  `target` varchar(200) CHARACTER SET utf8mb4 DEFAULT '_self' COMMENT '打开位置',
  `icon` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单图标',
  `banner` varchar(300) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT 'banner',
  `color` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '图标颜色',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `permission` int unsigned NOT NULL DEFAULT '0' COMMENT '可见类型 0所有人 1登录可见 2密码可见',
  `password` varchar(255) DEFAULT '' COMMENT '访问密码',
  `position` int NOT NULL DEFAULT '1' COMMENT '位置 0不限 1顶部 2底部',
  `top` int NOT NULL DEFAULT '0' COMMENT '仅在顶部显示',
  `bottom` int NOT NULL DEFAULT '1' COMMENT '仅在底部显示',
  `active` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单侧栏选中的path',
  `meta` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '其它路由元信息',
  `style` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT 'css样式',
  `parent_path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '父级栏目路由',
  `parent_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '父级栏目名称',
  `model_name` varchar(50) NOT NULL DEFAULT '' COMMENT '模型名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型（已废弃）',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面（已废弃）',
  `item_id` int unsigned NOT NULL DEFAULT '0' COMMENT '项目ID (存放示例productId、articleId等)',
  `is_mp_weixin` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否微信小程序菜单',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `home` int NOT NULL DEFAULT '0' COMMENT '设为首页',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`navigation_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `path` (`path`) USING BTREE,
  KEY `page_id` (`page_id`) USING BTREE,
  KEY `is_mp_weixin` (`is_mp_weixin`)
) ENGINE=InnoDB AUTO_INCREMENT=923 DEFAULT CHARSET=utf8 COMMENT='网站导航记录表';
CREATE TABLE `cms_product` (
  `product_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int NOT NULL DEFAULT '0' COMMENT '类型 0软件产品 1实物商品 2虚拟商品',
  `code` varchar(200) NOT NULL DEFAULT '' COMMENT '产品编码',
  `title` varchar(300) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '产品标题',
  `image` varchar(1000) NOT NULL DEFAULT '' COMMENT '封面图',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '产品详情',
  `navigation_id` int NOT NULL DEFAULT '0' COMMENT '栏目ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父级分类ID',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '产品分类ID',
  `menu_id` varchar(20) DEFAULT '' COMMENT '插件ID（关联menu表的ID）',
  `path` varchar(200) DEFAULT '' COMMENT '控制台路由地址',
  `tag` varchar(50) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '标签',
  `specs` int NOT NULL DEFAULT '0' COMMENT '产品规格 0单规格 1多规格',
  `position` varchar(50) DEFAULT NULL COMMENT '货架',
  `unit_name` varchar(32) DEFAULT NULL COMMENT '单位名称 (个)',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '进货价格',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '销售价格',
  `deduct_stock_type` tinyint unsigned NOT NULL DEFAULT '20' COMMENT '库存计算方式(10下单减库存 20付款减库存)',
  `delivery_method` tinyint DEFAULT '0' COMMENT '交付方式(0不启用，1 SaaS交付，2 源码交付)',
  `duration_method` tinyint DEFAULT '0' COMMENT '购买时长(0不启用，1 一次性，2 按时长)',
  `server_method` tinyint DEFAULT '0' COMMENT '技术服务包',
  `package_method` tinyint DEFAULT '0' COMMENT '套餐服务',
  `can_buy_number` int DEFAULT '1' COMMENT '可购买数量',
  `files` text NOT NULL COMMENT '轮播图',
  `sales` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '销量',
  `stock` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `install` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '安装次数',
  `rate` decimal(2,1) unsigned NOT NULL DEFAULT '0.0' COMMENT '评分',
  `gain_integral` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '消费赚取积分',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '推荐',
  `official` int NOT NULL DEFAULT '0' COMMENT '是否官方',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `is_show` tinyint DEFAULT '0' COMMENT '状态（0：未上架，1：上架）',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0上架 1待上架 2待审核 3审核不通过',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`product_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `navigation_id` (`navigation_id`) USING BTREE,
  KEY `category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=141 DEFAULT CHARSET=utf8 COMMENT='产品';
CREATE TABLE `cms_product_comment` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `product_id` int NOT NULL DEFAULT '0' COMMENT '产品ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父级ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `rate` decimal(2,1) unsigned NOT NULL DEFAULT '0.0' COMMENT '评分',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '评论内容',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2290 DEFAULT CHARSET=utf8 COMMENT='产品评论';
CREATE TABLE `cms_product_parameter` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '产品ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '参数名称',
  `value` varchar(200) NOT NULL DEFAULT '' COMMENT '参数内容',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8 COMMENT='产品参数';
CREATE TABLE `cms_product_record` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `product_id` int NOT NULL DEFAULT '0' COMMENT '产品ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已安装, 1已卸载',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2287 DEFAULT CHARSET=utf8 COMMENT='插件安装明细';
CREATE TABLE `cms_product_sku` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `sku` varchar(128) DEFAULT '' COMMENT '商品属性索引值 (attr_value|attr_value[|....])',
  `image` varchar(300) DEFAULT '' COMMENT '商品图片',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '市场价格',
  `cost` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '成本价',
  `stock` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `sku_no` varchar(300) DEFAULT '' COMMENT 'sku编码',
  `bar_code` varchar(255) NOT NULL DEFAULT '' COMMENT '商品条码',
  `weight` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '重量',
  `volume` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '体积',
  `uuid` varchar(100) NOT NULL DEFAULT '' COMMENT '唯一值',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0正常, 1异常',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `goods_id` (`goods_id`)
) ENGINE=InnoDB AUTO_INCREMENT=575 DEFAULT CHARSET=utf8 COMMENT='商品sku列表';
CREATE TABLE `cms_product_spec` (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `spec_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格ID',
  `spec_name` varchar(32) NOT NULL DEFAULT '' COMMENT '规格名称',
  `spec_value` json NOT NULL COMMENT '规格值',
  `type` tinyint DEFAULT '0' COMMENT '活动类型 0=商品，1=秒杀，2=砍价，3=拼团',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `spec_id` (`spec_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=200 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='商品多规格';
CREATE TABLE `cms_product_url` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '产品ID',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '域名类型',
  `domain` varchar(200) NOT NULL DEFAULT '' COMMENT '域名',
  `account` varchar(200) NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(200) NOT NULL DEFAULT '' COMMENT '密码',
  `qrcode` varchar(500) DEFAULT '' COMMENT '二维码',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8 COMMENT='域名';
CREATE TABLE `cms_spec` (
  `spec_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格ID',
  `spec_name` varchar(255) NOT NULL DEFAULT '' COMMENT '规格名称',
  `spec_value` json NOT NULL COMMENT '规格值',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '创建用户',
  `updater` int NOT NULL DEFAULT '0' COMMENT '更新者',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0正常, 1待修,2异常已修，3异常未修',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`spec_id`) USING BTREE,
  KEY `spec_name` (`spec_name`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8 COMMENT='规格';
CREATE TABLE `cms_spec_value` (
  `spec_value_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格值ID',
  `spec_id` int NOT NULL COMMENT '规格组ID',
  `spec_value` varchar(255) NOT NULL COMMENT '规格值',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`spec_value_id`) USING BTREE,
  KEY `spec_value` (`spec_value`),
  KEY `spec_id` (`spec_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8 COMMENT='规格值';
CREATE TABLE `cms_website` (
  `website_id` int NOT NULL AUTO_INCREMENT COMMENT '站点ID',
  `website_name` varchar(50) NOT NULL DEFAULT '' COMMENT '网站名称',
  `website_code` varchar(100) NOT NULL DEFAULT '' COMMENT '网站标识',
  `website_icon` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_dark_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO(深色模式)',
  `website_type` varchar(50) NOT NULL DEFAULT '' COMMENT '网站类型',
  `keywords` varchar(50) NOT NULL DEFAULT '' COMMENT '网站关键词',
  `prefix` varchar(100) DEFAULT NULL COMMENT '域名前缀',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `style` varchar(100) DEFAULT NULL COMMENT '全局样式',
  `admin_url` varchar(200) DEFAULT NULL COMMENT '后台管理地址',
  `version` int unsigned NOT NULL DEFAULT '10' COMMENT '应用版本 10免费版 20授权版 30永久授权',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `assets_id` int unsigned NOT NULL DEFAULT '10' COMMENT '服务器ID',
  `assets_name` varchar(100) NOT NULL DEFAULT '10' COMMENT '服务器名称',
  `template_id` int unsigned NOT NULL DEFAULT '10' COMMENT '模版ID',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `company_id` int unsigned NOT NULL DEFAULT '20' COMMENT '企业ID',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `phone` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `icp_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'ICP备案号',
  `police_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '公安备案',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `remarks` varchar(400) DEFAULT '' COMMENT '管理员备注',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `running` int NOT NULL DEFAULT '0' COMMENT '状态 0未开通 1运行中 2维护中 3已关闭 4已欠费停机 5违规关停',
  `soon` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1 即将过期',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态 0未开通 1运行中 2维护中 3已关闭 4已欠费停机 5违规关停',
  `status_text` varchar(400) DEFAULT '' COMMENT '维护说明',
  `status_close` varchar(400) DEFAULT '' COMMENT '关闭说明',
  `styles` varchar(200) NOT NULL DEFAULT '' COMMENT '全局样式',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`website_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=917 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='网站信息记录表';
CREATE TABLE `cms_website_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int DEFAULT '0' COMMENT '类型，0文本 1图片 2其他',
  `name` varchar(100) DEFAULT '' COMMENT '名称',
  `default_value` varchar(500) DEFAULT NULL COMMENT '默认值',
  `modify_range` varchar(500) DEFAULT NULL COMMENT '可修改的值 [on|off]',
  `comments` varchar(500) DEFAULT '' COMMENT '备注',
  `style` varchar(100) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT 'css样式',
  `value` varchar(5000) DEFAULT '' COMMENT '名称',
  `lang` varchar(50) DEFAULT '' COMMENT '语言',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `website_id` (`type`) USING BTREE,
  KEY `lang` (`lang`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10853 DEFAULT CHARSET=utf8 COMMENT='应用参数';
CREATE TABLE `oa_app` (
  `app_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '应用ID',
  `app_name` varchar(100) NOT NULL DEFAULT '' COMMENT '应用名称',
  `app_code` varchar(100) NOT NULL DEFAULT '' COMMENT '应用标识',
  `app_secret` varchar(200) NOT NULL DEFAULT '' COMMENT '应用秘钥',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `app_type` varchar(100) DEFAULT '' COMMENT '应用类型',
  `app_type_multiple` varchar(200) DEFAULT '' COMMENT '应用类型',
  `menu_type` int DEFAULT '0' COMMENT '类型, 0菜单, 1按钮',
  `company_id` int NOT NULL DEFAULT '0' COMMENT '企业ID',
  `company_name` varchar(50) NOT NULL DEFAULT '' COMMENT '企业名称',
  `app_icon` varchar(200) DEFAULT NULL COMMENT '应用图标',
  `app_qrcode` varchar(2000) DEFAULT NULL COMMENT '二维码',
  `app_url` varchar(200) DEFAULT NULL COMMENT '链接地址',
  `admin_url` varchar(200) DEFAULT NULL COMMENT '后台管理地址',
  `down_url` varchar(200) DEFAULT NULL COMMENT '下载地址',
  `server_url` varchar(200) DEFAULT NULL COMMENT '链接地址',
  `file_url` varchar(200) DEFAULT NULL COMMENT '文件服务器',
  `callback_url` varchar(200) DEFAULT NULL COMMENT '回调地址',
  `docs_url` varchar(200) DEFAULT NULL COMMENT '腾讯文档地址',
  `git_url` varchar(200) DEFAULT NULL COMMENT '代码仓库地址',
  `prototype_url` varchar(200) DEFAULT NULL COMMENT '原型图地址',
  `ip_address` varchar(200) DEFAULT NULL COMMENT 'IP白名单',
  `images` longtext COMMENT '应用截图',
  `package_name` varchar(100) DEFAULT '' COMMENT '应用包名',
  `clicks` int unsigned NOT NULL DEFAULT '0' COMMENT '下载次数',
  `installs` int unsigned NOT NULL DEFAULT '0' COMMENT '安装次数',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `content` longtext COMMENT '应用介绍',
  `requirement` longtext CHARACTER SET utf8mb4 COMMENT '项目需求',
  `developer` varchar(100) NOT NULL DEFAULT '' COMMENT '开发者(个人或公司)',
  `director` varchar(50) NOT NULL DEFAULT '0' COMMENT '项目负责人',
  `project_director` varchar(100) NOT NULL DEFAULT '' COMMENT '项目经理',
  `salesman` varchar(100) NOT NULL DEFAULT '' COMMENT '业务员',
  `price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '软件定价',
  `line_price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '划线价格',
  `score` varchar(11) NOT NULL DEFAULT '100' COMMENT '评分',
  `star` varchar(11) NOT NULL DEFAULT '100' COMMENT '星级',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单路由地址',
  `component` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单组件地址, 目录可为空',
  `authority` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '权限标识',
  `target` varchar(200) CHARACTER SET utf8mb4 DEFAULT '_self' COMMENT '打开位置',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `search` tinyint NOT NULL DEFAULT '1' COMMENT '禁止搜索，1禁止 0 允许',
  `active` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '菜单侧栏选中的path',
  `meta` varchar(800) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '其它路由元信息',
  `edition` varchar(100) NOT NULL DEFAULT '' COMMENT '版本，0正式版 1体验版 2开发版',
  `version` varchar(100) NOT NULL DEFAULT '' COMMENT '版本号',
  `is_use` int unsigned NOT NULL DEFAULT '0' COMMENT '是否已安装',
  `file1` text COMMENT '附近1',
  `file2` text COMMENT '附件2',
  `file3` text COMMENT '附件3',
  `show_expiration` int unsigned NOT NULL DEFAULT '0' COMMENT '是否显示续费提醒',
  `show_case` int unsigned NOT NULL DEFAULT '0' COMMENT '是否作为案例展示',
  `show_index` int NOT NULL DEFAULT '0' COMMENT '是否显示在首页',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '到期时间',
  `soon` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1 即将过期',
  `renew_money` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '续费金额',
  `app_status` varchar(50) NOT NULL DEFAULT '' COMMENT '应用状态',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `organization_id` int DEFAULT NULL COMMENT '机构id',
  `tenant_code` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '租户编号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`app_id`) USING BTREE,
  KEY `app_id` (`user_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10250 DEFAULT CHARSET=utf8 COMMENT='应用';
CREATE TABLE `oa_app_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `app_id` int DEFAULT '0' COMMENT '应用ID',
  `name` varchar(200) DEFAULT '' COMMENT '名称',
  `comments` varchar(1000) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1删除',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10651 DEFAULT CHARSET=utf8 COMMENT='应用参数';
CREATE TABLE `oa_app_renew` (
  `app_renew_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `money` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '续费金额',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `start_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `end_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '到期时间',
  `soon` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1 即将过期',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `images` longtext COMMENT '付款凭证',
  `nickname` varchar(100) NOT NULL DEFAULT '0' COMMENT '用户姓名',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`app_renew_id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE,
  CONSTRAINT `oa_app_renew_ibfk_1` FOREIGN KEY (`app_id`) REFERENCES `oa_app` (`app_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10663 DEFAULT CHARSET=utf8 COMMENT='续费管理';
CREATE TABLE `oa_app_url` (
  `app_url_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '域名类型',
  `domain` varchar(200) NOT NULL DEFAULT '' COMMENT '域名',
  `account` varchar(200) NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(200) NOT NULL DEFAULT '' COMMENT '密码',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`app_url_id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  CONSTRAINT `oa_app_url_ibfk_1` FOREIGN KEY (`app_id`) REFERENCES `oa_app` (`app_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8 COMMENT='项目域名';
CREATE TABLE `oa_app_user` (
  `app_user_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `role` int unsigned NOT NULL DEFAULT '10' COMMENT '角色，10体验成员 20开发者成员 30管理员 ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '昵称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`app_user_id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE,
  CONSTRAINT `oa_app_user_ibfk_1` FOREIGN KEY (`app_id`) REFERENCES `oa_app` (`app_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10446 DEFAULT CHARSET=utf8 COMMENT='应用成员';
CREATE TABLE `oa_assets` (
  `assets_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '资产ID',
  `name` varchar(100) NOT NULL DEFAULT '' COMMENT '资产名称',
  `code` varchar(100) NOT NULL COMMENT '资产标识',
  `type` int NOT NULL DEFAULT '0' COMMENT '资产类型',
  `brand` varchar(100) NOT NULL DEFAULT '' COMMENT '服务器厂商',
  `configuration` varchar(2000) DEFAULT '' COMMENT '服务器配置',
  `account` varchar(100) NOT NULL DEFAULT '' COMMENT '初始账号',
  `password` varchar(100) NOT NULL DEFAULT '' COMMENT '初始密码',
  `brand_account` varchar(100) NOT NULL DEFAULT '' COMMENT '(阿里云/腾讯云)登录账号',
  `brand_password` varchar(100) NOT NULL DEFAULT '' COMMENT '(阿里云/腾讯云)登录密码',
  `panel` varchar(200) NOT NULL DEFAULT '' COMMENT '宝塔面板',
  `panel_account` varchar(100) NOT NULL DEFAULT '' COMMENT '宝塔面板账号',
  `panel_password` varchar(100) NOT NULL DEFAULT '' COMMENT '宝塔面板密码',
  `finance_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '财务信息-合同金额',
  `finance_years` int unsigned NOT NULL DEFAULT '0' COMMENT '购买年限',
  `finance_renew` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '续费金额',
  `finance_customer_name` varchar(100) DEFAULT NULL COMMENT '客户名称',
  `finance_customer_contact` varchar(100) DEFAULT NULL COMMENT '客户联系人',
  `finance_customer_phone` varchar(100) DEFAULT NULL COMMENT '客户联系电话',
  `customer_id` int DEFAULT '0' COMMENT '客户ID',
  `customer_name` varchar(100) DEFAULT NULL COMMENT '客户名称',
  `open_port` varchar(200) DEFAULT NULL COMMENT '开放端口',
  `mysql_port` varchar(200) DEFAULT NULL COMMENT '数据库端口',
  `content` text COMMENT '详情内容',
  `start_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '购买时间',
  `end_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '到期时间',
  `is_top` varchar(50) NOT NULL DEFAULT '-' COMMENT '置顶状态',
  `visibility` varchar(300) DEFAULT NULL COMMENT '可见性(public,private,protected)',
  `bt_sign` varchar(200) DEFAULT NULL COMMENT '宝塔接口秘钥',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '文章排序(数字越小越靠前)',
  `comments` text COMMENT '描述',
  `company_id` int DEFAULT '0' COMMENT '客户ID',
