  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '10' COMMENT '状态, 10待审核 20已通过 30已驳回',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `user_ids` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '可见用户',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
