) ENGINE=InnoDB AUTO_INCREMENT=10538 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='服务';
CREATE TABLE `oa_assets_site` (
  `website_id` int NOT NULL AUTO_INCREMENT COMMENT '站点ID',
  `website_name` varchar(50) NOT NULL DEFAULT '' COMMENT '网站名称',
  `website_code` varchar(100) NOT NULL DEFAULT '' COMMENT '网站标识',
  `website_icon` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_dark_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO(深色模式)',
  `website_type` varchar(50) NOT NULL DEFAULT '' COMMENT '网站类型',
  `keywords` varchar(50) NOT NULL DEFAULT '' COMMENT '网站关键词',
  `prefix` varchar(100) DEFAULT NULL COMMENT '域名前缀',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `style` varchar(100) DEFAULT NULL COMMENT '全局样式',
  `admin_url` varchar(200) DEFAULT NULL COMMENT '后台管理地址',
  `version` int unsigned NOT NULL DEFAULT '10' COMMENT '应用版本 10免费版 20授权版 30永久授权',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `soon` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1 即将过期',
  `template_id` int unsigned NOT NULL DEFAULT '10' COMMENT '模版ID',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `company_id` int unsigned NOT NULL DEFAULT '20' COMMENT '企业ID',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `phone` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `icp_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'ICP备案号',
  `police_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '公安备案',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态 0未开通 1运行中 2维护中 3已关闭 4已欠费停机 5违规关停',
  `status_text` varchar(400) DEFAULT '' COMMENT '维护说明',
  `status_close` varchar(400) DEFAULT '' COMMENT '关闭说明',
  `styles` varchar(200) NOT NULL DEFAULT '' COMMENT '全局样式',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `assets_id` int unsigned NOT NULL DEFAULT '0' COMMENT '服务器ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `user_ids` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '可见用户',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`website_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=907 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='网站信息记录表';
