  PRIMARY KEY (`vhost_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='虚拟主机记录表';
CREATE TABLE `oa_company` (
  `company_id` int NOT NULL AUTO_INCREMENT COMMENT '企业id',
  `short_name` varchar(50) NOT NULL DEFAULT '' COMMENT '企业简称',
  `company_name` varchar(100) NOT NULL DEFAULT '' COMMENT '企业全称',
  `company_code` varchar(100) NOT NULL DEFAULT '' COMMENT '企业标识',
  `company_type` varchar(50) NOT NULL DEFAULT '' COMMENT '类型 10企业 20政府单位',
  `company_type_multiple` json DEFAULT NULL COMMENT '企业类型多选',
  `company_logo` varchar(200) DEFAULT NULL COMMENT '应用标识',
  `app_type` varchar(50) NOT NULL DEFAULT '' COMMENT '应用类型',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `phone` varchar(100) DEFAULT NULL COMMENT '联系电话',
  `tel` varchar(100) DEFAULT '' COMMENT '座机电话',
  `email` varchar(200) DEFAULT NULL COMMENT '邮箱',
  `Invoice_header` varchar(50) DEFAULT NULL COMMENT '发票抬头',
  `business_entity` varchar(50) DEFAULT '' COMMENT '企业法人',
  `start_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务开始时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `version` int unsigned NOT NULL DEFAULT '10' COMMENT '应用版本 10体验版 20授权版 30旗舰版',
  `members` int unsigned NOT NULL DEFAULT '20' COMMENT '成员数量(人数上限)',
  `users` int NOT NULL DEFAULT '0' COMMENT '成员数量(当前)',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `departments` int unsigned NOT NULL DEFAULT '100' COMMENT '部门数量',
  `storage` bigint NOT NULL DEFAULT '0' COMMENT '存储空间',
  `storage_max` bigint NOT NULL DEFAULT '524288000' COMMENT '存储空间(上限)',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `authentication` int NOT NULL DEFAULT '0' COMMENT '是否实名认证',
  `authoritative` int NOT NULL DEFAULT '0' COMMENT '企业默认主体',
  `request_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'request合法域名',
  `socket_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'socket合法域名',
  `server_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '主控端域名',
  `modules_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '业务域名',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数量',
  `clicks` int unsigned DEFAULT '0' COMMENT '点击数量',
  `buys` int unsigned DEFAULT '0' COMMENT '购买数量',
  `is_tax` int NOT NULL DEFAULT '0' COMMENT '是否含税, 0不含, 1含',
  `plan_id` int unsigned NOT NULL DEFAULT '0' COMMENT '当前克隆的租户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`company_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `authoritative` (`authoritative`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10210 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='企业信息';
CREATE TABLE `oa_company_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `company_id` int DEFAULT '0' COMMENT '企业ID',
  `name` varchar(200) DEFAULT '' COMMENT '名称',
  `comments` varchar(1000) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1删除',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10578 DEFAULT CHARSET=utf8 COMMENT='企业参数';
CREATE TABLE `oa_company_user` (
  `company_user_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `role` int unsigned NOT NULL DEFAULT '10' COMMENT '角色，10体验成员 20开发者成员 30管理员 ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '昵称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`company_user_id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10357 DEFAULT CHARSET=utf8 COMMENT='成员管理';
CREATE TABLE `oa_link` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(300) NOT NULL DEFAULT '0' COMMENT '链接名称',
  `icon` varchar(300) NOT NULL DEFAULT '' COMMENT '图标',
  `url` varchar(300) NOT NULL DEFAULT '0' COMMENT '链接地址',
  `link_type` varchar(50) NOT NULL DEFAULT '' COMMENT '链接分类',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '应用ID',
  `category_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属栏目',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `recommend` tinyint NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10314 DEFAULT CHARSET=utf8 COMMENT='常用链接';
CREATE TABLE `oa_product` (
  `product_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '产品ID',
  `name` varchar(300) DEFAULT NULL COMMENT '产品名称',
  `code` varchar(300) DEFAULT NULL COMMENT '产品标识',
  `content` longtext NOT NULL COMMENT '产品详情',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '产品类型',
  `logo` varchar(255) DEFAULT NULL COMMENT '产品图标',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '产品金额',
  `sales_initial` int unsigned NOT NULL DEFAULT '0' COMMENT '初始销量',
  `sales_actual` int unsigned NOT NULL DEFAULT '0' COMMENT '实际销量',
  `stock_total` int unsigned NOT NULL DEFAULT '0' COMMENT '库存总量(包含所有sku)',
  `background_color` varchar(255) DEFAULT NULL COMMENT '背景颜色',
  `background_image` varchar(255) DEFAULT NULL COMMENT '背景图片',
  `background_gif` varchar(255) DEFAULT NULL COMMENT '背景图片(gif)',
  `buy_url` varchar(255) DEFAULT NULL COMMENT '购买链接',
  `admin_url` varchar(255) DEFAULT NULL COMMENT '控制台链接',
  `files` longtext COMMENT '附件',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已上架, 1已下架',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`product_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`),
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `code` (`code`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10004 DEFAULT CHARSET=utf8 COMMENT='产品记录表';
CREATE TABLE `oa_product_tabs` (
  `tab_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '产品标签ID',
  `product_id` int unsigned NOT NULL DEFAULT '0' COMMENT '产品ID',
  `name` varchar(300) DEFAULT NULL COMMENT '标签名称',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '标签类型',
  `content` longtext NOT NULL COMMENT '产品标签详情',
  `background_color` varchar(255) DEFAULT NULL COMMENT '背景颜色',
  `background_image` varchar(255) DEFAULT NULL COMMENT '背景图片',
  `files` longtext COMMENT '附件',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0已上架, 1已下架',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`tab_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10003 DEFAULT CHARSET=utf8 COMMENT='产品标签记录表';
CREATE TABLE `oa_task` (
  `task_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `task_type` varchar(50) NOT NULL DEFAULT '' COMMENT '工单类型',
  `name` longtext COMMENT '任务内容',
  `content` longtext NOT NULL COMMENT '问题描述',
  `files` longtext COMMENT '工单附件',
  `promoter` int NOT NULL DEFAULT '0' COMMENT '工单发起人',
  `commander` int DEFAULT NULL COMMENT '受理人',
  `progress` int NOT NULL DEFAULT '0' COMMENT '工单状态， 0未开始 1已指派 ',
  `priority` varchar(50) NOT NULL DEFAULT '0' COMMENT '优先级',
  `quality` varchar(50) NOT NULL DEFAULT '0' COMMENT '品质要求',
  `day` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '时限(天)',
  `phone` varchar(200) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '手机号',
  `start_time` date DEFAULT NULL COMMENT '开始时间',
  `end_time` date DEFAULT NULL COMMENT '结束时间',
  `overdue_days` int DEFAULT NULL COMMENT '逾期天数',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '项目ID',
  `organization_id` int NOT NULL DEFAULT '0' COMMENT '机构id',
  `project_id` int unsigned NOT NULL DEFAULT '0' COMMENT '项目ID',
  `customer_id` int unsigned NOT NULL DEFAULT '0' COMMENT '客户ID',
  `assets_id` int unsigned NOT NULL DEFAULT '0' COMMENT '资产ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `is_read` int NOT NULL DEFAULT '0' COMMENT '是否已查阅',
  `last_read_user` int NOT NULL DEFAULT '0' COMMENT '最后回复人',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '发起人昵称',
  `avatar` varchar(200) NOT NULL DEFAULT '' COMMENT '发起人头像',
  `last_avatar` varchar(200) NOT NULL DEFAULT '' COMMENT '最后回复人头像',
  `last_nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '最后回复人昵称',
  `is_settled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '订单是否已结算(0未结算 1已结算)',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`task_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`),
  KEY `commander` (`commander`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=934 DEFAULT CHARSET=utf8 COMMENT='任务记录表';
CREATE TABLE `oa_task_count` (
  `task_count_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `pending` int unsigned NOT NULL DEFAULT '0' COMMENT '待处理数',
  `unused` int unsigned NOT NULL DEFAULT '0' COMMENT '闲置的工单(废弃)',
  `completed` int unsigned NOT NULL DEFAULT '0' COMMENT '已完成数(废弃)',
  `today` int unsigned NOT NULL DEFAULT '0' COMMENT '今天处理数',
  `month` int unsigned NOT NULL DEFAULT '0' COMMENT '本月处理数',
  `year` int unsigned NOT NULL DEFAULT '0' COMMENT '今年处理数',
  `total` int unsigned NOT NULL DEFAULT '0' COMMENT '总工单数',
  `organization_id` int NOT NULL DEFAULT '0' COMMENT '部门ID',
  `role_id` int unsigned NOT NULL DEFAULT '0' COMMENT '角色ID',
  `role_code` varchar(50) NOT NULL DEFAULT '' COMMENT '角色标识',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`task_count_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10558 DEFAULT CHARSET=utf8 COMMENT='数据统计';
CREATE TABLE `oa_task_record` (
  `task_record_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '回复ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `task_id` int unsigned NOT NULL DEFAULT '0' COMMENT '工单ID',
  `content` longtext NOT NULL COMMENT '内容',
  `confidential` varchar(300) DEFAULT NULL COMMENT '机密信息',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '联系电话',
  `files` longtext COMMENT '工单附件',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`task_record_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`),
  KEY `task_id` (`task_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2266 DEFAULT CHARSET=utf8 COMMENT='工单回复记录表';
CREATE TABLE `oa_task_user` (
  `task_user_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `role` int unsigned NOT NULL DEFAULT '10' COMMENT '角色，10体验成员 20开发者成员 30管理员 ',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `task_id` int unsigned NOT NULL DEFAULT '0' COMMENT '工单ID',
  `nickname` varchar(100) NOT NULL DEFAULT '' COMMENT '昵称',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '加入时间',
  PRIMARY KEY (`task_user_id`) USING BTREE,
  KEY `task_id` (`task_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10486 DEFAULT CHARSET=utf8 COMMENT='工单成员';
CREATE TABLE `shop_brand` (
  `brand_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `brand_name` varchar(255) NOT NULL DEFAULT '' COMMENT '品牌名称',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '图标',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`brand_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COMMENT='品牌';
CREATE TABLE `shop_cart` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '购物车表ID',
  `type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '类型 0商城 1外卖',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '唯一标识',
  `goods_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `spec` varchar(300) NOT NULL DEFAULT '' COMMENT '商品规格',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `cart_num` smallint unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `total_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单商品合计',
  `is_pay` tinyint NOT NULL DEFAULT '0' COMMENT '0 = 未购买 1 = 已购买',
  `is_new` tinyint NOT NULL DEFAULT '0' COMMENT '是否为立即购买',
  `combination_id` int unsigned DEFAULT '0' COMMENT '拼团id',
  `seckill_id` int unsigned NOT NULL DEFAULT '0' COMMENT '秒杀产品ID',
  `bargain_id` int unsigned NOT NULL DEFAULT '0' COMMENT '砍价id',
  `selected` tinyint NOT NULL DEFAULT '1' COMMENT '是否选中',
  `merchant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `uid` (`user_id`,`is_pay`) USING BTREE,
  KEY `uid_3` (`user_id`,`is_new`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=675 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='购物车';
CREATE TABLE `shop_cashier` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '收银单ID',
  `type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '类型 0商城 1外卖',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '唯一标识',
  `goods_id` bigint unsigned NOT NULL COMMENT '商品ID',
  `name` varchar(300) NOT NULL DEFAULT '' COMMENT '商品名称',
  `spec` varchar(300) NOT NULL DEFAULT '' COMMENT '商品规格',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `cart_num` smallint unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `total_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单商品合计',
  `is_pay` tinyint NOT NULL DEFAULT '0' COMMENT '0 = 未购买 1 = 已购买',
  `is_new` tinyint NOT NULL DEFAULT '0' COMMENT '是否为立即购买',
  `selected` tinyint NOT NULL DEFAULT '1' COMMENT '是否选中',
  `merchant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `comments` varchar(400) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '备注',
  `user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `cashier_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '收银员ID',
  `group_id` bigint NOT NULL DEFAULT '0' COMMENT '分组取单',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `uid` (`user_id`,`is_pay`) USING BTREE,
  KEY `uid_3` (`user_id`,`is_new`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=772 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='收银';
CREATE TABLE `shop_count` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `date_time` date NOT NULL COMMENT '统计日期',
  `total_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '总销售额',
  `today_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '今日销售额',
  `total_users` decimal(10,0) unsigned NOT NULL DEFAULT '0' COMMENT '总会员数',
  `today_users` decimal(10,0) unsigned NOT NULL DEFAULT '0' COMMENT '今日新增',
  `total_orders` decimal(10,0) unsigned NOT NULL DEFAULT '0' COMMENT '总订单笔数',
  `today_orders` decimal(10,0) unsigned NOT NULL DEFAULT '0' COMMENT '今日订单笔数',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=388 DEFAULT CHARSET=utf8 COMMENT='商城销售统计表';
CREATE TABLE `shop_dealer_apply` (
  `apply_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `real_name` varchar(30) NOT NULL DEFAULT '' COMMENT '姓名',
  `mobile` varchar(20) NOT NULL DEFAULT '' COMMENT '手机号',
  `referee_id` int unsigned NOT NULL DEFAULT '0' COMMENT '推荐人用户ID',
  `apply_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '申请方式(10需后台审核 20无需审核)',
  `apply_time` int unsigned NOT NULL DEFAULT '0' COMMENT '申请时间',
  `apply_status` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '审核状态 (10待审核 20审核通过 30驳回)',
  `audit_time` int unsigned NOT NULL DEFAULT '0' COMMENT '审核时间',
  `reject_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '驳回原因',
  `tenant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商城ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`apply_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8 COMMENT='分销商申请记录表';
CREATE TABLE `shop_dealer_capital` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '分销商用户ID',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单ID',
  `flow_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '资金流动类型 (10佣金收入 20提现支出 30转账支出 40转账收入)',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `describe` varchar(500) NOT NULL DEFAULT '' COMMENT '描述',
  `to_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '对方用户ID',
  `tenant_id` int unsigned NOT NULL DEFAULT '10001' COMMENT '商城ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8 COMMENT='分销商资金明细表';
CREATE TABLE `shop_dealer_order` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '买家用户ID',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '订单ID',
  `order_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '订单总金额(不含运费)',
  `first_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '分销商用户id(一级)',
  `second_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '分销商用户id(二级)',
  `third_user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '分销商用户id(三级)',
  `first_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '分销佣金(一级)',
  `second_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '分销佣金(二级)',
  `third_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '分销佣金(三级)',
  `is_invalid` tinyint NOT NULL DEFAULT '0' COMMENT '订单是否失效(0未失效 1已失效)',
  `is_settled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '佣金结算(0未结算 1已结算)',
  `settle_time` int unsigned NOT NULL DEFAULT '0' COMMENT '结算时间',
  `tenant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商城ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `order_id` (`order_id`),
  KEY `user_id` (`user_id`),
  KEY `first_user_id` (`first_user_id`),
  KEY `second_user_id` (`second_user_id`),
  KEY `third_user_id` (`third_user_id`),
  KEY `is_settled` (`is_settled`),
  KEY `is_invalid` (`is_invalid`),
  KEY `store_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8 COMMENT='分销商订单记录表';
CREATE TABLE `shop_dealer_referee` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `dealer_id` int unsigned NOT NULL DEFAULT '0' COMMENT '分销商用户ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id(被推荐人)',
  `level` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '推荐关系层级(1,2,3)',
  `tenant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商城ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `dealer_id` (`dealer_id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8 COMMENT='分销商推荐关系表';
CREATE TABLE `shop_dealer_setting` (
  `key` varchar(30) NOT NULL DEFAULT '' COMMENT '设置项标示',
  `describe` varchar(255) NOT NULL DEFAULT '' COMMENT '设置项描述',
  `values` mediumtext NOT NULL COMMENT '设置内容(json格式)',
  `tenant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商城ID',
  `update_time` int unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  UNIQUE KEY `unique_key` (`key`,`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='分销商设置表';
CREATE TABLE `shop_dealer_user` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '自增ID',
  `real_name` varchar(30) NOT NULL DEFAULT '' COMMENT '姓名',
  `mobile` varchar(20) NOT NULL DEFAULT '' COMMENT '手机号',
  `pay_password` varchar(200) NOT NULL DEFAULT '' COMMENT '支付密码',
  `money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '当前可提现佣金',
  `freeze_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '已冻结佣金',
  `total_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '累积提现佣金',
  `referee_id` int unsigned NOT NULL DEFAULT '0' COMMENT '推荐人用户ID',
  `first_num` int unsigned NOT NULL DEFAULT '0' COMMENT '成员数量(一级)',
  `second_num` int unsigned NOT NULL DEFAULT '0' COMMENT '成员数量(二级)',
  `third_num` int unsigned NOT NULL DEFAULT '0' COMMENT '成员数量(三级)',
  `qrcode` varchar(300) NOT NULL DEFAULT '' COMMENT '专属二维码',
  `is_delete` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否删除',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8 COMMENT='分销商用户记录表';
CREATE TABLE `shop_dealer_withdraw` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '分销商用户ID',
  `money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '提现金额',
  `pay_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '打款方式 (10微信 20支付宝 30银行卡)',
  `alipay_name` varchar(30) NOT NULL DEFAULT '' COMMENT '支付宝姓名',
  `alipay_account` varchar(30) NOT NULL DEFAULT '' COMMENT '支付宝账号',
  `bank_name` varchar(30) NOT NULL DEFAULT '' COMMENT '开户行名称',
  `bank_account` varchar(30) NOT NULL DEFAULT '' COMMENT '银行开户名',
  `bank_card` varchar(30) NOT NULL DEFAULT '' COMMENT '银行卡号',
  `apply_status` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '申请状态 (10待审核 20审核通过 30驳回 40已打款)',
  `audit_time` int unsigned NOT NULL DEFAULT '0' COMMENT '审核时间',
  `reject_reason` varchar(500) NOT NULL DEFAULT '' COMMENT '驳回原因',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '来源客户端(APP、H5、小程序等)',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8 COMMENT='分销商提现明细表';
CREATE TABLE `shop_express` (
  `express_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '物流公司ID',
  `express_name` varchar(255) NOT NULL DEFAULT '' COMMENT '物流公司名称',
  `kuaidi100_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物流公司编码 (快递100)',
  `kdniao_code` varchar(30) NOT NULL DEFAULT '' COMMENT '物流公司编码 (快递鸟)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`express_id`) USING BTREE,
  KEY `kuaidi100_code` (`kuaidi100_code`) USING BTREE,
  KEY `express_name` (`express_name`)
) ENGINE=InnoDB AUTO_INCREMENT=10011 DEFAULT CHARSET=utf8 COMMENT='物流公司记录表';
CREATE TABLE `shop_goods` (
  `goods_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int NOT NULL DEFAULT '1' COMMENT '类型 1实物商品 2虚拟商品',
  `code` varchar(200) NOT NULL DEFAULT '' COMMENT '商品编码',
  `goods_name` varchar(300) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '商品标题',
  `image` varchar(1000) NOT NULL DEFAULT '' COMMENT '商品封面图',
  `content` longtext CHARACTER SET utf8mb4 COMMENT '商品详情',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父级分类ID',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '商品分类ID',
  `parent_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '父级分类',
  `category_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '当前分类',
  `children_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '三级分类',
  `specs` int NOT NULL DEFAULT '0' COMMENT '商品规格 0单规格 1多规格',
  `position` varchar(50) DEFAULT NULL COMMENT '货架',
  `unit_name` varchar(32) DEFAULT NULL COMMENT '单位名称 (个)',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '进货价格',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '销售价格',
  `deduct_stock_type` tinyint unsigned NOT NULL DEFAULT '20' COMMENT '库存计算方式(10下单减库存 20付款减库存)',
  `files` text NOT NULL COMMENT '封面图',
  `sales` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '销量',
  `stock` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `goods_weight` int NOT NULL DEFAULT '0' COMMENT '商品重量',
  `gain_integral` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '消费赚取积分',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '推荐',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `merchant_name` varchar(200) DEFAULT '' COMMENT '商户名称',
  `is_show` tinyint DEFAULT '0' COMMENT '状态（0：未上架，1：上架）',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0上架 1待上架 2待审核 3审核不通过',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`goods_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8 COMMENT='商品记录表';
CREATE TABLE `shop_goods_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '商品分类ID',
  `category_code` varchar(50) NOT NULL DEFAULT '' COMMENT '分类标识',
  `title` varchar(50) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '分类名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0商城分类 1外卖分类',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '分类图片',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `path` varchar(300) NOT NULL DEFAULT '' COMMENT '路由/链接地址',
  `component` varchar(300) NOT NULL DEFAULT '' COMMENT '组件路径',
  `page_id` int unsigned NOT NULL DEFAULT '0' COMMENT '绑定的页面',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `count` int unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `show_index` int NOT NULL DEFAULT '0' COMMENT '是否显示在首页',
  `merchant_id` int NOT NULL DEFAULT '0' COMMENT '商铺ID',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1禁用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10105 DEFAULT CHARSET=utf8 COMMENT='商品分类';
CREATE TABLE `shop_goods_comment` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `uid` int NOT NULL DEFAULT '0' COMMENT '用户ID',
  `oid` int NOT NULL DEFAULT '0' COMMENT '订单ID',
  `unique` varchar(32) NOT NULL COMMENT '商品唯一id',
  `goods_id` int NOT NULL COMMENT '商品id',
  `reply_type` varchar(32) NOT NULL DEFAULT 'product' COMMENT '某种商品类型(普通商品、秒杀商品）',
  `goods_score` tinyint NOT NULL COMMENT '商品分数',
  `service_score` tinyint NOT NULL COMMENT '服务分数',
  `comment` varchar(512) NOT NULL COMMENT '评论内容',
  `pics` text NOT NULL COMMENT '评论图片',
  `merchant_reply_content` varchar(300) DEFAULT NULL COMMENT '管理员回复内容',
  `merchant_reply_time` int DEFAULT NULL COMMENT '管理员回复时间',
  `is_del` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未删除1已删除',
  `is_reply` tinyint NOT NULL DEFAULT '0' COMMENT '0未回复1已回复',
  `nickname` varchar(64) NOT NULL COMMENT '用户名称',
  `avatar` varchar(255) NOT NULL COMMENT '用户头像',
  `sku` varchar(128) NOT NULL DEFAULT '' COMMENT '商品规格属性值,多个,号隔开',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `parent_id` (`reply_type`) USING BTREE,
  KEY `is_del` (`is_del`) USING BTREE,
  KEY `goods_score` (`goods_score`) USING BTREE,
  KEY `service_score` (`service_score`) USING BTREE,
  KEY `uid+oid` (`uid`,`oid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='评论表';
CREATE TABLE `shop_goods_coupon` (
  `id` int NOT NULL AUTO_INCREMENT,
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '商品id',
  `issue_coupon_id` int NOT NULL DEFAULT '0' COMMENT '优惠劵id',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='商品优惠券表';
CREATE TABLE `shop_goods_log` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '统计ID',
  `type` varchar(10) NOT NULL COMMENT '类型visit,cart,order,pay,collect,refund',
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '商品ID',
  `visit_num` tinyint NOT NULL DEFAULT '0' COMMENT '是否浏览',
  `cart_num` int NOT NULL DEFAULT '0' COMMENT '加入购物车数量',
  `order_num` int NOT NULL DEFAULT '0' COMMENT '下单数量',
  `pay_num` int NOT NULL DEFAULT '0' COMMENT '支付数量',
  `pay_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '支付金额',
  `cost_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '商品成本价',
  `pay_uid` int NOT NULL DEFAULT '0' COMMENT '支付用户ID',
  `refund_num` int NOT NULL DEFAULT '0' COMMENT '退款数量',
  `refund_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `collect_num` tinyint NOT NULL DEFAULT '0' COMMENT '收藏',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int unsigned NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='商品日志表';
CREATE TABLE `shop_goods_relation` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` int unsigned NOT NULL COMMENT '用户ID',
  `goods_id` int unsigned NOT NULL COMMENT '商品ID',
  `type` varchar(32) NOT NULL COMMENT '类型(收藏(collect）、点赞(like))',
  `category` varchar(32) NOT NULL COMMENT '某种类型的商品(普通商品、秒杀商品)',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `user_id` (`user_id`,`goods_id`,`type`,`category`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `category` (`category`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='商品点赞和收藏表';
CREATE TABLE `shop_goods_sku` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `sku` varchar(128) DEFAULT '' COMMENT '商品属性索引值 (attr_value|attr_value[|....])',
  `image` varchar(300) DEFAULT '' COMMENT '商品图片',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `sale_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '市场价格',
  `cost` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '成本价',
  `stock` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '库存',
  `sku_no` varchar(300) DEFAULT '' COMMENT 'sku编码',
  `bar_code` varchar(255) NOT NULL DEFAULT '' COMMENT '商品条码',
  `weight` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '重量',
  `volume` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '体积',
  `uuid` varchar(100) NOT NULL DEFAULT '' COMMENT '唯一值',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0正常, 1异常',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `goods_id` (`goods_id`)
) ENGINE=InnoDB AUTO_INCREMENT=575 DEFAULT CHARSET=utf8 COMMENT='商品sku列表';
CREATE TABLE `shop_goods_spec` (
  `id` mediumint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `goods_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `spec_id` int unsigned NOT NULL DEFAULT '0' COMMENT '规格ID',
  `spec_name` varchar(32) NOT NULL DEFAULT '' COMMENT '规格名称',
  `spec_value` json NOT NULL COMMENT '规格值',
  `type` tinyint DEFAULT '0' COMMENT '活动类型 0=商品，1=秒杀，2=砍价，3=拼团',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `goods_id` (`goods_id`) USING BTREE,
  KEY `spec_id` (`spec_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=200 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='商品多规格';
CREATE TABLE `shop_merchant` (
  `merchant_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `merchant_name` varchar(255) NOT NULL DEFAULT '' COMMENT '商户名称',
  `merchant_code` varchar(100) NOT NULL DEFAULT '' COMMENT '商户编号',
  `type` int NOT NULL DEFAULT '0' COMMENT '商户类型',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '商户图标',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '商户手机号',
  `real_name` varchar(50) NOT NULL DEFAULT '' COMMENT '商户姓名',
  `shop_type` varchar(50) NOT NULL DEFAULT '' COMMENT '店铺类型',
  `item_type` varchar(50) NOT NULL DEFAULT '0' COMMENT '项目分类',
  `category` varchar(50) NOT NULL DEFAULT '' COMMENT '商户分类',
  `merchant_category_id` int NOT NULL DEFAULT '0' COMMENT '商户经营分类',
  `merchant_category_title` varchar(50) NOT NULL DEFAULT '' COMMENT '商户分类',
  `lng_and_lat` varchar(255) DEFAULT '' COMMENT '经纬度',
  `lng` varchar(255) DEFAULT NULL,
  `lat` varchar(255) DEFAULT NULL,
  `province` varchar(50) NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) NOT NULL DEFAULT '' COMMENT '详细地址',
  `commission` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `keywords` varchar(200) NOT NULL DEFAULT '' COMMENT '关键字',
  `files` varchar(2000) NOT NULL DEFAULT '' COMMENT '资质图片',
  `business_time` varchar(100) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '营业时间',
  `content` text CHARACTER SET utf8mb4 COMMENT '文章内容',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '每小时价格',
  `own_store` int NOT NULL DEFAULT '0' COMMENT '是否自营',
  `recommend` int NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `goods_review` int NOT NULL DEFAULT '1' COMMENT '是否需要审核',
  `admin_url` varchar(300) DEFAULT '' COMMENT '管理入口',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所有人',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`merchant_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchant_code` (`merchant_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3112 DEFAULT CHARSET=utf8 COMMENT='商户';
CREATE TABLE `shop_merchant_account` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '商户手机号',
  `real_name` varchar(200) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '真实姓名',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `role_id` int unsigned NOT NULL DEFAULT '0' COMMENT '角色ID',
  `role_name` varchar(50) NOT NULL DEFAULT '' COMMENT '角色名称',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商户账号';
CREATE TABLE `shop_merchant_apply` (
  `apply_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` int unsigned NOT NULL DEFAULT '1' COMMENT '类型，0个人 1企业',
  `shop_type` varchar(50) NOT NULL DEFAULT '' COMMENT '店铺类型',
  `merchant_name` varchar(255) NOT NULL DEFAULT '' COMMENT '商户名称',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '社会信用代码',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '门店图片',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '商户手机号',
  `real_name` varchar(50) NOT NULL DEFAULT '' COMMENT '商户姓名',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '行业分类ID',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '行业父级分类',
  `category` varchar(50) NOT NULL DEFAULT '' COMMENT '商户分类',
  `lng_and_lat` varchar(255) DEFAULT '' COMMENT '经纬度',
  `province` varchar(50) NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) NOT NULL DEFAULT '' COMMENT '详细地址',
  `region_id` varchar(50) NOT NULL DEFAULT '' COMMENT '地区ID',
  `commission` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `keywords` varchar(200) NOT NULL DEFAULT '' COMMENT '关键字',
  `yyzz` varchar(500) NOT NULL DEFAULT '' COMMENT '营业执照',
  `id_card` varchar(50) NOT NULL DEFAULT '' COMMENT '身份证号码',
  `sfz1` varchar(500) NOT NULL DEFAULT '' COMMENT '身份证正面',
  `sfz2` varchar(500) NOT NULL DEFAULT '' COMMENT '身份证反面',
  `files` varchar(2000) NOT NULL DEFAULT '' COMMENT '资质图片',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所有人',
  `own_store` int NOT NULL DEFAULT '0' COMMENT '是否自营',
  `recommend` int NOT NULL DEFAULT '1' COMMENT '是否推荐',
  `goods_review` int NOT NULL DEFAULT '1' COMMENT '是否需要审核',
  `name2` varchar(50) NOT NULL DEFAULT '' COMMENT '工作负责人',
  `reason` varchar(300) DEFAULT '' COMMENT '驳回原因',
  `completed_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审核完成时间',
  `check_status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '100' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`apply_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8 COMMENT='商户入驻申请';
CREATE TABLE `shop_merchant_category` (
  `category_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '商品分类ID',
  `title` varchar(50) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '分类名称',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '类型 0商家分类',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '分类图片',
  `parent_id` int unsigned NOT NULL DEFAULT '0' COMMENT '上级分类ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `count` int unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1禁用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`category_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `parent_id` (`parent_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='商家分类';
CREATE TABLE `shop_merchant_count` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '店铺名称',
  `comments` longtext NOT NULL COMMENT '店铺说明',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='门店销售统计表';
CREATE TABLE `shop_merchant_type` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '店铺类型',
  `comments` longtext NOT NULL COMMENT '店铺入驻条件',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8 COMMENT='商户类型';
CREATE TABLE `shop_order` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订单号',
  `order_no` char(64) NOT NULL DEFAULT '' COMMENT '订单编号',
  `type` int unsigned NOT NULL DEFAULT '1' COMMENT '订单类型，0商城订单 1预定订单 2会员卡 3软件 4插件',
  `channel` tinyint DEFAULT '0' COMMENT '下单渠道，0小程序预定 1俱乐部训练场 3活动订场',
  `transaction_id` char(64) DEFAULT '' COMMENT '微信支付订单号',
  `refund_order` char(64) DEFAULT '' COMMENT '微信退款订单号',
  `merchant_id` int NOT NULL DEFAULT '0' COMMENT '商户ID',
  `merchant_name` varchar(200) NOT NULL DEFAULT '' COMMENT '商户名称',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编号',
  `coupon_id` int DEFAULT '0' COMMENT '使用的优惠券id',
  `card_id` varchar(20) DEFAULT '' COMMENT '使用的会员卡id',
  `admin_id` int unsigned DEFAULT '0' COMMENT '关联管理员id',
  `confirm_id` int unsigned DEFAULT '0' COMMENT '核销管理员id',
  `ic_card` varchar(50) DEFAULT NULL COMMENT 'IC卡号',
  `real_name` char(20) DEFAULT '' COMMENT '真实姓名',
  `phone` char(11) DEFAULT NULL COMMENT '手机号码',
  `total_price` decimal(8,2) NOT NULL COMMENT '订单总额',
  `reduce_price` decimal(8,2) DEFAULT '0.00' COMMENT '减少的金额，使用VIP会员折扣、优惠券抵扣、优惠券折扣后减去的价格',
  `pay_price` decimal(8,2) NOT NULL COMMENT '实际付款',
  `price` decimal(8,2) DEFAULT NULL COMMENT '用于统计',
  `money` decimal(8,0) unsigned DEFAULT '0' COMMENT '价钱，用于积分赠送',
  `refund_money` decimal(8,2) DEFAULT '0.00' COMMENT '退款金额',
  `coach_price` decimal(8,2) DEFAULT '0.00' COMMENT '教练价格',
  `total_num` int unsigned NOT NULL DEFAULT '1' COMMENT '购买数量',
  `coach_id` mediumint unsigned DEFAULT '0' COMMENT '教练id',
  `pay_type` int unsigned NOT NULL DEFAULT '1' COMMENT '0余额支付, 1微信支付，102微信Native，2会员卡支付，3支付宝，4现金，5POS机，6VIP月卡，7VIP年卡，8VIP次卡，9IC月卡，10IC年卡，11IC次卡，12免费，13VIP充值卡，14IC充值卡，15积分支付，16VIP季卡，17IC季卡',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未付款，1已付款',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未使用，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `coupon_type` int NOT NULL DEFAULT '0' COMMENT '优惠类型：0无、1抵扣优惠券、2折扣优惠券、3、VIP月卡、4VIP年卡，5VIP次卡、6VIP会员卡、7IC月卡、8IC年卡、9IC次卡、10IC会员卡、11免费订单、12VIP充值卡、13IC充值卡、14VIP季卡、15IC季卡',
  `coupon_desc` varchar(200) DEFAULT NULL COMMENT '优惠说明',
  `qrcode` varchar(200) DEFAULT NULL COMMENT '二维码地址，保存订单号，支付成功后才生成',
  `return_num` mediumint DEFAULT '0' COMMENT 'vip月卡年卡、ic月卡年卡回退次数',
  `return_money` decimal(8,2) DEFAULT '0.00' COMMENT 'vip充值回退金额',
  `start_time` varchar(300) NOT NULL DEFAULT '' COMMENT '预约详情开始时间数组',
  `is_invoice` tinyint unsigned DEFAULT '0' COMMENT '是否已开具发票：0未开发票，1已开发票，2不能开具发票',
  `invoice_no` varchar(200) DEFAULT NULL COMMENT '发票流水号',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `refund_time` timestamp NULL DEFAULT NULL COMMENT '退款时间',
  `refund_apply_time` timestamp NULL DEFAULT NULL COMMENT '申请退款时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `check_bill` tinyint DEFAULT '0' COMMENT '对账情况：0=未对账；1=已对账；3=已对账，金额对不上；4=未查询到该订单',
  `is_settled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '订单是否已结算(0未结算 1已结算)',
  `version` int NOT NULL DEFAULT '0' COMMENT '系统版本号 0当前版本 value=其他版本',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `comments` varchar(500) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE,
  KEY `merchant_code` (`merchant_code`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COMMENT='订单';
CREATE TABLE `shop_order_cart_info` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `oid` bigint unsigned NOT NULL COMMENT '订单id',
  `order_id` varchar(32) DEFAULT NULL COMMENT '订单号',
  `cart_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '购物车id',
  `product_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '商品ID',
  `cart_info` text NOT NULL COMMENT '购买东西的详细信息',
  `unique` varchar(50) NOT NULL DEFAULT '' COMMENT '唯一id',
  `is_after_sales` tinyint DEFAULT '0' COMMENT '是否能售后0不能1能',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `oid` (`oid`,`unique`) USING BTREE,
  KEY `cart_id` (`cart_id`) USING BTREE,
  KEY `product_id` (`product_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='订单购物详情表';
CREATE TABLE `shop_order_goods` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联订单表id',
  `order_code` varchar(30) NOT NULL DEFAULT '' COMMENT '订单标识（记录是哪个模块的订单）',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联商户ID',
  `image` varchar(500) NOT NULL DEFAULT '' COMMENT '商品封面图',
  `goods_id` int NOT NULL DEFAULT '0' COMMENT '关联商品id',
  `goods_name` varchar(200) NOT NULL DEFAULT '' COMMENT '商品名称',
  `price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单价',
  `total_num` int unsigned NOT NULL DEFAULT '1' COMMENT '购买数量',
  `pay_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0 未付款 1已付款，2无需付款或占用状态',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未使用，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `is_free` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否免费：0收费、1免费',
  `version` tinyint NOT NULL DEFAULT '0' COMMENT '系统版本 0当前版本 其他版本',
  `time_period` varchar(30) NOT NULL DEFAULT '' COMMENT '预约时间段',
  `date_time` date DEFAULT NULL COMMENT '预定日期',
  `start_time` time DEFAULT NULL COMMENT '开场时间',
  `end_time` time DEFAULT NULL COMMENT '结束时间',
  `time_flag` bigint NOT NULL DEFAULT '0' COMMENT '毫秒时间戳',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `order_id` (`order_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='商品信息';
CREATE TABLE `shop_order_info` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `order_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联订单表id',
  `order_code` varchar(30) NOT NULL DEFAULT '' COMMENT '组合数据:日期+时间段+场馆id+场地id',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '关联商户ID',
  `merchant_name` varchar(30) NOT NULL DEFAULT '' COMMENT '商户名称',
  `field_id` int NOT NULL DEFAULT '0' COMMENT '关联场地id',
  `field_name` varchar(30) NOT NULL DEFAULT '' COMMENT '场地名称',
  `price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单价',
  `children_price` decimal(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '儿童价',
  `adult_num` int unsigned NOT NULL DEFAULT '0' COMMENT '成人人数',
  `children_num` int unsigned NOT NULL DEFAULT '0' COMMENT '儿童人数',
  `adult_num_use` int unsigned NOT NULL DEFAULT '0' COMMENT '已核销的成人票数',
  `children_num_use` int unsigned NOT NULL DEFAULT '0' COMMENT '已核销的儿童票数',
  `pay_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0 未付款 1已付款，2无需付款或占用状态',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未使用，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `is_free` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否免费：0收费、1免费',
  `is_children` tinyint NOT NULL DEFAULT '0' COMMENT '是否支持儿童票：0不支持、1支持',
  `version` tinyint NOT NULL DEFAULT '0' COMMENT '系统版本 0当前版本 其他版本',
  `is_half` tinyint NOT NULL DEFAULT '0' COMMENT '预订类型：0全场，1半场',
  `time_period` varchar(30) NOT NULL DEFAULT '' COMMENT '预约时间段',
  `date_time` date DEFAULT NULL COMMENT '预定日期',
  `start_time` time DEFAULT NULL COMMENT '开场时间',
  `end_time` time DEFAULT NULL COMMENT '结束时间',
  `time_flag` bigint NOT NULL DEFAULT '0' COMMENT '毫秒时间戳',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `oid` (`order_id`) USING BTREE,
  KEY `merge_time_status` (`order_code`,`date_time`,`pay_status`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='场地';
CREATE TABLE `shop_order_info_log` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int unsigned NOT NULL COMMENT '关联订单表id',
  `merchant_id` int unsigned NOT NULL COMMENT '关联商户ID',
  `field_id` int NOT NULL COMMENT '关联场地id',
  `use_num` tinyint NOT NULL DEFAULT '0' COMMENT '核销数量',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=288248 DEFAULT CHARSET=utf8mb4 COMMENT='订单核销';
CREATE TABLE `shop_recharge_order` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(20) NOT NULL DEFAULT '' COMMENT '订单号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `recharge_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '充值方式(10自定义金额 20套餐充值)',
  `organization_id` int DEFAULT '0' COMMENT '机构id',
  `plan_id` int unsigned NOT NULL DEFAULT '0' COMMENT '充值套餐ID',
  `pay_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '用户支付金额',
  `gift_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '赠送金额',
  `actual_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '实际到账金额',
  `balance` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '用户可用余额',
  `pay_method` varchar(20) NOT NULL DEFAULT '' COMMENT '支付方式（微信/支付宝）',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '支付状态(10待支付 20已支付)',
  `pay_time` int unsigned NOT NULL DEFAULT '0' COMMENT '付款时间',
  `trade_id` int unsigned NOT NULL DEFAULT '0' COMMENT '第三方交易记录ID',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '来源客户端 (APP、H5、小程序等)',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属门店ID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `order_no` (`order_no`),
  KEY `user_id` (`user_id`),
  KEY `plan_id` (`plan_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='会员充值订单表';
CREATE TABLE `shop_spec` (
  `spec_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格ID',
  `spec_name` varchar(255) NOT NULL DEFAULT '' COMMENT '规格名称',
  `spec_value` json NOT NULL COMMENT '规格值',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '创建用户',
  `updater` int NOT NULL DEFAULT '0' COMMENT '更新者',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态, 0正常, 1待修,2异常已修，3异常未修',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`spec_id`) USING BTREE,
  KEY `spec_name` (`spec_name`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8 COMMENT='规格';
CREATE TABLE `shop_spec_value` (
  `spec_value_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '规格值ID',
  `spec_id` int NOT NULL COMMENT '规格组ID',
  `spec_value` varchar(255) NOT NULL COMMENT '规格值',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`spec_value_id`) USING BTREE,
  KEY `spec_value` (`spec_value`),
  KEY `spec_id` (`spec_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8 COMMENT='规格值';
CREATE TABLE `shop_user_address` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '姓名',
  `phone` varchar(50) NOT NULL DEFAULT '' COMMENT '手机号码',
  `country` varchar(50) NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(1000) NOT NULL DEFAULT '' COMMENT '收货地址',
  `gender` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '1先生 2女士',
  `type` varchar(10) NOT NULL DEFAULT '' COMMENT '家、公司、学校',
  `is_default` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '默认收货地址',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10817 DEFAULT CHARSET=utf8 COMMENT='收货地址';
CREATE TABLE `shop_user_collection` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tid` int unsigned NOT NULL DEFAULT '0' COMMENT '租户ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='我的收藏';
CREATE TABLE `shop_wechat_deposit` (
  `id` mediumint unsigned NOT NULL AUTO_INCREMENT,
  `oid` mediumint unsigned NOT NULL COMMENT '订单id',
  `uid` mediumint unsigned NOT NULL DEFAULT '0' COMMENT '用户id',
  `order_num` char(27) NOT NULL COMMENT '场地订单号',
  `wechat_order` char(27) NOT NULL COMMENT '付款订单号',
  `wechat_return` char(27) DEFAULT NULL COMMENT '退款订单号 ',
  `site_name` varchar(50) NOT NULL COMMENT '场馆名称',
  `username` varchar(50) NOT NULL COMMENT '微信昵称',
  `phone` char(11) NOT NULL COMMENT '手机号码',
  `name` varchar(50) NOT NULL COMMENT '物品名称',
  `price` decimal(8,2) NOT NULL COMMENT '押金金额',
  `status` tinyint unsigned NOT NULL DEFAULT '2' COMMENT '押金状态，1已付款，2未付款，已退押金',
  `create_time` int unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8 COMMENT='押金';
CREATE TABLE `sys_access_key` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `access_key` varchar(100) NOT NULL COMMENT 'AccessKey',
  `access_secret` varchar(100) NOT NULL COMMENT 'AccessSecret',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=460 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='访问凭证';
CREATE TABLE `sys_cart` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '购物车表ID',
  `type` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '类型 0商城 1应用插件',
  `code` varchar(50) NOT NULL DEFAULT '' COMMENT '唯一标识',
  `item_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '项目ID',
  `spec` varchar(300) NOT NULL DEFAULT '' COMMENT '商品规格',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '商品价格',
  `month` int unsigned NOT NULL DEFAULT '0' COMMENT '购买时长(月)',
  `cart_num` smallint unsigned NOT NULL DEFAULT '0' COMMENT '商品数量',
  `total_price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '单商品合计',
  `is_pay` tinyint NOT NULL DEFAULT '0' COMMENT '0 = 未购买 1 = 已购买',
  `is_new` tinyint NOT NULL DEFAULT '0' COMMENT '是否为立即购买',
  `combination_id` int unsigned DEFAULT '0' COMMENT '拼团id',
  `seckill_id` int unsigned NOT NULL DEFAULT '0' COMMENT '秒杀产品ID',
  `bargain_id` int unsigned NOT NULL DEFAULT '0' COMMENT '砍价id',
  `selected` tinyint NOT NULL DEFAULT '1' COMMENT '是否选中',
  `merchant_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `user_id` bigint unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `item_id` (`item_id`) USING BTREE,
  KEY `uid` (`user_id`,`is_pay`) USING BTREE,
  KEY `uid_3` (`user_id`,`is_new`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=681 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='购物车';
CREATE TABLE `sys_chat_conversation` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `friend_id` int DEFAULT NULL COMMENT '好友ID',
  `type` int DEFAULT NULL COMMENT '消息类型',
  `content` text NOT NULL COMMENT '消息内容',
  `un_read` int NOT NULL DEFAULT '0' COMMENT '未读消息',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未读, 1已读',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `id` (`id`),
  KEY `user_id` (`user_id`),
  KEY `friend_id` (`friend_id`),
  KEY `type` (`type`),
  KEY `un_read` (`un_read`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=777 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='聊天消息表';
CREATE TABLE `sys_chat_message` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `form_user_id` int NOT NULL COMMENT '发送人ID',
  `to_user_id` int NOT NULL COMMENT '接收人ID',
  `type` varchar(255) NOT NULL COMMENT '消息类型',
  `content` text NOT NULL COMMENT '消息内容',
  `side_to` int NOT NULL DEFAULT '0' COMMENT '屏蔽接收方',
  `side_from` int NOT NULL DEFAULT '0' COMMENT '屏蔽发送方',
  `withdraw` int NOT NULL DEFAULT '0' COMMENT '是否撤回',
  `file_info` json DEFAULT NULL COMMENT '文件信息',
  `has_contact` int DEFAULT NULL COMMENT '存在联系方式',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未读, 1已读',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `id` (`id`),
  KEY `form_user_id` (`form_user_id`),
  KEY `to_user_id` (`to_user_id`),
  KEY `type` (`type`),
  KEY `withdraw` (`withdraw`),
  KEY `status` (`status`),
  KEY `deleted` (`deleted`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='聊天消息表';
CREATE TABLE `sys_company` (
  `company_id` int NOT NULL AUTO_INCREMENT COMMENT '企业id',
  `type` int DEFAULT '0' COMMENT '应用类型，0完整应用 1插件',
  `short_name` varchar(50) NOT NULL DEFAULT '' COMMENT '企业简称',
  `company_name` varchar(100) DEFAULT '' COMMENT '企业全称',
  `company_code` varchar(100) NOT NULL DEFAULT '' COMMENT '企业标识',
  `company_type` varchar(50) NOT NULL DEFAULT '' COMMENT '类型 10企业 20政府单位',
  `company_type_multiple` json DEFAULT NULL COMMENT '企业类型多选(已废弃)',
  `company_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '应用标识',
  `category_id` int NOT NULL DEFAULT '0' COMMENT '产品分类ID',
  `image` varchar(500) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '封面图',
  `app_type` varchar(50) NOT NULL DEFAULT '' COMMENT '应用类型',
  `official` int NOT NULL DEFAULT '0' COMMENT '是否官方',
  `price` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '销售价格',
  `delivery_method` tinyint DEFAULT '1' COMMENT '交付方式(0 SaaS 1源码交付)',
  `charging_method` tinyint DEFAULT '1' COMMENT '计费方式(0免费 1买断2按年 3按月4按日)',
  `free_domain` varchar(100) DEFAULT NULL COMMENT '免费域名',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `phone` varchar(100) DEFAULT NULL COMMENT '联系电话',
  `tel` varchar(100) DEFAULT NULL COMMENT '座机电话',
  `email` varchar(200) DEFAULT NULL COMMENT '邮箱',
  `files` text CHARACTER SET utf8 COMMENT '应用截图',
  `Invoice_header` varchar(50) DEFAULT NULL COMMENT '发票抬头',
  `business_entity` varchar(50) DEFAULT '' COMMENT '企业法人',
  `start_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务开始时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `soon` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1 即将过期',
  `version` int unsigned NOT NULL DEFAULT '10' COMMENT '应用版本 10体验版 20授权版 30永久授权',
  `version_name` varchar(50) NOT NULL DEFAULT '' COMMENT '版本名称',
  `version_code` varchar(50) NOT NULL DEFAULT '' COMMENT '版本号',
  `rate` decimal(2,1) unsigned NOT NULL DEFAULT '0.0' COMMENT '评分',
  `members` int unsigned NOT NULL DEFAULT '20' COMMENT '成员数量(人数上限)',
  `users` int NOT NULL DEFAULT '0' COMMENT '成员数量(当前)',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `departments` int unsigned NOT NULL DEFAULT '100' COMMENT '部门数量',
  `storage` bigint NOT NULL DEFAULT '0' COMMENT '存储空间',
  `storage_max` bigint NOT NULL DEFAULT '524288000' COMMENT '存储空间(上限)',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `authentication` int NOT NULL DEFAULT '0' COMMENT '是否实名认证',
  `authoritative` int NOT NULL DEFAULT '0' COMMENT '企业默认主体',
  `server_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '主控节点',
  `modules_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '模块节点',
  `redirect_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '重定向',
  `request_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'request合法域名',
  `socket_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'socket合法域名',
  `admin_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '总后台管理入口',
  `merchant_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '商户端入口',
  `website_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '网站域名',
  `mp_weixin_code` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '微信小程序二维码',
  `mp_alipay_code` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '支付宝小程序二维码',
  `h5_code` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'H5端应用二维码',
  `android_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '安卓APP二维码',
  `ios_url` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '苹果APP二维码',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数量',
  `clicks` int unsigned DEFAULT '0' COMMENT '点击数量',
  `buys` int unsigned DEFAULT '0' COMMENT '购买数量',
  `is_tax` int NOT NULL DEFAULT '0' COMMENT '是否含税, 0不含, 1含',
  `menu_id` int unsigned NOT NULL DEFAULT '0' COMMENT '插件ID（菜单根节点ID）',
  `plan_id` int unsigned NOT NULL DEFAULT '0' COMMENT '当前克隆的租户ID',
  `hide` int NOT NULL DEFAULT '1' COMMENT '是否允许搜索 0允许 1不允许',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `website_status` int unsigned NOT NULL DEFAULT '0' COMMENT '是否开启网站',
  `sort_number` int NOT NULL DEFAULT '100' COMMENT '排序号',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `tid` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`company_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `authoritative` (`authoritative`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10583 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='企业信息';
CREATE TABLE `sys_company_comment` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '父级ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `rate` decimal(2,1) unsigned NOT NULL DEFAULT '0.0' COMMENT '评分',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '评论内容',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2302 DEFAULT CHARSET=utf8 COMMENT='应用评论';
CREATE TABLE `sys_company_content` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `company_id` int unsigned DEFAULT '0' COMMENT '企业ID',
  `content` longtext COMMENT '详细内容',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=518 DEFAULT CHARSET=utf8mb4 COMMENT='应用详情';
CREATE TABLE `sys_company_git` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `title` varchar(50) NOT NULL DEFAULT '' COMMENT '仓库名称',
  `language` varchar(200) DEFAULT NULL COMMENT '开发语言',
  `brand` varchar(50) NOT NULL DEFAULT '' COMMENT '厂商 0私有仓库 1github 2gitee 3其他',
  `icon` varchar(200) DEFAULT NULL COMMENT '图标',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `domain` varchar(200) NOT NULL DEFAULT '' COMMENT '仓库地址',
  `account` varchar(200) NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(200) NOT NULL DEFAULT '' COMMENT '密码',
  `comments` varchar(300) DEFAULT '' COMMENT '仓库描述',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=69 DEFAULT CHARSET=utf8 COMMENT='代码仓库';
CREATE TABLE `sys_company_parameter` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '参数名称',
  `value` varchar(200) NOT NULL DEFAULT '' COMMENT '参数内容',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=87 DEFAULT CHARSET=utf8 COMMENT='应用参数';
CREATE TABLE `sys_company_url` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '域名类型',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `domain` varchar(200) NOT NULL DEFAULT '' COMMENT '域名',
  `account` varchar(200) NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(200) NOT NULL DEFAULT '' COMMENT '密码',
  `qrcode` varchar(500) DEFAULT '' COMMENT '二维码',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1待确认',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=72 DEFAULT CHARSET=utf8 COMMENT='应用域名';
CREATE TABLE `sys_dict` (
  `dict_id` int NOT NULL AUTO_INCREMENT COMMENT '字典id',
  `dict_code` varchar(100) NOT NULL COMMENT '字典标识',
  `dict_name` varchar(200) NOT NULL COMMENT '字典名称',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`dict_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1457 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='字典(业务类)';
CREATE TABLE `sys_dict_data` (
  `dict_data_id` int NOT NULL AUTO_INCREMENT COMMENT '字典项id',
  `dict_id` int NOT NULL COMMENT '字典id',
  `dict_data_code` varchar(100) NOT NULL COMMENT '字典项标识',
  `dict_data_name` varchar(200) NOT NULL COMMENT '字典项名称',
  `path` varchar(100) NOT NULL DEFAULT '' COMMENT '路由地址(预留字段)',
  `component` varchar(100) NOT NULL DEFAULT '' COMMENT '组件路径(预留字段)',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`dict_data_id`) USING BTREE,
  KEY `dict_id` (`dict_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3729 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='字典项(业务类)';
CREATE TABLE `sys_dictionary` (
  `dict_id` int NOT NULL AUTO_INCREMENT COMMENT '字典id',
  `dict_code` varchar(100) NOT NULL COMMENT '字典标识',
  `dict_name` varchar(200) NOT NULL COMMENT '字典名称',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`dict_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='字典';
CREATE TABLE `sys_dictionary_data` (
  `dict_data_id` int NOT NULL AUTO_INCREMENT COMMENT '字典项id',
  `dict_id` int NOT NULL COMMENT '字典id',
  `dict_data_code` varchar(100) NOT NULL COMMENT '字典项标识',
  `dict_data_name` varchar(200) NOT NULL COMMENT '字典项名称',
  `path` varchar(100) NOT NULL DEFAULT '' COMMENT '路由地址',
  `component` varchar(100) NOT NULL DEFAULT '' COMMENT '组件路径',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`dict_data_id`) USING BTREE,
  KEY `dict_id` (`dict_id`) USING BTREE,
  CONSTRAINT `sys_dictionary_data_ibfk_1` FOREIGN KEY (`dict_id`) REFERENCES `sys_dictionary` (`dict_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=298 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='字典项';
CREATE TABLE `sys_domain` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `domain` varchar(100) DEFAULT NULL COMMENT '域名',
  `host_name` varchar(100) CHARACTER SET utf8 DEFAULT '' COMMENT '主机记录',
  `host_value` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '记录值',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `type` int NOT NULL DEFAULT '0' COMMENT '类型 0常规 1顶级域名 2免费后台域名',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `company_id` int NOT NULL DEFAULT '1' COMMENT '企业ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10708 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='授权域名';
CREATE TABLE `sys_email_record` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `title` varchar(200) DEFAULT NULL COMMENT '邮件标题',
  `content` text COMMENT '邮件内容',
  `receiver` varchar(200) DEFAULT NULL COMMENT '收件邮箱',
  `sender` varchar(200) DEFAULT NULL COMMENT '发件邮箱',
  `create_user_id` int DEFAULT NULL COMMENT '创建人',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `create_user_id` (`create_user_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=60 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='邮件记录';
CREATE TABLE `sys_environment` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '插件id',
  `environment_name` varchar(200) NOT NULL COMMENT '环境名称',
  `environment_code` varchar(200) NOT NULL COMMENT '环境编号',
  `modules_url` varchar(200) NOT NULL COMMENT '模块访问地址',
  `brand` varchar(100) CHARACTER SET utf8 NOT NULL COMMENT '服务器厂商',
  `server_ip` varchar(200) NOT NULL COMMENT '服务器IP',
  `modules_api` varchar(200) NOT NULL COMMENT '模块API',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '10' COMMENT '状态, 10待审核 20已通过 30已驳回',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10503 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='环境管理';
CREATE TABLE `sys_file_record` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `group_id` int unsigned NOT NULL DEFAULT '0' COMMENT '文件分组ID',
  `name` varchar(200) DEFAULT NULL COMMENT '文件名称',
  `path` varchar(200) DEFAULT NULL COMMENT '文件存储路径',
  `type` int DEFAULT NULL COMMENT '文件类型(已废弃)',
  `length` int DEFAULT NULL COMMENT '文件大小',
  `content_type` varchar(80) DEFAULT NULL COMMENT '文件类型',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `app_id` int unsigned NOT NULL DEFAULT '0' COMMENT '项目ID',
  `company_id` int unsigned NOT NULL DEFAULT '0' COMMENT '企业ID',
  `merchant_id` int unsigned NOT NULL DEFAULT '0' COMMENT '商户ID',
  `create_user_id` int DEFAULT NULL COMMENT '创建人',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `create_user_id` (`create_user_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `app_id` (`app_id`) USING BTREE,
  KEY `group_id` (`group_id`) USING BTREE,
  KEY `company_id` (`company_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=50473 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='文件列表';
CREATE TABLE `sys_file_type` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `type` int unsigned NOT NULL DEFAULT '0' COMMENT '0本地存储，1阿里云oss，2腾讯云cos，3七牛云，4其他',
  `name` varchar(200) DEFAULT NULL COMMENT '名称',
  `domain` varchar(200) DEFAULT NULL COMMENT '访问域名',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='存储类型';
CREATE TABLE `sys_login_record` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` varchar(128) NOT NULL COMMENT '用户账号',
  `os` varchar(200) DEFAULT NULL COMMENT '操作系统',
  `device` varchar(200) DEFAULT NULL COMMENT '设备名',
  `browser` varchar(200) DEFAULT NULL COMMENT '浏览器类型',
  `ip` varchar(200) DEFAULT NULL COMMENT 'ip地址',
  `login_type` int NOT NULL COMMENT '操作类型, 0登录成功, 1登录失败, 2退出登录, 3续签token',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=81586 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='登录日志';
CREATE TABLE `sys_menu` (
  `menu_id` int NOT NULL AUTO_INCREMENT COMMENT '菜单id',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `title` varchar(200) NOT NULL COMMENT '菜单名称',
  `path` varchar(200) DEFAULT NULL COMMENT '菜单路由地址',
  `component` varchar(300) DEFAULT NULL COMMENT '菜单组件地址, 目录可为空',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `authority` varchar(200) DEFAULT NULL COMMENT '权限标识',
  `target` varchar(200) DEFAULT '_self' COMMENT '打开位置',
  `icon` varchar(200) DEFAULT NULL COMMENT '菜单图标',
  `color` varchar(200) DEFAULT NULL COMMENT '图标颜色',
  `hide` int NOT NULL DEFAULT '0' COMMENT '是否隐藏, 0否, 1是(仅注册路由不显示在左侧菜单)',
  `active` varchar(200) DEFAULT NULL COMMENT '菜单侧栏选中的path',
  `meta` varchar(800) DEFAULT NULL COMMENT '其它路由元信息',
  `app_id` int NOT NULL DEFAULT '0' COMMENT '关联应用ID',
  `modules` varchar(100) DEFAULT NULL COMMENT '模块ID',
  `modules_url` varchar(300) DEFAULT NULL COMMENT '模块访问地址',
  `menu_type` int DEFAULT '0' COMMENT '类型, 0菜单, 1按钮',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`menu_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=198413 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='菜单';
CREATE TABLE `sys_modules` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '插件id',
  `modules` varchar(200) NOT NULL COMMENT '环境编号',
  `modules_url` varchar(200) NOT NULL COMMENT '模块访问地址',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `assets_id` int unsigned NOT NULL DEFAULT '0' COMMENT '服务器ID',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '10' COMMENT '状态, 10待审核 20已通过 30已驳回',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `user_ids` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '可见用户',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10534 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='模块管理';
CREATE TABLE `sys_notice` (
  `notice_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type` varchar(50) NOT NULL DEFAULT '' COMMENT '消息类型',
  `title` varchar(300) NOT NULL DEFAULT '' COMMENT '标题',
  `icon` varchar(100) DEFAULT NULL COMMENT '图标',
  `color` varchar(50) DEFAULT NULL COMMENT '颜色',
  `content` longtext COMMENT '内容',
  `tokens` int unsigned NOT NULL DEFAULT '0' COMMENT '代币',
  `is_read` int NOT NULL DEFAULT '0' COMMENT '是否已查阅',
  `progress` int NOT NULL DEFAULT '0' COMMENT '工单状态， 0未开始 1已指派 ',
  `channel` tinyint NOT NULL DEFAULT '0' COMMENT '聚道',
  `source` varchar(50) NOT NULL DEFAULT '10' COMMENT '消息来源',
  `source_id` int unsigned NOT NULL DEFAULT '0' COMMENT '来源记录ID',
  `path` varchar(200) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '路由地址',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态, 0待处理, 1已完成',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`notice_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='消息记录表';
CREATE TABLE `sys_operation_record` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` int DEFAULT NULL COMMENT '用户id',
  `module` varchar(200) DEFAULT NULL COMMENT '操作模块',
  `description` varchar(200) DEFAULT NULL COMMENT '操作功能',
  `url` varchar(200) DEFAULT NULL COMMENT '请求地址',
  `request_method` varchar(200) DEFAULT NULL COMMENT '请求方式',
  `method` varchar(200) DEFAULT NULL COMMENT '调用方法',
  `params` varchar(1000) DEFAULT NULL COMMENT '请求参数',
  `result` varchar(1000) DEFAULT NULL COMMENT '返回结果',
  `error` varchar(1000) DEFAULT NULL COMMENT '异常信息',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `spend_time` int DEFAULT NULL COMMENT '消耗时间, 单位毫秒',
  `os` varchar(50) DEFAULT NULL COMMENT '操作系统',
  `device` varchar(50) DEFAULT NULL COMMENT '设备名称',
  `browser` varchar(50) DEFAULT NULL COMMENT '浏览器类型',
  `ip` varchar(200) DEFAULT NULL COMMENT 'ip地址',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0成功, 1异常',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1291756 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='操作日志';
CREATE TABLE `sys_order` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订单号',
  `order_no` char(64) NOT NULL DEFAULT '' COMMENT '订单编号',
  `type` int unsigned NOT NULL DEFAULT '1' COMMENT '订单类型，0商城 1应用插件',
  `channel` tinyint DEFAULT '0' COMMENT '下单渠道，0网站 1小程序 2其他',
  `transaction_id` char(64) DEFAULT '' COMMENT '微信支付订单号',
  `refund_order` char(64) DEFAULT '' COMMENT '微信退款订单号',
  `coupon_id` int DEFAULT '0' COMMENT '使用的优惠券id',
  `real_name` char(20) DEFAULT '' COMMENT '真实姓名',
  `phone` char(11) DEFAULT NULL COMMENT '手机号码',
  `total_price` decimal(8,2) NOT NULL COMMENT '订单总额',
  `reduce_price` decimal(8,2) DEFAULT '0.00' COMMENT '减少的金额，使用VIP会员折扣、优惠券抵扣、优惠券折扣后减去的价格',
  `pay_price` decimal(8,2) NOT NULL COMMENT '实际付款',
  `price` decimal(8,2) DEFAULT NULL COMMENT '用于统计',
  `money` decimal(8,0) unsigned DEFAULT '0' COMMENT '价钱，用于积分赠送',
  `refund_money` decimal(8,2) DEFAULT '0.00' COMMENT '退款金额',
  `total_num` int unsigned NOT NULL DEFAULT '1' COMMENT '购买数量',
  `pay_type` int unsigned NOT NULL DEFAULT '1' COMMENT '0余额支付, 1微信支付，102微信Native，2会员卡支付，3支付宝，4现金，5POS机',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未付款，1已付款',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未完成，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `coupon_type` int NOT NULL DEFAULT '0' COMMENT '优惠类型：0无、1抵扣优惠券、2折扣优惠券、3、VIP月卡、4VIP年卡，5VIP次卡、6VIP会员卡、7IC月卡、8IC年卡、9IC次卡、10IC会员卡、11免费订单、12VIP充值卡、13IC充值卡、14VIP季卡、15IC季卡',
  `coupon_desc` varchar(200) DEFAULT NULL COMMENT '优惠说明',
  `qrcode` varchar(200) DEFAULT NULL COMMENT '二维码地址，保存订单号，支付成功后才生成',
  `start_time` varchar(300) NOT NULL DEFAULT '' COMMENT '预约详情开始时间数组',
  `is_invoice` tinyint unsigned DEFAULT '0' COMMENT '是否已开具发票：0未开发票，1已开发票，2不能开具发票',
  `invoice_no` varchar(200) DEFAULT NULL COMMENT '发票流水号',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `refund_time` timestamp NULL DEFAULT NULL COMMENT '退款时间',
  `refund_apply_time` timestamp NULL DEFAULT NULL COMMENT '申请退款时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `check_bill` tinyint DEFAULT '0' COMMENT '对账情况：0=未对账；1=已对账；3=已对账，金额对不上；4=未查询到该订单',
  `is_settled` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '订单是否已结算(0未结算 1已结算)',
  `version` int NOT NULL DEFAULT '0' COMMENT '系统版本号 0当前版本 value=其他版本',
  `app_name` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '应用名称',
  `admin_url` varchar(200) DEFAULT NULL COMMENT '控制台地址',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `comments` varchar(500) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `type` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=583599 DEFAULT CHARSET=utf8mb4 COMMENT='订单';
CREATE TABLE `sys_order_goods` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增编号',
  `type` int unsigned NOT NULL DEFAULT '1' COMMENT '订单类型，0商城 1应用插件',
  `order_id` int NOT NULL DEFAULT '0' COMMENT '订单号',
  `item_id` int NOT NULL DEFAULT '0' COMMENT '项目ID',
  `menu_id` int NOT NULL DEFAULT '0' COMMENT '插件ID',
  `pay_price` decimal(8,2) NOT NULL COMMENT '实际付款',
  `month` int unsigned NOT NULL DEFAULT '0' COMMENT '购买时长(月)',
  `total_num` int unsigned NOT NULL DEFAULT '1' COMMENT '购买数量',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0未付款，1已付款',
  `order_status` int unsigned NOT NULL DEFAULT '0' COMMENT '0未完成，1已完成，2已取消，3取消中，4退款申请中，5退款被拒绝，6退款成功，7客户端申请退款',
  `start_time` varchar(300) NOT NULL DEFAULT '' COMMENT '预约详情开始时间数组',
  `is_invoice` tinyint unsigned DEFAULT '0' COMMENT '是否已开具发票：0未开发票，1已开发票，2不能开具发票',
  `invoice_no` varchar(200) DEFAULT NULL COMMENT '发票流水号',
  `pay_time` timestamp NULL DEFAULT NULL COMMENT '支付时间',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '过期时间',
  `user_id` int NOT NULL DEFAULT '0' COMMENT '用户id',
  `app_name` varchar(200) CHARACTER SET utf8 DEFAULT '' COMMENT '应用名称',
  `admin_url` varchar(300) NOT NULL DEFAULT '' COMMENT '产品控制台',
  `comments` varchar(500) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `item_id` (`item_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=583597 DEFAULT CHARSET=utf8mb4 COMMENT='订单商品';
CREATE TABLE `sys_organization` (
  `organization_id` int NOT NULL AUTO_INCREMENT COMMENT '机构id',
  `parent_id` int NOT NULL DEFAULT '0' COMMENT '上级id, 0是顶级',
  `organization_name` varchar(200) NOT NULL DEFAULT '' COMMENT '机构名称',
  `organization_full_name` varchar(200) DEFAULT NULL COMMENT '机构全称',
  `organization_code` varchar(100) DEFAULT NULL COMMENT '机构代码',
  `organization_type` varchar(100) NOT NULL DEFAULT '' COMMENT '机构类型',
  `province` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 DEFAULT '' COMMENT '所在辖区',
  `zip_code` varchar(100) DEFAULT NULL COMMENT '邮政编码',
  `park` varchar(200) NOT NULL DEFAULT '' COMMENT '所属园区',
  `phone` varchar(100) NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(100) NOT NULL DEFAULT '' COMMENT '企业邮箱',
  `establish_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '成立日期',
  `registered_capital` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '注册资本',
  `business` varchar(200) NOT NULL DEFAULT '' COMMENT '经营范围',
  `business_status` varchar(50) DEFAULT '0' COMMENT '经营状态',
  `insureds` int DEFAULT '0' COMMENT '参保人数',
  `industry` varchar(100) NOT NULL DEFAULT '' COMMENT '所属行业',
  `estate` varchar(255) DEFAULT NULL COMMENT '所属产业',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '园区图片',
  `about` varchar(3000) NOT NULL DEFAULT '' COMMENT '园区介绍',
  `is_coop` tinyint DEFAULT '0' COMMENT '是否合作单位',
  `is_chief` tinyint DEFAULT '0' COMMENT '是否办公室主任',
  `leader_id` int DEFAULT NULL COMMENT '负责人id',
  `legal_person` varchar(255) DEFAULT NULL COMMENT '法定代表人',
  `set_up_date` varchar(20) DEFAULT NULL COMMENT '成立日期',
  `tag` varchar(200) DEFAULT NULL COMMENT '企业标签',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`organization_id`) USING BTREE,
  KEY `leader_id` (`leader_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=459 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='组织机构';
CREATE TABLE `sys_payment` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '支付方式',
  `type` int NOT NULL DEFAULT '0' COMMENT '类型 0余额支付 1微信支付 2 会员卡支付 3支付宝',
  `code` varchar(50) NOT NULL COMMENT '标识',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '支付图标',
  `wechat_type` int NOT NULL DEFAULT '0' COMMENT '微信商户号类型 1普通商户2子商户',
  `app_id` varchar(100) NOT NULL DEFAULT '' COMMENT '应用ID',
  `mch_id` varchar(100) NOT NULL DEFAULT '' COMMENT '商户号',
  `api_key` varchar(300) NOT NULL DEFAULT '' COMMENT '设置APIv3密钥',
  `apiclient_cert` varchar(300) NOT NULL DEFAULT '' COMMENT '证书文件 (CERT)',
  `apiclient_key` varchar(300) NOT NULL DEFAULT '' COMMENT '证书文件 (KEY)',
  `merchant_serial_number` varchar(100) NOT NULL DEFAULT '' COMMENT '商户证书序列号',
  `pub_key` varchar(300) NOT NULL DEFAULT '' COMMENT '公钥文件',
  `pub_key_id` varchar(300) NOT NULL DEFAULT '' COMMENT '公钥ID',
  `notify_url` varchar(300) NOT NULL DEFAULT '' COMMENT '支付回调地址',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未启用, 1启用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10201 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='支付方式';
CREATE TABLE `sys_plug` (
  `plug_id` int NOT NULL AUTO_INCREMENT COMMENT '插件id',
  `plug_name` varchar(200) NOT NULL COMMENT '菜单名称',
  `plug_code` varchar(200) NOT NULL COMMENT '插件ID',
  `plug_type` int NOT NULL DEFAULT '10' COMMENT '插件类型 10后台模块',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `price` decimal(10,2) unsigned DEFAULT '0.00' COMMENT '插件价格',
  `score` decimal(3,1) unsigned DEFAULT '3.0' COMMENT '评分',
  `clicks` int unsigned NOT NULL DEFAULT '0' COMMENT '下载次数',
  `installs` int unsigned NOT NULL DEFAULT '0' COMMENT '安装次数',
  `comments` varchar(300) CHARACTER SET utf8 DEFAULT '' COMMENT '备注',
  `content` longtext CHARACTER SET utf8 COMMENT '插件详情',
  `status` int NOT NULL DEFAULT '10' COMMENT '状态, 10待审核 20已通过 30已驳回',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`plug_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='插件扩展';
CREATE TABLE `sys_recharge_order` (
  `order_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(20) NOT NULL DEFAULT '' COMMENT '订单号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `recharge_type` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '充值方式(10自定义金额 20套餐充值)',
  `organization_id` int DEFAULT '0' COMMENT '机构id',
  `plan_id` int unsigned NOT NULL DEFAULT '0' COMMENT '充值套餐ID',
  `pay_price` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '用户支付金额',
  `gift_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '赠送金额',
  `actual_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '实际到账金额',
  `balance` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '用户可用余额',
  `pay_method` varchar(20) NOT NULL DEFAULT '' COMMENT '支付方式（微信/支付宝）',
  `pay_status` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '支付状态(10待支付 20已支付)',
  `pay_time` int unsigned NOT NULL DEFAULT '0' COMMENT '付款时间',
  `trade_id` int unsigned NOT NULL DEFAULT '0' COMMENT '第三方交易记录ID',
  `platform` varchar(20) NOT NULL DEFAULT '' COMMENT '来源客户端 (APP、H5、小程序等)',
  `shop_id` int unsigned NOT NULL DEFAULT '0' COMMENT '所属门店ID',
  `operator` varchar(20) NOT NULL DEFAULT '' COMMENT '操作员',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  KEY `order_no` (`order_no`),
  KEY `user_id` (`user_id`),
  KEY `plan_id` (`plan_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=897 DEFAULT CHARSET=utf8 COMMENT='会员充值订单表';
CREATE TABLE `sys_role` (
  `role_id` int NOT NULL AUTO_INCREMENT COMMENT '角色id',
  `role_name` varchar(200) NOT NULL COMMENT '角色名称',
  `role_code` varchar(200) NOT NULL COMMENT '角色标识',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`role_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1825 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='角色';
CREATE TABLE `sys_role_menu` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `role_id` int NOT NULL COMMENT '角色id',
  `menu_id` int NOT NULL COMMENT '菜单id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `FK_sys_role_permission_role` (`role_id`) USING BTREE,
  KEY `menu_id` (`menu_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  CONSTRAINT `sys_role_menu_ibfk_1` FOREIGN KEY (`role_id`) REFERENCES `sys_role` (`role_id`) ON DELETE CASCADE,
  CONSTRAINT `sys_role_menu_ibfk_2` FOREIGN KEY (`menu_id`) REFERENCES `sys_menu` (`menu_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=453372 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='角色权限';
CREATE TABLE `sys_setting` (
  `setting_id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `setting_key` varchar(200) NOT NULL DEFAULT '' COMMENT '设置项标示',
  `content` mediumtext COMMENT '设置内容（json格式）',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`setting_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=299 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='系统设置';
CREATE TABLE `sys_tenant` (
  `tenant_id` int NOT NULL AUTO_INCREMENT COMMENT '租户id',
  `tenant_name` varchar(200) NOT NULL COMMENT '租户名称',
  `tenant_code` varchar(200) DEFAULT NULL COMMENT '租户编号',
  `comments` varchar(400) DEFAULT NULL COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '100' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10557 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='租户';
CREATE TABLE `sys_upload` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '支付方式',
  `code` varchar(50) NOT NULL COMMENT '标识',
  `image` varchar(200) NOT NULL DEFAULT '' COMMENT '支付图标',
  `wechat_type` int NOT NULL DEFAULT '0' COMMENT '微信商户号类型 1普通商户2子商户',
  `app_id` varchar(100) NOT NULL DEFAULT '' COMMENT '应用ID',
  `mch_id` varchar(100) NOT NULL DEFAULT '' COMMENT '商户号',
  `api_key` varchar(300) NOT NULL DEFAULT '' COMMENT '设置APIv3密钥',
  `apiclient_cert` varchar(300) NOT NULL DEFAULT '' COMMENT '证书文件 (CERT)',
  `apiclient_key` varchar(300) NOT NULL DEFAULT '' COMMENT '证书文件 (KEY)',
  `merchant_serial_number` varchar(100) NOT NULL DEFAULT '' COMMENT '商户证书序列号',
  `notify_url` varchar(300) NOT NULL DEFAULT '' COMMENT '支付回调地址',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0未启用, 1启用',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='支付方式';
CREATE TABLE `sys_user` (
  `user_id` int NOT NULL AUTO_INCREMENT COMMENT '用户id',
  `type` int unsigned DEFAULT '0' COMMENT '用户类型',
  `username` varchar(100) NOT NULL DEFAULT '' COMMENT '账号',
  `password` varchar(100) NOT NULL DEFAULT '' COMMENT '密码',
  `nickname` varchar(100) NOT NULL COMMENT '昵称',
  `phone` varchar(50) DEFAULT NULL COMMENT '手机号',
  `sex` int DEFAULT NULL COMMENT '性别 1男 2女',
  `position` varchar(50) DEFAULT NULL COMMENT '职务',
  `platform` varchar(20) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '注册来源客户端 (APP、H5、MP-WEIXIN等)',
  `email` varchar(50) DEFAULT NULL COMMENT '邮箱',
  `email_verified` int NOT NULL DEFAULT '0' COMMENT '邮箱是否验证, 0否, 1是',
  `alias` varchar(50) DEFAULT NULL COMMENT '别名',
  `real_name` varchar(50) DEFAULT '' COMMENT '真实姓名',
  `id_card` varchar(50) DEFAULT NULL COMMENT '证件号码',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `address` varchar(100) DEFAULT NULL COMMENT '街道地址',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `balance` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '用户可用余额',
  `cashed_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '已提现金额',
  `points` int unsigned NOT NULL DEFAULT '0' COMMENT '用户可用积分',
  `pay_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '用户总支付的金额',
  `expend_money` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '实际消费的金额(不含退款)',
  `pay_password` varchar(100) DEFAULT NULL COMMENT '密码',
  `grade_id` int unsigned NOT NULL DEFAULT '0' COMMENT '会员等级ID',
  `category` varchar(200) DEFAULT NULL COMMENT '行业分类',
  `introduction` varchar(200) DEFAULT NULL COMMENT '个人简介',
  `organization_id` int DEFAULT NULL COMMENT '机构id',
  `group_id` int unsigned DEFAULT '0' COMMENT '会员分组ID',
  `avatar` varchar(300) DEFAULT NULL COMMENT '头像',
  `bg_image` varchar(200) DEFAULT NULL COMMENT '背景图',
  `user_code` varchar(100) DEFAULT NULL COMMENT '用户编码',
  `certification` int DEFAULT '0' COMMENT '是否已实名认证',
  `age` int DEFAULT NULL COMMENT '年龄',
  `offline` tinyint unsigned DEFAULT '0' COMMENT '是否线下会员',
  `followers` int unsigned DEFAULT '0' COMMENT '关注数',
  `fans` int unsigned DEFAULT '0' COMMENT '粉丝数',
  `likes` int unsigned DEFAULT '0' COMMENT '点赞数',
  `comment_numbers` int unsigned DEFAULT '0' COMMENT '评论数',
  `recommend` tinyint NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `openid` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '微信openid',
  `office_openid` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '微信公众号openid',
  `unionid` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '微信unionID',
  `client_id` varchar(100) DEFAULT '' COMMENT '客户端ID',
  `not_allow_vip` tinyint NOT NULL DEFAULT '0' COMMENT '不允许办卡',
  `is_admin` tinyint NOT NULL DEFAULT '0' COMMENT '是否管理员',
  `is_organization_admin` tinyint NOT NULL DEFAULT '0' COMMENT '是否企业管理员',
  `login_num` int unsigned DEFAULT '0' COMMENT '累计登录次数',
  `company_id` int DEFAULT NULL COMMENT '企业ID',
  `merchants` varchar(300) DEFAULT NULL COMMENT '可管理的场馆',
  `merchant_id` int DEFAULT NULL COMMENT '商户ID',
  `merchant_name` varchar(100) DEFAULT NULL COMMENT '商户名称',
  `merchant_avatar` varchar(500) DEFAULT NULL COMMENT '商户头像',
  `uid` int unsigned NOT NULL DEFAULT '0' COMMENT '第三方系统的用户ID',
  `expert_type` tinyint DEFAULT NULL COMMENT '专家角色',
  `expire_time` int NOT NULL DEFAULT '0' COMMENT '过期时间',
  `settlement_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最后结算时间',
  `aptitude` varchar(255) DEFAULT NULL COMMENT '资质',
  `industry_parent` varchar(50) DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) DEFAULT NULL COMMENT '行业类型(子级)',
  `title` varchar(255) DEFAULT NULL COMMENT '头衔',
  `template_id` int NOT NULL DEFAULT '10257' COMMENT '安装的产品ID',
  `installed` int DEFAULT '0' COMMENT '插件安装状态(仅对超超管判断) 0未安装 1已安装 ',
  `speciality` varchar(255) DEFAULT NULL COMMENT '特长',
  `comments` varchar(300) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0在线, 1离线',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`user_id`) USING BTREE,
  KEY `organization_id` (`organization_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  KEY `is_admin` (`is_admin`) USING BTREE,
  KEY `merchant_id` (`merchant_id`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `city` (`city`)
) ENGINE=InnoDB AUTO_INCREMENT=35581 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='用户记录表';
CREATE TABLE `sys_user_balance_log` (
  `log_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `scene` tinyint unsigned NOT NULL DEFAULT '10' COMMENT '余额变动场景(10用户充值 20用户消费 30管理员操作 40订单退款)',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '变动金额',
  `balance` decimal(20,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '变动后余额',
  `transaction_id` char(64) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '支付流水号',
  `order_no` char(64) CHARACTER SET utf8mb4 NOT NULL DEFAULT '' COMMENT '订单编号',
  `remark` varchar(500) NOT NULL DEFAULT '' COMMENT '管理员备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '0' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`log_id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=101721 DEFAULT CHARSET=utf8 COMMENT='用户余额变动明细表';
CREATE TABLE `sys_user_collection` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tid` int unsigned NOT NULL DEFAULT '0' COMMENT '租户ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10865 DEFAULT CHARSET=utf8 COMMENT='我的收藏';
CREATE TABLE `sys_user_file` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` int NOT NULL COMMENT '用户id',
  `name` varchar(200) DEFAULT NULL COMMENT '文件名称',
  `is_directory` int DEFAULT NULL COMMENT '是否是文件夹',
  `parent_id` int DEFAULT NULL COMMENT '上级id',
  `path` varchar(400) DEFAULT NULL COMMENT '文件路径',
  `length` int DEFAULT NULL COMMENT '文件大小',
  `content_type` varchar(80) DEFAULT NULL COMMENT '文件类型',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='用户文件';
CREATE TABLE `sys_user_grade` (
  `grade_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '等级ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '等级名称',
  `weight` int unsigned NOT NULL DEFAULT '1' COMMENT '等级权重(1-9999)',
  `upgrade` text NOT NULL COMMENT '升级条件',
  `equity` text NOT NULL COMMENT '等级权益(折扣率0-100)',
  `commission` text COMMENT '佣金比率',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `merchant_code` varchar(50) NOT NULL DEFAULT '' COMMENT '商户编码',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`grade_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8 COMMENT='用户会员等级表';
CREATE TABLE `sys_user_group` (
  `group_id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '分组ID',
  `name` varchar(50) NOT NULL DEFAULT '' COMMENT '分组名称',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`group_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8 COMMENT='用户分组管理表';
CREATE TABLE `sys_user_oauth` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `oauth_type` varchar(255) NOT NULL DEFAULT '' COMMENT '第三方登陆类型(MP-WEIXIN)',
  `oauth_id` varchar(100) NOT NULL DEFAULT '' COMMENT '第三方用户唯一标识 (uid openid)',
  `unionid` varchar(100) NOT NULL DEFAULT '' COMMENT '微信unionID',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `comments` varchar(300) DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`),
  KEY `oauth_type` (`oauth_type`),
  KEY `oauth_type_2` (`oauth_type`,`oauth_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=415 DEFAULT CHARSET=utf8 COMMENT='第三方用户信息表';
CREATE TABLE `sys_user_referee` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `dealer_id` int unsigned NOT NULL DEFAULT '0' COMMENT '推荐人ID',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户id(被推荐人)',
  `level` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '推荐关系层级(1,2,3)',
  `comments` varchar(400) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '备注',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `dealer_id` (`dealer_id`),
  KEY `user_id` (`user_id`),
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1937 DEFAULT CHARSET=utf8 COMMENT='用户推荐关系表';
CREATE TABLE `sys_user_role` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `user_id` int NOT NULL COMMENT '用户id',
  `role_id` int NOT NULL COMMENT '角色id',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `FK_sys_user_role` (`user_id`) USING BTREE,
  KEY `FK_sys_user_role_role` (`role_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE,
  CONSTRAINT `sys_user_role_ibfk_2` FOREIGN KEY (`role_id`) REFERENCES `sys_role` (`role_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16303 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='用户角色';
CREATE TABLE `sys_user_verify` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `user_id` int unsigned DEFAULT '0' COMMENT '用户ID',
  `type` int unsigned DEFAULT '0' COMMENT '认证类型 0个人 1企业',
  `name` varchar(50) DEFAULT '' COMMENT '主体名称',
  `zz_code` varchar(50) DEFAULT NULL COMMENT '营业执照号',
  `zz_img` varchar(200) DEFAULT NULL COMMENT '营业执照图片',
  `real_name` varchar(50) DEFAULT '' COMMENT '真实姓名',
  `id_card` varchar(50) DEFAULT NULL COMMENT '身份证号码',
  `sfz1` varchar(200) DEFAULT NULL COMMENT '正面',
  `sfz2` varchar(200) DEFAULT NULL COMMENT '反面',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `files` varchar(2000) DEFAULT NULL COMMENT '其他证件',
  `admin_id` int unsigned DEFAULT '0' COMMENT '操作员',
  `organization_id` int unsigned DEFAULT '0' COMMENT '所属机构',
  `user_role_id` int unsigned DEFAULT '0' COMMENT '记录当前用户的角色',
  `comments` varchar(300) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '备注',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0在线, 1离线',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=32933 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='实名认证';
CREATE TABLE `sys_version` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `version_name` varchar(255) NOT NULL DEFAULT '' COMMENT '版本名',
  `version_code` int NOT NULL COMMENT '版本号',
  `vue_download_url` varchar(200) DEFAULT NULL COMMENT '下载链接',
  `android_download_url` varchar(200) DEFAULT NULL COMMENT '下载链接',
  `ios_download_url` varchar(200) DEFAULT NULL COMMENT '下载链接',
  `update_info` varchar(500) DEFAULT NULL COMMENT '更新日志',
  `is_hard` int NOT NULL DEFAULT '0' COMMENT '强制更新',
  `is_hot` int DEFAULT '0' COMMENT '热更',
  `comments` varchar(300) NOT NULL DEFAULT '' COMMENT '备注',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '文章排序(数字越小越靠前)',
  `user_id` int DEFAULT NULL,
  `status` int NOT NULL DEFAULT '0' COMMENT '状态, 0正常, 1冻结',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '注册时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10165 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='版本更新';
CREATE TABLE `sys_website` (
  `website_id` int NOT NULL AUTO_INCREMENT COMMENT '站点ID',
  `website_name` varchar(50) NOT NULL DEFAULT '' COMMENT '网站名称',
  `website_code` varchar(100) NOT NULL DEFAULT '' COMMENT '网站标识',
  `website_icon` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO',
  `website_dark_logo` varchar(200) NOT NULL DEFAULT '' COMMENT '网站LOGO(深色模式)',
  `website_type` varchar(50) NOT NULL DEFAULT '' COMMENT '网站类型',
  `keywords` varchar(50) NOT NULL DEFAULT '' COMMENT '网站关键词',
  `prefix` varchar(100) DEFAULT NULL COMMENT '域名前缀',
  `domain` varchar(100) DEFAULT NULL COMMENT '绑定域名',
  `style` varchar(100) DEFAULT NULL COMMENT '全局样式',
  `admin_url` varchar(200) DEFAULT NULL COMMENT '后台管理地址',
  `version` int unsigned NOT NULL DEFAULT '10' COMMENT '应用版本 10免费版 20授权版 30永久授权',
  `expiration_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '服务到期时间',
  `template_id` int unsigned NOT NULL DEFAULT '10' COMMENT '模版ID',
  `industry_parent` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(父级)',
  `industry_child` varchar(50) NOT NULL DEFAULT '' COMMENT '行业类型(子级)',
  `company_id` int unsigned NOT NULL DEFAULT '20' COMMENT '企业ID',
  `country` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在国家',
  `province` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在省份',
  `city` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在城市',
  `region` varchar(50) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '所在辖区',
  `longitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '经度',
  `latitude` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '纬度',
  `address` varchar(200) DEFAULT '' COMMENT '街道地址',
  `phone` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '联系电话',
  `email` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '电子邮箱',
  `icp_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT 'ICP备案号',
  `police_no` varchar(100) CHARACTER SET utf8 NOT NULL DEFAULT '' COMMENT '公安备案',
  `comments` varchar(400) DEFAULT '' COMMENT '备注',
  `recommend` int NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态 0未开通 1运行中 2维护中 3已关闭 4已欠费停机 5违规关停',
  `status_text` varchar(400) DEFAULT '' COMMENT '维护说明',
  `status_close` varchar(400) DEFAULT '' COMMENT '关闭说明',
  `styles` varchar(200) NOT NULL DEFAULT '' COMMENT '全局样式',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`website_id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=982 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='网站信息记录表';
CREATE TABLE `sys_website_field` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `type` int DEFAULT '0' COMMENT '类型，0文本 1图片 2其他',
  `name` varchar(100) DEFAULT '' COMMENT '名称',
  `default_value` varchar(1000) DEFAULT NULL COMMENT '默认值',
  `style` varchar(255) DEFAULT NULL COMMENT '样式',
  `modify_range` varchar(255) DEFAULT NULL COMMENT '可修改的值 [on|off]',
  `comments` varchar(500) DEFAULT '' COMMENT '备注',
  `value` varchar(1000) DEFAULT '' COMMENT '名称',
  `sort_number` int unsigned NOT NULL DEFAULT '100' COMMENT '排序(数字越小越靠前)',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `website_id` (`type`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10714 DEFAULT CHARSET=utf8 COMMENT='参数';
CREATE TABLE `sys_white_domain` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `domain` varchar(100) DEFAULT NULL COMMENT '域名',
  `status` int NOT NULL DEFAULT '0' COMMENT '状态',
  `sort_number` int NOT NULL DEFAULT '1' COMMENT '排序号',
  `user_id` int unsigned NOT NULL DEFAULT '0' COMMENT '用户ID',
  `deleted` int NOT NULL DEFAULT '0' COMMENT '是否删除, 0否, 1是',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户id',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `tenant_id` (`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=10215 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='服务器白名单';

SET FOREIGN_KEY_CHECKS=1;